INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2499282a-00c2-4327-9891-e5949d06373b', '宿醉', '宿醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["風引春心不自由，等閑衝席飲多籌。","朝來始向花前覺，度却醒時一夜愁。"]', '["风引春心不自由，等闲衝席饮多籌。","朝来始向花前覺，度却醒时一夜愁。"]', '诗', 'shi', '', NULL, '宿醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('249ef03d-725c-4f4f-bc02-ab39171d4945', '懼醉', '懼醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["聞道秋來怯夜寒，不辭泥水爲桮盤。","殷勤懼醉有深意，愁到醒時燈火闌。"]', '["闻道秋来怯夜寒，不辞泥水爲桮盤。","殷勤懼醉有深意，愁到醒时灯火闌。"]', '诗', 'shi', '', NULL, '懼醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a3e3b6f-f6c3-495c-b5e7-f5d4b36e64d1', '羨醉', '羨醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["綺陌高樓競醉眠，共期顦顇不相憐。","也應自有尋春日，虛度而今正少年。"]', '["綺陌高楼競醉眠，共期顦顇不相怜。","也應自有尋春日，虛度而今正少年。"]', '诗', 'shi', '', NULL, '羨醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9e0cca7-70dd-4d08-954b-72fdd42aae28', '憶醉', '憶醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["自歎旅人行意速，每嫌桮酒緩歸期。","今朝偏遇醒時別，淚落風前憶醉時。"]', '["自歎旅人行意速，每嫌桮酒緩归期。","今朝偏遇醒时別，泪落风前憶醉时。"]', '诗', 'shi', '', NULL, '憶醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29467c48-ba36-40cf-8ef6-3d9c92de5150', '病醉', '病醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["醉伴見儂因病酒，道儂無酒不相窺。","那知下藥還沽底，人去人來剩一巵。"]', '["醉伴见儂因病酒，道儂無酒不相窺。","那知下藥還沽底，人去人来剩一巵。"]', '诗', 'shi', '', NULL, '病醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6959f1b1-0404-44a4-99cf-7834fee41a28', '擬醉', '擬醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["九月閑宵初向火，一尊清酒始行桮。","憐君城外遙相憶，冒雨衝泥黑地來。"]', '["九月闲宵初向火，一尊清酒始行桮。","怜君城外遙相憶，冒雨衝泥黑地来。"]', '诗', 'shi', '', NULL, '擬醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65635820-9d48-4902-b107-ef280fcacb67', '勸醉', '勸醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["竇家能釀銷愁酒，但是愁人便與銷。","願我共君俱寂寞，只應連夜復連朝。"]', '["竇家能釀銷愁酒，但是愁人便與銷。","願我共君俱寂寞，只應連夜复連朝。"]', '诗', 'shi', '', NULL, '勸醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f444942-bb38-42c9-bc82-c8e908b04d31', '任醉', '任醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["本怕酒醒渾不飲，因君相勸覺情來。","殷勤滿酌從聽醉，乍可欲醒還一桮。"]', '["本怕酒醒渾不饮，因君相勸覺情来。","殷勤满酌從听醉，乍可欲醒還一桮。"]', '诗', 'shi', '', NULL, '任醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cad7c85-58ea-4593-bbb7-00e74fe24bd4', '同醉', '同醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["柏樹臺中推事人，杏花壇上鍊形真。","心源一種閑如水，同醉櫻桃林下春。"]', '["柏樹台中推事人，杏花壇上鍊形真。","心源一種闲如水，同醉櫻桃林下春。"]', '诗', 'shi', '', NULL, '同醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d18e7036-1278-442b-b849-c2ee42ca8522', '狂醉', '狂醉', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["一自柏臺爲御史，二年辜負兩京春。","峴亭今日顛狂醉，舞引紅娘亂打人。"]', '["一自柏台爲御史，二年辜負兩京春。","峴亭今日顛狂醉，舞引紅娘亂打人。"]', '诗', 'shi', '', NULL, '狂醉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f29311e8-c609-423a-973a-5c70f9578f51', '伴僧行', '伴僧行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春來求事百無成，因向愁中識道情。","花滿杏園千萬樹，幾人能伴老僧行。"]', '["春来求事百無成，因向愁中識道情。","花满杏园千万樹，幾人能伴老僧行。"]', '诗', 'shi', '', NULL, '伴僧行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b53f8e5-9021-431f-997b-2d50fd290a1a', '古寺', '古寺', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["古寺春餘日半斜，竹風蕭爽勝人家。","花時不到有花院，意在尋僧不在花。"]', '["古寺春餘日半斜，竹风蕭爽勝人家。","花时不到有花院，意在尋僧不在花。"]', '诗', 'shi', '', NULL, '古寺 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59bdc6e-6a2a-4759-8592-10a3724e0a69', '定僧', '定僧', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["落魄閑行不著家，徧尋春寺賞年華。","野僧偶向花前定，滿樹狂風滿樹花。"]', '["落魄闲行不著家，徧尋春寺賞年华。","野僧偶向花前定，满樹狂风满樹花。"]', '诗', 'shi', '', NULL, '定僧 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9991d806-3930-408e-a943-54a3d69e56db', '觀心處', '观心处', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["滿坐喧喧笑語頻，獨憐方丈了無塵。","燈前便是觀心處，要似觀心有幾人。"]', '["满坐喧喧笑語頻，独怜方丈了無塵。","灯前便是观心处，要似观心有幾人。"]', '诗', 'shi', '', NULL, '觀心處 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b696659-42b7-4695-8251-971a0cf706e2', '智度師二首 一', '智度師二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["四十年前馬上飛，功名藏盡擁禪衣。","石榴園下擒生處，獨自閑行獨自歸。"]', '["四十年前马上飞，功名藏尽擁禪衣。","石榴园下擒生处，独自闲行独自归。"]', '诗', 'shi', '', NULL, '智度師二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f801df9d-6ccc-42bb-998a-3772c86e3077', '智度師二首 二', '智度師二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["三陷思明三突圍，鐵衣拋盡衲禪衣。","天津橋上無人識，閑凭欄干望落暉。"]', '["三陷思明三突圍，鐵衣拋尽衲禪衣。","天津橋上無人識，闲凭欄干望落暉。"]', '诗', 'shi', '', NULL, '智度師二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1409f02-1aa8-4837-a92a-7a0b5c8c86ff', '西明寺牡丹', '西明寺牡丹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["花向琉璃地上生，光風炫轉紫雲英。","自從天女盤中見，直至今朝眼更明。"]', '["花向琉璃地上生，光风炫轉紫云英。","自從天女盤中见，直至今朝眼更明。"]', '诗', 'shi', '', NULL, '西明寺牡丹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a328d410-7fbb-4727-bfd9-9f15129a7241', '憶楊十二', '憶楊十二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["去時芍藥纔堪贈，看却殘花已度春。","只爲情深偏愴別，等閑相見莫相親。"]', '["去时芍藥纔堪贈，看却殘花已度春。","只爲情深偏愴別，等闲相见莫相親。"]', '诗', 'shi', '', NULL, '憶楊十二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f813a11-a3a7-4612-b48d-69ee1a234bbd', '送復夢赴韋令幕', '送复梦赴韋令幕', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["世上於今重檢身，吾徒耽酒作狂人。","西曹舊事多持法，慎莫吐他丞相茵。"]', '["世上於今重檢身，吾徒耽酒作狂人。","西曹旧事多持法，慎莫吐他丞相茵。"]', '诗', 'shi', '', NULL, '送復夢赴韋令幕 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c11ab39-c2d2-40f6-8487-b849f20a15e1', '送劉太白', '送劉太白', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["洛陽大底居人少，從善坊西最寂寥。","想得劉君獨騎馬，古堤愁樹隔中橋。"]', '["洛陽大底居人少，從善坊西最寂寥。","想得劉君独騎马，古堤愁樹隔中橋。"]', '诗', 'shi', '', NULL, '送劉太白 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd719b17-e5f3-45ac-ba44-8caa8b298024', '奉誠園', '奉誠园', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蕭相深誠奉至尊，舊居求作奉誠園。","秋來古巷無人掃，樹滿空牆閉戟門。"]', '["蕭相深誠奉至尊，旧居求作奉誠园。","秋来古巷無人掃，樹满空牆閉戟门。"]', '诗', 'shi', '', NULL, '奉誠園 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d68459e-3fac-4968-99fd-e0c1e3e7509c', '與太白同之東洛至櫟陽太白染疾駐行予九月二十五日至華嶽寺雪後望山', '與太白同之东洛至櫟陽太白染疾駐行予九月二十五日至华嶽寺雪後望山', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["共作洛陽千里伴，老劉因疾駐行軒。","今朝獨自山前立，雪滿三峰倚寺門。"]', '["共作洛陽千里伴，老劉因疾駐行軒。","今朝独自山前立，雪满三峰倚寺门。"]', '诗', 'shi', '', NULL, '與太白同之東洛至櫟陽太白染疾駐行予九月二十五日至華嶽寺雪後望山 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cc954d2-0b6b-4fc5-aec8-1841b8ea46bc', '野狐泉柳林', '野狐泉柳林', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["去日野狐泉上柳，紫牙初綻拂眉低。","秋來寥落驚風雨，葉滿空林踏作泥。"]', '["去日野狐泉上柳，紫牙初綻拂眉低。","秋来寥落驚风雨，葉满空林踏作泥。"]', '诗', 'shi', '', NULL, '野狐泉柳林 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cdfbdae-79ce-462c-ab32-37f809b326fa', '酬胡三憑人問牡丹', '酬胡三憑人问牡丹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["竊見胡三問牡丹，爲言依舊滿西欄。","花時何處偏相憶，寥落衰紅雨後看。"]', '["竊见胡三问牡丹，爲言依旧满西欄。","花时何处偏相憶，寥落衰紅雨後看。"]', '诗', 'shi', '', NULL, '酬胡三憑人問牡丹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31791a22-6ec0-47c8-a3b6-1a207d69e749', '酬樂天秋興見贈本句云莫怪獨吟秋興苦比君校近二毛年', '酬乐天秋兴见贈本句云莫怪独吟秋兴苦比君校近二毛年', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["勸君休作悲秋賦，白髮如星也任垂。","畢竟百年同是夢，長年何異少何爲。"]', '["勸君休作悲秋賦，白髮如星也任垂。","畢竟百年同是梦，长年何異少何爲。"]', '诗', 'shi', '', NULL, '酬樂天秋興見贈本句云莫怪獨吟秋興苦比君校近二毛年 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f406cf-90f0-4aa2-b594-1473ced4856b', '雪後宿同軌店上法護寺鐘樓望月', '雪後宿同軌店上法護寺鐘楼望月', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["滿山殘雪滿山風，野寺無門院院空。","煙火漸稀孤店靜，月明深夜古樓中。"]', '["满山殘雪满山风，野寺無门院院空。","煙火漸稀孤店静，月明深夜古楼中。"]', '诗', 'shi', '', NULL, '雪後宿同軌店上法護寺鐘樓望月 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2acc06f6-6da2-4b71-8d57-95fe33b3af30', '陪韋尚書丈歸履信宅因贈韋氏兄弟', '陪韋尚书丈归履信宅因贈韋氏兄弟', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["紫垣騶騎入華居，公子文衣護錦輿。","眠閣書生復何事，也騎羸馬從尚書。"]', '["紫垣騶騎入华居，公子文衣護錦輿。","眠閣书生复何事，也騎羸马從尚书。"]', '诗', 'shi', '', NULL, '陪韋尚書丈歸履信宅因贈韋氏兄弟 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33d01690-c6e7-449b-964d-d3cbfb8de2b2', '永貞二年正月二日上御丹鳳樓赦天下予與李公垂庾順之閑行曲江不及盛觀', '永貞二年正月二日上御丹鳳楼赦天下予與李公垂庾順之闲行曲江不及盛观', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春來饒夢慵朝起，不看千官擁御樓。","却著閑行是忙事，數人同傍曲江頭。"]', '["春来饒梦慵朝起，不看千官擁御楼。","却著闲行是忙事，數人同傍曲江头。"]', '诗', 'shi', '', NULL, '永貞二年正月二日上御丹鳳樓赦天下予與李公垂庾順之閑行曲江不及盛觀 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d314c99-5469-4867-8969-9990cbdabf54', '韋居守晚歲常言退休之志因署其居曰大隱洞命予賦詩因贈絕句', '韋居守晚歲常言退休之志因署其居曰大隐洞命予賦诗因贈絕句', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["謝公潛有東山意，已向朱門啓洞門。","大隱猶疑戀朝市，不如名作罷歸園。"]', '["謝公潛有东山意，已向朱门啓洞门。","大隐猶疑戀朝市，不如名作罷归园。"]', '诗', 'shi', '', NULL, '韋居守晚歲常言退休之志因署其居曰大隱洞命予賦詩因贈絕句 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13202e47-9430-4789-89b8-f3bdc623e49e', '贈李十二牡丹花片因以餞行', '贈李十二牡丹花片因以餞行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鸎澁餘聲絮墮風，牡丹花盡葉成叢。","可憐顏色經年別，收取朱闌一片紅。"]', '["鸎澁餘声絮墮风，牡丹花尽葉成叢。","可怜顏色經年別，收取朱闌一片紅。"]', '诗', 'shi', '', NULL, '贈李十二牡丹花片因以餞行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35388b3e-a98a-479d-aee4-e22a573cbb0c', '題李十一修行里居壁', '題李十一修行里居壁', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雲闕朝迴塵騎合，杏花春盡曲江閑。","憐君雖在城中住，不隔人家便是山。"]', '["云闕朝迴塵騎合，杏花春尽曲江闲。","怜君雖在城中住，不隔人家便是山。"]', '诗', 'shi', '', NULL, '題李十一修行里居壁 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('069ab4ed-53f7-4d02-bb5b-5ea859971f72', '靖安窮居', '靖安窮居', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["喧靜不由居遠近，大都車馬就權門。","野人住處無名利，草滿空階樹滿園。"]', '["喧静不由居远近，大都车马就權门。","野人住处無名利，草满空階樹满园。"]', '诗', 'shi', '', NULL, '靖安窮居 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a59963b-3551-4e86-8016-4391234956bd', '贈樂天', '贈乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["等閑相見銷長日，也有閑時更學琴。","不是眼前無外物，不關心事不經心。"]', '["等闲相见銷长日，也有闲时更学琴。","不是眼前無外物，不关心事不經心。"]', '诗', 'shi', '', NULL, '贈樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f6f93a-4705-4416-994b-f0bed8471193', '使東川 駱口驛二首 一', '使东川 駱口驛二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["郵亭壁上數行字，崔李題名王白詩。","盡日無人共言語，不離牆下至行時。"]', '["郵亭壁上數行字，崔李題名王白诗。","尽日無人共言語，不離牆下至行时。"]', '诗', 'shi', '', NULL, '使東川 駱口驛二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5515d6a8-272d-4a16-827b-ed8d3d8448e4', '使東川 駱口驛二首 二', '使东川 駱口驛二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["二星徼外通蠻服，五夜燈前草御文。","我到東川恰相半，向南看月北看雲。"]', '["二星徼外通蠻服，五夜灯前草御文。","我到东川恰相半，向南看月北看云。"]', '诗', 'shi', '', NULL, '使東川 駱口驛二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6854aa9-80fd-4b31-9e7e-802cfcbee4f9', '使東川 清明日', '使东川 清明日', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["常年寒食好風輕，觸處相隨取次行。","今日清明漢江上，一身騎馬縣官迎。"]', '["常年寒食好风轻，觸处相隨取次行。","今日清明漢江上，一身騎马縣官迎。"]', '诗', 'shi', '', NULL, '使東川 清明日 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fe16304-7de7-4383-9501-eab14dedd165', '使東川 亞枝紅', '使东川 亞枝紅', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["平陽池上亞枝紅，悵望山郵事事同。","還向萬竿深竹裏，一枝渾臥碧流中。"]', '["平陽池上亞枝紅，悵望山郵事事同。","還向万竿深竹裏，一枝渾臥碧流中。"]', '诗', 'shi', '', NULL, '使東川 亞枝紅 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('103e1b52-b0b7-412b-9b76-02a4b834848f', '使東川 梁州夢', '使东川 梁州梦', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夢君同繞曲江頭，也向慈恩院院遊。","亭吏呼人排去馬，忽驚身在古梁州。"]', '["梦君同繞曲江头，也向慈恩院院游。","亭吏呼人排去马，忽驚身在古梁州。"]', '诗', 'shi', '', NULL, '使東川 梁州夢 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('581d09df-97be-40e5-af0c-88be3c8dfd6f', '使東川 南秦雪', '使东川 南秦雪', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["帝城寒盡臨寒食，駱谷春深未有春。","纔見嶺頭雲似蓋，已驚巖下雪如塵。","千峰筍石千株玉，萬樹松蘿萬朵銀。","飛鳥不飛猿不動，青驄御史上南秦。"]', '["帝城寒尽臨寒食，駱谷春深未有春。","纔见嶺头云似蓋，已驚巖下雪如塵。","千峰筍石千株玉，万樹松蘿万朵銀。","飞鸟不飞猿不动，青驄御史上南秦。"]', '诗', 'shi', '', NULL, '使東川 南秦雪 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5133a5c-8a3b-4200-87c0-1e5bb03e3de9', '使東川 江樓月', '使东川 江楼月', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["嘉陵江岸驛樓中，江在樓前月在空。","月色滿牀兼滿地，江聲如鼓復如風。","誠知遠近皆三五，但恐陰晴有異同。","萬一帝鄉還潔白，幾人潛傍杏園東。"]', '["嘉陵江岸驛楼中，江在楼前月在空。","月色满牀兼满地，江声如鼓复如风。","誠知远近皆三五，但恐陰晴有異同。","万一帝乡還潔白，幾人潛傍杏园东。"]', '诗', 'shi', '', NULL, '使東川 江樓月 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caf88efc-7f27-44ce-bfd5-aebe4cb6468e', '使東川 慙問囚', '使东川 慙问囚', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["司馬子微壇上頭，與君深結白雲儔。","尚平村落擬連買，王屋山泉爲別遊。","各待陸渾求一尉，共資三徑便同休。","那知今日蜀門路，帶月夜行緣問囚。"]', '["司马子微壇上头，與君深結白云儔。","尚平村落擬連買，王屋山泉爲別游。","各待陸渾求一尉，共資三徑便同休。","那知今日蜀门路，带月夜行緣问囚。"]', '诗', 'shi', '', NULL, '使東川 慙問囚 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c7b9255-66db-4c4e-b2ae-73342be2502b', '使東川 江上行', '使东川 江上行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["悶見漢江流不息，悠悠漫漫竟何成。","江流不語意相問，何事遠來江上行。"]', '["悶见漢江流不息，悠悠漫漫竟何成。","江流不語意相问，何事远来江上行。"]', '诗', 'shi', '', NULL, '使東川 江上行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a08255-3ae2-4d5c-9b54-bcfb48808ea7', '使東川 漢江上笛', '使东川 漢江上笛', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["小年爲寫遊梁賦，最說漢江聞笛愁。","今夜聽時在何處，月明西縣驛南樓。"]', '["小年爲寫游梁賦，最说漢江闻笛愁。","今夜听时在何处，月明西縣驛南楼。"]', '诗', 'shi', '', NULL, '使東川 漢江上笛 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('218da403-736a-4102-8308-09c22230e8a0', '使東川 郵亭月', '使东川 郵亭月', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["君多務實我多情，大抵偏嗔步月明。","今夜山郵與蠻嶂，君應堅臥我還行。"]', '["君多務實我多情，大抵偏嗔步月明。","今夜山郵與蠻嶂，君應堅臥我還行。"]', '诗', 'shi', '', NULL, '使東川 郵亭月 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac58dd5-d86a-49ca-bf31-08520f85d513', '使東川 嘉陵驛二首 一', '使东川 嘉陵驛二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["嘉陵驛上空牀客，一夜嘉陵江水聲。","仍對牆南滿山樹，野花撩亂月朧明。"]', '["嘉陵驛上空牀客，一夜嘉陵江水声。","仍对牆南满山樹，野花撩亂月朧明。"]', '诗', 'shi', '', NULL, '使東川 嘉陵驛二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb059bc3-708b-4a8a-a835-4060b9803c57', '使東川 嘉陵驛二首 二', '使东川 嘉陵驛二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["牆外花枝壓短牆，月明還照半張牀。","無人會得此時意，一夜獨眠西畔廊。"]', '["牆外花枝壓短牆，月明還照半張牀。","無人會得此时意，一夜独眠西畔廊。"]', '诗', 'shi', '', NULL, '使東川 嘉陵驛二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccd386d2-a2d8-486d-bd99-4532e92530ca', '使東川 百牢關', '使东川 百牢关', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["嘉陵江上萬重山，何事臨江一破顏。","自笑只緣任敬仲，等閑身度百牢關。"]', '["嘉陵江上万重山，何事臨江一破顏。","自笑只緣任敬仲，等闲身度百牢关。"]', '诗', 'shi', '', NULL, '使東川 百牢關 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53a82ea9-ce9f-40cc-800c-4e5032afb150', '使東川 江花落', '使东川 江花落', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["日暮嘉陵江水東，棃花萬片逐江風。","江花何處最腸斷，半落江流半在空。"]', '["日暮嘉陵江水东，棃花万片逐江风。","江花何处最腸斷，半落江流半在空。"]', '诗', 'shi', '', NULL, '使東川 江花落 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d55cbd0-897e-4c01-b618-0830269835cb', '使東川 嘉陵江二首 一', '使东川 嘉陵江二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["秦人惟識秦中水，長想吳江與蜀江。","今日嘉川驛樓下，可憐如練繞明窗。"]', '["秦人惟識秦中水，长想吳江與蜀江。","今日嘉川驛楼下，可怜如練繞明窗。"]', '诗', 'shi', '', NULL, '使東川 嘉陵江二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7ae908f-1310-4d18-8713-b2b712183b13', '使東川 嘉陵江二首 二', '使东川 嘉陵江二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["千里嘉陵江水聲，何年重繞此江行。","只應添得清宵夢，時見滿江流月明。"]', '["千里嘉陵江水声，何年重繞此江行。","只應添得清宵梦，时见满江流月明。"]', '诗', 'shi', '', NULL, '使東川 嘉陵江二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9527fca2-6423-461d-a129-0f123026a333', '使東川 西縣驛', '使东川 西縣驛', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["去時樓上清明夜，月照樓前撩亂花。","今日成陰復成子，可憐春盡未還家。"]', '["去时楼上清明夜，月照楼前撩亂花。","今日成陰复成子，可怜春尽未還家。"]', '诗', 'shi', '', NULL, '使東川 西縣驛 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a03faa6-9ccc-4839-a2ee-c480b8fd861e', '使東川 望喜驛', '使东川 望喜驛', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["滿眼文書堆案邊，眼昏偷得暫時眠。","子規驚覺燈又滅，一道月光橫枕前。"]', '["满眼文书堆案邊，眼昏偷得暫时眠。","子規驚覺灯又滅，一道月光橫枕前。"]', '诗', 'shi', '', NULL, '使東川 望喜驛 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51736f4-8fe8-400e-92eb-8a1b9c1a6a16', '使東川 好時節', '使东川 好时節', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["身騎驄馬峨眉下，面帶霜威卓氏前。","虛度東川好時節，酒樓元被蜀兒眠。"]', '["身騎驄马峨眉下，面带霜威卓氏前。","虛度东川好时節，酒楼元被蜀兒眠。"]', '诗', 'shi', '', NULL, '使東川 好時節 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319ecb16-94e3-4fad-9d34-437eca2ea1be', '使東川 夜深行', '使东川 夜深行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夜深猶自繞江行，震地江聲似鼓聲。","漸見戍樓疑近驛，百牢關吏火前迎。"]', '["夜深猶自繞江行，震地江声似鼓声。","漸见戍楼疑近驛，百牢关吏火前迎。"]', '诗', 'shi', '', NULL, '使東川 夜深行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125359bd-6743-482e-9dcd-66c680233ca3', '使東川 望驛臺', '使东川 望驛台', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["可憐三月三旬足，悵望江邊望驛臺。","料得孟光今日語，不曾春盡不歸來。"]', '["可怜三月三旬足，悵望江邊望驛台。","料得孟光今日語，不曾春尽不归来。"]', '诗', 'shi', '', NULL, '使東川 望驛臺 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25fb5507-0913-44d8-ab9e-b2e113537535', '贈咸陽少府蕭郎', '贈咸陽少府蕭郎', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫怪逢君淚每盈，仲由多感有深情。","陸家幼女託良壻，阮氏諸房無外生。","顧我自傷爲弟拙，念渠能繼事姑名。","別時何處最腸斷，日暮渭陽驅馬行。"]', '["莫怪逢君泪每盈，仲由多感有深情。","陸家幼女託良壻，阮氏諸房無外生。","顧我自傷爲弟拙，念渠能繼事姑名。","別时何处最腸斷，日暮渭陽驱马行。"]', '诗', 'shi', '', NULL, '贈咸陽少府蕭郎 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('153d317f-8d14-4278-a8cb-781acb795453', '贈呂三校書', '贈呂三校书', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["同年同拜校書郎，觸處潛行爛熳狂。","共占花園爭趙辟，競添錢貫定秋娘。","七年浮世皆經眼，八月閑宵忽竝牀。","語到欲明歡又泣，傍人相笑兩相傷。"]', '["同年同拜校书郎，觸处潛行爛熳狂。","共占花园爭趙辟，競添錢貫定秋娘。","七年浮世皆經眼，八月闲宵忽竝牀。","語到欲明歡又泣，傍人相笑兩相傷。"]', '诗', 'shi', '', NULL, '贈呂三校書 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8583100a-bd5c-48c1-966f-9c28a73d0a43', '封書', '封书', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鶴臺南望白雲關，城市猶存暫一還。","書出步虛三百韻，蘂珠文字在人間。"]', '["鹤台南望白云关，城市猶存暫一還。","书出步虛三百韻，蘂珠文字在人间。"]', '诗', 'shi', '', NULL, '封書 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48a7d3fe-36c1-4654-b957-07ba14de0d58', '仁風李著作園醉後寄李十', '仁风李著作园醉後寄李十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["朧明春月照花枝，花下音聲是管兒。","却笑西京李員外，五更騎馬趁朝時。"]', '["朧明春月照花枝，花下音声是管兒。","却笑西京李員外，五更騎马趁朝时。"]', '诗', 'shi', '', NULL, '仁風李著作園醉後寄李十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcc75cc7-04a6-4599-81e8-48817a28a056', '燈影', '灯影', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["洛陽晝夜無車馬，漫挂紅紗滿樹頭。","見說平時燈影裏，玄宗潛伴太真游。"]', '["洛陽晝夜無车马，漫挂紅紗满樹头。","见说平时灯影裏，玄宗潛伴太真游。"]', '诗', 'shi', '', NULL, '燈影 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46cb00e3-d659-463b-bff9-da3047e3eaa3', '貶江陵途中寄樂天杓直杓直以員外郎判鹽鐵樂天以拾遺在翰林', '貶江陵途中寄乐天杓直杓直以員外郎判鹽鐵乐天以拾遺在翰林', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["想到江陵無一事，酒杯書卷綴新文。","紫芽嫩茗和枝采，朱橘香苞數瓣分。","暇日上山狂逐鹿，凌晨過寺飽看雲。","算緡草詔終須解，不敢將心遠羨君。"]', '["想到江陵無一事，酒杯书卷綴新文。","紫芽嫩茗和枝采，朱橘香苞數瓣分。","暇日上山狂逐鹿，凌晨過寺飽看云。","算緡草詔終須解，不敢將心远羨君。"]', '诗', 'shi', '', NULL, '貶江陵途中寄樂天杓直杓直以員外郎判鹽鐵樂天以拾遺在翰林 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fe83bb3-c791-47a4-a66b-b7f0d7551a94', '渡漢江', '渡漢江', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["嶓冢去年尋漾水，襄陽今日渡江濆。","山遙遠樹纔成點，浦靜沈碑欲辨文。","萬里朝宗誠可羨，百川流入渺難分。","鯢鯨歸穴東溟溢，又作波濤隨伍員。"]', '["嶓冢去年尋漾水，襄陽今日渡江濆。","山遙远樹纔成点，浦静沈碑欲辨文。","万里朝宗誠可羨，百川流入渺难分。","鯢鯨归穴东溟溢，又作波濤隨伍員。"]', '诗', 'shi', '', NULL, '渡漢江 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065548d2-57c9-4735-b6cf-161f25c999d5', '哀病驄呈致用', '哀病驄呈致用', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["櫪上病驄啼褭褭，江邊廢宅路迢迢。","自經梅雨長垂耳，乍食菰蔣欲折腰。","金絡頭銜光未滅，玉花衫色瘦來燋。","曾聽禁漏驚衙鼓，慣蹋康衢怕小橋。","半夜雄嘶心不死，日高飢臥尾還搖。","龍媒薄地天池遠，何事牽牛在碧霄。"]', '["櫪上病驄啼褭褭，江邊廢宅路迢迢。","自經梅雨长垂耳，乍食菰蔣欲折腰。","金絡头銜光未滅，玉花衫色瘦来燋。","曾听禁漏驚衙鼓，慣蹋康衢怕小橋。","半夜雄嘶心不死，日高飢臥尾還搖。","龙媒薄地天池远，何事牽牛在碧霄。"]', '诗', 'shi', '', NULL, '哀病驄呈致用 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a97e8535-9ed3-43a2-b7a1-929399a49229', '送嶺南崔侍御', '送嶺南崔侍御', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["我是北人長北望，每嗟南雁更南飛。","君今又作嶺南別，南雁北歸君未歸。","洞主參承驚豸角，島夷安集慕霜威。","黃家賊用鑹刀利，白水郎行旱地稀。","蜃吐朝光樓隱隱，鼇吹細浪雨霏霏。","毒龍蛻骨轟雷鼓，野象埋牙斸石磯。","火布垢塵須火浣，木綿溫軟當綿衣。","桄榔麪磣檳榔澀，海氣常昏海日微。","蛟老變爲妖婦女，舶來多賣假珠璣。","此中無限相憂事，請爲殷勤事事依。"]', '["我是北人长北望，每嗟南雁更南飞。","君今又作嶺南別，南雁北归君未归。","洞主參承驚豸角，島夷安集慕霜威。","黄家賊用鑹刀利，白水郎行旱地稀。","蜃吐朝光楼隐隐，鼇吹細浪雨霏霏。","毒龙蛻骨轟雷鼓，野象埋牙斸石磯。","火布垢塵須火浣，木綿溫軟當綿衣。","桄榔麪磣檳榔澀，海氣常昏海日微。","蛟老变爲妖婦女，舶来多賣假珠璣。","此中無限相憂事，請爲殷勤事事依。"]', '诗', 'shi', '', NULL, '送嶺南崔侍御 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f754fbb8-3279-4407-a77e-2ac280c5d0df', '酬樂天八月十五夜禁中獨直玩月見寄', '酬乐天八月十五夜禁中独直玩月见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["一年秋半月偏深，況就煙霄極賞心。","金鳳臺前波漾漾，玉鉤簾下影沈沈。","宴移明處清蘭路，歌待新詞促翰林。","何意枚臯正承詔，瞥然塵念到江陰。"]', '["一年秋半月偏深，況就煙霄極賞心。","金鳳台前波漾漾，玉鉤簾下影沈沈。","宴移明处清蘭路，歌待新词促翰林。","何意枚臯正承詔，瞥然塵念到江陰。"]', '诗', 'shi', '', NULL, '酬樂天八月十五夜禁中獨直玩月見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edfe9ceb-1e18-4799-af69-5829d529694c', '予病瘴樂天寄通中散碧腴垂雲膏仍題四韻以慰遠懷開坼之間因有酬答', '予病瘴乐天寄通中散碧腴垂云膏仍題四韻以慰远懷开坼之间因有酬答', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["紫河變鍊紅霞散，翠液煎研碧玉英。","金籍真人天上合，鹽車病驥軛前驚。","愁腸欲轉蛟龍吼，醉眼初開日月明。","唯有思君治不得，膏銷雪盡意還生。"]', '["紫河变鍊紅霞散，翠液煎研碧玉英。","金籍真人天上合，鹽车病驥軛前驚。","愁腸欲轉蛟龙吼，醉眼初开日月明。","唯有思君治不得，膏銷雪尽意還生。"]', '诗', 'shi', '', NULL, '予病瘴樂天寄通中散碧腴垂雲膏仍題四韻以慰遠懷開坼之間因有酬答 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f39e73-e021-4d61-99ba-ce3b1176262a', '陪諸公游故江西韋大夫通德湖舊居有感題四韻兼呈李六侍御即韋大夫舊寮也', '陪諸公游故江西韋大夫通德湖旧居有感題四韻兼呈李六侍御即韋大夫旧寮也', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["高墉行馬接通湖，巨壑藏舟感大夫。","塵壁暗埋悲舊札，風簾吹斷落殘珠。","煙波漾日侵隤岸，狐兔奔叢拂坐隅。","唯有滿園桃李下，膺門偏拜阮元瑜。"]', '["高墉行马接通湖，巨壑藏舟感大夫。","塵壁暗埋悲旧札，风簾吹斷落殘珠。","煙波漾日侵隤岸，狐兔奔叢拂坐隅。","唯有满园桃李下，膺门偏拜阮元瑜。"]', '诗', 'shi', '', NULL, '陪諸公游故江西韋大夫通德湖舊居有感題四韻兼呈李六侍御即韋大夫舊寮也 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44b7d6c5-3933-419e-aa66-612fdd30da63', '送友封二首 一', '送友封二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["桃葉成陰燕引雛，南風吹浪颭檣烏。","瘴雲拂地黃梅雨，明月滿帆青草湖。","迢遞旅魂歸去遠，顛狂酒興病來孤。","知君兄弟憐詩句，徧爲姑將惱大巫。"]', '["桃葉成陰燕引雛，南风吹浪颭檣烏。","瘴云拂地黄梅雨，明月满帆青草湖。","迢遞旅魂归去远，顛狂酒兴病来孤。","知君兄弟怜诗句，徧爲姑將惱大巫。"]', '诗', 'shi', '', NULL, '送友封二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('401288e9-ef20-4c63-9fe0-53df908806b0', '送友封二首 二', '送友封二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["惠和坊裏當時別，豈料江陵送上船。","鵬翼張風期萬里，馬頭無角已三年。","甘將泥尾隨龜後，尚有雲心在鶴前。","若見中丞忽相問，爲言腰折氣衝天。"]', '["惠和坊裏當时別，豈料江陵送上船。","鵬翼張风期万里，马头無角已三年。","甘將泥尾隨龟後，尚有云心在鹤前。","若见中丞忽相问，爲言腰折氣衝天。"]', '诗', 'shi', '', NULL, '送友封二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f00f292-9d3f-4cc7-ab13-297aff196f5f', '放言五首 一', '放言五首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["近來逢酒便高歌，醉舞詩狂漸欲魔。","五斗解酲猶恨少，十分飛盞未嫌多。","眼前讐敵都休問，身外功名一任他。","死是等閑生也得，擬將何事奈吾何。"]', '["近来逢酒便高歌，醉舞诗狂漸欲魔。","五斗解酲猶恨少，十分飞盞未嫌多。","眼前讐敵都休问，身外功名一任他。","死是等闲生也得，擬將何事奈吾何。"]', '诗', 'shi', '', NULL, '放言五首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d1d35a-bac6-495b-9e38-38d6846772d2', '放言五首 二', '放言五首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫將心事厭長沙，雲到何方不是家。","酒熟餔糟學漁父，飯來開口似神鵶。","竹枝待鳳千莖直，柳樹迎風一向斜。","總被天公霑雨露，等頭成長盡生涯。"]', '["莫將心事厭长沙，云到何方不是家。","酒熟餔糟学漁父，飯来开口似神鵶。","竹枝待鳳千莖直，柳樹迎风一向斜。","總被天公霑雨露，等头成长尽生涯。"]', '诗', 'shi', '', NULL, '放言五首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e578601-f9a4-4e47-9734-821810766962', '放言五首 三', '放言五首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["霆轟電烻數聲頻，不奈狂夫不藉身。","縱使被雷燒作燼，寧殊埋骨颺爲塵。","得成蝴蝶尋花樹，儻化江魚掉錦鱗。","必若乖龍在諸處，何須驚動自來人。"]', '["霆轟電烻數声頻，不奈狂夫不藉身。","縱使被雷燒作燼，寧殊埋骨颺爲塵。","得成蝴蝶尋花樹，儻化江鱼掉錦鱗。","必若乖龙在諸处，何須驚动自来人。"]', '诗', 'shi', '', NULL, '放言五首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5114e2e5-60fd-4ee2-aba2-8951729fa82a', '放言五首 四', '放言五首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["安得心源處處安，何勞終日望林巒。","玉英惟向火中冷，蓮葉元來水上乾。","甯戚飯牛圖底事，陸通歌鳳也無端。","孫登不語啓期樂，各自當情各自歡。"]', '["安得心源处处安，何勞終日望林巒。","玉英惟向火中冷，蓮葉元来水上乾。","甯戚飯牛圖底事，陸通歌鳳也無端。","孫登不語啓期乐，各自當情各自歡。"]', '诗', 'shi', '', NULL, '放言五首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9c59af9-f28a-484d-a458-16a924ebf20f', '放言五首 五', '放言五首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["三十年來世上行，也曾狂走趁浮名。","兩廻左降須知命，數度登朝何處榮。","乞我杯中松葉滿，遮渠肘上柳枝生。","他時定葬燒缸地，賣與人家得酒盛。"]', '["三十年来世上行，也曾狂走趁浮名。","兩廻左降須知命，數度登朝何处榮。","乞我杯中松葉满，遮渠肘上柳枝生。","他时定葬燒缸地，賣與人家得酒盛。"]', '诗', 'shi', '', NULL, '放言五首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd8c120-42de-41c2-bb28-964055bc1b6b', '劉二十八以文石枕見贈仍題絕句以將厚意因持壁州鞭酬謝兼廣爲四韻', '劉二十八以文石枕见贈仍題絕句以將厚意因持壁州鞭酬謝兼廣爲四韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["枕截文瓊珠綴篇，野人酬贈壁州鞭。","用長時節君須策，泥醉風雲我要眠。","歌眄彩霞臨藥竈，執陪仙仗引爐煙。","張騫却上知何日，隨會歸期在此年。"]', '["枕截文瓊珠綴篇，野人酬贈壁州鞭。","用长时節君須策，泥醉风云我要眠。","歌眄彩霞臨藥竈，執陪仙仗引爐煙。","張騫却上知何日，隨會归期在此年。"]', '诗', 'shi', '', NULL, '劉二十八以文石枕見贈仍題絕句以將厚意因持壁州鞭酬謝兼廣爲四韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ecebb3-979f-4f9c-9a05-9478cc6f50c9', '奉和嚴司空重陽日同崔常侍崔郎中及諸公登龍山落帽臺佳宴', '奉和嚴司空重陽日同崔常侍崔郎中及諸公登龙山落帽台佳宴', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["謝公愁思眇天涯，蠟屐登高爲菊花。","貴重近臣光綺席，笑憐從事落烏紗。","萸房暗綻紅珠朵，茗椀寒供白露芽。","詠碎龍山歸去號，馬奔流電妓奔車。"]', '["謝公愁思眇天涯，蠟屐登高爲菊花。","貴重近臣光綺席，笑怜從事落烏紗。","萸房暗綻紅珠朵，茗椀寒供白露芽。","詠碎龙山归去號，马奔流電妓奔车。"]', '诗', 'shi', '', NULL, '奉和嚴司空重陽日同崔常侍崔郎中及諸公登龍山落帽臺佳宴 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17fc2b97-0137-4bfd-8b5e-21cbdb3c5c21', '送王十一郎游剡中', '送王十一郎游剡中', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["越州都在浙河灣，塵土消沈景象閑。","百里油盆鏡湖水，千峰鈿朵會稽山。","軍城樓閣隨高下，禹廟煙霞自往還。","想得玉郎乘畫舸，幾回明月墜雲間。"]', '["越州都在浙河灣，塵土消沈景象闲。","百里油盆镜湖水，千峰鈿朵會稽山。","軍城楼閣隨高下，禹廟煙霞自往還。","想得玉郎乘畫舸，幾回明月墜云间。"]', '诗', 'shi', '', NULL, '送王十一郎游剡中 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2c3cef-2901-4358-bebc-9845c8934941', '送友封', '送友封', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["輕風略略柳欣欣，晴色空濛遠似塵。","斗柄未回猶帶閏，江痕潛上已生春。","蘭成宅裏尋枯樹，宋玉亭前別故人。","心斷洛陽三兩處，窈娘堤抱古天津。"]', '["轻风略略柳欣欣，晴色空濛远似塵。","斗柄未回猶带閏，江痕潛上已生春。","蘭成宅裏尋枯樹，宋玉亭前別故人。","心斷洛陽三兩处，窈娘堤抱古天津。"]', '诗', 'shi', '', NULL, '送友封 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26fe9cf9-c9ce-4131-a8d0-0e744ee2e908', '送致用', '送致用', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["淚霑雙袖血成文，不爲悲身爲別君。","望鶴眼穿期海外，待烏頭白老江濆。","遙看逆浪愁翻雪，漸失征帆錯認雲。","欲識九迴腸斷處，潯陽流水逐條分。"]', '["泪霑雙袖血成文，不爲悲身爲別君。","望鹤眼穿期海外，待烏头白老江濆。","遙看逆浪愁翻雪，漸失征帆錯認云。","欲識九迴腸斷处，潯陽流水逐條分。"]', '诗', 'shi', '', NULL, '送致用 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb061d4b-6db3-4bcc-8419-69675988fd83', '早春登龍山靜勝寺時非休澣司空特許是行因贈幕中諸公', '早春登龙山静勝寺时非休澣司空特許是行因贈幕中諸公', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["謝傅知憐景氣新，許尋高寺望江春。","龍文遠水吞平岸，羊角輕風旋細塵。","山茗粉含鷹觜嫩，海榴紅綻錦窼勻。","歸來笑問諸從事，占得閑行有幾人。"]', '["謝傅知怜景氣新，許尋高寺望江春。","龙文远水吞平岸，羊角轻风旋細塵。","山茗粉含鷹觜嫩，海榴紅綻錦窼勻。","归来笑问諸從事，占得闲行有幾人。"]', '诗', 'shi', '', NULL, '早春登龍山靜勝寺時非休澣司空特許是行因贈幕中諸公 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d5d0633-0c57-45ea-8371-936e27e3d34d', '書樂天紙', '书乐天紙', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["金鑾殿裏書殘紙，乞與荆州元判司。","不忍拈將等閑用，半封京信半題詩。"]', '["金鑾殿裏书殘紙，乞與荆州元判司。","不忍拈將等闲用，半封京信半題诗。"]', '诗', 'shi', '', NULL, '書樂天紙 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05e914dd-60fb-4791-8e0c-daf41541c420', '酬孝甫見贈十首 一', '酬孝甫见贈十首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["宋玉秋來續楚詞，陰鏗官漫足閑詩。","親情書札相安慰，多道蕭何作判司。"]', '["宋玉秋来續楚词，陰鏗官漫足闲诗。","親情书札相安慰，多道蕭何作判司。"]', '诗', 'shi', '', NULL, '酬孝甫見贈十首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4cfd02-1a4b-49f4-ad95-ca3ee133d8ef', '酬孝甫見贈十首 二', '酬孝甫见贈十首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["杜甫天材頗絕倫，每尋詩卷似情親。","憐渠直道當時語，不著心源傍古人。"]', '["杜甫天材頗絕倫，每尋诗卷似情親。","怜渠直道當时語，不著心源傍古人。"]', '诗', 'shi', '', NULL, '酬孝甫見贈十首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e42d75a4-6cd5-462f-8c18-09b20caa551f', '酬孝甫見贈十首 三', '酬孝甫见贈十首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["十歲荒狂任博徒，挼莎五木擲梟盧。","野詩良輔偏憐假，長借金鞍迓酒胡。"]', '["十歲荒狂任博徒，挼莎五木擲梟盧。","野诗良輔偏怜假，长借金鞍迓酒胡。"]', '诗', 'shi', '', NULL, '酬孝甫見贈十首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a961e6d4-fc6e-46e1-b212-bd73617410ef', '酬孝甫見贈十首 四', '酬孝甫见贈十首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["曾經綽立侍丹墀，綻蘂宮花拂面枝。","雉尾扇開朝日出，柘黃衫對碧霄垂。"]', '["曾經綽立侍丹墀，綻蘂宮花拂面枝。","雉尾扇开朝日出，柘黄衫对碧霄垂。"]', '诗', 'shi', '', NULL, '酬孝甫見贈十首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c8ac34a-303a-4917-90d9-0c49999f58d6', '酬孝甫見贈十首 五', '酬孝甫见贈十首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["一自低心翰墨場，箭靫拋盡負書囊。","近來兼愛休糧藥，柏葉紗羅雜豆黃。"]', '["一自低心翰墨場，箭靫拋尽負书囊。","近来兼愛休糧藥，柏葉紗羅杂豆黄。"]', '诗', 'shi', '', NULL, '酬孝甫見贈十首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89af457a-eed7-4f97-a704-56b86550b3c1', '酬孝甫見贈十首 六', '酬孝甫见贈十首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫笑風塵滿病顏，此生元在有無間。","卷舒蓮葉終難濕，去住雲心一種閑。"]', '["莫笑风塵满病顏，此生元在有無间。","卷舒蓮葉終难濕，去住云心一種闲。"]', '诗', 'shi', '', NULL, '酬孝甫見贈十首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e690110-479a-4ae8-b56a-9236bc55a0a2', '酬孝甫見贈十首 七', '酬孝甫见贈十首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["無事拋棊侵虎口，幾時開眼復聯行。","終須殺盡緣邊敵，四面通同掩大荒。"]', '["無事拋棊侵虎口，幾时开眼复聯行。","終須殺尽緣邊敵，四面通同掩大荒。"]', '诗', 'shi', '', NULL, '酬孝甫見贈十首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e855a15e-c329-4680-9618-cbb64093f207', '酬孝甫見贈十首 八', '酬孝甫见贈十首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["原憲甘貧每自開，子春傷足少人哀。","巷南唯有陳居士，時學文殊一問來。"]', '["原憲甘貧每自开，子春傷足少人哀。","巷南唯有陳居士，时学文殊一问来。"]', '诗', 'shi', '', NULL, '酬孝甫見贈十首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('655caa56-0339-466e-8a64-c1bc18bee630', '酬孝甫見贈十首 九', '酬孝甫见贈十首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["每識閑人如未識，與君相識更相憐。","經旬不解來過宿，忍見空牀夜夜眠。"]', '["每識闲人如未識，與君相識更相怜。","經旬不解来過宿，忍见空牀夜夜眠。"]', '诗', 'shi', '', NULL, '酬孝甫見贈十首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecdaff64-1a61-4095-8f71-99cbb6894f03', '酬孝甫見贈十首 十', '酬孝甫见贈十首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["開坼新詩展大璆，明珠炫轉玉音浮。","酬君十首三更坐，減却常時半夜愁。"]', '["开坼新诗展大璆，明珠炫轉玉音浮。","酬君十首三更坐，減却常时半夜愁。"]', '诗', 'shi', '', NULL, '酬孝甫見贈十首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7866d1fc-c4ad-45aa-937d-8a4e56009551', '和樂天招錢蔚章看山絕句', '和乐天招錢蔚章看山絕句', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["碧落招邀閑曠望，黃金城外玉方壺。","人間還有大江海，萬里煙波天上無。"]', '["碧落招邀闲曠望，黄金城外玉方壺。","人间還有大江海，万里煙波天上無。"]', '诗', 'shi', '', NULL, '和樂天招錢蔚章看山絕句 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('780c74aa-ce85-4c49-9e83-76a4b6474239', '折枝花贈行', '折枝花贈行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["櫻桃花下送君時，一寸春心逐折枝。","別後相思最多處，千株萬片繞林垂。"]', '["櫻桃花下送君时，一寸春心逐折枝。","別後相思最多处，千株万片繞林垂。"]', '诗', 'shi', '', NULL, '折枝花贈行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce2c5fd-3ca4-482c-8233-75c3691accc6', '寄劉頗二首 一', '寄劉頗二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["平生嗜酒顛狂甚，不許諸公占丈夫。","唯愛劉君一片膽，近來還敢似人無。"]', '["平生嗜酒顛狂甚，不許諸公占丈夫。","唯愛劉君一片膽，近来還敢似人無。"]', '诗', 'shi', '', NULL, '寄劉頗二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d9ed58-6e83-464e-bce1-ec76a436d318', '寄劉頗二首 二', '寄劉頗二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["前年碣石煙塵起，共看官軍過洛城。","無限公卿因戰得，與君依舊綠衫行。"]', '["前年碣石煙塵起，共看官軍過洛城。","無限公卿因戰得，與君依旧綠衫行。"]', '诗', 'shi', '', NULL, '寄劉頗二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a2f0b5a-da02-4443-8116-881970a9a120', '晨起送使病不行因過王十一館居二首 一', '晨起送使病不行因過王十一館居二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["自笑今朝誤夙興，逢他御史瘧相仍。","過君未起房門掩，深映寒窗一盞燈。"]', '["自笑今朝誤夙兴，逢他御史瘧相仍。","過君未起房门掩，深映寒窗一盞灯。"]', '诗', 'shi', '', NULL, '晨起送使病不行因過王十一館居二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be42df12-c77c-4588-a356-80696925fd4f', '晨起送使病不行因過王十一館居二首 二', '晨起送使病不行因過王十一館居二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["密宇深房小火爐，飯香魚熟近中廚。","野人愛靜仍耽寢，自問黃昏肯去無。"]', '["密宇深房小火爐，飯香鱼熟近中廚。","野人愛静仍耽寢，自问黄昏肯去無。"]', '诗', 'shi', '', NULL, '晨起送使病不行因過王十一館居二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04f51dd4-f4d1-428f-a9ef-2a8766f08256', '送孫勝', '送孫勝', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["桐花暗澹柳惺愡，池帶輕波柳帶風。","今日與君臨水別，可憐春盡宋亭中。"]', '["桐花暗澹柳惺愡，池带轻波柳带风。","今日與君臨水別，可怜春尽宋亭中。"]', '诗', 'shi', '', NULL, '送孫勝 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5502b4a1-0db6-47ba-a727-3acbf6c276f6', '遊三寺回呈上府主嚴司空時因尋寺道出當陽縣奉命覆視縣囚牽於游行不暇詳究故以詩自誚爾', '游三寺回呈上府主嚴司空时因尋寺道出當陽縣奉命覆視縣囚牽於游行不暇詳究故以诗自誚爾', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["謝公恣縱顛狂掾，觸處閑行許自由。","舉板支頤對山色，當筵吹帽落臺頭。","貪緣稽首他方佛，無暇精心滿縣囚。","莫責尋常吐茵吏，書囊赤白報君侯。"]', '["謝公恣縱顛狂掾，觸处闲行許自由。","舉板支頤对山色，當筵吹帽落台头。","貪緣稽首他方佛，無暇精心满縣囚。","莫責尋常吐茵吏，书囊赤白報君侯。"]', '诗', 'shi', '', NULL, '遊三寺回呈上府主嚴司空時因尋寺道出當陽縣奉命覆視縣囚牽於游行不暇詳究故以詩自誚爾 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76da7844-78b3-4c64-881b-6a24eec3a700', '遠望', '远望', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["滿眼傷心冬景和，一山紅樹寺邊多。","仲宣無限思鄉淚，漳水東流碧玉波。"]', '["满眼傷心冬景和，一山紅樹寺邊多。","仲宣無限思乡泪，漳水东流碧玉波。"]', '诗', 'shi', '', NULL, '遠望 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6897ce9e-24f0-418d-a07c-20e17c14591c', '早春尋李校書', '早春尋李校书', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["款款春風澹澹雲，柳枝低作翠櫳帬。","梅含雞舌兼紅氣，江弄瓊花散綠紋。","帶霧山鶯啼尚小，穿沙蘆筍葉纔分。","今朝何事偏相覓，撩亂芳情最是君。"]', '["款款春风澹澹云，柳枝低作翠櫳帬。","梅含雞舌兼紅氣，江弄瓊花散綠紋。","带霧山鶯啼尚小，穿沙蘆筍葉纔分。","今朝何事偏相覓，撩亂芳情最是君。"]', '诗', 'shi', '', NULL, '早春尋李校書 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a2f6dd-30f5-4709-8155-1533c76a9522', '過襄陽樓呈上府主嚴司空樓在江陵節度使宅北隅', '過襄陽楼呈上府主嚴司空楼在江陵節度使宅北隅', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["襄陽樓下樹陰成，荷葉如錢水面平。","拂水柳花千萬點，隔林鶯舌兩三聲。","有時水畔看雲立，每日樓前信馬行。","早晚暫教王粲上，庾公應待月分明。"]', '["襄陽楼下樹陰成，荷葉如錢水面平。","拂水柳花千万点，隔林鶯舌兩三声。","有时水畔看云立，每日楼前信马行。","早晚暫教王粲上，庾公應待月分明。"]', '诗', 'shi', '', NULL, '過襄陽樓呈上府主嚴司空樓在江陵節度使宅北隅 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a770646-a61f-4d9d-a4db-aa90da365787', '八月六日與僧如展前松滋主簿韋戴同游碧澗寺賦得扉字韻寺臨蜀江內有碧澗穿注兩廊又有龍女洞能興雲雨詩中噴字以平聲韻', '八月六日與僧如展前松滋主簿韋戴同游碧澗寺賦得扉字韻寺臨蜀江內有碧澗穿注兩廊又有龙女洞能兴云雨诗中噴字以平声韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["空闊長江礙鐵圍，高低行樹倚巖扉。","穿廊玉澗噴紅旭，踴墖金輪拆翠微。","草引風輕馴虎睡，洞驅雲入毒龍歸。","他生莫忘靈山別，滿壁人名後會稀。"]', '["空闊长江礙鐵圍，高低行樹倚巖扉。","穿廊玉澗噴紅旭，踴墖金輪拆翠微。","草引风轻馴虎睡，洞驱云入毒龙归。","他生莫忘靈山別，满壁人名後會稀。"]', '诗', 'shi', '', NULL, '八月六日與僧如展前松滋主簿韋戴同游碧澗寺賦得扉字韻寺臨蜀江內有碧澗穿注兩廊又有龍女洞能興雲雨詩中噴字以平聲韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4b26c8c-4996-4cf3-8ea6-a689b3cb53eb', '奉和竇容州', '奉和竇容州', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["明公莫訝容州遠，一路瀟湘景氣濃。","斑竹初成二妃廟，碧蓮遙聳九疑峰。","禁林聞道長傾鳳，池水那能久滯龍。","自歎風波去無極，不知何日又相逢。"]', '["明公莫訝容州远，一路瀟湘景氣濃。","斑竹初成二妃廟，碧蓮遙聳九疑峰。","禁林闻道长傾鳳，池水那能久滯龙。","自歎风波去無極，不知何日又相逢。"]', '诗', 'shi', '', NULL, '奉和竇容州 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44847c0-440e-4262-b8bc-3e0dc78fb775', '盧頭陀詩', '盧头陀诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["盧師深話出家由，剃盡心花始剃頭。","馬哭青山別車匿，鵲飛螺髻見羅睺。","還來舊日經過處，似隔前身夢寐游。","爲向八龍兄弟說，他生緣會此生休。"]', '["盧師深話出家由，剃尽心花始剃头。","马哭青山別车匿，鵲飞螺髻见羅睺。","還来旧日經過处，似隔前身梦寐游。","爲向八龙兄弟说，他生緣會此生休。"]', '诗', 'shi', '', NULL, '盧頭陀詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b9ed22b-117c-4c0e-8fd6-06c4cf4758ba', '醉別盧頭陀', '醉別盧头陀', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["醉迷狂象別吾師，夢覺觀空始自悲。","盡日笙歌人散後，滿江風雨獨醒時。","心超幾地行無處，雲到何天住有期。","頓見佛光身上出，已蒙衣內綴摩尼。"]', '["醉迷狂象別吾師，梦覺观空始自悲。","尽日笙歌人散後，满江风雨独醒时。","心超幾地行無处，云到何天住有期。","頓见佛光身上出，已蒙衣內綴摩尼。"]', '诗', 'shi', '', NULL, '醉別盧頭陀 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66398840-9533-4dfb-bf03-e694729d116d', '陪張湖南宴望岳樓稹爲監察御史張中丞知雜事', '陪張湖南宴望岳楼稹爲監察御史張中丞知杂事', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["觀象樓前奉末班，絳峰只似殿庭間。","今日高樓重陪宴，雨籠衡岳是南山。"]', '["观象楼前奉末班，絳峰只似殿庭间。","今日高楼重陪宴，雨籠衡岳是南山。"]', '诗', 'shi', '', NULL, '陪張湖南宴望岳樓稹爲監察御史張中丞知雜事 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f48c31bd-d6da-4078-84d7-adf90f3faa30', '岳陽樓', '岳陽楼', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["岳陽樓上日銜窗，影到深潭赤玉幢。","悵望殘春萬般意，滿櫺湖水入西江。"]', '["岳陽楼上日銜窗，影到深潭赤玉幢。","悵望殘春万般意，满櫺湖水入西江。"]', '诗', 'shi', '', NULL, '岳陽樓 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcfc31e8-1e68-41b0-abec-a57bd13cd7e7', '寄庾敬休', '寄庾敬休', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["小來同在曲江頭，不省春時不共游。","今日江風好暄煖，可憐春盡古湘州。"]', '["小来同在曲江头，不省春时不共游。","今日江风好暄煖，可怜春尽古湘州。"]', '诗', 'shi', '', NULL, '寄庾敬休 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0107f56-3bd9-4b0b-aa6f-a3f032b924a4', '花栽二首 一', '花栽二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["買得山花一兩栽，離鄉別土易摧隤。","欲知北客居南意，看取南花北地來。"]', '["買得山花一兩栽，離乡別土易摧隤。","欲知北客居南意，看取南花北地来。"]', '诗', 'shi', '', NULL, '花栽二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f400052-1671-4b2f-ac66-9698274a449a', '花栽二首 二', '花栽二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["南花北地種應難，且向船中盡日看。","縱使將來眼前死，猶勝拋擲在空欄。"]', '["南花北地種應难，且向船中尽日看。","縱使將来眼前死，猶勝拋擲在空欄。"]', '诗', 'shi', '', NULL, '花栽二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99df8155-2ebe-4971-96a2-27e762843ff4', '宿石磯', '宿石磯', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["石磯江水夜潺湲，半夜江風引杜鵑。","燈暗酒醒顛倒枕，五更斜月入空船。"]', '["石磯江水夜潺湲，半夜江风引杜鵑。","灯暗酒醒顛倒枕，五更斜月入空船。"]', '诗', 'shi', '', NULL, '宿石磯 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d28bcf11-8e69-47a8-8848-8a0606eeff9a', '遭風二十韻', '遭风二十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["洞庭瀰漫接天廻，一點君山似措杯。","暝色已籠秋竹樹，夕陽猶帶舊樓臺。","湘南賈伴乘風信，夏口篙工厄泝洄。","後侶逢灘方拽𥮘，前宗到浦已眠桅。","俄驚四面雲屏合，坐見千峰雪浪堆。","罔象睢盱頻逞怪，石尤翻動忽成災。","勝凌豈但河宮溢，坱軋渾憂地軸摧。","疑是陰兵致昏黑，果聞靈鼓借喧豗。","龍歸窟穴深潭漩，蜃作波濤古岸隤。","水客暗遊燒野火，楓人夜長吼春雷。","浸淫沙市兒童亂，汩沒汀洲雁鶩哀。","自歎生涯看轉燭，更悲商旅哭沈財。","檣烏斗折頭倉掉，水狗斜傾尾纜開。","在昔詎慙橫海志，此時甘乏濟川才。","歷陽舊事曾爲鼈，鮌穴相傳有化能。","閉目唯愁滿空電，冥心真類不然灰。","那知否極休徵至，漸覺宵分曙氣催。","怪族潛收湖黯湛，幽妖盡走日崔嵬。","紫衣將校臨船問，白馬君侯傍柳來。","喚上驛亭還酩酊，兩行紅袖拂樽罍。"]', '["洞庭瀰漫接天廻，一点君山似措杯。","暝色已籠秋竹樹，夕陽猶带旧楼台。","湘南賈伴乘风信，夏口篙工厄泝洄。","後侶逢灘方拽𥮘，前宗到浦已眠桅。","俄驚四面云屏合，坐见千峰雪浪堆。","罔象睢盱頻逞怪，石尤翻动忽成災。","勝凌豈但河宮溢，坱軋渾憂地軸摧。","疑是陰兵致昏黑，果闻靈鼓借喧豗。","龙归窟穴深潭漩，蜃作波濤古岸隤。","水客暗游燒野火，楓人夜长吼春雷。","浸淫沙市兒童亂，汩沒汀洲雁鶩哀。","自歎生涯看轉燭，更悲商旅哭沈財。","檣烏斗折头倉掉，水狗斜傾尾纜开。","在昔詎慙橫海志，此时甘乏濟川才。","歷陽旧事曾爲鼈，鮌穴相傳有化能。","閉目唯愁满空電，冥心真類不然灰。","那知否極休徵至，漸覺宵分曙氣催。","怪族潛收湖黯湛，幽妖尽走日崔嵬。","紫衣將校臨船问，白马君侯傍柳来。","喚上驛亭還酩酊，兩行紅袖拂樽罍。"]', '诗', 'shi', '', NULL, '遭風二十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3ce89d-d4ee-46f3-965a-c71c09f6be18', '贈崔元儒', '贈崔元儒', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["殷勤夏口阮元瑜，二十年前舊飲徒。","最愛輕欺杏園客，也曾辜負酒家胡。","些些風景閑猶在，事事顛狂老漸無。","今日頭盤三兩擲，翠娥潛笑白髭鬚。"]', '["殷勤夏口阮元瑜，二十年前旧饮徒。","最愛轻欺杏园客，也曾辜負酒家胡。","些些风景闲猶在，事事顛狂老漸無。","今日头盤三兩擲，翠娥潛笑白髭鬚。"]', '诗', 'shi', '', NULL, '贈崔元儒 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a301563-c053-427b-b3f0-a374bacd8568', '鄂州寓館嚴澗宅', '鄂州寓館嚴澗宅', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鳳有高梧鶴有松，偶來江外寄行踪。","花枝滿院空啼鳥，塵榻無人憶臥龍。","心想夜閑唯足夢，眼看春盡不相逢。","何時最是思君處，月入斜窗曉寺鐘。"]', '["鳳有高梧鹤有松，偶来江外寄行踪。","花枝满院空啼鸟，塵榻無人憶臥龙。","心想夜闲唯足梦，眼看春尽不相逢。","何时最是思君处，月入斜窗晓寺鐘。"]', '诗', 'shi', '', NULL, '鄂州寓館嚴澗宅 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('618d8ca7-54f4-4be9-aa45-81a110966efb', '送杜元穎', '送杜元穎', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["江上五年同送客，與君長羨北歸人。","今朝又送君先去，千里洛陽城裏塵。"]', '["江上五年同送客，與君长羨北归人。","今朝又送君先去，千里洛陽城裏塵。"]', '诗', 'shi', '', NULL, '送杜元穎 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18891019-da60-4001-9f72-f2e0170954f1', '貽蜀五首 病馬詩寄上李尚書', '貽蜀五首 病马诗寄上李尚书', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["萬里長鳴望蜀門，病身猶帶舊瘡痕。","遙看雲路心空在，久服鹽車力漸煩。","尚有高懸雙鏡眼，何由竝駕兩朱轓。","唯應夜識深山道，忽遇君侯一報恩。"]', '["万里长鳴望蜀门，病身猶带旧瘡痕。","遙看云路心空在，久服鹽车力漸煩。","尚有高懸雙镜眼，何由竝駕兩朱轓。","唯應夜識深山道，忽遇君侯一報恩。"]', '诗', 'shi', '', NULL, '貽蜀五首 病馬詩寄上李尚書 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1290f2c0-886d-4d57-b4fb-695ddc211a3c', '貽蜀五首 李中丞表臣', '貽蜀五首 李中丞表臣', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["韋門同是舊親賓，獨恨潘牀簟有塵。","十里花谿錦城麗，五年沙尾白頭新。","倅戎何事勞專席，老掾甘心逐衆人。","却待文星上天去，少分光影照沈淪。"]', '["韋门同是旧親賓，独恨潘牀簟有塵。","十里花谿錦城丽，五年沙尾白头新。","倅戎何事勞專席，老掾甘心逐衆人。","却待文星上天去，少分光影照沈淪。"]', '诗', 'shi', '', NULL, '貽蜀五首 李中丞表臣 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a98565-5963-495b-9a8c-f50163242486', '貽蜀五首 盧評事子蒙', '貽蜀五首 盧評事子蒙', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["爲我殷勤盧子蒙，近來無復昔時同。","懶成積疹推難動，禪盡狂心鍊到空。","老愛早眠虛夜月，病妨杯酒負春風。","唯公兩弟閑相訪，往往潸然一望公。"]', '["爲我殷勤盧子蒙，近来無复昔时同。","懶成積疹推难动，禪尽狂心鍊到空。","老愛早眠虛夜月，病妨杯酒負春风。","唯公兩弟闲相訪，往往潸然一望公。"]', '诗', 'shi', '', NULL, '貽蜀五首 盧評事子蒙 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d254d6fe-12b2-4ddf-9f2d-972c788081ac', '貽蜀五首 張校書元夫', '貽蜀五首 張校书元夫', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["未面西川張校書，書來稠疊頗相於。","我聞聲價金應敵，衆道風姿玉不如。","遠處從人須謹慎，少年爲事要舒徐。","勸君便是酬君愛，莫比尋常贈鯉魚。"]', '["未面西川張校书，书来稠叠頗相於。","我闻声價金應敵，衆道风姿玉不如。","远处從人須謹慎，少年爲事要舒徐。","勸君便是酬君愛，莫比尋常贈鯉鱼。"]', '诗', 'shi', '', NULL, '貽蜀五首 張校書元夫 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('139fb7e9-3caa-4b0f-98f1-210861bffdfb', '貽蜀五首 韋兵曹臧文', '貽蜀五首 韋兵曹臧文', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["處處侯門可曳裙，人人爭事蜀尚書。","摩天氣直山曾拔，澈底心清水共虛。","鵬翼已翻君好去，烏頭未變我何如。","殷勤爲話深相感，不學馮諼待食魚。"]', '["处处侯门可曳裙，人人爭事蜀尚书。","摩天氣直山曾拔，澈底心清水共虛。","鵬翼已翻君好去，烏头未变我何如。","殷勤爲話深相感，不学馮諼待食鱼。"]', '诗', 'shi', '', NULL, '貽蜀五首 韋兵曹臧文 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a1c0b87-3c7f-410b-9e32-e018ec2cc25d', '贈嚴童子', '贈嚴童子', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["衛瓘諸孫衛玠珍，可憐雛鳳好青春。","解拈玉葉排新句，認得金環識舊身。","十歲佩觿嬌稚子，八行飛札老成人。","楊公莫訝清無業，家有驪珠不復貧。"]', '["衛瓘諸孫衛玠珍，可怜雛鳳好青春。","解拈玉葉排新句，認得金环識旧身。","十歲佩觿嬌稚子，八行飞札老成人。","楊公莫訝清無業，家有驪珠不复貧。"]', '诗', 'shi', '', NULL, '贈嚴童子 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0765b10a-b9e0-4194-87c8-8e399e1899e7', '桐孫詩', '桐孫诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["去日桐花半桐葉，別來桐樹老桐孫。","城中過盡無窮事，白髮滿頭歸故園。"]', '["去日桐花半桐葉，別来桐樹老桐孫。","城中過尽無窮事，白髮满头归故园。"]', '诗', 'shi', '', NULL, '桐孫詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc9ca99-a48d-4336-98e1-46c17d2c03b3', '西歸絕句十二首 一', '西归絕句十二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雙堠頻頻減去程，漸知身得近京城。","春來愛有歸鄉夢，一半猶疑夢裏行。"]', '["雙堠頻頻減去程，漸知身得近京城。","春来愛有归乡梦，一半猶疑梦裏行。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac663770-d191-439c-bb7f-9317e53f98c9', '西歸絕句十二首 二', '西归絕句十二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["五年江上損容顏，今日春風到武關。","兩紙京書臨水讀，小桃花樹滿商山。"]', '["五年江上損容顏，今日春风到武关。","兩紙京书臨水读，小桃花樹满商山。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb77b34-d37d-414e-b698-8078d9a66b84', '西歸絕句十二首 三', '西归絕句十二首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["同歸諫院韋丞相，共貶河南亞大夫。","今日還鄉獨憔悴，幾人憐見白髭鬚。"]', '["同归諫院韋丞相，共貶河南亞大夫。","今日還乡独憔悴，幾人怜见白髭鬚。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37358051-b1c7-4bac-ac27-7fe8da8fd095', '西歸絕句十二首 四', '西归絕句十二首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["只去長安六日期，多應及得杏花時。","春明門外誰相待，不夢閑人夢酒巵。"]', '["只去长安六日期，多應及得杏花时。","春明门外誰相待，不梦闲人梦酒巵。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6964340-3839-4970-bb5b-de894b310524', '西歸絕句十二首 五', '西归絕句十二首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["白頭歸舍意如何，賀處無窮弔亦多。","左降去時裴相宅，舊來車馬幾人過。"]', '["白头归舍意如何，賀处無窮弔亦多。","左降去时裴相宅，旧来车马幾人過。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b761aec-8aff-48d7-82c6-f5cd02bcd345', '西歸絕句十二首 六', '西归絕句十二首 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["還鄉何用淚沾襟，一半雲霄一半沈。","世事漸多饒悵望，舊曾行處便傷心。"]', '["還乡何用泪沾襟，一半云霄一半沈。","世事漸多饒悵望，旧曾行处便傷心。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aebbcbe-9897-4b8b-bc8d-e817a9196cd7', '西歸絕句十二首 七', '西归絕句十二首 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["閑遊寺觀從容到，遍問親知次第尋。","腸斷裴家光德宅，無人掃地戟門深。"]', '["闲游寺观從容到，遍问親知次第尋。","腸斷裴家光德宅，無人掃地戟门深。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d349709-b78c-47d2-8213-ea0e71863878', '西歸絕句十二首 八', '西归絕句十二首 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["一世營營死是休，生前無事定無由。","不知山下東流水，何事長須日夜流。"]', '["一世營營死是休，生前無事定無由。","不知山下东流水，何事长須日夜流。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6817d04-378a-446f-b00d-bafaee9f06ef', '西歸絕句十二首 九', '西归絕句十二首 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["今朝西渡丹河水，心寄丹河無限愁。","若到莊前竹園下，殷勤爲遶故山流。"]', '["今朝西渡丹河水，心寄丹河無限愁。","若到莊前竹园下，殷勤爲遶故山流。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e3bbc34-4415-43fe-b07c-c2fb4f920d41', '西歸絕句十二首 十', '西归絕句十二首 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["寒窗風雪擁深爐，彼此相傷指白鬚。","一夜思量十年事，幾人強健幾人無。"]', '["寒窗风雪擁深爐，彼此相傷指白鬚。","一夜思量十年事，幾人強健幾人無。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('646e2ebb-bcca-4dd6-91ee-a67afce84122', '西歸絕句十二首 十一', '西归絕句十二首 十一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雲覆藍橋雪滿溪，須臾便與碧峰齊。","風回麵市連天合，凍壓花枝著水低。"]', '["云覆藍橋雪满溪，須臾便與碧峰齊。","风回麵市連天合，凍壓花枝著水低。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 十一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b105e766-89f1-47ac-b213-bd1c52a67499', '西歸絕句十二首 十二', '西归絕句十二首 十二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["寒花帶雪滿山腰，著柳冰珠滿碧條。","天色漸明回一望，玉塵隨馬度藍橋。"]', '["寒花带雪满山腰，著柳冰珠满碧條。","天色漸明回一望，玉塵隨马度藍橋。"]', '诗', 'shi', '', NULL, '西歸絕句十二首 十二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad007ffd-f419-4839-baf6-0a8f2108fb1f', '留呈夢得子厚致用', '留呈梦得子厚致用', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["泉溜才通疑夜磬，燒煙餘暖有春泥。","千層玉帳鋪松蓋，五出銀區印虎蹄。","暗落金烏山漸黑，深埋粉堠路渾迷。","心知魏闕無多地，十二瓊樓百里西。"]', '["泉溜才通疑夜磬，燒煙餘暖有春泥。","千層玉帳鋪松蓋，五出銀區印虎蹄。","暗落金烏山漸黑，深埋粉堠路渾迷。","心知魏闕無多地，十二瓊楼百里西。"]', '诗', 'shi', '', NULL, '留呈夢得子厚致用 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502fe27d-2c80-4e35-9f75-51d5e587059e', '小碎', '小碎', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["小碎詩篇取次書，等閑題柱意何如。","諸郎到處應相問，留取三行代鯉魚。"]', '["小碎诗篇取次书，等闲題柱意何如。","諸郎到处應相问，留取三行代鯉鱼。"]', '诗', 'shi', '', NULL, '小碎 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('515b1986-7fb3-41e4-ad83-a5db9cbd1ce0', '和樂天高相宅', '和乐天高相宅', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫愁已去無窮事，漫苦如今有限身。","二百年來城裏宅，一家知換幾多人。"]', '["莫愁已去無窮事，漫苦如今有限身。","二百年来城裏宅，一家知換幾多人。"]', '诗', 'shi', '', NULL, '和樂天高相宅 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b50413c4-6976-4b43-bf5e-fa1a9b8b2af7', '和樂天仇家酒', '和乐天仇家酒', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["病嗟酒戶年年減，老覺塵機漸漸深。","飲罷醒餘更惆悵，不如閒事不經心。"]', '["病嗟酒戶年年減，老覺塵機漸漸深。","饮罷醒餘更惆悵，不如閒事不經心。"]', '诗', 'shi', '', NULL, '和樂天仇家酒 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ddb49c-86d0-43b2-ad43-f56e2d1b3f83', '和樂天贈雲寂僧', '和乐天贈云寂僧', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["欲離煩惱三千界，不在禪門八萬條。","心火自生還自滅，雲師無路與君銷。"]', '["欲離煩惱三千界，不在禪门八万條。","心火自生還自滅，云師無路與君銷。"]', '诗', 'shi', '', NULL, '和樂天贈雲寂僧 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51b29661-bad2-4158-bfed-a346f386224e', '灃西別樂天博載樊宗憲李景信兩秀才姪谷三月三十日相餞送', '灃西別乐天博載樊宗憲李景信兩秀才姪谷三月三十日相餞送', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["今朝相送自同遊，酒語詩情替別愁。","忽到灃西總回去，一身騎馬向通州。"]', '["今朝相送自同游，酒語诗情替別愁。","忽到灃西總回去，一身騎马向通州。"]', '诗', 'shi', '', NULL, '灃西別樂天博載樊宗憲李景信兩秀才姪谷三月三十日相餞送 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7209d60e-019c-41c2-b070-8c5a2aac9b3d', '寄曇嵩寂三上人', '寄曇嵩寂三上人', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["長學對治思苦處，偏將死苦教人間。","今因爲說無生死，無可對治心更閑。"]', '["长学对治思苦处，偏將死苦教人间。","今因爲说無生死，無可对治心更闲。"]', '诗', 'shi', '', NULL, '寄曇嵩寂三上人 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc5993dd-fd40-43af-8a0a-df2ba4a95baa', '題漫天嶺智藏師蘭若僧云住此二十八年', '題漫天嶺智藏師蘭若僧云住此二十八年', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["僧臨大道閱浮生，來往憧憧利與名。","二十八年何限客，不曾閑見一人行。"]', '["僧臨大道閱浮生，来往憧憧利與名。","二十八年何限客，不曾闲见一人行。"]', '诗', 'shi', '', NULL, '題漫天嶺智藏師蘭若僧云住此二十八年 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb82a619-3e41-47f8-979a-a4c7dcdd6ecc', '蒼溪縣寄揚州兄弟', '蒼溪縣寄揚州兄弟', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蒼溪縣下嘉陵水，入峽穿江到海流。","憑仗鯉魚將遠信，雁回時節到揚州。"]', '["蒼溪縣下嘉陵水，入峽穿江到海流。","憑仗鯉鱼將远信，雁回时節到揚州。"]', '诗', 'shi', '', NULL, '蒼溪縣寄揚州兄弟 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4c141f1-3842-4897-9cba-d374f4184a64', '贈吳渠州從姨兄士則', '贈吳渠州從姨兄士則', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶昔分襟童子郎，白頭拋擲又他鄉。","三千里外巴南恨，二十年前城裏狂。","甯氏舅甥俱寂寞，荀家兄弟半淪亡。","淚因生別兼懷舊，廻首江山欲萬行。"]', '["憶昔分襟童子郎，白头拋擲又他乡。","三千里外巴南恨，二十年前城裏狂。","甯氏舅甥俱寂寞，荀家兄弟半淪亡。","泪因生別兼懷旧，廻首江山欲万行。"]', '诗', 'shi', '', NULL, '贈吳渠州從姨兄士則 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e7382a5-4b76-4fd5-a057-5efff2e4769b', '長灘夢李紳', '长灘梦李紳', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["孤吟獨寢意千般，合眼逢君一夜歡。","慙愧夢魂無遠近，不辭風雨到長灘。"]', '["孤吟独寢意千般，合眼逢君一夜歡。","慙愧梦魂無远近，不辞风雨到长灘。"]', '诗', 'shi', '', NULL, '長灘夢李紳 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08ba2d6a-f60b-4a0d-bc4e-37cf030ce96f', '新政縣', '新政縣', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["新政縣前逢月夜，嘉陵江底看星辰。","已聞城上三更鼓，不見心中一箇人。","鬚鬢暗添巴路雪，衣裳無復帝鄉塵。","曾沾幾許名兼利，勞動生涯涉苦辛。"]', '["新政縣前逢月夜，嘉陵江底看星辰。","已闻城上三更鼓，不见心中一箇人。","鬚鬢暗添巴路雪，衣裳無复帝乡塵。","曾沾幾許名兼利，勞动生涯涉苦辛。"]', '诗', 'shi', '', NULL, '新政縣 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bcce198-75e6-4d7e-b0a3-e0f63da01585', '南昌灘', '南昌灘', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["渠江明淨峽逶迤，船到明灘拽𥮘遲。","櫓窡動搖妨作夢，巴童指點笑吟詩。","畬餘宿麥黃山腹，日背殘花白水湄。","物色可憐心莫恨，此行都是獨行時。"]', '["渠江明淨峽逶迤，船到明灘拽𥮘遲。","櫓窡动搖妨作梦，巴童指点笑吟诗。","畬餘宿麦黄山腹，日背殘花白水湄。","物色可怜心莫恨，此行都是独行时。"]', '诗', 'shi', '', NULL, '南昌灘 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a2bc8b9-7f81-42cb-ab91-f577ab6b9521', '見樂天詩', '见乐天诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["通州到日日平西，江館無人虎印泥。","忽向破簷殘漏處，見君詩在柱心題。"]', '["通州到日日平西，江館無人虎印泥。","忽向破簷殘漏处，见君诗在柱心題。"]', '诗', 'shi', '', NULL, '見樂天詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43e7d760-bd9f-4268-aecb-0fd3ff32cd5a', '夜坐', '夜坐', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雨滯更愁南瘴毒，月明兼喜北風涼。","古城樓影橫空館，濕地蟲聲遶暗廊。","螢火亂飛秋已近，星辰早沒夜初長。","孩提萬里何時見，狼籍家書滿臥牀。"]', '["雨滯更愁南瘴毒，月明兼喜北风涼。","古城楼影橫空館，濕地蟲声遶暗廊。","螢火亂飞秋已近，星辰早沒夜初长。","孩提万里何时见，狼籍家书满臥牀。"]', '诗', 'shi', '', NULL, '夜坐 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9aaced5-982b-499f-9ef0-f78eb2141d1d', '聞樂天授江州司馬', '闻乐天授江州司马', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["殘燈無焰影幢幢，此夕聞君謫九江。","垂死病中驚坐起，暗風吹雨入寒窗。"]', '["殘灯無焰影幢幢，此夕闻君謫九江。","垂死病中驚坐起，暗风吹雨入寒窗。"]', '诗', 'shi', '', NULL, '聞樂天授江州司馬 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('085c00d9-01d2-4cc2-9bb3-2e8f4a478516', '歲日贈拒非', '歲日贈拒非', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["君思曲水嗟身老，我望通州感道窮。","同入新年兩行淚，白頭翁坐說城中。"]', '["君思曲水嗟身老，我望通州感道窮。","同入新年兩行泪，白头翁坐说城中。"]', '诗', 'shi', '', NULL, '歲日贈拒非 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad6e82d6-6b30-4193-8329-c407719a1cbb', '送盧戡', '送盧戡', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["紅樹蟬聲滿夕陽，白頭相送倍相傷。","老嗟去日光陰促，病覺今年晝夜長。","顧我親情皆遠道，念君兄弟欲他鄉。","紅旗滿眼襄州路，此別淚流千萬行。"]', '["紅樹蟬声满夕陽，白头相送倍相傷。","老嗟去日光陰促，病覺今年晝夜长。","顧我親情皆远道，念君兄弟欲他乡。","紅旗满眼襄州路，此別泪流千万行。"]', '诗', 'shi', '', NULL, '送盧戡 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df23d825-4db8-4bd9-88dd-9f47cbe46e89', '雨聲', '雨声', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["風吹竹葉休還動，雨點荷心暗復明。","曾向西江船上宿，慣聞寒夜滴篷聲。"]', '["风吹竹葉休還动，雨点荷心暗复明。","曾向西江船上宿，慣闻寒夜滴篷声。"]', '诗', 'shi', '', NULL, '雨聲 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2618397e-f65f-4680-9751-f0f1e2ce2533', '奉和滎陽公離筵作', '奉和滎陽公離筵作', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["南郡生徒辭絳帳，東山妓樂擁油旌。","鈞天排比簫韶待，猶顧人間有別情。"]', '["南郡生徒辞絳帳，东山妓乐擁油旌。","鈞天排比簫韶待，猶顧人间有別情。"]', '诗', 'shi', '', NULL, '奉和滎陽公離筵作 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14132406-bb4c-4479-8863-d2504d6073e9', '嘉陵水', '嘉陵水', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["古時應是山頭水，自古流來江路深。","若使江流會人意，也應知我遠來心。"]', '["古时應是山头水，自古流来江路深。","若使江流會人意，也應知我远来心。"]', '诗', 'shi', '', NULL, '嘉陵水 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('060f08fe-2bb0-4435-b83d-61930063de12', '閬州開元寺壁題樂天詩', '閬州开元寺壁題乐天诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶君無計寫君詩，寫盡千行說向誰。","題在閬州東寺壁，幾時知是見君時。"]', '["憶君無計寫君诗，寫尽千行说向誰。","題在閬州东寺壁，幾时知是见君时。"]', '诗', 'shi', '', NULL, '閬州開元寺壁題樂天詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee493a91-1009-4b75-a338-e0e16dc7e866', '憑李忠州寄書樂天', '憑李忠州寄书乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["萬里寄書將出峽，却憑巫峽寄江州。","傷心最是江頭月，莫把書將上庾樓。"]', '["万里寄书將出峽，却憑巫峽寄江州。","傷心最是江头月，莫把书將上庾楼。"]', '诗', 'shi', '', NULL, '憑李忠州寄書樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27388ed8-54ae-4da2-b390-b6db716d623e', '得樂天書', '得乐天书', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["遠信入門先有淚，妻驚女哭問何如。","尋常不省曾如此，應是江州司馬書。"]', '["远信入门先有泪，妻驚女哭问何如。","尋常不省曾如此，應是江州司马书。"]', '诗', 'shi', '', NULL, '得樂天書 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d44b19d-fe73-4bac-bac7-2d9ce37bae1e', '寄樂天', '寄乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["無身尚擬魂相就，身在那無夢往還。","直到他生亦相覓，不能空記樹中環。"]', '["無身尚擬魂相就，身在那無梦往還。","直到他生亦相覓，不能空記樹中环。"]', '诗', 'shi', '', NULL, '寄樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c72f22-c622-42dd-a194-6ad48342dc72', '酬知退', '酬知退', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["終須修到無修處，聞盡聲聞始不聞。","莫著妄心銷彼我，我心無我亦無君。"]', '["終須修到無修处，闻尽声闻始不闻。","莫著妄心銷彼我，我心無我亦無君。"]', '诗', 'shi', '', NULL, '酬知退 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1715338-0fb2-4757-b961-44c30d377493', '通州', '通州', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["平生欲得山中住，天與通州遶郡山。","睡到日西無一事，月儲三萬買教閑。"]', '["平生欲得山中住，天與通州遶郡山。","睡到日西無一事，月儲三万買教闲。"]', '诗', 'shi', '', NULL, '通州 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bd2b921-b675-4367-9e6f-04f083579fd5', '酬樂天書後三韻', '酬乐天书後三韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["今日廬峰霞遶寺，昔時鸞殿鳳廻書。","兩封相去八年後，一種俱云五夜初。","漸覺此生都是夢，不能將淚滴雙魚。"]', '["今日廬峰霞遶寺，昔时鸾殿鳳廻书。","兩封相去八年後，一種俱云五夜初。","漸覺此生都是梦，不能將泪滴雙鱼。"]', '诗', 'shi', '', NULL, '酬樂天書後三韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ca87ea3-72e3-4281-ae8c-4a7af85562eb', '相憶淚', '相憶泪', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["西江流水到江州，聞道分成九道流。","我滴兩行相憶淚，遣君何處遣人求。","除非入海無由住，縱使逢灘未擬休。","會向伍員潮上見，氣充頑石報心讎。"]', '["西江流水到江州，闻道分成九道流。","我滴兩行相憶泪，遣君何处遣人求。","除非入海無由住，縱使逢灘未擬休。","會向伍員潮上见，氣充頑石報心讎。"]', '诗', 'shi', '', NULL, '相憶淚 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9101cedd-dfbb-4b59-b3fd-69b95c6591cc', '喜李十一景信到', '喜李十一景信到', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何事相逢翻有淚，念君緣我到通州。","留君剩住君須住，我不自由君自由。"]', '["何事相逢翻有泪，念君緣我到通州。","留君剩住君須住，我不自由君自由。"]', '诗', 'shi', '', NULL, '喜李十一景信到 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18937f00-bf1f-485e-a5da-2d719a6b9ab4', '與李十一夜飲', '與李十一夜饮', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["寒夜燈前賴酒壺，與君相對興猶孤。","忠州刺史應閑臥，江水猿聲睡得無。"]', '["寒夜灯前賴酒壺，與君相对兴猶孤。","忠州刺史應闲臥，江水猿声睡得無。"]', '诗', 'shi', '', NULL, '與李十一夜飲 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82ad28f-e540-4280-8cd5-fe7ffe82b28c', '贈李十一', '贈李十一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["淮水連年起戰塵，油旌三換一何頻。","共君前後俱從事，羞見功名與別人。"]', '["淮水連年起戰塵，油旌三換一何頻。","共君前後俱從事，羞见功名與別人。"]', '诗', 'shi', '', NULL, '贈李十一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa9621ac-9410-4629-b4ef-4c66150c4aeb', '寒食日', '寒食日', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["今年寒食好風流，此日一家同出游。","碧水青山無限思，莫將心道是涪州。"]', '["今年寒食好风流，此日一家同出游。","碧水青山無限思，莫將心道是涪州。"]', '诗', 'shi', '', NULL, '寒食日 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f2db908-c927-4d2d-a841-4bb340f0119c', '三兄以白角巾寄遺髮不勝冠因有感歎', '三兄以白角巾寄遺髮不勝冠因有感歎', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["病瘴年深渾禿盡，那能勝置角頭巾。","暗梳蓬髮羞臨鏡，私戴蓮花恥見人。","白髮過於冠色白，銀釘少校頷中銀。","我身四十猶如此，何況吾兄六十身。"]', '["病瘴年深渾禿尽，那能勝置角头巾。","暗梳蓬髮羞臨镜，私戴蓮花恥见人。","白髮過於冠色白，銀釘少校頷中銀。","我身四十猶如此，何況吾兄六十身。"]', '诗', 'shi', '', NULL, '三兄以白角巾寄遺髮不勝冠因有感歎 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6d7ce58-acbe-4b70-a82b-1a4dee278b24', '別李十一五絕 一', '別李十一五絕 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["巴南分與親情別，不料與君牀竝頭。","爲我遠來休悵望，折君災難是通州。"]', '["巴南分與親情別，不料與君牀竝头。","爲我远来休悵望，折君災难是通州。"]', '诗', 'shi', '', NULL, '別李十一五絕 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58a279dd-a328-4a09-a58d-5089c640546c', '別李十一五絕 二', '別李十一五絕 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["京城每與閑人別，猶自傷心與白頭。","今日別君心更苦，別君緣是在通州。"]', '["京城每與闲人別，猶自傷心與白头。","今日別君心更苦，別君緣是在通州。"]', '诗', 'shi', '', NULL, '別李十一五絕 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d31706-816f-43ef-b537-3ebbaef4c1ca', '別李十一五絕 三', '別李十一五絕 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["萬里尚能來遠道，一程那忍便分頭。","鳥籠猿檻君應會，十步向前非我州。"]', '["万里尚能来远道，一程那忍便分头。","鸟籠猿檻君應會，十步向前非我州。"]', '诗', 'shi', '', NULL, '別李十一五絕 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc87baf9-31fe-4235-a00a-e88d155a2007', '別李十一五絕 四', '別李十一五絕 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["來時見我江南岸，今日送君江上頭。","別後料添新夢寐，虎驚蛇伏是通州。"]', '["来时见我江南岸，今日送君江上头。","別後料添新梦寐，虎驚蛇伏是通州。"]', '诗', 'shi', '', NULL, '別李十一五絕 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2ac5796-0feb-43a9-911a-7ca66f608d9d', '別李十一五絕 五', '別李十一五絕 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["聞君欲去潛銷骨，一夜暗添新白頭。","明朝別後應腸斷，獨櫂破船歸到州。"]', '["闻君欲去潛銷骨，一夜暗添新白头。","明朝別後應腸斷，独櫂破船归到州。"]', '诗', 'shi', '', NULL, '別李十一五絕 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fe0c25a-d6bb-4325-97fc-0344e2b1bb86', '酬樂天醉別', '酬乐天醉別', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["前回一去五年別，此別又知何日回。","好住樂天休悵望，匹如元不到京來。"]', '["前回一去五年別，此別又知何日回。","好住乐天休悵望，匹如元不到京来。"]', '诗', 'shi', '', NULL, '酬樂天醉別 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b341faad-2bb5-466f-83d5-e5719cb39b67', '酬樂天雨後見憶', '酬乐天雨後见憶', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雨滑危梁性命愁，差池一步一生休。","黃泉便是通州郡，漸入深泥漸到州。"]', '["雨滑危梁性命愁，差池一步一生休。","黄泉便是通州郡，漸入深泥漸到州。"]', '诗', 'shi', '', NULL, '酬樂天雨後見憶 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea31989-5102-4438-b6af-a792c98f1531', '和樂天過祕閣書省舊廳', '和乐天過祕閣书省旧廳', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["聞君西省重徘徊，祕閣書房次第開。","壁記欲題三漏合，吏人驚問十年來。","經排蠹簡憐初校，芸長陳根識舊栽。","司馬見詩心最苦，滿身蚊蚋哭煙埃。"]', '["闻君西省重徘徊，祕閣书房次第开。","壁記欲題三漏合，吏人驚问十年来。","經排蠹簡怜初校，芸长陳根識旧栽。","司马见诗心最苦，满身蚊蚋哭煙埃。"]', '诗', 'shi', '', NULL, '和樂天過祕閣書省舊廳 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67b27a0d-fa9f-4ff6-85b0-29bbde94d15d', '和樂天贈楊祕書', '和乐天贈楊祕书', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["舊與楊郎在帝城，搜天斡地覓詩情。","曾因竝句甘稱小，不爲論年便喚兄。","刮骨直穿由苦鬬，夢腸翻出暫閑行。","因君投贈還相和，老去那能競底名。"]', '["旧與楊郎在帝城，搜天斡地覓诗情。","曾因竝句甘稱小，不爲論年便喚兄。","刮骨直穿由苦鬬，梦腸翻出暫闲行。","因君投贈還相和，老去那能競底名。"]', '诗', 'shi', '', NULL, '和樂天贈楊祕書 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f08f1763-5066-4130-8e59-ababbee17d32', '和樂天題王家亭子', '和乐天題王家亭子', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["風吹筍籜飄紅砌，雨打桐花蓋綠莎。","都大資人無暇日，泛池全少買池多。"]', '["风吹筍籜飄紅砌，雨打桐花蓋綠莎。","都大資人無暇日，泛池全少買池多。"]', '诗', 'shi', '', NULL, '和樂天題王家亭子 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('405029da-b7b6-4bc6-a42c-1d774799d41a', '酬樂天頻夢微之', '酬乐天頻梦微之', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["山水萬重書斷絕，念君憐我夢相聞。","我今因病魂顛倒，唯夢閑人不夢君。"]', '["山水万重书斷絕，念君怜我梦相闻。","我今因病魂顛倒，唯梦闲人不梦君。"]', '诗', 'shi', '', NULL, '酬樂天頻夢微之 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4e67c9-700f-4880-9d1e-596ba3860446', '琵琶', '琵琶', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["學語胡兒撼玉玲，甘州破裏最星星。","使君自恨常多事，不得工夫夜夜聽。"]', '["学語胡兒撼玉玲，甘州破裏最星星。","使君自恨常多事，不得工夫夜夜听。"]', '诗', 'shi', '', NULL, '琵琶 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc86bac4-879d-47ae-942f-e680876f6a3b', '春詞', '春词', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["山翠湖光似欲流，蜂聲鳥思却堪愁。","西施顏色今何在，但看春風百草頭。"]', '["山翠湖光似欲流，蜂声鸟思却堪愁。","西施顏色今何在，但看春风百草头。"]', '诗', 'shi', '', NULL, '春詞 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c60ca2a-09d7-4c8d-8aac-564211636c2a', '酬樂天春寄微之', '酬乐天春寄微之', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鸚心明黠雀幽蒙，何事相將盡入籠。","君避海鯨驚浪裏，我隨巴蟒瘴煙中。","千山塞路音書絕，兩地知春曆日同。","一樹梅花數升酒，醉尋江岸哭東風。"]', '["鸚心明黠雀幽蒙，何事相將尽入籠。","君避海鯨驚浪裏，我隨巴蟒瘴煙中。","千山塞路音书絕，兩地知春曆日同。","一樹梅花數升酒，醉尋江岸哭东风。"]', '诗', 'shi', '', NULL, '酬樂天春寄微之 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7735b268-73d5-4da5-aa07-7a9b2f74f58c', '酬樂天舟泊夜讀微之詩', '酬乐天舟泊夜读微之诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["知君暗泊西江岸，讀我閑詩欲到明。","今夜通州還不睡，滿山風雨杜鵑聲。"]', '["知君暗泊西江岸，读我闲诗欲到明。","今夜通州還不睡，满山风雨杜鵑声。"]', '诗', 'shi', '', NULL, '酬樂天舟泊夜讀微之詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cd822e2-77bd-4aff-814c-76e32d58ec94', '酬樂天武關南見微之題山石榴花詩', '酬乐天武关南见微之題山石榴花诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["比因酬贈爲花時，不爲君行不復知。","又更幾年還共到，滿牆塵土兩篇詩。"]', '["比因酬贈爲花时，不爲君行不复知。","又更幾年還共到，满牆塵土兩篇诗。"]', '诗', 'shi', '', NULL, '酬樂天武關南見微之題山石榴花詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('467af7d6-7c0c-4982-9908-5f5caa9612db', '酬樂天見寄', '酬乐天见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["三千里外巴虵穴，四十年來司馬官。","瘴色滿身治不盡，瘡痕刮骨洗應難。","常甘人向衰容薄，獨訝君將舊眼看。","前日詩中高蓋字，至今脣舌遍長安。"]', '["三千里外巴虵穴，四十年来司马官。","瘴色满身治不尽，瘡痕刮骨洗應难。","常甘人向衰容薄，独訝君將旧眼看。","前日诗中高蓋字，至今脣舌遍长安。"]', '诗', 'shi', '', NULL, '酬樂天見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf1b76a-8334-48a3-9aed-928dc56ac5ba', '酬樂天得稹所寄紵絲布白輕庸製成衣服以詩報之', '酬乐天得稹所寄紵絲布白轻庸製成衣服以诗報之', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["湓城萬里隔巴庸，紵薄綈輕共一封。","腰帶定知今瘦小，衣衫難作遠裁縫。","唯愁書到炎涼變，忽見詩來意緒濃。","春草綠茸雲色白，想君騎馬好儀容。"]', '["湓城万里隔巴庸，紵薄綈轻共一封。","腰带定知今瘦小，衣衫难作远裁縫。","唯愁书到炎涼变，忽见诗来意緒濃。","春草綠茸云色白，想君騎马好儀容。"]', '诗', 'shi', '', NULL, '酬樂天得稹所寄紵絲布白輕庸製成衣服以詩報之 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1bdea57-346d-498b-b799-20916336a3b9', '和樂天尋郭道士不遇', '和乐天尋郭道士不遇', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔年我見杯中渡，今日人言鶴上逢。","兩虎定隨千歲鹿，雙林添作幾株松。","方瞳應是新燒藥，短脚知緣舊施舂。","欲請僧繇遠相畫，苦愁頻變本形容。"]', '["昔年我见杯中渡，今日人言鹤上逢。","兩虎定隨千歲鹿，雙林添作幾株松。","方瞳應是新燒藥，短脚知緣旧施舂。","欲請僧繇远相畫，苦愁頻变本形容。"]', '诗', 'shi', '', NULL, '和樂天尋郭道士不遇 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4576e2-e9bc-4709-9817-5bf233398ec1', '酬樂天寄生衣', '酬乐天寄生衣', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["秋茅處處流痎瘧，夜鳥聲聲哭瘴雲。","羸骨不勝纖細物，欲將文服却還君。"]', '["秋茅处处流痎瘧，夜鸟声声哭瘴云。","羸骨不勝纖細物，欲將文服却還君。"]', '诗', 'shi', '', NULL, '酬樂天寄生衣 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e02909-ddc5-4308-9349-7e1613594a4f', '酬樂天得微之詩知通州事因成四首 一', '酬乐天得微之诗知通州事因成四首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["茅簷屋舍竹籬州，虎怕偏蹄虵兩頭。","暗蠱有時迷酒影，浮塵向日似波流。","沙含水弩多傷骨，田仰畬刀少用牛。","知得共君相見否，近來魂夢轉悠悠。"]', '["茅簷屋舍竹籬州，虎怕偏蹄虵兩头。","暗蠱有时迷酒影，浮塵向日似波流。","沙含水弩多傷骨，田仰畬刀少用牛。","知得共君相见否，近来魂梦轉悠悠。"]', '诗', 'shi', '', NULL, '酬樂天得微之詩知通州事因成四首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dedc7b24-9ac7-44a4-8ee2-3fa3eb8157bd', '酬樂天得微之詩知通州事因成四首 二', '酬乐天得微之诗知通州事因成四首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["平地才應一頃餘，閣欄都大似巢居。","入衙官吏聲疑鳥，下峽舟船腹似魚。","市井無錢論尺丈，田疇付火罷耘鋤。","此中愁殺須甘分，惟惜平生舊著書。"]', '["平地才應一頃餘，閣欄都大似巢居。","入衙官吏声疑鸟，下峽舟船腹似鱼。","市井無錢論尺丈，田疇付火罷耘鋤。","此中愁殺須甘分，惟惜平生旧著书。"]', '诗', 'shi', '', NULL, '酬樂天得微之詩知通州事因成四首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('881cb6a0-9019-490b-b763-91e6d1582d4e', '酬樂天得微之詩知通州事因成四首 三', '酬乐天得微之诗知通州事因成四首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["哭鳥晝飛人少見，倀魂夜嘯虎行多。","滿身沙虱無防處，獨脚山魈不奈何。","甘受鬼神侵骨髓，常憂岐路處風波。","南歌未有東西分，敢唱滄浪一字歌。"]', '["哭鸟晝飞人少见，倀魂夜嘯虎行多。","满身沙虱無防处，独脚山魈不奈何。","甘受鬼神侵骨髓，常憂岐路处风波。","南歌未有东西分，敢唱滄浪一字歌。"]', '诗', 'shi', '', NULL, '酬樂天得微之詩知通州事因成四首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6af7eb8e-7528-4646-a437-d88bceb36b7d', '酬樂天得微之詩知通州事因成四首 四', '酬乐天得微之诗知通州事因成四首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["荒蕪滿院不能鋤，甑有塵埃圃乏蔬。","定覺身將囚一種，未知生共死何如。","飢搖困尾喪家狗，熱暴枯鱗失水魚。","苦境萬般君莫問，自憐方寸本來虛。"]', '["荒蕪满院不能鋤，甑有塵埃圃乏蔬。","定覺身將囚一種，未知生共死何如。","飢搖困尾喪家狗，熱暴枯鱗失水鱼。","苦境万般君莫问，自怜方寸本来虛。"]', '诗', 'shi', '', NULL, '酬樂天得微之詩知通州事因成四首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99660a0e-febc-47da-9d17-6713424fa287', '酬樂天聞李尚書拜相以詩見賀', '酬乐天闻李尚书拜相以诗见賀', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["初因彈劾死東川，又爲親情弄化權百口共經三峽水，一時重上兩漫天。","尚書入用雖旬月，司馬銜冤已十年。","若待更遭秋瘴後，便愁平地有重泉。"]', '["初因彈劾死东川，又爲親情弄化權百口共經三峽水，一时重上兩漫天。","尚书入用雖旬月，司马銜冤已十年。","若待更遭秋瘴後，便愁平地有重泉。"]', '诗', 'shi', '', NULL, '酬樂天聞李尚書拜相以詩見賀 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a26eb899-f846-4194-8c47-964305503dca', '酬樂天歎窮愁見寄', '酬乐天歎窮愁见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["病煎愁緒轉紛紛，百里何由說向君。","老去心情隨日減，遠來書信隔年聞。","三冬有電連春雨，九月無霜盡火雲。","併與巴南終歲熱，四時誰道各平分。"]', '["病煎愁緒轉紛紛，百里何由说向君。","老去心情隨日減，远来书信隔年闻。","三冬有電連春雨，九月無霜尽火云。","併與巴南終歲熱，四时誰道各平分。"]', '诗', 'shi', '', NULL, '酬樂天歎窮愁見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15cf8bec-a050-4001-89a1-4bc9ef1f19ff', '酬樂天三月三日見寄', '酬乐天三月三日见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["當年此日花前醉，今日花前病裏銷。","獨倚破簾閑悵望，可憐虛度好春朝。"]', '["當年此日花前醉，今日花前病裏銷。","独倚破簾闲悵望，可怜虛度好春朝。"]', '诗', 'shi', '', NULL, '酬樂天三月三日見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7693bdaf-285f-4156-b251-4e4ee36cb9df', '酬樂天歎損傷見寄', '酬乐天歎損傷见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["前途何在轉茫茫，漸老那能不自傷。","病爲怕風多睡月，起因花藥暫扶牀。","函關氣索迷真侶，峽水波翻礙故鄉。","唯有秋來兩行淚，對君新贈遠詩章。"]', '["前途何在轉茫茫，漸老那能不自傷。","病爲怕风多睡月，起因花藥暫扶牀。","函关氣索迷真侶，峽水波翻礙故乡。","唯有秋来兩行泪，对君新贈远诗章。"]', '诗', 'shi', '', NULL, '酬樂天歎損傷見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea561390-5c93-4cac-a95e-dcd37f78924b', '瘴塞', '瘴塞', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["瘴塞巴山哭鳥悲，紅妝少婦斂啼眉。","殷勤奉藥來相勸，云是前年欲病時。"]', '["瘴塞巴山哭鸟悲，紅妝少婦斂啼眉。","殷勤奉藥来相勸，云是前年欲病时。"]', '诗', 'shi', '', NULL, '瘴塞 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3865968-bc9b-4a42-8191-ff3987321fe6', '紅荆', '紅荆', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["庭中栽得紅荆樹，十月花開不待春。","直到孩提盡驚怪，一家同是北來人。"]', '["庭中栽得紅荆樹，十月花开不待春。","直到孩提尽驚怪，一家同是北来人。"]', '诗', 'shi', '', NULL, '紅荆 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3baebc1-a02d-4dbd-bcab-7aef6e5517d8', '黃草峽聽柔之琴二首 一', '黄草峽听柔之琴二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["胡笳夜奏塞聲寒，是我鄉音聽漸難。","料得小來辛苦學，又因知向峽中彈。"]', '["胡笳夜奏塞声寒，是我乡音听漸难。","料得小来辛苦学，又因知向峽中彈。"]', '诗', 'shi', '', NULL, '黃草峽聽柔之琴二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14a622f1-e6a2-45eb-b917-a273c33487e7', '黃草峽聽柔之琴二首 二', '黄草峽听柔之琴二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["別鶴淒清覺露寒，離聲漸咽命雛難。","憐君伴我涪州宿，猶有心情徹夜彈。"]', '["別鹤淒清覺露寒，離声漸咽命雛难。","怜君伴我涪州宿，猶有心情徹夜彈。"]', '诗', 'shi', '', NULL, '黃草峽聽柔之琴二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eb36125-dfd3-4a34-94ff-3551e27cf68d', '書劒', '书劒', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["渝工劒刃皆歐冶，巴吏書蹤盡子雲。","唯我心知有來處，泊船黃草夜思君。"]', '["渝工劒刃皆歐冶，巴吏书蹤尽子云。","唯我心知有来处，泊船黄草夜思君。"]', '诗', 'shi', '', NULL, '書劒 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3123c4e8-25a5-44db-ba9b-b3f65386e571', '內狀詩寄楊白二員外', '內狀诗寄楊白二員外', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["天門暗闢玉琤鍧，晝送中樞曉禁清。","彤管內人書細膩，金匳御印篆分明。","衝街不避將軍令，跋勅兼題宰相名。","南省郎官誰待詔，與君將向世間行。"]', '["天门暗闢玉琤鍧，晝送中樞晓禁清。","彤管內人书細膩，金匳御印篆分明。","衝街不避將軍令，跋勅兼題宰相名。","南省郎官誰待詔，與君將向世间行。"]', '诗', 'shi', '', NULL, '內狀詩寄楊白二員外 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbbd4c1d-576d-417c-a1c9-6595d7a8b55d', '別毅郎 一', '別毅郎 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["爾爺只爲一杯酒，此別那知死與生。","兒有何辜才七歲，亦教兒作瘴江行。"]', '["爾爺只爲一杯酒，此別那知死與生。","兒有何辜才七歲，亦教兒作瘴江行。"]', '诗', 'shi', '', NULL, '別毅郎 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83826df1-8aff-4051-afed-89741cdcff29', '別毅郎 二', '別毅郎 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["愛惜爾爺唯有我，我今顦顇望何人。","傷心自比籠中鶴，翦盡翅翎愁到身。"]', '["愛惜爾爺唯有我，我今顦顇望何人。","傷心自比籠中鹤，翦尽翅翎愁到身。"]', '诗', 'shi', '', NULL, '別毅郎 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1f4b9b9-bb8f-4ed9-8564-6a86f8e0161c', '自責', '自責', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["犀帶金魚束紫袍，不能將命報分毫。","他時得見牛常侍，爲爾君前捧佩刀。"]', '["犀带金鱼束紫袍，不能將命報分毫。","他时得见牛常侍，爲爾君前捧佩刀。"]', '诗', 'shi', '', NULL, '自責 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2958e20-77ac-42a3-bf43-f9bfaf967288', '送公度之福建', '送公度之福建', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["棠陰猶在建溪磯，此去那論是與非。","若見白頭須盡敬，恐曾江岸識胡威。"]', '["棠陰猶在建溪磯，此去那論是與非。","若见白头須尽敬，恐曾江岸識胡威。"]', '诗', 'shi', '', NULL, '送公度之福建 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('433b2b4d-1490-455c-b242-f751078e05ca', '喜五兄自泗州至', '喜五兄自泗州至', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["眼中三十年來淚，一望南雲一度垂。","慚愧臨淮李常侍，遠教形影暫相隨。"]', '["眼中三十年来泪，一望南云一度垂。","慚愧臨淮李常侍，远教形影暫相隨。"]', '诗', 'shi', '', NULL, '喜五兄自泗州至 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0844874f-28de-4901-bb53-811ef142d677', '杏花', '杏花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["常年出入右銀臺，每怪春光例早回。","慚愧杏園行在景，同州園裏也先開。"]', '["常年出入右銀台，每怪春光例早回。","慚愧杏园行在景，同州园裏也先开。"]', '诗', 'shi', '', NULL, '杏花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d8021d-9fbd-476f-8f61-3b5f3bb85ada', '第三歲日詠春風憑楊員外寄長安柳', '第三歲日詠春风憑楊員外寄长安柳', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["三日春風已有情，拂人頭面稍憐輕。","殷勤爲報長安柳，莫惜枝條動軟聲。"]', '["三日春风已有情，拂人头面稍怜轻。","殷勤爲報长安柳，莫惜枝條动軟声。"]', '诗', 'shi', '', NULL, '第三歲日詠春風憑楊員外寄長安柳 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43b2cd4a-de59-4d02-9d34-a10657efef2c', '贈別楊員外巨源', '贈別楊員外巨源', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶昔西河縣下時，青山顦顇宦名卑。","揄揚陶令緣求酒，結託蕭娘只在詩。","朱紫衣裳浮世重，蒼黃歲序長年悲。","白頭後會知何日，一盞煩君不用辭。"]', '["憶昔西河縣下时，青山顦顇宦名卑。","揄揚陶令緣求酒，結託蕭娘只在诗。","朱紫衣裳浮世重，蒼黄歲序长年悲。","白头後會知何日，一盞煩君不用辞。"]', '诗', 'shi', '', NULL, '贈別楊員外巨源 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a55cf688-bed6-4a89-a271-7dda6ac16d7b', '寄樂天二首 一', '寄乐天二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["榮辱升沈影與身，世情誰是舊雷陳。","唯應鮑叔猶憐我，自保曾參不殺人。","山入白樓沙苑暮，潮生滄海野塘春。","老逢佳景唯惆悵，兩地各傷何限神。"]', '["榮辱升沈影與身，世情誰是旧雷陳。","唯應鲍叔猶怜我，自保曾參不殺人。","山入白楼沙苑暮，潮生滄海野塘春。","老逢佳景唯惆悵，兩地各傷何限神。"]', '诗', 'shi', '', NULL, '寄樂天二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29623661-eb54-4ac9-a23d-b969b860010e', '寄樂天二首 二', '寄乐天二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["論才賦命不相干，鳳有文章雉有冠。","羸骨欲銷猶被刻，瘡痕未沒又遭彈。","劒頭已折藏須蓋，丁字雖剛屈莫難。","休學州前羅剎石，一生身敵海波瀾。"]', '["論才賦命不相干，鳳有文章雉有冠。","羸骨欲銷猶被刻，瘡痕未沒又遭彈。","劒头已折藏須蓋，丁字雖剛屈莫难。","休学州前羅剎石，一生身敵海波瀾。"]', '诗', 'shi', '', NULL, '寄樂天二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b8bb2d-b3b2-4ef6-9433-357c981114db', '聽妻彈別鶴操', '听妻彈別鹤操', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["別鶴聲聲怨夜弦，聞君此奏欲潸然。","商瞿五十知無子，更付琴書與仲宣。"]', '["別鹤声声怨夜弦，闻君此奏欲潸然。","商瞿五十知無子，更付琴书與仲宣。"]', '诗', 'shi', '', NULL, '聽妻彈別鶴操 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64831176-2482-4e3a-b941-3540ad74f810', '和王侍郎酬廣宣上人觀放牓後相賀', '和王侍郎酬廣宣上人观放牓後相賀', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["渥洼徒自有權奇，伯樂書名世始知。","競走牆前希得儁，高縣日下表無私。","都中紙貴流傳後，海外金填姓字時。","珍重劉繇因首薦，爲君送和碧雲詩。"]', '["渥洼徒自有權奇，伯乐书名世始知。","競走牆前希得儁，高縣日下表無私。","都中紙貴流傳後，海外金填姓字时。","珍重劉繇因首薦，爲君送和碧云诗。"]', '诗', 'shi', '', NULL, '和王侍郎酬廣宣上人觀放牓後相賀 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a92c882-6091-4204-a665-276ea1007541', '酬樂天喜鄰郡', '酬乐天喜鄰郡', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蹇驢瘦馬塵中伴，紫綬朱衣夢裏身。","符竹偶因成對岸，文章虛被配爲鄰。","湖翻白浪常看雪，火照紅妝不待春。","老大那能更爭競，任君投募醉鄉人。"]', '["蹇驢瘦马塵中伴，紫綬朱衣梦裏身。","符竹偶因成对岸，文章虛被配爲鄰。","湖翻白浪常看雪，火照紅妝不待春。","老大那能更爭競，任君投募醉乡人。"]', '诗', 'shi', '', NULL, '酬樂天喜鄰郡 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24c527df-26c7-4fee-b2b9-3215bf6bc43a', '再酬復言和前篇', '再酬复言和前篇', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["經過二郡逢賢牧，聚集諸郎宴老身。","清夜漫勞紅燭會，白頭非是翠娥鄰。","曾攜酒伴無端宿，自入朝行便別春。","潦倒微之從不占，未知公議道何人。"]', '["經過二郡逢賢牧，聚集諸郎宴老身。","清夜漫勞紅燭會，白头非是翠娥鄰。","曾携酒伴無端宿，自入朝行便別春。","潦倒微之從不占，未知公議道何人。"]', '诗', 'shi', '', NULL, '再酬復言和前篇 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f87a45a-6c36-41ed-a223-60fcf71df72e', '贈樂天', '贈乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫言鄰境易經過，彼此分符欲奈何。","垂老相逢漸難別，白頭期限各無多。"]', '["莫言鄰境易經過，彼此分符欲奈何。","垂老相逢漸难別，白头期限各無多。"]', '诗', 'shi', '', NULL, '贈樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a5f32f-9e1b-47d7-811c-f94b24e270a6', '重贈', '重贈', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["休遣玲瓏唱我詩，我詩多是別君詞。","明朝又向江頭別，月落潮平是去時。"]', '["休遣玲瓏唱我诗，我诗多是別君词。","明朝又向江头別，月落潮平是去时。"]', '诗', 'shi', '', NULL, '重贈 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('138e0d16-ee85-4d75-9ae1-156bc57f1a58', '別後西陵晚眺', '別後西陵晚眺', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["晚日未拋詩筆硯，夕陽空望郡樓臺。","與君後會知何日，不似潮頭暮却廻。"]', '["晚日未拋诗笔硯，夕陽空望郡楼台。","與君後會知何日，不似潮头暮却廻。"]', '诗', 'shi', '', NULL, '別後西陵晚眺 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f051ef36-ede4-4af3-b167-699a70b268ed', '以州宅夸於樂天', '以州宅夸於乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["州城迥遶拂雲堆，鏡水稽山滿眼來。","四面常時對屏障，一家終日在樓臺。","星河似向簷前落，鼓角驚從地底廻。","我是玉皇香案吏，謫居猶得住蓬萊。"]', '["州城迥遶拂云堆，镜水稽山满眼来。","四面常时对屏障，一家終日在楼台。","星河似向簷前落，鼓角驚從地底廻。","我是玉皇香案吏，謫居猶得住蓬萊。"]', '诗', 'shi', '', NULL, '以州宅夸於樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5d517fe-003f-4e06-9653-f1500f97b9c0', '重夸州宅旦暮景色兼酬前篇末句', '重夸州宅旦暮景色兼酬前篇末句', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["仙都難畫亦難書，暫合登臨不合居。","繞郭煙嵐新雨後，滿山樓閣上燈初。","人聲曉動千門闢，湖色宵涵萬象虛。","爲問西州羅剎岸，濤頭衝突近何如。"]', '["仙都难畫亦难书，暫合登臨不合居。","繞郭煙嵐新雨後，满山楼閣上灯初。","人声晓动千门闢，湖色宵涵万象虛。","爲问西州羅剎岸，濤头衝突近何如。"]', '诗', 'shi', '', NULL, '重夸州宅旦暮景色兼酬前篇末句 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c850801-7809-4363-80a7-2b7012e5c2df', '酬樂天吟張員外詩見寄因思上京每與樂天於居敬兄升平里詠張新詩', '酬乐天吟張員外诗见寄因思上京每與乐天於居敬兄升平里詠張新诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["樂天書內重封到，居敬堂前共讀時。","四友一爲泉路客，三人兩詠浙江詩。","別無遠近皆難見，老減心情自各知。","杯酒與他年少隔，不相酬贈欲何之。"]', '["乐天书內重封到，居敬堂前共读时。","四友一爲泉路客，三人兩詠浙江诗。","別無远近皆难见，老減心情自各知。","杯酒與他年少隔，不相酬贈欲何之。"]', '诗', 'shi', '', NULL, '酬樂天吟張員外詩見寄因思上京每與樂天於居敬兄升平里詠張新詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c4faba-d4e1-4b89-b912-e4fc60977c6b', '寄樂天', '寄乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["閑夜思君坐到明，追尋往事倍傷情。","同登科後心相合，初得官時髭未生。","二十年來諳世路，三千里外老江城。","猶應更有前途在，知向人間何處行。"]', '["闲夜思君坐到明，追尋往事倍傷情。","同登科後心相合，初得官时髭未生。","二十年来諳世路，三千里外老江城。","猶應更有前途在，知向人间何处行。"]', '诗', 'shi', '', NULL, '寄樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f354c1eb-9dbb-4c39-9c65-478cba9cbd35', '戲贈樂天復言', '戲贈乐天复言', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["樂事難逢歲易徂，白頭光景莫令孤。","弄濤船更曾觀否，望市樓還有會無。","眼力少將尋案牘，心情且強擲梟盧。","孫園虎寺隨宜看，不必遙遙羨鏡湖。"]', '["乐事难逢歲易徂，白头光景莫令孤。","弄濤船更曾观否，望市楼還有會無。","眼力少將尋案牘，心情且強擲梟盧。","孫园虎寺隨宜看，不必遙遙羨镜湖。"]', '诗', 'shi', '', NULL, '戲贈樂天復言 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('914a23fb-d48f-4c97-8d39-8ea9170b2374', '重酬樂天', '重酬乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["紅塵擾擾日西徂，我興雲心兩共孤。","暫出已遭千騎擁，故交求見一人無。","百篇書判從饒白，八米詩章未伏盧。","最笑近來黃叔度，自投名刺占陂湖。"]', '["紅塵擾擾日西徂，我兴云心兩共孤。","暫出已遭千騎擁，故交求见一人無。","百篇书判從饒白，八米诗章未伏盧。","最笑近来黄叔度，自投名刺占陂湖。"]', '诗', 'shi', '', NULL, '重酬樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93e29bd7-032b-45e6-bcf4-3392ea55a58d', '再酬復言', '再酬复言', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["繞郭笙歌夜景徂，稽山迥帶月輪孤。","休文欲詠心應破，道子雖來畫得無。","顧我小才同培塿，知君險鬬敵都盧。","不然豈有姑蘇郡，擬著陂塘比鏡湖。"]', '["繞郭笙歌夜景徂，稽山迥带月輪孤。","休文欲詠心應破，道子雖来畫得無。","顧我小才同培塿，知君險鬬敵都盧。","不然豈有姑蘇郡，擬著陂塘比镜湖。"]', '诗', 'shi', '', NULL, '再酬復言 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397f644b-719f-4800-9e18-88f4106fe711', '郡務稍簡因得整比舊詩幷連綴焚削封章委篋僅逾百軸偶成自歎因寄樂天', '郡務稍簡因得整比旧诗幷連綴焚削封章委篋僅逾百軸偶成自歎因寄乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["近來章奏小年詩，一種成空盡可悲。","書得眼昏朱似碧，用來心破髮如絲。","催身易老緣多事，報主深恩在幾時。","天遣兩家無嗣子，欲將文集與它誰。"]', '["近来章奏小年诗，一種成空尽可悲。","书得眼昏朱似碧，用来心破髮如絲。","催身易老緣多事，報主深恩在幾时。","天遣兩家無嗣子，欲將文集與它誰。"]', '诗', 'shi', '', NULL, '郡務稍簡因得整比舊詩幷連綴焚削封章委篋僅逾百軸偶成自歎因寄樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7d60fa-dba6-420f-be59-4173a745e571', '酬樂天餘思不盡加爲六韻之作', '酬乐天餘思不尽加爲六韻之作', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["律呂同聲我爾身，文章君是一伶倫。","衆推賈誼爲才子，帝喜相如作侍臣。","次韻千言曾報荅，直詞三道共經綸。","元詩駮雜真難辨，白樸流傳用轉新。","蔡女圖書雖在口，于公門戶豈生塵。","商瞿未老猶希冀，莫把籝金便付人。"]', '["律呂同声我爾身，文章君是一伶倫。","衆推賈誼爲才子，帝喜相如作侍臣。","次韻千言曾報荅，直词三道共經綸。","元诗駮杂真难辨，白樸流傳用轉新。","蔡女圖书雖在口，于公门戶豈生塵。","商瞿未老猶希冀，莫把籝金便付人。"]', '诗', 'shi', '', NULL, '酬樂天餘思不盡加爲六韻之作 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4663cd7-5c90-4af8-9fc7-e1af158dffa8', '寄樂天', '寄乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫嗟虛老海壖西，天下風光數會稽。","靈氾橋前百里鏡，石帆山崦五雲溪。","冰銷田地蘆錐短，春入枝條柳眼低。","安得故人生羽翼，飛來相伴醉如泥。"]', '["莫嗟虛老海壖西，天下风光數會稽。","靈氾橋前百里镜，石帆山崦五云溪。","冰銷田地蘆錐短，春入枝條柳眼低。","安得故人生羽翼，飞来相伴醉如泥。"]', '诗', 'shi', '', NULL, '寄樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('207b2dcf-2f03-4fe2-8a1d-47e4f41f9325', '酬樂天雪中見寄', '酬乐天雪中见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["知君夜聽風蕭索，曉望林亭雪半糊。","撼落不教封柳眼，埽來偏盡附梅株。","敲扶密竹枝猶亞，煦暖寒禽氣漸蘇。","坐覺湖聲迷遠浪，回驚雲路在長途。","錢塘湖上蘋先合，梳洗樓前粉暗鋪。","石立玉童披鶴氅，臺施瑤席換龍鬚。","滿空飛舞應爲瑞，寡和高歌只自娛。","莫遣擁簾傷思婦，且將盈尺慰農夫。","稱觴彼此情何異，對景東西事有殊。","鏡水遶山山盡白，琉璃雲母世間無。"]', '["知君夜听风蕭索，晓望林亭雪半糊。","撼落不教封柳眼，埽来偏尽附梅株。","敲扶密竹枝猶亞，煦暖寒禽氣漸蘇。","坐覺湖声迷远浪，回驚云路在长途。","錢塘湖上蘋先合，梳洗楼前粉暗鋪。","石立玉童披鹤氅，台施瑤席換龙鬚。","满空飞舞應爲瑞，寡和高歌只自娛。","莫遣擁簾傷思婦，且將盈尺慰農夫。","稱觴彼此情何異，对景东西事有殊。","镜水遶山山尽白，琉璃云母世间無。"]', '诗', 'shi', '', NULL, '酬樂天雪中見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('342875c5-a2ee-41a4-a8a7-46b5c228a8c4', '和樂天早春見寄', '和乐天早春见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雨香雲澹覺微和，誰送春聲入櫂歌。","萱近北堂穿土早，柳偏東面受風多。","湖添水色消殘雪，江送潮頭湧漫波。","同受新年不同賞，無由縮地欲如何。"]', '["雨香云澹覺微和，誰送春声入櫂歌。","萱近北堂穿土早，柳偏东面受风多。","湖添水色消殘雪，江送潮头湧漫波。","同受新年不同賞，無由縮地欲如何。"]', '诗', 'shi', '', NULL, '和樂天早春見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3955fe87-c138-42aa-95f3-018520621eb6', '酬復言長慶四年元日郡齋感懷見寄', '酬复言长慶四年元日郡斋感懷见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["臘盡殘銷春又歸，逢新別故欲沾衣。","自驚身上添年紀，休繫心中小是非。","富貴祝來何所遂，聰明鞭得轉無機。","羞看稚子先拈酒，悵望平生舊採薇。","去日漸加餘日少，賀人雖鬧故人稀。","椒花麗句閑重檢，艾髮衰容惜寸輝。","苦思正旦酬白雪，閑觀風色動青旂。","千官仗下爐煙裏，東海西頭意獨違。"]', '["臘尽殘銷春又归，逢新別故欲沾衣。","自驚身上添年紀，休繫心中小是非。","富貴祝来何所遂，聰明鞭得轉無機。","羞看稚子先拈酒，悵望平生旧採薇。","去日漸加餘日少，賀人雖鬧故人稀。","椒花丽句闲重檢，艾髮衰容惜寸輝。","苦思正旦酬白雪，闲观风色动青旂。","千官仗下爐煙裏，东海西头意独違。"]', '诗', 'shi', '', NULL, '酬復言長慶四年元日郡齋感懷見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15bd12b8-915d-4bdd-acec-477448457968', '代郡齋神荅樂天', '代郡斋神荅乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["虛白堂神傳好語，二年長伴獨吟時。","夜憐星月多離燭，日滉波濤一下帷。","爲報何人償酒債，引看牆上使君詩。"]', '["虛白堂神傳好語，二年长伴独吟时。","夜怜星月多離燭，日滉波濤一下帷。","爲報何人償酒債，引看牆上使君诗。"]', '诗', 'shi', '', NULL, '代郡齋神荅樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1809840-a969-4554-9220-76cc32b786ee', '酬樂天重寄別', '酬乐天重寄別', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["却報君侯聽苦辭，老頭拋我欲何之。","武牢關外雖分手，不似如今衰白時。"]', '["却報君侯听苦辞，老头拋我欲何之。","武牢关外雖分手，不似如今衰白时。"]', '诗', 'shi', '', NULL, '酬樂天重寄別 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98f20cf9-073d-4149-b69f-9b71ee348944', '和樂天重題別東樓', '和乐天重題別东楼', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["山容水態使君知，樓上從容萬狀移。","日映文章霞細麗，風驅鱗甲浪參差。","鼓催潮戶凌晨擊，笛賽婆官徹夜吹。","喚客潛揮遠紅袖，賣壚高掛小青旗。","賸鋪牀席春眠處，乍捲簾帷月上時。","光景無因將得去，爲郎抄在和郎詩。"]', '["山容水態使君知，楼上從容万狀移。","日映文章霞細丽，风驱鱗甲浪參差。","鼓催潮戶凌晨擊，笛賽婆官徹夜吹。","喚客潛揮远紅袖，賣壚高掛小青旗。","賸鋪牀席春眠处，乍捲簾帷月上时。","光景無因將得去，爲郎抄在和郎诗。"]', '诗', 'shi', '', NULL, '和樂天重題別東樓 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48540e70-9d79-4ea9-9970-518b84ce4d63', '餘杭周從事以十章見寄詞調清婉難於遍酬聊和詩首篇以荅來貺', '餘杭周從事以十章见寄词調清婉难於遍酬聊和诗首篇以荅来貺', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["擾擾紛紛旦暮間，經營閑事不曾閑。","多緣老病推辭酒，少有功夫久羨山。","清夜笙歌喧四郭，黃昏鐘漏下重關。","何由得似周從事，醉入人家醒始還。"]', '["擾擾紛紛旦暮间，經營闲事不曾闲。","多緣老病推辞酒，少有功夫久羨山。","清夜笙歌喧四郭，黄昏鐘漏下重关。","何由得似周從事，醉入人家醒始還。"]', '诗', 'shi', '', NULL, '餘杭周從事以十章見寄詞調清婉難於遍酬聊和詩首篇以荅來貺 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c46fc5d-743c-4b72-b064-d0c6219f4e0f', '寄浙西李大夫四首 一', '寄浙西李大夫四首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["柳眼梅心漸欲春，白頭西望憶何人。","金陵太守曾相伴，共蹋銀臺一路塵。"]', '["柳眼梅心漸欲春，白头西望憶何人。","金陵太守曾相伴，共蹋銀台一路塵。"]', '诗', 'shi', '', NULL, '寄浙西李大夫四首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba915b96-e7a5-4465-ba13-f6b76ac87751', '寄浙西李大夫四首 二', '寄浙西李大夫四首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["蘂珠深處少人知，網索西臨太液池。","浴殿曉聞天語後，步廊騎馬笑相隨。"]', '["蘂珠深处少人知，網索西臨太液池。","浴殿晓闻天語後，步廊騎马笑相隨。"]', '诗', 'shi', '', NULL, '寄浙西李大夫四首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f089f679-1db3-4825-af74-a490c9c81d0f', '寄浙西李大夫四首 三', '寄浙西李大夫四首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["禁林同直話交情，無夜無曾不到明。","最憶西樓人靜夜，玉晨鐘磬兩三聲。"]', '["禁林同直話交情，無夜無曾不到明。","最憶西楼人静夜，玉晨鐘磬兩三声。"]', '诗', 'shi', '', NULL, '寄浙西李大夫四首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8e5d653-7cb2-4121-acbf-7eb016500211', '寄浙西李大夫四首 四', '寄浙西李大夫四首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["由來鵬化便圖南，浙右雖雄我未甘。","早渡西江好歸去，莫拋舟楫滯春潭。"]', '["由来鵬化便圖南，浙右雖雄我未甘。","早渡西江好归去，莫拋舟楫滯春潭。"]', '诗', 'shi', '', NULL, '寄浙西李大夫四首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da8f662d-c8d7-47f2-ba1c-90344883a422', '初除浙東妻有阻色因以四韻曉之', '初除浙东妻有阻色因以四韻晓之', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["嫁時五月歸巴地，今日雙旌上越州。","興慶首行千命婦，會稽旁帶六諸侯。","海樓翡翠閑相逐，鏡水鴛鴦煖共遊。","我有主恩羞未報，君於此外更何求。"]', '["嫁时五月归巴地，今日雙旌上越州。","兴慶首行千命婦，會稽旁带六諸侯。","海楼翡翠闲相逐，镜水鴛鴦煖共游。","我有主恩羞未報，君於此外更何求。"]', '诗', 'shi', '', NULL, '初除浙東妻有阻色因以四韻曉之 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca4f708a-296c-49e6-b2c4-a4e465b6b535', '爲樂天自勘詩集因思頃年城南醉歸馬上遞唱豔曲十餘里不絕長慶初俱以制誥侍宿南郊齋宮夜後偶吟數十篇兩掖諸公洎翰林學士三十餘人驚起就聽逮至卒吏莫不衆觀羣公直至侍從行禮之時不復聚寐予與樂天吟哦竟亦不絕因書於樂天卷後越中冬夜風雨不覺將曉諸門互啓關鎖即事成篇', '爲乐天自勘诗集因思頃年城南醉归马上遞唱豔曲十餘里不絕长慶初俱以制誥侍宿南郊斋宮夜後偶吟數十篇兩掖諸公洎翰林学士三十餘人驚起就听逮至卒吏莫不衆观羣公直至侍從行禮之时不复聚寐予與乐天吟哦竟亦不絕因书於乐天卷後越中冬夜风雨不覺將晓諸门互啓关鎖即事成篇', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春野醉吟十里程，齋宮潛詠萬人驚。","今宵不寐到明讀，風雨曉聞開鎖聲。"]', '["春野醉吟十里程，斋宮潛詠万人驚。","今宵不寐到明读，风雨晓闻开鎖声。"]', '诗', 'shi', '', NULL, '爲樂天自勘詩集因思頃年城南醉歸馬上遞唱豔曲十餘里不絕長慶初俱以制誥侍宿南郊齋宮夜後偶吟數十篇兩掖諸公洎翰林學士三十餘人驚起就聽逮至卒吏莫不衆觀羣公直至侍從行禮之時不復聚寐予與樂天吟哦竟亦不絕因書於樂天卷後越中冬夜風雨不覺將曉諸門互啓關鎖即事成篇 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6919bbf0-1e19-47d1-9247-9ac9b0503af9', '題長慶四年曆日尾', '題长慶四年曆日尾', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["殘曆半張餘十四，灰心雪鬢兩悽然。","定知新歲御樓後，從此不名長慶年。"]', '["殘曆半張餘十四，灰心雪鬢兩悽然。","定知新歲御楼後，從此不名长慶年。"]', '诗', 'shi', '', NULL, '題長慶四年曆日尾 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4908de78-1c45-4507-af50-6c370faca309', '樂府古題序 夢上天', '乐府古題序 梦上天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夢上高高天，高高蒼蒼高不極。","下視五嶽塊纍纍，仰天依舊蒼蒼色。","蹋雲聳身身更上，攀天上天攀未得。","西瞻若水兔輪低，東望蟠桃海波黑。","日月之光不到此，非暗非明煙塞塞。","天悠地遠身跨風，下無階梯上無力。","來時畏有他人上，截斷龍胡斬鵬翼。","茫茫漫漫方自悲，哭向青雲椎素臆。","哭聲厭咽旁人惡，喚起驚悲淚飄露。","千慙萬謝喚厭人，向使無君終不寤。"]', '["梦上高高天，高高蒼蒼高不極。","下視五嶽塊纍纍，仰天依旧蒼蒼色。","蹋云聳身身更上，攀天上天攀未得。","西瞻若水兔輪低，东望蟠桃海波黑。","日月之光不到此，非暗非明煙塞塞。","天悠地远身跨风，下無階梯上無力。","来时畏有他人上，截斷龙胡斬鵬翼。","茫茫漫漫方自悲，哭向青云椎素臆。","哭声厭咽旁人惡，喚起驚悲泪飄露。","千慙万謝喚厭人，向使無君終不寤。"]', '诗', 'shi', '', NULL, '樂府古題序 夢上天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12bfaef5-8d1a-4b71-bc00-cee246d124ce', '樂府古題序 冬白紵', '乐府古題序 冬白紵', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["吳宮夜長宮漏款，簾幕四垂燈燄煖。","西施自舞王自管，雪紵翻翻鶴翎散。","促節牽繁舞腰嬾，舞腰嬾，王罷飲。","蓋覆西施鳳花錦，身作匡牀臂爲枕。","朝珮樅玉王晏寢，寢醒閽報門無事。","子胥死後言爲諱，近王之臣諭王意。","共笑越王窮惴惴，夜夜抱冰寒不睡。"]', '["吳宮夜长宮漏款，簾幕四垂灯燄煖。","西施自舞王自管，雪紵翻翻鹤翎散。","促節牽繁舞腰嬾，舞腰嬾，王罷饮。","蓋覆西施鳳花錦，身作匡牀臂爲枕。","朝珮樅玉王晏寢，寢醒閽報门無事。","子胥死後言爲諱，近王之臣諭王意。","共笑越王窮惴惴，夜夜抱冰寒不睡。"]', '诗', 'shi', '', NULL, '樂府古題序 冬白紵 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a6f605-8339-44ef-9208-af90b6e4e9ec', '樂府古題序 將進酒', '乐府古題序 將進酒', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["將進酒，將進酒。","酒中有毒酖主父，言之主父傷主母。","母爲妾地父妾天，仰天俯地不忍言。","陽爲僵踣主父前，主父不知加妾鞭。","旁人知妾爲主說，主將淚洗鞭頭血。","推椎主母牽下堂，扶妾遣升堂上牀。","將進酒，酒中無毒令主壽。","願主廻恩歸主母，遣妾如此由主父。","妾爲此事人偶知，自慙不密方自悲。","主今顛倒安置妾，貪天僭地誰不爲。"]', '["將進酒，將進酒。","酒中有毒酖主父，言之主父傷主母。","母爲妾地父妾天，仰天俯地不忍言。","陽爲僵踣主父前，主父不知加妾鞭。","旁人知妾爲主说，主將泪洗鞭头血。","推椎主母牽下堂，扶妾遣升堂上牀。","將進酒，酒中無毒令主壽。","願主廻恩归主母，遣妾如此由主父。","妾爲此事人偶知，自慙不密方自悲。","主今顛倒安置妾，貪天僭地誰不爲。"]', '诗', 'shi', '', NULL, '樂府古題序 將進酒 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b23b9487-ac91-4800-9aa7-b1bc09a3344c', '樂府古題序 採珠行', '乐府古題序 採珠行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["海波無底珠沈海，採珠之人判死採。","萬人判死一得珠，斛量買婢人何在。","年年採珠珠避人，今年採珠由海神。","海神採珠珠盡死，死盡明珠空海水。","珠爲海物海屬神，神今自採何況人。"]', '["海波無底珠沈海，採珠之人判死採。","万人判死一得珠，斛量買婢人何在。","年年採珠珠避人，今年採珠由海神。","海神採珠珠尽死，死尽明珠空海水。","珠爲海物海屬神，神今自採何況人。"]', '诗', 'shi', '', NULL, '樂府古題序 採珠行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e01dc2d3-9313-48b5-b358-c3a08d9da808', '樂府古題序 董逃行', '乐府古題序 董逃行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["董逃董逃董卓逃，揩鏗戈甲聲勞嘈。","剜剜深臍脂燄燄，人皆數歎曰。","爾獨不憶年年取我身上膏，膏銷骨盡煙火死。","長安城中賊毛起，城門四走公卿士。","走勸劉虞作天子，劉虞不敢作天子。","曹瞞篡亂從此始，董逃董逃人莫喜。","勝負相環相枕倚，縫綴難成裁破易。","何況曲鍼不能伸巧指，欲學裁縫須準擬。"]', '["董逃董逃董卓逃，揩鏗戈甲声勞嘈。","剜剜深臍脂燄燄，人皆數歎曰。","爾独不憶年年取我身上膏，膏銷骨尽煙火死。","长安城中賊毛起，城门四走公卿士。","走勸劉虞作天子，劉虞不敢作天子。","曹瞞篡亂從此始，董逃董逃人莫喜。","勝負相环相枕倚，縫綴难成裁破易。","何況曲鍼不能伸巧指，欲学裁縫須準擬。"]', '诗', 'shi', '', NULL, '樂府古題序 董逃行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb57d9e-adaf-4a08-aff4-240a23a7d088', '樂府古題序 憶遠曲', '乐府古題序 憶远曲', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶遠曲，郎身不遠郎心遠。","沙隨郎飯俱在匙，郎意看沙那比飯。","水中書字無字痕，君心暗畫誰會君。","況妾事姑姑進止，身去門前同萬里。","一家盡是郎腹心，妾似生來無兩耳。","妾身何足言，聽妾私勸君。","君今夜夜醉何處？姑來伴妾自閉門。","嫁夫恨不早，養兒將備老。","妾自嫁郎身骨立，老姑爲郎求娶妾。","妾不忍見姑郎忍見，爲郎忍耐看姑面。"]', '["憶远曲，郎身不远郎心远。","沙隨郎飯俱在匙，郎意看沙那比飯。","水中书字無字痕，君心暗畫誰會君。","況妾事姑姑進止，身去门前同万里。","一家尽是郎腹心，妾似生来無兩耳。","妾身何足言，听妾私勸君。","君今夜夜醉何处？姑来伴妾自閉门。","嫁夫恨不早，養兒將備老。","妾自嫁郎身骨立，老姑爲郎求娶妾。","妾不忍见姑郎忍见，爲郎忍耐看姑面。"]', '诗', 'shi', '', NULL, '樂府古題序 憶遠曲 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10ca127f-b941-4689-8217-99a5e09c79b4', '樂府古題序 夫遠征', '乐府古題序 夫远征', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["趙卒四十萬，盡爲坑中鬼。","趙王未信趙母言，猶點新兵更填死。","填死之兵兵氣索，秦強趙破括敵起。","括雖專命起尚輕，何況牽肘之人牽不已。","坑中之鬼妻在營，髽麻戴絰鵝雁鳴。","送夫之婦又行哭，哭聲送死非送行。","夫遠征，遠征不必戍長城，出門便不知死生。"]', '["趙卒四十万，尽爲坑中鬼。","趙王未信趙母言，猶点新兵更填死。","填死之兵兵氣索，秦強趙破括敵起。","括雖專命起尚轻，何況牽肘之人牽不已。","坑中之鬼妻在營，髽麻戴絰鵝雁鳴。","送夫之婦又行哭，哭声送死非送行。","夫远征，远征不必戍长城，出门便不知死生。"]', '诗', 'shi', '', NULL, '樂府古題序 夫遠征 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a9273b-3081-4575-a9f1-bb6ad27cd93f', '樂府古題序 織婦詞', '乐府古題序 织婦词', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["織夫何太忙，蠶經三臥行欲老。","蠶神女聖早成絲，今年絲稅抽徵早。","早徵非是官人惡，去歲官家事戎索。","征人戰苦束刀瘡，主將勳高換羅幕。","繅絲織帛猶努力，變緝撩機苦難織。","東家頭白雙女兒，爲解挑紋嫁不得。","檐前嫋嫋游絲上，上有蜘蛛巧來往。","羨他蟲豸解緣天，能向虛空織羅網。"]', '["织夫何太忙，蠶經三臥行欲老。","蠶神女聖早成絲，今年絲稅抽徵早。","早徵非是官人惡，去歲官家事戎索。","征人戰苦束刀瘡，主將勳高換羅幕。","繅絲织帛猶努力，变緝撩機苦难织。","东家头白雙女兒，爲解挑紋嫁不得。","檐前嫋嫋游絲上，上有蜘蛛巧来往。","羨他蟲豸解緣天，能向虛空织羅網。"]', '诗', 'shi', '', NULL, '樂府古題序 織婦詞 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ebfbcd5-a4e9-4e05-9396-82b390c73091', '樂府古題序 田家詞', '乐府古題序 田家词', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["牛吒吒，田确确。","旱塊敲牛蹄趵趵，種得官倉珠顆穀。","六十年來兵蔟蔟，月月食糧車轆轆。","一日官軍收海服，驅牛駕車食牛肉。","歸來攸得牛兩角，重鑄鋤犂作斤劚。","姑舂婦擔去輸官，輸官不足歸賣屋。","願官早勝讎早覆，農死有兒牛有犢，誓不遣官軍糧不足。"]', '["牛吒吒，田确确。","旱塊敲牛蹄趵趵，種得官倉珠顆穀。","六十年来兵蔟蔟，月月食糧车轆轆。","一日官軍收海服，驱牛駕车食牛肉。","归来攸得牛兩角，重鑄鋤犂作斤劚。","姑舂婦擔去輸官，輸官不足归賣屋。","願官早勝讎早覆，農死有兒牛有犢，誓不遣官軍糧不足。"]', '诗', 'shi', '', NULL, '樂府古題序 田家詞 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('446bec5f-c3ab-4caa-af4f-66ce21a8f2bd', '樂府古題序 俠客行', '乐府古題序 俠客行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["俠客不怕死，怕在事不成。","事成不肯藏姓名，我非竊賊誰夜行。","白日堂堂殺袁盎，九衢草草人面青。","此客此心師海鯨，海鯨露背橫滄溟。","海波分作兩處生，分海減海刀，俠客有謀。","人不識測，三尺鐵蛇延二國。"]', '["俠客不怕死，怕在事不成。","事成不肯藏姓名，我非竊賊誰夜行。","白日堂堂殺袁盎，九衢草草人面青。","此客此心師海鯨，海鯨露背橫滄溟。","海波分作兩处生，分海減海刀，俠客有謀。","人不識測，三尺鐵蛇延二国。"]', '诗', 'shi', '', NULL, '樂府古題序 俠客行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d4bd083-3717-434d-9284-b0c34dde5475', '樂府古題序 君莫非', '乐府古題序 君莫非', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鳥不解走，獸不解飛。","兩不相解，那得相譏。","犬不飲露，蟬不噉肥。","以蟬易犬，蟬死犬飢。","燕在梁棟，鼠在階基。","各自窠窟，人不能移。","婦好鍼縷，夫讀書詩。","男翁女嫁，卒不相知。","懼聾摘耳，效痛嚬眉。","我不非爾，爾無我非。"]', '["鸟不解走，獸不解飞。","兩不相解，那得相譏。","犬不饮露，蟬不噉肥。","以蟬易犬，蟬死犬飢。","燕在梁棟，鼠在階基。","各自窠窟，人不能移。","婦好鍼縷，夫读书诗。","男翁女嫁，卒不相知。","懼聾摘耳，效痛嚬眉。","我不非爾，爾無我非。"]', '诗', 'shi', '', NULL, '樂府古題序 君莫非 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab89c83e-a4ac-4ec9-9a21-186019ef8a03', '樂府古題序 田野狐兔行', '乐府古題序 田野狐兔行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["種豆耘鋤，種禾溝甽。","禾苗豆甲，狐榾兔翦。","割鵠餧鷹，烹麟噉犬。","鷹怕兔毫，犬被狐引。","狐兔相須，鷹犬相盡。","日暗天寒，禾稀豆損。","鷹犬就烹，狐兔俱哂。"]', '["種豆耘鋤，種禾溝甽。","禾苗豆甲，狐榾兔翦。","割鵠餧鷹，烹麟噉犬。","鷹怕兔毫，犬被狐引。","狐兔相須，鷹犬相尽。","日暗天寒，禾稀豆損。","鷹犬就烹，狐兔俱哂。"]', '诗', 'shi', '', NULL, '樂府古題序 田野狐兔行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9450f35-87bb-4295-9de7-34914fadc24d', '樂府古題序 當來日大難行', '乐府古題序 當来日大难行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["當來日大難行，前有阪，後有坑。","大梁側，小梁傾。","兩軸相絞，兩輪相撐。","大牛豎，小牛橫。","烏啄牛背，足趺力儜，當來日大難行。","太行雖險，險可使平。","輪軸自撓，牽制不停。","泥潦漸久，荆棘旋生。","行必不得，不如不行。"]', '["當来日大难行，前有阪，後有坑。","大梁側，小梁傾。","兩軸相絞，兩輪相撐。","大牛豎，小牛橫。","烏啄牛背，足趺力儜，當来日大难行。","太行雖險，險可使平。","輪軸自撓，牽制不停。","泥潦漸久，荆棘旋生。","行必不得，不如不行。"]', '诗', 'shi', '', NULL, '樂府古題序 當來日大難行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dec1d0c4-b4b3-430e-9d82-40946c67b108', '樂府古題序 人道短', '乐府古題序 人道短', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["古道天道長人道短，我道天道短人道長。","天道晝夜廻轉不曾住，春秋冬夏忙，顛風暴雨電雷狂。","晴被陰暗，月奪日光。","往往星宿，日亦堂堂。","天既職性命，道德人自強。","堯舜有聖德，天不能遣。","壽命永昌，泥金刻玉。","與秦始皇，周公傅說。","何不長宰相，老耼仲尼。","何事栖遑，莽卓恭顯。","皆數十年富貴，梁冀夫婦。","車馬煌煌，若此顛倒事。","豈非天道短，豈非人道長。","堯舜留得神聖事，百代天子有典章。","仲尼留得孝順語，千年萬歲父子不敢相滅亡。","歿後千餘載，唐家天子封作文宣王。","老君留得五千字，子孫萬萬稱聖唐。","諡作玄元帝，魂魄坐天堂。","周公周禮二十卷，有能行者知紀綱。","傅說說命三四紙，有能師者稱祖宗。","天能夭人命，人使道無窮。","若此神聖事，誰道人道短。","豈非人道長，天能種百草。","蕕得十年有氣息，蕣纔一日芳。","人能揀得丁沈蘭蕙，料理百和香。","天解養禽獸，餧虎豹豺狼。","人解和麯糵，充礿祀烝嘗。","杜鵑無百作，天遣百鳥哺雛。","不遣哺鳳皇，巨蟒壽千歲。","天遣食牛吞象充腹腸，蛟螭與變化。","鬼怪與隱藏，蚊蚋與利觜。","枳棘與鋒鋩，賴得人道有揀別。","信任天道真茫茫，若此撩亂事。","豈非天道短，賴得人道長。"]', '["古道天道长人道短，我道天道短人道长。","天道晝夜廻轉不曾住，春秋冬夏忙，顛风暴雨電雷狂。","晴被陰暗，月奪日光。","往往星宿，日亦堂堂。","天既職性命，道德人自強。","堯舜有聖德，天不能遣。","壽命永昌，泥金刻玉。","與秦始皇，周公傅说。","何不长宰相，老耼仲尼。","何事栖遑，莽卓恭显。","皆數十年富貴，梁冀夫婦。","车马煌煌，若此顛倒事。","豈非天道短，豈非人道长。","堯舜留得神聖事，百代天子有典章。","仲尼留得孝順語，千年万歲父子不敢相滅亡。","歿後千餘載，唐家天子封作文宣王。","老君留得五千字，子孫万万稱聖唐。","諡作玄元帝，魂魄坐天堂。","周公周禮二十卷，有能行者知紀綱。","傅说说命三四紙，有能師者稱祖宗。","天能夭人命，人使道無窮。","若此神聖事，誰道人道短。","豈非人道长，天能種百草。","蕕得十年有氣息，蕣纔一日芳。","人能揀得丁沈蘭蕙，料理百和香。","天解養禽獸，餧虎豹豺狼。","人解和麯糵，充礿祀烝嘗。","杜鵑無百作，天遣百鸟哺雛。","不遣哺鳳皇，巨蟒壽千歲。","天遣食牛吞象充腹腸，蛟螭與变化。","鬼怪與隐藏，蚊蚋與利觜。","枳棘與鋒鋩，賴得人道有揀別。","信任天道真茫茫，若此撩亂事。","豈非天道短，賴得人道长。"]', '诗', 'shi', '', NULL, '樂府古題序 人道短 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6326b33-4250-4766-ac58-d742b6cb4ebe', '樂府古題序 苦樂相倚曲', '乐府古題序 苦乐相倚曲', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["古來苦樂之相倚，近於掌上之十指。","君心半夜猜恨生，荆棘滿懷天未明。","漢成眼瞥飛燕時，可憐班女恩已衰。","未有因由相決絕，猶得半年佯暖熱。","轉將深意諭旁人，緝綴瑕疵遣潛說。","一朝詔下辭金屋，班姬自痛何倉卒。","呼天撫地將自明，不悟尋時暗銷骨。","白首宮人前再拜，願將日月相輝解。","苦樂相尋晝夜間，燈光那有天明在。","主今被奪心應苦，妾奪深恩初爲主。","欲知妾意恨主時，主今爲妾思量取。","班姬收淚抱妾身，我曾排擯無限人。"]', '["古来苦乐之相倚，近於掌上之十指。","君心半夜猜恨生，荆棘满懷天未明。","漢成眼瞥飞燕时，可怜班女恩已衰。","未有因由相決絕，猶得半年佯暖熱。","轉將深意諭旁人，緝綴瑕疵遣潛说。","一朝詔下辞金屋，班姬自痛何倉卒。","呼天撫地將自明，不悟尋时暗銷骨。","白首宮人前再拜，願將日月相輝解。","苦乐相尋晝夜间，灯光那有天明在。","主今被奪心應苦，妾奪深恩初爲主。","欲知妾意恨主时，主今爲妾思量取。","班姬收泪抱妾身，我曾排擯無限人。"]', '诗', 'shi', '', NULL, '樂府古題序 苦樂相倚曲 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ddef83-d86f-4f00-8f98-1cedc22cf519', '樂府古題序 出門行', '乐府古題序 出门行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["兄弟同出門，同行不同志。","悽悽分岐路，各各營所爲。","兄上荆山巔，翻石辨虹氣。","弟沈滄海底，偷珠待龍睡。","出門不數年，同歸亦同遂。","俱用私所珍，升沈自茲異。","獻珠龍王宮，值龍覓珠次。","但喜復得珠，不求珠所自。","酬客雙龍女，授客六龍轡。","遣充行雨神，雨澤隨客意。","雩夏鐘鼓繁，禜秋玉帛積。","彩色畫廊廟，奴僮被珠翠。","驥騄千萬雙，鴛鴦七十二。","言者未搖舌，無人敢輕議。","其兄因獻璞，再刖不履地。","門戶親戚疎，匡牀妻妾棄。","銘心有所待，視足無所愧。","持璞自枕頭，淚痕雙血漬。","一朝龍醒寤，本問偷珠事。","因知行雨偏，妻子五刑備。","仁兄捧尸哭，勢友掉頭諱。","喪車黔首葬，弔客青蠅至。","楚有望氣人，王前忽長跪。","賀王得貴寶，不遠王所莅。","求之果如言，剖出浮筠膩。","白珩無顏色，垂棘有瑕累。","在楚裂地封，入趙連城貴。","秦遣李斯書，書爲傳國瑞。","秦亡漢魏傳，傳者得神器。","卞和名永永，與寶不相墜。","勸爾出門行，行難莫行易。","易得還易失，難同亦難離。","善賈識貪廉，良田無稙穉。","磨劒莫磨錐，磨錐成小利。"]', '["兄弟同出门，同行不同志。","悽悽分岐路，各各營所爲。","兄上荆山巔，翻石辨虹氣。","弟沈滄海底，偷珠待龙睡。","出门不數年，同归亦同遂。","俱用私所珍，升沈自茲異。","獻珠龙王宮，值龙覓珠次。","但喜复得珠，不求珠所自。","酬客雙龙女，授客六龙轡。","遣充行雨神，雨澤隨客意。","雩夏鐘鼓繁，禜秋玉帛積。","彩色畫廊廟，奴僮被珠翠。","驥騄千万雙，鴛鴦七十二。","言者未搖舌，無人敢轻議。","其兄因獻璞，再刖不履地。","门戶親戚疎，匡牀妻妾棄。","銘心有所待，視足無所愧。","持璞自枕头，泪痕雙血漬。","一朝龙醒寤，本问偷珠事。","因知行雨偏，妻子五刑備。","仁兄捧尸哭，勢友掉头諱。","喪车黔首葬，弔客青蠅至。","楚有望氣人，王前忽长跪。","賀王得貴寶，不远王所莅。","求之果如言，剖出浮筠膩。","白珩無顏色，垂棘有瑕累。","在楚裂地封，入趙連城貴。","秦遣李斯书，书爲傳国瑞。","秦亡漢魏傳，傳者得神器。","卞和名永永，與寶不相墜。","勸爾出门行，行难莫行易。","易得還易失，难同亦难離。","善賈識貪廉，良田無稙穉。","磨劒莫磨錐，磨錐成小利。"]', '诗', 'shi', '', NULL, '樂府古題序 出門行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d5fff46-32e1-4118-98f5-120146079b6a', '樂府古題序 捉捕歌', '乐府古題序 捉捕歌', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["捉捕復捉捕，莫捉狐與兔。","狐兔藏窟穴，豺狼妨道路。","道路非不妨，最憂螻蟻聚。","豺狼不陷穽，螻蟻潛幽蠹。","切切主人窗，主人輕細故。","延緣蝕𣡵櫨，漸入棟梁柱。","梁棟盡空虛，攻穿痕不露。","主人坦然意，晝夜安寢寤。","網羅布參差，鷹犬走回互。","盡力窮窟穴，無心自還顧。","客來歌捉捕，歌竟淚如雨。","豈是惜狐兔，畏君先後誤。","願君埽梁棟，莫遣螻蟻附。","次及清道塗，盡滅豺狼步。","主人堂上坐，行客門前度。","然後巡野田，徧張畋獵具。","外無梟獍援，內有熊羆驅。","狡兔掘荒榛，妖狐熏古墓。","用力不足多，得禽自無數。","畏君聽未詳，聽客有明喻。","蟣蝨誰不輕，鯨鯢誰不惡。","在海尚幽遐，在懷交穢汚。","歌此勸主人，主人那不悟。","不悟還更歌，誰能恐違忤。"]', '["捉捕复捉捕，莫捉狐與兔。","狐兔藏窟穴，豺狼妨道路。","道路非不妨，最憂螻蟻聚。","豺狼不陷穽，螻蟻潛幽蠹。","切切主人窗，主人轻細故。","延緣蝕𣡵櫨，漸入棟梁柱。","梁棟尽空虛，攻穿痕不露。","主人坦然意，晝夜安寢寤。","網羅布參差，鷹犬走回互。","尽力窮窟穴，無心自還顧。","客来歌捉捕，歌竟泪如雨。","豈是惜狐兔，畏君先後誤。","願君埽梁棟，莫遣螻蟻附。","次及清道塗，尽滅豺狼步。","主人堂上坐，行客门前度。","然後巡野田，徧張畋獵具。","外無梟獍援，內有熊羆驱。","狡兔掘荒榛，妖狐熏古墓。","用力不足多，得禽自無數。","畏君听未詳，听客有明喻。","蟣蝨誰不轻，鯨鯢誰不惡。","在海尚幽遐，在懷交穢汚。","歌此勸主人，主人那不悟。","不悟還更歌，誰能恐違忤。"]', '诗', 'shi', '', NULL, '樂府古題序 捉捕歌 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe9f4c9e-c71e-458f-b18c-44ce2036869c', '樂府古題序 古築城曲五解 一', '乐府古題序 古築城曲五解 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["年年塞下丁，長作出塞兵。","自從冒頓強，官築遮虜城。"]', '["年年塞下丁，长作出塞兵。","自從冒頓強，官築遮虜城。"]', '诗', 'shi', '', NULL, '樂府古題序 古築城曲五解 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c3c9603-68ed-44fe-92f1-01e84616a974', '樂府古題序 古築城曲五解 二', '乐府古題序 古築城曲五解 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["築城須努力，城高遮得賊。","但恐賊路多，有城遮不得。"]', '["築城須努力，城高遮得賊。","但恐賊路多，有城遮不得。"]', '诗', 'shi', '', NULL, '樂府古題序 古築城曲五解 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e92bbc7a-2373-492a-9ba7-0b146391cf8e', '樂府古題序 古築城曲五解 三', '乐府古題序 古築城曲五解 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["丁口傳父言，莫問城堅不。","平城被虜圍，漢劚城牆走。"]', '["丁口傳父言，莫问城堅不。","平城被虜圍，漢劚城牆走。"]', '诗', 'shi', '', NULL, '樂府古題序 古築城曲五解 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48a9c53a-4441-4160-b19a-e8bfca566cc9', '樂府古題序 古築城曲五解 四', '乐府古題序 古築城曲五解 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["因茲請休和，虜往騎來過。","半疑兼半信，築城猶嵯峨。"]', '["因茲請休和，虜往騎来過。","半疑兼半信，築城猶嵯峨。"]', '诗', 'shi', '', NULL, '樂府古題序 古築城曲五解 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c85e8697-9e78-40cb-8f8e-5d4a9bf772b4', '樂府古題序 古築城曲五解 五', '乐府古題序 古築城曲五解 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["築城安敢煩，願聽丁一言。","請築鴻臚寺，兼愁虜出關。"]', '["築城安敢煩，願听丁一言。","請築鴻臚寺，兼愁虜出关。"]', '诗', 'shi', '', NULL, '樂府古題序 古築城曲五解 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16e8df55-02ae-4e52-b8c9-f72a27cd99fe', '樂府古題序 估客樂', '乐府古題序 估客乐', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["估客無住著，有利身則行。","出門求火伴，入戶辭父兄。","父兄相教示，求利莫求名。","求名有所避，求利無不營。","火伴相勒縛，賣假莫賣誠。","交關但交假，本生得失輕。","自茲相將去，誓死意不更。","亦解市頭語，便無鄰里情。","鍮石打臂釧，糯米吹項瓔。","歸來邨中賣，敲作金石聲。","邨中田舍娘，貴賤不敢爭。","所費百錢本，已得十倍贏。","顏色轉光淨，飲食亦甘馨。","子本頻蕃息，貨販日兼幷。","求珠駕滄海，採玉上荆衡。","北買党項馬，西擒吐蕃鸚。","炎洲布火浣，蜀地錦織成。","越婢脂肉滑，奚僮眉眼明。","通算衣食費，不計遠近程。","經遊天下徧，却到長安城。","城中東西市，聞客次第迎。","迎客兼說客，多財爲勢傾。","客心本明黠，聞語心已驚。","先問十常侍，次求百公卿。","侯家與主第，點綴無不精。","歸來始安坐，富與王者勍。","市卒酒肉臭，縣胥家舍成。","豈唯絕言語，奔走極使令。","大兒販材木，巧識梁棟形。","小兒販鹽鹵，不入州縣征。","一身偃市利，突若截海鯨。","鉤距不敢下，下則牙齒橫。","生爲估客樂，判爾樂一生。","爾又生兩子，錢刀何歲平。"]', '["估客無住著，有利身則行。","出门求火伴，入戶辞父兄。","父兄相教示，求利莫求名。","求名有所避，求利無不營。","火伴相勒縛，賣假莫賣誠。","交关但交假，本生得失轻。","自茲相將去，誓死意不更。","亦解市头語，便無鄰里情。","鍮石打臂釧，糯米吹項瓔。","归来邨中賣，敲作金石声。","邨中田舍娘，貴賤不敢爭。","所費百錢本，已得十倍贏。","顏色轉光淨，饮食亦甘馨。","子本頻蕃息，貨販日兼幷。","求珠駕滄海，採玉上荆衡。","北買党項马，西擒吐蕃鸚。","炎洲布火浣，蜀地錦织成。","越婢脂肉滑，奚僮眉眼明。","通算衣食費，不計远近程。","經游天下徧，却到长安城。","城中东西市，闻客次第迎。","迎客兼说客，多財爲勢傾。","客心本明黠，闻語心已驚。","先问十常侍，次求百公卿。","侯家與主第，点綴無不精。","归来始安坐，富與王者勍。","市卒酒肉臭，縣胥家舍成。","豈唯絕言語，奔走極使令。","大兒販材木，巧識梁棟形。","小兒販鹽鹵，不入州縣征。","一身偃市利，突若截海鯨。","鉤距不敢下，下則牙齒橫。","生爲估客乐，判爾乐一生。","爾又生兩子，錢刀何歲平。"]', '诗', 'shi', '', NULL, '樂府古題序 估客樂 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f19c587-32cc-47b4-9671-d1129116d9c2', '連昌宮詞', '連昌宮词', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["連昌宮中滿宮竹，歲久無人森似束。","又有牆頭千葉桃，風動落花紅蔌蔌。","宮邊老翁爲余泣，小年進食曾因入。","上皇正在望仙樓，太真同凭闌干立。","樓上樓前盡珠翠，炫轉熒煌照天地。","歸來如夢復如癡，何暇備言宮裏事。","初過寒食一百六，店舍無煙宮樹綠。","夜半月高弦索鳴，賀老琵琶定場屋。","力士傳呼覓念奴，念奴潛伴諸郎宿。","須臾覓得又連催，特敕街中許然燭。","春嬌滿眼睡紅綃，掠削雲鬟旋裝束。","飛上九天歌一聲，二十五郎吹管逐。","逡巡大徧涼州徹，色色龜茲轟錄續。","李謩擪笛傍宮牆，偷得新翻數般曲。","平明大駕發行宮，萬人歌舞塗路中。","百官隊仗避岐薛，楊氏諸姨車鬬風。","明年十月東都破，御路猶存祿山過。","驅令供頓不敢藏，萬姓無聲淚潛墮。","兩京定後六七年，却尋家舍行宮前。","莊園燒盡有枯井，行宮門閉樹宛然。","爾後相傳六皇帝，不到離宮門久閉。","往來年少說長安，玄武樓成花萼廢。","去年敕使因斫竹，偶值門開暫相逐。","荆榛櫛比塞池塘，狐兔驕癡緣樹木。","舞榭敧傾基尚在，文窗窈窕紗猶綠。","塵埋粉壁舊花鈿，烏啄風箏碎珠玉。","上皇偏愛臨砌花，依然御榻臨階斜。","蛇出燕巢盤鬬栱，菌生香案正當衙。","寢殿相連端正樓，太真梳洗樓上頭。","晨光未出簾影黑，至今反挂珊瑚鉤。","指似傍人因慟哭，却出宮門淚相續。","自從此後還閉門，夜夜狐貍上門屋。","我聞此語心骨悲，太平誰致亂者誰。","翁言野父何分別，耳聞眼見爲君說。","姚崇宋璟作相公，勸諫上皇言語切。","燮理陰陽禾黍豐，調和中外無兵戎。","長官清平太守好，揀選皆言由相公。","開元之末姚宋死，朝廷漸漸由妃子。","祿山宮裏養作兒，虢國門前鬧如市。","弄權宰相不記名，依稀憶得楊與李。","廟謨顛倒四海搖，五十年來作瘡痏。","今皇神聖丞相明，詔書纔下吳蜀平。","官軍又取淮西賊，此賊亦除天下寧。","年年耕種宮前道，今年不遣子孫耕。","老翁此意深望幸，努力廟謀休用兵。"]', '["連昌宮中满宮竹，歲久無人森似束。","又有牆头千葉桃，风动落花紅蔌蔌。","宮邊老翁爲余泣，小年進食曾因入。","上皇正在望仙楼，太真同凭闌干立。","楼上楼前尽珠翠，炫轉熒煌照天地。","归来如梦复如癡，何暇備言宮裏事。","初過寒食一百六，店舍無煙宮樹綠。","夜半月高弦索鳴，賀老琵琶定場屋。","力士傳呼覓念奴，念奴潛伴諸郎宿。","須臾覓得又連催，特敕街中許然燭。","春嬌满眼睡紅綃，掠削云鬟旋裝束。","飞上九天歌一声，二十五郎吹管逐。","逡巡大徧涼州徹，色色龟茲轟錄續。","李謩擪笛傍宮牆，偷得新翻數般曲。","平明大駕發行宮，万人歌舞塗路中。","百官隊仗避岐薛，楊氏諸姨车鬬风。","明年十月东都破，御路猶存祿山過。","驱令供頓不敢藏，万姓無声泪潛墮。","兩京定後六七年，却尋家舍行宮前。","莊园燒尽有枯井，行宮门閉樹宛然。","爾後相傳六皇帝，不到離宮门久閉。","往来年少说长安，玄武楼成花萼廢。","去年敕使因斫竹，偶值门开暫相逐。","荆榛櫛比塞池塘，狐兔驕癡緣樹木。","舞榭敧傾基尚在，文窗窈窕紗猶綠。","塵埋粉壁旧花鈿，烏啄风箏碎珠玉。","上皇偏愛臨砌花，依然御榻臨階斜。","蛇出燕巢盤鬬栱，菌生香案正當衙。","寢殿相連端正楼，太真梳洗楼上头。","晨光未出簾影黑，至今反挂珊瑚鉤。","指似傍人因慟哭，却出宮门泪相續。","自從此後還閉门，夜夜狐貍上门屋。","我闻此語心骨悲，太平誰致亂者誰。","翁言野父何分別，耳闻眼见爲君说。","姚崇宋璟作相公，勸諫上皇言語切。","燮理陰陽禾黍豐，調和中外無兵戎。","长官清平太守好，揀選皆言由相公。","开元之末姚宋死，朝廷漸漸由妃子。","祿山宮裏養作兒，虢国门前鬧如市。","弄權宰相不記名，依稀憶得楊與李。","廟謨顛倒四海搖，五十年来作瘡痏。","今皇神聖丞相明，詔书纔下吳蜀平。","官軍又取淮西賊，此賊亦除天下寧。","年年耕種宮前道，今年不遣子孫耕。","老翁此意深望幸，努力廟謀休用兵。"]', '诗', 'shi', '', NULL, '連昌宮詞 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84eaa5b6-6ea8-4904-acf8-7f7f8b100932', '望雲騅馬歌', '望云騅马歌', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["憶昔先皇幸蜀時，八馬入谷七馬疲。","肉綻筋攣四蹄脫，七馬死盡無馬騎。","天子蒙塵天雨泣，巉巖道路淋漓濕。","崢嶸白草眇難期，謥洞黃泉安可入。","朱泚圍兵抽未盡，懷光寇騎追行及。","嬪娥相顧倚樹啼，鵷鷺無聲仰天立。","圉人初進望雲騅，彩色顦顇衆馬欺。","上前噴吼如有意，耳尖卓立節踠奇。","君王試遣廻胸臆，撮骨鋸牙駢兩肋。","蹄懸四跼腦顆方，胯聳三山尾株直。","圉人畏誚仍相惑，此馬無良空有力。","頻頻囓掣轡難施，往往跳趫鞍不得。","色沮聲悲仰天訴，天不遣言君未識。","亞身受取白玉羈，開口銜將紫金勒。","君王自此方敢騎，似遇良臣久悽惻。","龍騰魚鼈啅然驚，驥朌驢騾少顏色。","七聖心迷運方厄，五丁力盡路猶窄。","橐它山上斧刃堆，望秦嶺下錐頭石。","五六百里真符縣，八十四盤青山驛。","掣開流電有輝光，突過浮雲無朕跡。","地平險盡施黃屋，九九屬車十二纛。","齊暎前導引騅頭，嚴震迎號抱騅足。","路傍垂白天寶民，望騅禮拜見騅哭。","皆言玄宗當時無此馬，不免騎騾來幸蜀。","雄雄猛將李令公，收城殺賊豺狼空。","天旋地轉日再中，天子却坐明光宮。","朝廷無事忘征戰，校獵朝廻暮毬宴。","御馬齊登擬用槽，君王自試宣徽殿。","圉人還進望雲騅，性強步闊無方便。","分騣擺杖頭太高，擘肘廻頭項難轉。","人人共惡難廻跋，潛遣飛龍減芻秣。","銀鞍繡韂不復施，空盡天年御槽活。","當時鄒諺已有言，莫倚功高浪開闊。","登山縱似望雲騅，平地須饒紅叱撥。","長安三月花垂草，果下翩翩紫騮好。","千官煖熱李令閑，百馬生獰望雲老。","望雲騅，爾之種類世世奇。","當時項王乘爾祖，分配英豪稱霸王。","爾身今日逢聖人，從幸巴渝歸入秦。","功成事遂身退天之道，何必隨羣逐隊到死蹋紅塵。","望雲騅，用與不用各有時，爾勿悲。"]', '["憶昔先皇幸蜀时，八马入谷七马疲。","肉綻筋攣四蹄脫，七马死尽無马騎。","天子蒙塵天雨泣，巉巖道路淋漓濕。","崢嶸白草眇难期，謥洞黄泉安可入。","朱泚圍兵抽未尽，懷光寇騎追行及。","嬪娥相顧倚樹啼，鵷鷺無声仰天立。","圉人初進望云騅，彩色顦顇衆马欺。","上前噴吼如有意，耳尖卓立節踠奇。","君王試遣廻胸臆，撮骨鋸牙駢兩肋。","蹄懸四跼腦顆方，胯聳三山尾株直。","圉人畏誚仍相惑，此马無良空有力。","頻頻囓掣轡难施，往往跳趫鞍不得。","色沮声悲仰天訴，天不遣言君未識。","亞身受取白玉羈，开口銜將紫金勒。","君王自此方敢騎，似遇良臣久悽惻。","龙腾鱼鼈啅然驚，驥朌驢騾少顏色。","七聖心迷運方厄，五丁力尽路猶窄。","橐它山上斧刃堆，望秦嶺下錐头石。","五六百里真符縣，八十四盤青山驛。","掣开流電有輝光，突過浮云無朕跡。","地平險尽施黄屋，九九屬车十二纛。","齊暎前導引騅头，嚴震迎號抱騅足。","路傍垂白天寶民，望騅禮拜见騅哭。","皆言玄宗當时無此马，不免騎騾来幸蜀。","雄雄猛將李令公，收城殺賊豺狼空。","天旋地轉日再中，天子却坐明光宮。","朝廷無事忘征戰，校獵朝廻暮毬宴。","御马齊登擬用槽，君王自試宣徽殿。","圉人還進望云騅，性強步闊無方便。","分騣擺杖头太高，擘肘廻头項难轉。","人人共惡难廻跋，潛遣飞龙減芻秣。","銀鞍繡韂不复施，空尽天年御槽活。","當时鄒諺已有言，莫倚功高浪开闊。","登山縱似望云騅，平地須饒紅叱撥。","长安三月花垂草，果下翩翩紫騮好。","千官煖熱李令闲，百马生獰望云老。","望云騅，爾之種類世世奇。","當时項王乘爾祖，分配英豪稱霸王。","爾身今日逢聖人，從幸巴渝归入秦。","功成事遂身退天之道，何必隨羣逐隊到死蹋紅塵。","望云騅，用與不用各有时，爾勿悲。"]', '诗', 'shi', '', NULL, '望雲騅馬歌 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1819e9db-aa89-4523-8662-783a06dfac6e', '和李校書新題樂府十二首 上陽白髮人', '和李校书新題乐府十二首 上陽白髮人', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["天寶年中花鳥使，撩花狎鳥含春思。","滿懷墨詔求嬪御，走上高樓半酣醉。","醉酣直入卿士家，閨闈不得偷廻避。","良人顧妾心死別，小女呼爺血垂淚。","十中有一得更衣，永配深宮作宮婢。","御馬南奔胡馬蹙，宮女三千合宮棄。","宮門一閉不復開，上陽花草青苔地。","月夜閑聞洛水聲，秋池暗度風荷氣。","日日長看提衆門，終身不見門前事。","近年又送數人來，自言興慶南宮至。","我悲此曲將徹骨，更想深冤復酸鼻。","此輩賤嬪何足言，帝子天孫古稱貴。","諸王在閤四十年，七宅六宮門戶閟。","隋煬枝條襲封邑，肅宗血胤無官位。","王無妃媵主無壻，陽亢陰淫結災累。","何如決壅順衆流，女遣從夫男作吏。"]', '["天寶年中花鸟使，撩花狎鸟含春思。","满懷墨詔求嬪御，走上高楼半酣醉。","醉酣直入卿士家，閨闈不得偷廻避。","良人顧妾心死別，小女呼爺血垂泪。","十中有一得更衣，永配深宮作宮婢。","御马南奔胡马蹙，宮女三千合宮棄。","宮门一閉不复开，上陽花草青苔地。","月夜闲闻洛水声，秋池暗度风荷氣。","日日长看提衆门，終身不见门前事。","近年又送數人来，自言兴慶南宮至。","我悲此曲將徹骨，更想深冤复酸鼻。","此輩賤嬪何足言，帝子天孫古稱貴。","諸王在閤四十年，七宅六宮门戶閟。","隋煬枝條襲封邑，肅宗血胤無官位。","王無妃媵主無壻，陽亢陰淫結災累。","何如決壅順衆流，女遣從夫男作吏。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 上陽白髮人 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebdc03e3-3b42-42a0-ac94-42efd22f537c', '和李校書新題樂府十二首 華原磬', '和李校书新題乐府十二首 华原磬', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["泗濱浮石裁爲磬，古樂疎音少人聽。","工師小賤牙曠稀，不辨邪聲嫌雅正。","正聲不屈古調高，鍾律參差管絃病。","鏗金戛瑟徒相雜，投玉敲冰杳然零。","華原輭石易追琢，高下隨人無雅鄭。","棄舊美新由樂胥，自此黃鍾不能競。","玄宗愛樂愛新樂，梨園弟子承恩橫。","霓裳纔徹胡騎來，雲門未得蒙親定。","我藏古磬藏在心，有時激作南風詠。","伯夔曾撫野獸馴，仲尼暫叩春雷盛。","何時得向筍簴懸，爲君一吼君心醒。","願君每聽念封疆，不遣豺狼勦人命。"]', '["泗濱浮石裁爲磬，古乐疎音少人听。","工師小賤牙曠稀，不辨邪声嫌雅正。","正声不屈古調高，鍾律參差管絃病。","鏗金戛瑟徒相杂，投玉敲冰杳然零。","华原輭石易追琢，高下隨人無雅鄭。","棄旧美新由乐胥，自此黄鍾不能競。","玄宗愛乐愛新乐，梨园弟子承恩橫。","霓裳纔徹胡騎来，云门未得蒙親定。","我藏古磬藏在心，有时激作南风詠。","伯夔曾撫野獸馴，仲尼暫叩春雷盛。","何时得向筍簴懸，爲君一吼君心醒。","願君每听念封疆，不遣豺狼勦人命。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 華原磬 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d20399f-aebe-402c-9c30-f048a7010313', '和李校書新題樂府十二首 五弦彈', '和李校书新題乐府十二首 五弦彈', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["趙璧五弦彈徵調，徵聲巉絕何清峭。","辭雄皓鶴警露啼，失子哀猿繞林嘯。","風入春松正凌亂，鶯含曉舌憐嬌妙。","嗚嗚暗溜咽冰泉，殺殺霜刀澀寒鞘。","促節頻催漸繁撥，珠幢斗絕金鈴掉。","千靫鳴鏑發胡弓，萬片清球擊虞廟。","衆樂雖同第一部，德宗皇帝常偏召。","旬休節假暫歸來，一聲狂殺長安少。","主第侯家最難見，挼歌按曲皆承詔。","水精簾外教貴嬪，瑇瑁筵心伴中要。","臣有五賢非此弦，或在拘囚或屠釣。","一賢得進勝累百，兩賢得進同周召。","三賢事漢滅暴彊，四賢鎮岳寧邊徼。","五賢竝用調五常，五常既敘三光耀。","趙璧五弦非此賢，九九何勞設庭燎。"]', '["趙璧五弦彈徵調，徵声巉絕何清峭。","辞雄皓鹤警露啼，失子哀猿繞林嘯。","风入春松正凌亂，鶯含晓舌怜嬌妙。","嗚嗚暗溜咽冰泉，殺殺霜刀澀寒鞘。","促節頻催漸繁撥，珠幢斗絕金鈴掉。","千靫鳴鏑發胡弓，万片清球擊虞廟。","衆乐雖同第一部，德宗皇帝常偏召。","旬休節假暫归来，一声狂殺长安少。","主第侯家最难见，挼歌按曲皆承詔。","水精簾外教貴嬪，瑇瑁筵心伴中要。","臣有五賢非此弦，或在拘囚或屠釣。","一賢得進勝累百，兩賢得進同周召。","三賢事漢滅暴彊，四賢鎮岳寧邊徼。","五賢竝用調五常，五常既敘三光耀。","趙璧五弦非此賢，九九何勞設庭燎。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 五弦彈 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3dbf3c4-e30a-4d37-bfbf-5697282f3c97', '和李校書新題樂府十二首 西涼伎', '和李校书新題乐府十二首 西涼伎', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["吾聞昔日西涼州，人煙撲地桑柘稠。","蒲萄酒熟恣行樂，紅豔青旗朱粉樓。","樓下當壚稱卓女，樓頭伴客名莫愁。","鄉人不識離別苦，更卒多爲沈滯遊。","哥舒開府設高宴，八珍九醞當前頭。","前頭百戲競撩亂，丸劒跳躑霜雪浮。","獅子搖光毛彩豎，胡騰醉舞筋骨柔。","大宛來獻赤汗馬，贊普亦奉翠茸裘。","一朝燕賊亂中國，河湟沒盡空遺丘。","開遠門前萬里堠，今來蹙到行原州。","去京五百而近何其逼，天子縣內半沒爲荒陬。","西涼之道爾阻脩，連城邊將但高會，每聽此曲能不羞。"]', '["吾闻昔日西涼州，人煙撲地桑柘稠。","蒲萄酒熟恣行乐，紅豔青旗朱粉楼。","楼下當壚稱卓女，楼头伴客名莫愁。","乡人不識離別苦，更卒多爲沈滯游。","哥舒开府設高宴，八珍九醞當前头。","前头百戲競撩亂，丸劒跳躑霜雪浮。","獅子搖光毛彩豎，胡腾醉舞筋骨柔。","大宛来獻赤汗马，贊普亦奉翠茸裘。","一朝燕賊亂中国，河湟沒尽空遺丘。","开远门前万里堠，今来蹙到行原州。","去京五百而近何其逼，天子縣內半沒爲荒陬。","西涼之道爾阻脩，連城邊將但高會，每听此曲能不羞。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 西涼伎 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68711ded-7564-4b9b-afd3-711d0bcc78cd', '和李校書新題樂府十二首 法曲', '和李校书新題乐府十二首 法曲', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["吾聞黃帝鼓清角，弭伏熊羆舞玄鶴。","舜持干羽苗革心，堯用咸池鳳巢閣。","大夏濩武皆象功，功多已訝玄功薄。","漢祖過沛亦有歌，秦王破陣非無作。","作之宗廟見艱難，作之軍旅傳糟粕。","明皇度曲多新態，宛轉侵淫易沈著。","赤白桃李取花名，霓裳羽衣號天落。","雅弄雖云已變亂，夷音未得相參錯。","自從胡騎起煙塵，毛毳腥羶滿咸洛。","女爲胡婦學胡妝，伎進胡音務胡樂。","火鳳聲沈多咽絕，春鶯囀罷長蕭索。","胡音胡騎與胡妝，五十年來競紛泊。"]', '["吾闻黄帝鼓清角，弭伏熊羆舞玄鹤。","舜持干羽苗革心，堯用咸池鳳巢閣。","大夏濩武皆象功，功多已訝玄功薄。","漢祖過沛亦有歌，秦王破陣非無作。","作之宗廟见艱难，作之軍旅傳糟粕。","明皇度曲多新態，宛轉侵淫易沈著。","赤白桃李取花名，霓裳羽衣號天落。","雅弄雖云已变亂，夷音未得相參錯。","自從胡騎起煙塵，毛毳腥羶满咸洛。","女爲胡婦学胡妝，伎進胡音務胡乐。","火鳳声沈多咽絕，春鶯囀罷长蕭索。","胡音胡騎與胡妝，五十年来競紛泊。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 法曲 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5663eff3-c9cf-4a2f-beec-36e3616ceaf2', '和李校書新題樂府十二首 馴犀', '和李校书新題乐府十二首 馴犀', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["建中之初放馴象，遠歸林邑近交廣。","獸返深山鳥搆巢，鷹鵰鷂鶻無羈鞅。","貞元之歲貢馴犀，上林置圈官司養。","玉盆金棧非不珍，虎噉狴牢魚食網。","渡江之橘踰汶貉，反時易性安能長。","臘月北風霜雪深，踡跼鱗身遂長往。","行地無疆費傳驛，通天異物罹幽枉。","乃知養獸如養人，不必人人自敦獎。","不擾則得之於理，不奪有以多於賞。","脫衣推食衣食之，不若男耕女令紡。","堯民不自知有堯，但見安閑聊擊壤。","前觀馴象後馴犀，理國其如指諸掌。"]', '["建中之初放馴象，远归林邑近交廣。","獸返深山鸟搆巢，鷹鵰鷂鶻無羈鞅。","貞元之歲貢馴犀，上林置圈官司養。","玉盆金棧非不珍，虎噉狴牢鱼食網。","渡江之橘踰汶貉，反时易性安能长。","臘月北风霜雪深，踡跼鱗身遂长往。","行地無疆費傳驛，通天異物罹幽枉。","乃知養獸如養人，不必人人自敦獎。","不擾則得之於理，不奪有以多於賞。","脫衣推食衣食之，不若男耕女令紡。","堯民不自知有堯，但见安闲聊擊壤。","前观馴象後馴犀，理国其如指諸掌。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 馴犀 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('227fbb31-176f-4e56-aa43-f33b3eef917d', '和李校書新題樂府十二首 立部伎', '和李校书新題乐府十二首 立部伎', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["胡部新聲錦筵坐，中庭漢振高音播。","太宗廟樂傳子孫，取類羣兇陣初破。","戢戢攢槍霜雪耀，騰騰擊鼓雲雷磨。","初疑遇敵身啓行，終象由文士憲左。","昔日高宗常立聽，曲終然後臨玉座。","如今節將一掉頭，電卷風收盡摧挫。","宋晉鄭女歌聲發，滿堂會客齊喧㰤。","珊珊珮玉動腰身，一一貫珠隨咳唾。","頃向圜丘見郊祀，亦曾正旦親朝賀。","太常雅樂備宮懸，九奏未終百寮惰。","惉滯難令季札辨，遲廻但恐文侯臥。","工師盡取聾昧人，豈是先王作之過。","宋沇嘗傳天寶季，法曲胡音忽相和。","明年十月燕寇來，九廟千門虜塵涴我聞此語歎復泣，古來邪正將誰奈。","奸聲入耳佞入心，侏儒飽飯夷齊餓。"]', '["胡部新声錦筵坐，中庭漢振高音播。","太宗廟乐傳子孫，取類羣兇陣初破。","戢戢攢槍霜雪耀，腾腾擊鼓云雷磨。","初疑遇敵身啓行，終象由文士憲左。","昔日高宗常立听，曲終然後臨玉座。","如今節將一掉头，電卷风收尽摧挫。","宋晉鄭女歌声發，满堂會客齊喧㰤。","珊珊珮玉动腰身，一一貫珠隨咳唾。","頃向圜丘见郊祀，亦曾正旦親朝賀。","太常雅乐備宮懸，九奏未終百寮惰。","惉滯难令季札辨，遲廻但恐文侯臥。","工師尽取聾昧人，豈是先王作之過。","宋沇嘗傳天寶季，法曲胡音忽相和。","明年十月燕寇来，九廟千门虜塵涴我闻此語歎复泣，古来邪正將誰奈。","奸声入耳佞入心，侏儒飽飯夷齊餓。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 立部伎 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5deb4404-3d22-4019-95c9-b0c23dbb91cc', '和李校書新題樂府十二首 驃國樂', '和李校书新題乐府十二首 驃国乐', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["驃之樂器頭象駝，音聲不合十二和。","促舞跳趫筋節硬，繁辭變亂名字訛。","千彈萬唱皆咽咽，左旋右轉空傞傞。","俯地呼天終不會，曲成調變當如何。","德宗深意在柔遠，笙鏞不御停嬌娥。","史館書爲朝貢傳，太常編入鞮靺科。","古時陶堯作天子，遜遁親聽康衢歌。","又遣遒人持木鐸，徧采謳謠天下過。","萬人有意皆洞達，四岳不敢施煩苛。","盡令區中擊壤塊，燕及海外覃恩波。","秦霸周衰古官廢，下堙上塞王道頗。","共矜異俗同聲教，不念齊民方薦瘥。","傳稱魚鼈亦咸若，苟能效此誠足多。","借如牛馬未蒙澤，豈在抱甕滋黿鼉。","教化從來有源委，必將泳海先泳河。","是非倒置自古有，驃兮驃兮誰爾訶。"]', '["驃之乐器头象駝，音声不合十二和。","促舞跳趫筋節硬，繁辞变亂名字訛。","千彈万唱皆咽咽，左旋右轉空傞傞。","俯地呼天終不會，曲成調变當如何。","德宗深意在柔远，笙鏞不御停嬌娥。","史館书爲朝貢傳，太常編入鞮靺科。","古时陶堯作天子，遜遁親听康衢歌。","又遣遒人持木鐸，徧采謳謠天下過。","万人有意皆洞達，四岳不敢施煩苛。","尽令區中擊壤塊，燕及海外覃恩波。","秦霸周衰古官廢，下堙上塞王道頗。","共矜異俗同声教，不念齊民方薦瘥。","傳稱鱼鼈亦咸若，苟能效此誠足多。","借如牛马未蒙澤，豈在抱甕滋黿鼉。","教化從来有源委，必將泳海先泳河。","是非倒置自古有，驃兮驃兮誰爾訶。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 驃國樂 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7b809cc-caa8-4dcc-8c46-f0ae914e7ca9', '和李校書新題樂府十二首 胡旋女', '和李校书新題乐府十二首 胡旋女', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["天寶欲末胡欲亂，胡人獻女能胡旋。","旋得明王不覺迷，妖胡奄到長生殿。","胡旋之義世莫知，胡旋之容我能傳。","蓬斷霜根羊角疾，竿戴朱盤火輪炫。","驪珠迸珥逐飛星，虹暈輕巾掣流電。","潛鯨暗噏笡波海，回風亂舞當空霰。","萬過其誰辨終始，四座安能分背面。","才人觀者相爲言，承奉君恩在圜變。","是非好惡隨君口，南北東西逐君眄。","柔輭依身著佩帶，裴回繞指同環釧。","佞臣聞此心計回，熒惑君心君眼眩。","君言似曲屈爲鉤，君言好直舒爲箭。","巧隨清影觸處行，妙學春鶯百般囀。","傾天側地用君力，抑塞周遮恐君見。","翠華南幸萬里橋，玄宗始悟坤維轉寄言旋目與旋心，有國有家當共譴。"]', '["天寶欲末胡欲亂，胡人獻女能胡旋。","旋得明王不覺迷，妖胡奄到长生殿。","胡旋之義世莫知，胡旋之容我能傳。","蓬斷霜根羊角疾，竿戴朱盤火輪炫。","驪珠迸珥逐飞星，虹暈轻巾掣流電。","潛鯨暗噏笡波海，回风亂舞當空霰。","万過其誰辨終始，四座安能分背面。","才人观者相爲言，承奉君恩在圜变。","是非好惡隨君口，南北东西逐君眄。","柔輭依身著佩带，裴回繞指同环釧。","佞臣闻此心計回，熒惑君心君眼眩。","君言似曲屈爲鉤，君言好直舒爲箭。","巧隨清影觸处行，妙学春鶯百般囀。","傾天側地用君力，抑塞周遮恐君见。","翠华南幸万里橋，玄宗始悟坤維轉寄言旋目與旋心，有国有家當共譴。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 胡旋女 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc24eec5-132f-42af-9c19-01108dd28c44', '和李校書新題樂府十二首 蠻子朝', '和李校书新題乐府十二首 蠻子朝', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["西南六詔有遺種，僻在荒陬路尋壅。","部落支離君長賤，比諸夷狄爲幽冗。","犬戎彊盛頻侵削，降有憤心戰無勇。","夜防抄盜保深山，朝望煙塵上高冢。","鳥道繩橋來款附，非因慕化因危悚。","清平官繫金呿嵯，求天叩地持雙珙。","益州大將韋令公，頃實遭時定汧隴。","自居劇鎮無他績，幸得蠻來固恩寵。","爲蠻開道引蠻朝，迎蠻送蠻常繼踵。","天子臨軒四方賀，朝廷無事唯端拱。","漏天走馬春雨寒，瀘水飛蛇瘴煙重。","椎頭醜類除憂患，瘇足役夫勞洶湧。","匈奴互市歲不供，雲蠻通好轡長駷。","戎王養馬漸多年，南人耗顇西人恐。"]', '["西南六詔有遺種，僻在荒陬路尋壅。","部落支離君长賤，比諸夷狄爲幽冗。","犬戎彊盛頻侵削，降有憤心戰無勇。","夜防抄盜保深山，朝望煙塵上高冢。","鸟道繩橋来款附，非因慕化因危悚。","清平官繫金呿嵯，求天叩地持雙珙。","益州大將韋令公，頃實遭时定汧隴。","自居劇鎮無他績，幸得蠻来固恩寵。","爲蠻开道引蠻朝，迎蠻送蠻常繼踵。","天子臨軒四方賀，朝廷無事唯端拱。","漏天走马春雨寒，瀘水飞蛇瘴煙重。","椎头醜類除憂患，瘇足役夫勞洶湧。","匈奴互市歲不供，云蠻通好轡长駷。","戎王養马漸多年，南人耗顇西人恐。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 蠻子朝 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f925f98a-ddf0-4c1e-a5e6-25b624ac1e12', '和李校書新題樂府十二首 縛戎人', '和李校书新題乐府十二首 縛戎人', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["邊頭大將差健卒，入抄禽生快於鶻。","但逢赬面即捉來，半是邊人半戎羯。","大將論功重多級，捷書飛奏何超忽。","聖朝不殺諧至仁，遠送炎方示微罰。","萬里虛勞肉食費，連頭盡被氈裘暍。","華裀重席臥腥臊，病犬愁鴣聲咽嗢。","中有一人能漢語，自言家本長城窟。","少年隨父戍安西，河渭瓜沙眼看沒。","天寶未亂猶數載，狼星四角光蓬勃。","中原禍作邊防危，果有豺狼四來伐。","蕃馬臕成正翹健，蕃兵肉飽爭唐突。","煙塵亂起無亭燧，主帥驚跳棄旄鉞。","半夜城摧鵝雁鳴，妻啼子叫曾不歇。","陰森神廟未敢依，脆薄河冰安可越。","荆棘深處共潛身，前困蒺藜後臲卼。","平明蕃騎四面走，古墓深林盡株榾。","少壯爲俘頭被髠，老翁留居足多刖。","烏鳶滿野尸狼藉，樓榭成灰牆突兀。","暗水濺濺入舊池，平沙漫漫鋪明月。","戎王遣將來安慰，口不敢言心咄咄。","供進腋腋御叱般，豈料穹廬揀肥腯。","五六十年消息絕，中間盟會又猖獗。","眼穿東日望堯雲，腸斷正朝梳漢髮。","近年如此思漢者，半爲老病半埋骨。","常教孫子學鄉音，猶話平時好城闕。","老者儻盡少者壯，生長蕃中似蕃悖。","不知祖父皆漢民，便恐爲蕃心矻矻。","緣邊飽餧十萬衆，何不齊驅一時發。","年年但捉兩三人，精衛銜蘆塞溟渤。"]', '["邊头大將差健卒，入抄禽生快於鶻。","但逢赬面即捉来，半是邊人半戎羯。","大將論功重多級，捷书飞奏何超忽。","聖朝不殺諧至仁，远送炎方示微罰。","万里虛勞肉食費，連头尽被氈裘暍。","华裀重席臥腥臊，病犬愁鴣声咽嗢。","中有一人能漢語，自言家本长城窟。","少年隨父戍安西，河渭瓜沙眼看沒。","天寶未亂猶數載，狼星四角光蓬勃。","中原禍作邊防危，果有豺狼四来伐。","蕃马臕成正翹健，蕃兵肉飽爭唐突。","煙塵亂起無亭燧，主帥驚跳棄旄鉞。","半夜城摧鵝雁鳴，妻啼子叫曾不歇。","陰森神廟未敢依，脆薄河冰安可越。","荆棘深处共潛身，前困蒺藜後臲卼。","平明蕃騎四面走，古墓深林尽株榾。","少壯爲俘头被髠，老翁留居足多刖。","烏鳶满野尸狼藉，楼榭成灰牆突兀。","暗水濺濺入旧池，平沙漫漫鋪明月。","戎王遣將来安慰，口不敢言心咄咄。","供進腋腋御叱般，豈料穹廬揀肥腯。","五六十年消息絕，中间盟會又猖獗。","眼穿东日望堯云，腸斷正朝梳漢髮。","近年如此思漢者，半爲老病半埋骨。","常教孫子学乡音，猶話平时好城闕。","老者儻尽少者壯，生长蕃中似蕃悖。","不知祖父皆漢民，便恐爲蕃心矻矻。","緣邊飽餧十万衆，何不齊驱一时發。","年年但捉兩三人，精衛銜蘆塞溟渤。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 縛戎人 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d8487d4-8d9f-41ed-8455-14af95c78bd4', '和李校書新題樂府十二首 陰山道', '和李校书新題乐府十二首 陰山道', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["年年買馬陰山道，馬死陰山帛空耗。","元和天子念女工，內出金銀代酬犒。","臣有一言昧死進，死生甘分荅恩燾。","費財爲馬不獨生，耗帛傷工有他盜。","臣聞平時七十萬匹馬，關中不省聞嘶噪。","四十八監選龍媒，時貢天庭付良造。","如今坰野十無一，盡在飛龍相踐暴。","萬束芻茭供旦暮，千鍾菽粟長牽漕。","屯軍郡國百餘鎮，縑緗歲奉春冬勞。","稅戶逋逃例攤配，官司折納仍貪冒。","挑紋變䌰力倍費，棄舊從新人所好。","越縠繚綾織一端，十匹素縑功未到。","豪家富賈踰常制，令族清班無雅操。","從騎愛奴絲布衫，臂鷹小兒雲錦韜。","羣臣利己要差僭，天子深衷空憫悼。","綽立花塼鵷鳳行，雨露恩波幾時報。"]', '["年年買马陰山道，马死陰山帛空耗。","元和天子念女工，內出金銀代酬犒。","臣有一言昧死進，死生甘分荅恩燾。","費財爲马不独生，耗帛傷工有他盜。","臣闻平时七十万匹马，关中不省闻嘶噪。","四十八監選龙媒，时貢天庭付良造。","如今坰野十無一，尽在飞龙相踐暴。","万束芻茭供旦暮，千鍾菽粟长牽漕。","屯軍郡国百餘鎮，縑緗歲奉春冬勞。","稅戶逋逃例攤配，官司折納仍貪冒。","挑紋变䌰力倍費，棄旧從新人所好。","越縠繚綾织一端，十匹素縑功未到。","豪家富賈踰常制，令族清班無雅操。","從騎愛奴絲布衫，臂鷹小兒云錦韜。","羣臣利己要差僭，天子深衷空憫悼。","綽立花塼鵷鳳行，雨露恩波幾时報。"]', '诗', 'shi', '', NULL, '和李校書新題樂府十二首 陰山道 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10552516-d84b-43d1-afea-a3b5aa7a8581', '有鳥二十章 一', '有鸟二十章 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥名老鴟，鴟張貪很老不衰。","似鷹指爪唯攫肉，戾天羽翮徒翰飛。","朝偷暮竊恣昏飽，後顧前瞻高樹枝。","珠丸彈射死不去，意在護巢兼護兒。"]', '["有鸟有鸟名老鴟，鴟張貪很老不衰。","似鷹指爪唯攫肉，戾天羽翮徒翰飞。","朝偷暮竊恣昏飽，後顧前瞻高樹枝。","珠丸彈射死不去，意在護巢兼護兒。"]', '诗', 'shi', '', NULL, '有鳥二十章 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bf3ae6b-1a13-4b55-a429-65f57f4b0c29', '有鳥二十章 二', '有鸟二十章 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥毛似鶴，行步雖遲性靈惡。","主人但見閑慢容，許占蓬萊最高閣。","弱羽長憂俊鶻拳，疽腸暗著鵷雛啄。","千年不死伴靈龜，梟心鶴貌何人覺。"]', '["有鸟有鸟毛似鹤，行步雖遲性靈惡。","主人但见闲慢容，許占蓬萊最高閣。","弱羽长憂俊鶻拳，疽腸暗著鵷雛啄。","千年不死伴靈龟，梟心鹤貌何人覺。"]', '诗', 'shi', '', NULL, '有鳥二十章 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65247e61-4db8-432a-a236-cf36329605ce', '有鳥二十章 三', '有鸟二十章 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥如鸛雀，食蛇抱礐天姿惡。","行經水滸爲毒流，羽拂酒杯爲死藥。","漢后忍渴天豈知，驪姬墳地君寧覺。","嗚呼爲有白色毛，亦得乘軒謬稱鶴。"]', '["有鸟有鸟如鸛雀，食蛇抱礐天姿惡。","行經水滸爲毒流，羽拂酒杯爲死藥。","漢后忍渴天豈知，驪姬墳地君寧覺。","嗚呼爲有白色毛，亦得乘軒謬稱鹤。"]', '诗', 'shi', '', NULL, '有鳥二十章 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad8858a8-53aa-4d5d-9e02-63d622229ee0', '有鳥二十章 四', '有鸟二十章 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥名爲鳩，毛衣輭毳心性柔。","鶻緣暖足憐不喫，鷂爲同科曾共游。","飛飛漸上高高閣，百鳥不猜稱好逑。","佳人許伴鵷雛食，望爾化爲張氏鉤。"]', '["有鸟有鸟名爲鳩，毛衣輭毳心性柔。","鶻緣暖足怜不喫，鷂爲同科曾共游。","飞飞漸上高高閣，百鸟不猜稱好逑。","佳人許伴鵷雛食，望爾化爲張氏鉤。"]', '诗', 'shi', '', NULL, '有鳥二十章 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da427a5-0339-4a15-9443-6a9ff8456b00', '有鳥二十章 五', '有鸟二十章 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥名野雞，天姿耿介行步齊。","主人偏養憐整頓，玉粟充腸瑤樹栖。","池塘潛狎不鳴雁，津梁暗引無用鵜。","秋鷹迸逐霜鶻遠，鵩鳥護巢當晝啼。","主人頻問遣妖術，力盡計窮音響悽。","當時何不早量分，莫遣輝光深照泥。"]', '["有鸟有鸟名野雞，天姿耿介行步齊。","主人偏養怜整頓，玉粟充腸瑤樹栖。","池塘潛狎不鳴雁，津梁暗引無用鵜。","秋鷹迸逐霜鶻远，鵩鸟護巢當晝啼。","主人頻问遣妖術，力尽計窮音响悽。","當时何不早量分，莫遣輝光深照泥。"]', '诗', 'shi', '', NULL, '有鳥二十章 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f29c90a2-a21d-4f31-9da3-480022d62c12', '有鳥二十章 六', '有鸟二十章 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥羣翠碧，毛羽短長心竝窄。","皆曾偷食淥池魚，前去後來更逼迫。","食魚滿腹各自飛，池上見人長似客。","飛飛競占嘉樹林，百鳥不爭緣鳳惜。"]', '["有鸟有鸟羣翠碧，毛羽短长心竝窄。","皆曾偷食淥池鱼，前去後来更逼迫。","食鱼满腹各自飞，池上见人长似客。","飞飞競占嘉樹林，百鸟不爭緣鳳惜。"]', '诗', 'shi', '', NULL, '有鳥二十章 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14418c40-8711-4298-8d39-83728bc95484', '有鳥二十章 七', '有鸟二十章 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥羣紙鳶，因風假勢童子牽。","去地漸高人眼亂，世人爲爾羽毛全。","風吹繩斷童子走，餘勢尚存猶在天。","愁爾一朝還到地，落在深泥誰復憐。"]', '["有鸟有鸟羣紙鳶，因风假勢童子牽。","去地漸高人眼亂，世人爲爾羽毛全。","风吹繩斷童子走，餘勢尚存猶在天。","愁爾一朝還到地，落在深泥誰复怜。"]', '诗', 'shi', '', NULL, '有鳥二十章 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a787853-f034-4a5e-8e02-bc5f3a95cd1c', '有鳥二十章 八', '有鸟二十章 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥名啄木，木中求食常不足。","偏啄鄧林求一蟲，蟲孔未穿長觜禿。","木皮已穴蟲在信，蟲蝕木心根柢覆。","可憐樹上百鳥兒，有時飛向新林宿。"]', '["有鸟有鸟名啄木，木中求食常不足。","偏啄鄧林求一蟲，蟲孔未穿长觜禿。","木皮已穴蟲在信，蟲蝕木心根柢覆。","可怜樹上百鸟兒，有时飞向新林宿。"]', '诗', 'shi', '', NULL, '有鳥二十章 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9343276f-7c83-4e34-b6ec-f222da7af8ee', '有鳥二十章 九', '有鸟二十章 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥衆蝙蝠，長伴佳人占華屋。","妖鼠多年羽翮生，不辨雌雄無本族。","穿墉伺隙善潛身，晝伏宵飛惡明燭。","大廈雖存柱石傾，暗齧棟梁成蠹木。"]', '["有鸟有鸟衆蝙蝠，长伴佳人占华屋。","妖鼠多年羽翮生，不辨雌雄無本族。","穿墉伺隙善潛身，晝伏宵飞惡明燭。","大廈雖存柱石傾，暗齧棟梁成蠹木。"]', '诗', 'shi', '', NULL, '有鳥二十章 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a7813b-5020-4970-9d89-4ac4cafb7ca4', '有鳥二十章 十', '有鸟二十章 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥名爲鴞，深藏孔穴難動搖。","鷹鸇繞樹探不得，隨珠彈盡聲轉嬌。","主人煩惑罷擒取，許占神林爲物妖。"]', '["有鸟有鸟名爲鴞，深藏孔穴难动搖。","鷹鸇繞樹探不得，隨珠彈尽声轉嬌。","主人煩惑罷擒取，許占神林爲物妖。"]', '诗', 'shi', '', NULL, '有鳥二十章 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b71f5e31-bd8b-42ab-89e5-73f7b5c21342', '有鳥二十章 十一', '有鸟二十章 十一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥名燕子，口中未省無泥滓。","春風吹送廊廡間，秋社驅將嵌孔裏。","雷驚雨灑一時蘇，雲壓霜摧半年死。","驅去驅來長信風，暫託棟梁何用喜。"]', '["有鸟有鸟名燕子，口中未省無泥滓。","春风吹送廊廡间，秋社驱將嵌孔裏。","雷驚雨灑一时蘇，云壓霜摧半年死。","驱去驱来长信风，暫託棟梁何用喜。"]', '诗', 'shi', '', NULL, '有鳥二十章 十一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d212155-6f49-43cf-aa4f-45c9ca08f944', '有鳥二十章 十二', '有鸟二十章 十二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥名老烏，貪癡突誖天下無。","田中攫肉吞不足，偏入諸巢探衆雛。","歸來仍占主人樹，腹飽巢高聲響麤。","山鵶野鵲閑受肉，鳳皇不得聞罪辜。","秋鷹掣斷架上索，利爪一揮毛血落。","可憐鵶鵲慕腥羶，猶向巢邊競紛泊。"]', '["有鸟有鸟名老烏，貪癡突誖天下無。","田中攫肉吞不足，偏入諸巢探衆雛。","归来仍占主人樹，腹飽巢高声响麤。","山鵶野鵲闲受肉，鳳皇不得闻罪辜。","秋鷹掣斷架上索，利爪一揮毛血落。","可怜鵶鵲慕腥羶，猶向巢邊競紛泊。"]', '诗', 'shi', '', NULL, '有鳥二十章 十二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0726816-032e-4b36-9c6f-8e5eb382064d', '有鳥二十章 十三', '有鸟二十章 十三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥謂白鷴，雪毛皓白紅觜殷。","貴人妾婦愛光彩，行提坐臂怡朱顏。","妖姬謝寵辭金屋，雕籠又伴新人宿。","無心爲主擬銜花，空長白毛映紅肉。"]', '["有鸟有鸟謂白鷴，雪毛皓白紅觜殷。","貴人妾婦愛光彩，行提坐臂怡朱顏。","妖姬謝寵辞金屋，雕籠又伴新人宿。","無心爲主擬銜花，空长白毛映紅肉。"]', '诗', 'shi', '', NULL, '有鳥二十章 十三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f903c49-7695-4505-89da-b2710b250e4a', '有鳥二十章 十四', '有鸟二十章 十四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥羣雀兒，中庭啄粟籬上飛。","秋鷹欺小嫌不食，鳳皇容衆從爾隨。","大鵬忽起遮白日，餘風簸蕩山岳移。","翩翾百萬徒驚噪，扶搖勢遠何由知。","古來妄說銜花報，縱解銜花何所爲。","可惜官倉無限粟，伯夷餓死黃口肥。"]', '["有鸟有鸟羣雀兒，中庭啄粟籬上飞。","秋鷹欺小嫌不食，鳳皇容衆從爾隨。","大鵬忽起遮白日，餘风簸蕩山岳移。","翩翾百万徒驚噪，扶搖勢远何由知。","古来妄说銜花報，縱解銜花何所爲。","可惜官倉無限粟，伯夷餓死黄口肥。"]', '诗', 'shi', '', NULL, '有鳥二十章 十四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fe4f4b5-8251-41f7-b2c9-c8f6fe3f37c2', '有鳥二十章 十五', '有鸟二十章 十五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥皆百舌，舌端百囀聲咄㗌。","先春盡學百鳥啼，真僞不分聽者悅。","伶倫鳳律亂宮商，盤木天雞誤時節。","朝朝暮暮主人耳，桃李無言管弦咽。","五月炎光朱火盛，陽燄燒陰幽響絕。","安知不是卷舌星，化作剛刀一時截。"]', '["有鸟有鸟皆百舌，舌端百囀声咄㗌。","先春尽学百鸟啼，真僞不分听者悅。","伶倫鳳律亂宮商，盤木天雞誤时節。","朝朝暮暮主人耳，桃李無言管弦咽。","五月炎光朱火盛，陽燄燒陰幽响絕。","安知不是卷舌星，化作剛刀一时截。"]', '诗', 'shi', '', NULL, '有鳥二十章 十五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8477519a-d221-4ee5-b8aa-8c88558b4368', '有鳥二十章 十六', '有鸟二十章 十六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥毛羽黃，雄者爲鴛雌者鴦。","主人幷養七十二，羅列雕籠開洞房。","雄鳴一聲雌鼓翼，夜不得栖朝不食。","氣息榻然雙翅垂，猶入籠中就顏色。"]', '["有鸟有鸟毛羽黄，雄者爲鴛雌者鴦。","主人幷養七十二，羅列雕籠开洞房。","雄鳴一声雌鼓翼，夜不得栖朝不食。","氣息榻然雙翅垂，猶入籠中就顏色。"]', '诗', 'shi', '', NULL, '有鳥二十章 十六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50923de2-a14a-4bdf-a02e-67afaf8d122a', '有鳥二十章 十七', '有鸟二十章 十七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥名鷂雛，鈴子眼睛蒼錦襦。","貴人腕輭憐易臂，奮肘一揮前後呼。","俊鶻無由拳狡兔，金雕不得擒魅狐。","文王長在苑中獵，何日非熊休賣屠。"]', '["有鸟有鸟名鷂雛，鈴子眼睛蒼錦襦。","貴人腕輭怜易臂，奮肘一揮前後呼。","俊鶻無由拳狡兔，金雕不得擒魅狐。","文王长在苑中獵，何日非熊休賣屠。"]', '诗', 'shi', '', NULL, '有鳥二十章 十七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1147622f-41a8-4111-8d0f-440cd9ef98c6', '有鳥二十章 十八', '有鸟二十章 十八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥名鸚鵡，養在雕籠解人語。","主人曾問私所聞，因說妖姬暗欺主。","主人方惑翻見疑，趁歸隴底雙翅垂。","山鵶野雀怪鸚語，競噪爭窺無已時。","君不見隋朝隴頭姥，嬌養雙鸚囑新婦。","一鸚曾說婦無儀，悍婦殺鸚欺主母。","一鸚閉口不復言，母問不言何太久。","鸚言悍婦殺鸚由，母爲逐之鄉里醜。","當時主母信爾言，顧爾微禽命何有。","今之主人翻爾疑，何事籠中漫開口。"]', '["有鸟有鸟名鸚鵡，養在雕籠解人語。","主人曾问私所闻，因说妖姬暗欺主。","主人方惑翻见疑，趁归隴底雙翅垂。","山鵶野雀怪鸚語，競噪爭窺無已时。","君不见隋朝隴头姥，嬌養雙鸚囑新婦。","一鸚曾说婦無儀，悍婦殺鸚欺主母。","一鸚閉口不复言，母问不言何太久。","鸚言悍婦殺鸚由，母爲逐之乡里醜。","當时主母信爾言，顧爾微禽命何有。","今之主人翻爾疑，何事籠中漫开口。"]', '诗', 'shi', '', NULL, '有鳥二十章 十八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2744b904-f72e-49b5-badf-0d8180e22f82', '有鳥二十章 十九', '有鸟二十章 十九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥名俊鶻，鷂小鵰癡俊無匹。","雛鴨拂爪血迸天，狡兔中拳頭粉骨。","平明度海朝未食，拔上秋空雲影沒。","瞥然飛下人不知，攪碎荒城魅狐窟。"]', '["有鸟有鸟名俊鶻，鷂小鵰癡俊無匹。","雛鴨拂爪血迸天，狡兔中拳头粉骨。","平明度海朝未食，拔上秋空云影沒。","瞥然飞下人不知，攪碎荒城魅狐窟。"]', '诗', 'shi', '', NULL, '有鳥二十章 十九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb7bd301-b8bd-4683-ba3e-bfc014cb4064', '有鳥二十章 二十', '有鸟二十章 二十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有鳥有鳥真白鶴，飛上九霄雲漠漠。","司晨守夜悲雞犬，啄腐吞腥笑鵰鶚。","堯年值雪度關山，晉室聞琴下寥廓。","遼東盡爾千歲人，悵望橋邊舊城郭。"]', '["有鸟有鸟真白鹤，飞上九霄云漠漠。","司晨守夜悲雞犬，啄腐吞腥笑鵰鶚。","堯年值雪度关山，晉室闻琴下寥廓。","遼东尽爾千歲人，悵望橋邊旧城郭。"]', '诗', 'shi', '', NULL, '有鳥二十章 二十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6acceec3-68d6-4e33-8386-901930cb01fe', '有酒十章 一', '有酒十章 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有酒有酒雞初鳴，夜長睡足神慮清。","悄然危坐心不平，浩思一氣初彭亨。","澒洞浩汗真無名，胡不終渾成。","胡爲沈濁以升清，矗然分畫高下程。","天蒸地鬱羣動萌，毛鱗裸介如鬇鬡。","嗚呼萬物紛已生，我可奈何兮杯一傾。"]', '["有酒有酒雞初鳴，夜长睡足神慮清。","悄然危坐心不平，浩思一氣初彭亨。","澒洞浩汗真無名，胡不終渾成。","胡爲沈濁以升清，矗然分畫高下程。","天蒸地鬱羣动萌，毛鱗裸介如鬇鬡。","嗚呼万物紛已生，我可奈何兮杯一傾。"]', '诗', 'shi', '', NULL, '有酒十章 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cae9a98-ea56-45b1-8853-db959cd6f414', '有酒十章 二', '有酒十章 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有酒有酒東方明，一杯既進吞元精。","尚思天地之始名，一元既二分濁清。","地居方直天體明，胡不八荒圢圢如砥平。","胡山高屹崪海泓澄，胡不日車杲杲晝夜行。","胡爲月輪滅缺星𥋝盯，嗚呼不得真宰情，我可奈何兮杯再傾。"]', '["有酒有酒东方明，一杯既進吞元精。","尚思天地之始名，一元既二分濁清。","地居方直天體明，胡不八荒圢圢如砥平。","胡山高屹崪海泓澄，胡不日车杲杲晝夜行。","胡爲月輪滅缺星𥋝盯，嗚呼不得真宰情，我可奈何兮杯再傾。"]', '诗', 'shi', '', NULL, '有酒十章 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e230b2c3-83cd-43a1-ac7c-0c76fd7a60d5', '有酒十章 三', '有酒十章 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有酒有酒兮湛淥波，飲將愉兮氣彌和。","念萬古之紛羅，我獨慨然而浩歌。","歌曰：天耶，地耶。","肇萬物耶，儲胥大庭之君耶。","恍耶，忽耶。","有耶，傳而信耶。","久而謬耶，文字生而羲農作耶。","仁義別而聖賢出耶，炎始暴耶。","蚩尤熾耶，軒轅戰耶。","不得已耶，仁耶。","聖耶，愍人之毒耶。","天蕩蕩耶，堯穆穆耶。","豈其讓耶，歸有德耶。","舜其貪耶，德能嗣耶。","豈其讓耶，授有功耶。","禹功大耶，人戴之耶。","益不逮耶，啓能德耶。","家天下耶，榮後嗣耶。","於後嗣之榮則可耶，於天下之榮其可耶。","嗚呼遠堯舜之日耶，何棄舜之速耶。","辛癸虐耶，湯武革耶。","順天意耶，公天下耶。","踵夏榮嗣，私其公耶。","竝建萬國，均其私耶。","專征遞伐，鬬海內耶。","秦埽其類，威定之耶。","二代而隕，守不仁耶。","漢魏而降，乘其機耶。","短長理亂，繫其術耶。","堯耶，舜耶。","終不可逮耶，將德之者不位。","位者不逮其德耶，時耶。","時耶，時其可耶，我可奈何兮一杯又進歌且歌。"]', '["有酒有酒兮湛淥波，饮將愉兮氣彌和。","念万古之紛羅，我独慨然而浩歌。","歌曰：天耶，地耶。","肇万物耶，儲胥大庭之君耶。","恍耶，忽耶。","有耶，傳而信耶。","久而謬耶，文字生而羲農作耶。","仁義別而聖賢出耶，炎始暴耶。","蚩尤熾耶，軒轅戰耶。","不得已耶，仁耶。","聖耶，愍人之毒耶。","天蕩蕩耶，堯穆穆耶。","豈其讓耶，归有德耶。","舜其貪耶，德能嗣耶。","豈其讓耶，授有功耶。","禹功大耶，人戴之耶。","益不逮耶，啓能德耶。","家天下耶，榮後嗣耶。","於後嗣之榮則可耶，於天下之榮其可耶。","嗚呼远堯舜之日耶，何棄舜之速耶。","辛癸虐耶，湯武革耶。","順天意耶，公天下耶。","踵夏榮嗣，私其公耶。","竝建万国，均其私耶。","專征遞伐，鬬海內耶。","秦埽其類，威定之耶。","二代而隕，守不仁耶。","漢魏而降，乘其機耶。","短长理亂，繫其術耶。","堯耶，舜耶。","終不可逮耶，將德之者不位。","位者不逮其德耶，时耶。","时耶，时其可耶，我可奈何兮一杯又進歌且歌。"]', '诗', 'shi', '', NULL, '有酒十章 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('164aa318-3aae-4fd5-a15c-f278cb50f744', '有酒十章 四', '有酒十章 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有酒有酒兮黯兮溟，仰天大呼兮。","天漫漫兮高兮青，高兮漫兮吾孰知天否與靈。","取人之仰者，無乃在乎昭昭乎曰與夫日星。","何三光之竝照兮，奄雲雨之冥冥。","幽妖倏忽兮水怪族形，黿鼉岸走兮海若鬬鯨。","河潰潰兮愈濁，濟翻翻兮不寧。","蛇噴雲而出穴，虎嘯風兮屢鳴。","汙高巢而鳳去兮，溺厚地而芝蘭以之不生。","葵心傾兮何向，松影直而孰明。","人懼愁兮戴榮，天寂默兮無聲。","嗚呼！天在雲之上兮，人在雲之下兮。","又安能決雲而上征，嗚呼。","既上征之不可兮，我奈何兮杯復傾。"]', '["有酒有酒兮黯兮溟，仰天大呼兮。","天漫漫兮高兮青，高兮漫兮吾孰知天否與靈。","取人之仰者，無乃在乎昭昭乎曰與夫日星。","何三光之竝照兮，奄云雨之冥冥。","幽妖倏忽兮水怪族形，黿鼉岸走兮海若鬬鯨。","河潰潰兮愈濁，濟翻翻兮不寧。","蛇噴云而出穴，虎嘯风兮屢鳴。","汙高巢而鳳去兮，溺厚地而芝蘭以之不生。","葵心傾兮何向，松影直而孰明。","人懼愁兮戴榮，天寂默兮無声。","嗚呼！天在云之上兮，人在云之下兮。","又安能決云而上征，嗚呼。","既上征之不可兮，我奈何兮杯复傾。"]', '诗', 'shi', '', NULL, '有酒十章 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80c69cc-cdcb-461a-a0e7-2f228baff17b', '有酒十章 五', '有酒十章 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有酒有酒香滿尊，君寧不飲開君顏。","豈不知君飲此心恨，君今獨醒誰與言。","君寧不見颶風翻海火燎原，巨鼇唐突高燄延。","精衛銜蘆塞海溢，枯魚噴沫救池燔。","筋疲力竭波更大，鰭燋甲裂身已乾。","有翼勸爾升九天，有鱗勸爾登龍門。","九天下視日月轉，龍門上激雷雨奔。","螗蜋雖怒誰爾懼，鶡旦雖啼誰爾憐。","摶空意遠風來壯，我可奈何兮一杯又進消我煩。"]', '["有酒有酒香满尊，君寧不饮开君顏。","豈不知君饮此心恨，君今独醒誰與言。","君寧不见颶风翻海火燎原，巨鼇唐突高燄延。","精衛銜蘆塞海溢，枯鱼噴沫救池燔。","筋疲力竭波更大，鰭燋甲裂身已乾。","有翼勸爾升九天，有鱗勸爾登龙门。","九天下視日月轉，龙门上激雷雨奔。","螗蜋雖怒誰爾懼，鶡旦雖啼誰爾怜。","摶空意远风来壯，我可奈何兮一杯又進消我煩。"]', '诗', 'shi', '', NULL, '有酒十章 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06276d06-ff4a-4f9b-b867-d83d17fbcb7e', '有酒十章 六', '有酒十章 六', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有酒有酒歌且哀，江春例早多早梅。","櫻桃桃李相續開，間以木蘭之秀香裴回。","東風吹盡南風來，鶯聲漸澀花摧隤。","四月清和豔殘卉，芍藥翻紅蒲映水。","夏龍痡毒雷雨多，蒲葉離披豔紅死。","紅豔猶存榴樹花，紫苞欲綻高筍牙。","筍牙成竹冒霜雪，榴花落地還銷歇。","萬古盈虧相逐行，君看夜夜當窗月。","榮落虧盈可奈何，生成未徧霜霰過。","霜霰過兮復奈何，靈芝敻絕荆棘多。","荆棘多兮可奈何，可奈何兮終奈何。","秦皇堯舜俱腐骨，我可奈何兮又進一杯歌復歌。"]', '["有酒有酒歌且哀，江春例早多早梅。","櫻桃桃李相續开，间以木蘭之秀香裴回。","东风吹尽南风来，鶯声漸澀花摧隤。","四月清和豔殘卉，芍藥翻紅蒲映水。","夏龙痡毒雷雨多，蒲葉離披豔紅死。","紅豔猶存榴樹花，紫苞欲綻高筍牙。","筍牙成竹冒霜雪，榴花落地還銷歇。","万古盈虧相逐行，君看夜夜當窗月。","榮落虧盈可奈何，生成未徧霜霰過。","霜霰過兮复奈何，靈芝敻絕荆棘多。","荆棘多兮可奈何，可奈何兮終奈何。","秦皇堯舜俱腐骨，我可奈何兮又進一杯歌复歌。"]', '诗', 'shi', '', NULL, '有酒十章 六 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a61f06f-f695-484b-af4c-670de001ab5b', '有酒十章 七', '有酒十章 七', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有酒有酒方爛漫，飲酣拔劒心眼亂。","聲若雷砰目流電，醉舞翻環身眩轉。","乾綱倒軋坤維旋，白日橫空星宿見，一夫心醉萬物變。","何況蚩尤之蹴蹋，安得不以熊羆戰。","嗚呼！風后力牧得親見，我可奈何兮又進一杯除健羨。"]', '["有酒有酒方爛漫，饮酣拔劒心眼亂。","声若雷砰目流電，醉舞翻环身眩轉。","乾綱倒軋坤維旋，白日橫空星宿见，一夫心醉万物变。","何況蚩尤之蹴蹋，安得不以熊羆戰。","嗚呼！风后力牧得親见，我可奈何兮又進一杯除健羨。"]', '诗', 'shi', '', NULL, '有酒十章 七 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7956f1c-64bd-4a54-b3b8-364eb1c4aae9', '有酒十章 八', '有酒十章 八', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有酒有酒兮告臨江，風漫漫兮波長。","渺渺兮注海，海蒼蒼兮路茫茫。","彼萬流之混入兮，又安能分若畎澮淮河與夫岷吳之巨江。","味作鹹而若一，雖甘淡兮誰謂爾爲良。","濟涓涓而縷貫，將奈何兮萬里之渾黃。","鯨歸穴兮渤溢，鼇載山兮低昂。","陰火然兮衆族沸渭，颶風作兮晝夜猖狂。","顧千珍與萬怪兮，皆委潤而深藏。","信天地之瀦蓄兮，我可奈何兮一杯又進兮包大荒。"]', '["有酒有酒兮告臨江，风漫漫兮波长。","渺渺兮注海，海蒼蒼兮路茫茫。","彼万流之混入兮，又安能分若畎澮淮河與夫岷吳之巨江。","味作鹹而若一，雖甘淡兮誰謂爾爲良。","濟涓涓而縷貫，將奈何兮万里之渾黄。","鯨归穴兮渤溢，鼇載山兮低昂。","陰火然兮衆族沸渭，颶风作兮晝夜猖狂。","顧千珍與万怪兮，皆委潤而深藏。","信天地之瀦蓄兮，我可奈何兮一杯又進兮包大荒。"]', '诗', 'shi', '', NULL, '有酒十章 八 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed87f022-102c-44ad-9e41-45b0d46aa7fc', '有酒十章 九', '有酒十章 九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有酒有酒兮日將落，餘光委照在林薄。","陽烏撩亂兮屋上栖，陰怪跳趫兮水中躍。","月爭光兮星又繁，燒橫空兮燄仍爍。","我可奈何兮時既昏，一杯又進兮聊處廓。"]', '["有酒有酒兮日將落，餘光委照在林薄。","陽烏撩亂兮屋上栖，陰怪跳趫兮水中躍。","月爭光兮星又繁，燒橫空兮燄仍爍。","我可奈何兮时既昏，一杯又進兮聊处廓。"]', '诗', 'shi', '', NULL, '有酒十章 九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba6a6549-70ea-4296-ad36-63ce8a93b5d6', '有酒十章 十', '有酒十章 十', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有酒有酒兮再祝，祝予心兮何欲。","欲天泰而地寧，欲人康而歲熟。","欲鳳翥而鵷隨兮，欲龍亨而驥逐。","欲日盛而星微兮，欲滋蘭而殲毒。","欲人欲而天從，苟天未從兮，我可奈何兮一杯又進聊自足。"]', '["有酒有酒兮再祝，祝予心兮何欲。","欲天泰而地寧，欲人康而歲熟。","欲鳳翥而鵷隨兮，欲龙亨而驥逐。","欲日盛而星微兮，欲滋蘭而殲毒。","欲人欲而天從，苟天未從兮，我可奈何兮一杯又進聊自足。"]', '诗', 'shi', '', NULL, '有酒十章 十 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16147bf3-1a81-4699-ad1b-fa25fd1bfcb2', '華之巫', '华之巫', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["有一人兮神之側，廟森森兮神默默。","神默默兮可奈何，願一見神兮何可得。","女巫索我何所有，神之開閉予之手。","我能進若神之前，神不自言寄予口。","爾欲見神安爾身，買我神錢沽我酒。","我家又有神之盤，爾進此盤神爾安。","此盤不進行路難，陸有摧車舟有瀾。","我聞此語長太息，豈有神明欺正直。","爾居大道誰南北，恣矯神言假神力。","假神力兮神未悟，行道之人不得度。","我欲見神誅爾巫，豈是因巫假神祜。","爾巫，爾巫。","爾獨不聞乎？","與其媚於奧，不若媚於竈。","使我傾心事爾巫，吾寧驅車守吾道。","爾巫爾巫且相保，吾心自有丘之禱。"]', '["有一人兮神之側，廟森森兮神默默。","神默默兮可奈何，願一见神兮何可得。","女巫索我何所有，神之开閉予之手。","我能進若神之前，神不自言寄予口。","爾欲见神安爾身，買我神錢沽我酒。","我家又有神之盤，爾進此盤神爾安。","此盤不進行路难，陸有摧车舟有瀾。","我闻此語长太息，豈有神明欺正直。","爾居大道誰南北，恣矯神言假神力。","假神力兮神未悟，行道之人不得度。","我欲见神誅爾巫，豈是因巫假神祜。","爾巫，爾巫。","爾独不闻乎？","與其媚於奧，不若媚於竈。","使我傾心事爾巫，吾寧驱车守吾道。","爾巫爾巫且相保，吾心自有丘之禱。"]', '诗', 'shi', '', NULL, '華之巫 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('276771ed-6210-4d63-b145-80d27a03091c', '廟之神', '廟之神', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["我馬煩兮釋我車，神之廟兮山之阿。","予一拜而一祝，祝予心之無涯。","涕汍瀾而零落，神寂默而無譁。","神兮，神兮。","奈神之寂默而不言何，復再拜而再祝。","鼓吾腹兮歌吾歌，歌曰。","今耶，古耶。","有耶，無耶。","福不自神耶，神不福人耶。","巫爾惑耶，稔而誅耶。","謁不得耶，終不可謁耶。","返吾駕而遵吾道，廟之木兮山之花。"]', '["我马煩兮釋我车，神之廟兮山之阿。","予一拜而一祝，祝予心之無涯。","涕汍瀾而零落，神寂默而無譁。","神兮，神兮。","奈神之寂默而不言何，复再拜而再祝。","鼓吾腹兮歌吾歌，歌曰。","今耶，古耶。","有耶，無耶。","福不自神耶，神不福人耶。","巫爾惑耶，稔而誅耶。","謁不得耶，終不可謁耶。","返吾駕而遵吾道，廟之木兮山之花。"]', '诗', 'shi', '', NULL, '廟之神 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c92f93b-48e5-40bf-b4c9-78c84d0e987c', '村花晚', '村花晚', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["三春已暮桃李傷，棠梨花白蔓菁黃。","村中女兒爭摘將，插刺頭鬢相誇張。","田翁蠶老迷臭香，曬暴𢽱𣀳熏衣裳。","非無後秀與孤芳，奈爾千株萬頃之茫茫。","天公此意何可量，長教爾輩時節長。"]', '["三春已暮桃李傷，棠梨花白蔓菁黄。","村中女兒爭摘將，插刺头鬢相誇張。","田翁蠶老迷臭香，曬暴𢽱𣀳熏衣裳。","非無後秀與孤芳，奈爾千株万頃之茫茫。","天公此意何可量，长教爾輩时節长。"]', '诗', 'shi', '', NULL, '村花晚 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a77e8de6-b1d1-478a-b0d1-f610c95b1f5e', '紫躑躅', '紫躑躅', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["紫躑躅，滅紫攏帬倚山腹。","文君新寡乍歸來，羞怨春風不能哭。","我從相識便相憐，但是花叢不迴目。","去年春別湘水頭，今年夏見青山曲。","迢迢遠在青山上，山高水闊難容足。","願爲朝日早相暾，願作輕風暗相觸。","爾躑躅，我向通州爾幽獨。","可憐今夜宿青山，何年卻向青山宿。","山花漸暗月漸明，月照空山滿山綠。"]', '["紫躑躅，滅紫攏帬倚山腹。","文君新寡乍归来，羞怨春风不能哭。","我從相識便相怜，但是花叢不迴目。","去年春別湘水头，今年夏见青山曲。","迢迢远在青山上，山高水闊难容足。","願爲朝日早相暾，願作轻风暗相觸。","爾躑躅，我向通州爾幽独。","可怜今夜宿青山，何年卻向青山宿。","山花漸暗月漸明，月照空山满山綠。"]', '诗', 'shi', '', NULL, '紫躑躅 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faffa10f-f063-4447-a22a-569815771787', '山枇杷', '山枇杷', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["山枇杷，花似牡丹殷潑血。","往年乘傳過青山，正值山花好時節。","壓枝凝豔已全開，映葉香苞纔半裂。","緊搏紅袖欲支頤，慢解絳囊初破結。","金線叢飄繁蘂亂，珊瑚朵重纖莖折。","因風旋落帬片飛，帶日斜看目精熱。","亞水依巖半傾側，籠雲隱霧多愁絕。","綠珠語盡身欲投，漢武眼穿神漸滅。","穠姿秀色人皆愛，怨媚羞容我偏別。","說向閑人人不聽，曾向樂天時一說。","昨來谷口先相問，及到山前已消歇。","左降通州十日遲，又與幽花一年別。","山枇杷，爾託深山何太拙。","天高萬里看不精，帝在九重聲不徹。","園中杏樹良人醉，陌上柳枝年少折。","因爾幽芳喻昔賢，磻谿冷坐權門咽。"]', '["山枇杷，花似牡丹殷潑血。","往年乘傳過青山，正值山花好时節。","壓枝凝豔已全开，映葉香苞纔半裂。","緊搏紅袖欲支頤，慢解絳囊初破結。","金線叢飄繁蘂亂，珊瑚朵重纖莖折。","因风旋落帬片飞，带日斜看目精熱。","亞水依巖半傾側，籠云隐霧多愁絕。","綠珠語尽身欲投，漢武眼穿神漸滅。","穠姿秀色人皆愛，怨媚羞容我偏別。","说向闲人人不听，曾向乐天时一说。","昨来谷口先相问，及到山前已消歇。","左降通州十日遲，又與幽花一年別。","山枇杷，爾託深山何太拙。","天高万里看不精，帝在九重声不徹。","园中杏樹良人醉，陌上柳枝年少折。","因爾幽芳喻昔賢，磻谿冷坐權门咽。"]', '诗', 'shi', '', NULL, '山枇杷 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bad57ac-1f5f-41b9-af2e-ae1bb1a35834', '樹上烏', '樹上烏', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["樹上烏，洲中有樹巢若鋪。","百巢一樹知幾烏，一烏不下三四雛。","雛又生雛知幾雛，老烏未死雛已烏。","散向人間何處無，攫麑啄卵方可食。","男女羣強最多力，靈蛇萬古唯一珠。","豈可抨彈千萬億，吾不會天教爾輩多子孫，告訴天公天不言。"]', '["樹上烏，洲中有樹巢若鋪。","百巢一樹知幾烏，一烏不下三四雛。","雛又生雛知幾雛，老烏未死雛已烏。","散向人间何处無，攫麑啄卵方可食。","男女羣強最多力，靈蛇万古唯一珠。","豈可抨彈千万億，吾不會天教爾輩多子孫，告訴天公天不言。"]', '诗', 'shi', '', NULL, '樹上烏 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa144363-256e-4951-b960-ba406800555e', '琵琶歌', '琵琶歌', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["琵琶宮調八十一，旋宮三調彈不出。","玄宗偏許賀懷智，段師此藝還相匹。","自後流傳指撥衰，崑崙善才徒爾爲。","澒聲少得似雷吼，纏弦不敢彈羊皮。","人間奇事會相續，但有卞和無有玉。","段師弟子數十人，李家管兒稱上足。","管兒不作供奉兒，拋在東都雙鬢絲。","逢人便請送杯盞，著盡工夫人不知。","李家兄弟皆愛酒，我是酒徒爲密友。","著作曾邀連夜宿，中碾春溪華新綠。","平明船載管兒行，盡日聽彈無限曲。","曲名無限知者鮮，霓裳羽衣偏宛轉。","涼州大徧最豪嘈，六么散序多籠撚。","我聞此曲深賞奇，賞著奇處驚管兒。","管兒爲我雙淚垂，自彈此曲長自悲。","淚垂捍撥朱弦濕，冰泉嗚咽流鶯澀。","因茲彈作雨霖鈴，風雨蕭條鬼神泣。","一彈既罷又一彈，珠幢夜靜風珊珊。","低回慢弄關山思，坐對燕然秋月寒。","月寒一聲深殿磬，驟彈曲破音繁併。","百萬金鈴旋玉盤，醉客滿船皆暫醒。","自茲聽後六七年，管兒在洛我朝天。","游想慈恩杏園裏，夢寐仁風花樹前。","去年御史留東臺，公私蹙促顏不開。","今春制獄正撩亂，晝夜推囚心似灰。","暫輟歸時尋著作，著作南園花坼萼。","臙脂耀眼桃正紅，雪片滿溪梅已落。","是夕青春值三五，花枝向月雲含吐。","著作施罇命管兒，管兒久別今方覩。","管兒還爲彈六么，六么依舊聲迢迢。","猿鳴雪岫來三峽，鶴唳晴空聞九霄。","逡巡彈得六么徹，霜刀破竹無殘節。","幽關鵶軋胡雁悲，斷弦砉騞層冰裂。","我爲含悽歎奇絕，許作長歌始終說。","藝奇思寡塵事多，許來寒暑又經過。","如今左降在閒處，始爲管兒歌此歌。","歌此歌，寄管兒，管兒管兒憂爾衰。","爾衰之後繼者誰，繼之無乃在鐵山。","鐵山已近曹穆間，性靈甚好功猶淺。","急處未得臻幽閒，努力鐵山勤學取，莫遣後來無所祖。"]', '["琵琶宮調八十一，旋宮三調彈不出。","玄宗偏許賀懷智，段師此藝還相匹。","自後流傳指撥衰，崑崙善才徒爾爲。","澒声少得似雷吼，纏弦不敢彈羊皮。","人间奇事會相續，但有卞和無有玉。","段師弟子數十人，李家管兒稱上足。","管兒不作供奉兒，拋在东都雙鬢絲。","逢人便請送杯盞，著尽工夫人不知。","李家兄弟皆愛酒，我是酒徒爲密友。","著作曾邀連夜宿，中碾春溪华新綠。","平明船載管兒行，尽日听彈無限曲。","曲名無限知者鲜，霓裳羽衣偏宛轉。","涼州大徧最豪嘈，六么散序多籠撚。","我闻此曲深賞奇，賞著奇处驚管兒。","管兒爲我雙泪垂，自彈此曲长自悲。","泪垂捍撥朱弦濕，冰泉嗚咽流鶯澀。","因茲彈作雨霖鈴，风雨蕭條鬼神泣。","一彈既罷又一彈，珠幢夜静风珊珊。","低回慢弄关山思，坐对燕然秋月寒。","月寒一声深殿磬，驟彈曲破音繁併。","百万金鈴旋玉盤，醉客满船皆暫醒。","自茲听後六七年，管兒在洛我朝天。","游想慈恩杏园裏，梦寐仁风花樹前。","去年御史留东台，公私蹙促顏不开。","今春制獄正撩亂，晝夜推囚心似灰。","暫輟归时尋著作，著作南园花坼萼。","臙脂耀眼桃正紅，雪片满溪梅已落。","是夕青春值三五，花枝向月云含吐。","著作施罇命管兒，管兒久別今方覩。","管兒還爲彈六么，六么依旧声迢迢。","猿鳴雪岫来三峽，鹤唳晴空闻九霄。","逡巡彈得六么徹，霜刀破竹無殘節。","幽关鵶軋胡雁悲，斷弦砉騞層冰裂。","我爲含悽歎奇絕，許作长歌始終说。","藝奇思寡塵事多，許来寒暑又經過。","如今左降在閒处，始爲管兒歌此歌。","歌此歌，寄管兒，管兒管兒憂爾衰。","爾衰之後繼者誰，繼之無乃在鐵山。","鐵山已近曹穆间，性靈甚好功猶淺。","急处未得臻幽閒，努力鐵山勤学取，莫遣後来無所祖。"]', '诗', 'shi', '', NULL, '琵琶歌 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d104a8e7-e89c-40c2-98e2-7b708f5b7186', '小胡笳引', '小胡笳引', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雷氏金徽琴，王君寶重輕千金。","三峽流中將得來，明窗拂席幽匣開。","朱弦宛轉盤鳳足，驟擊數聲風雨迴。","哀笳慢指董家本，姜生得之妙思忖。","泛徽胡雁咽蕭蕭，繞指轆轤圓衮衮。","吞恨緘情乍輕激，故國關山心歷歷。","潺湲疑是雁鸊鵜，砉騞如聞發鳴鏑。","流宮變徵漸幽咽，別鶴欲飛猿欲絕。","秋霜滿樹葉辭風，寒雛墜地烏啼血。","哀弦已罷春恨長，恨長何恨懷我鄉。","我鄉安在長城窟，聞君虜奏心飄忽。","何時窄袖短貂裘，臙脂山下彎明月。"]', '["雷氏金徽琴，王君寶重轻千金。","三峽流中將得来，明窗拂席幽匣开。","朱弦宛轉盤鳳足，驟擊數声风雨迴。","哀笳慢指董家本，姜生得之妙思忖。","泛徽胡雁咽蕭蕭，繞指轆轤圓衮衮。","吞恨緘情乍轻激，故国关山心歷歷。","潺湲疑是雁鸊鵜，砉騞如闻發鳴鏑。","流宮变徵漸幽咽，別鹤欲飞猿欲絕。","秋霜满樹葉辞风，寒雛墜地烏啼血。","哀弦已罷春恨长，恨长何恨懷我乡。","我乡安在长城窟，闻君虜奏心飄忽。","何时窄袖短貂裘，臙脂山下彎明月。"]', '诗', 'shi', '', NULL, '小胡笳引 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc83be6-9f75-4612-af7d-f4fa66548049', '去杭州', '去杭州', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["房杜王魏之子孫，雖及百代爲清門。","駿骨鳳毛真可貴，岡頭澤底何足論。","去年江上識君面，愛君風貌情已敦。","與君言語見君性，靈府坦蕩消塵煩。","自茲心洽跡亦洽，居常並榻游竝軒。","柳陰覆岸鄭監水，李花壓樹韋公園。","每出新詩共聯綴，閑因醉舞相牽援。","時尋沙尾楓林夕，夜摘蘭叢衣露繁。","今君別我欲何去，自言遠結迢迢婚。","簡書五府已再至，波濤萬里酬一言。","爲君再拜贈君語，願君靜聽君勿喧。","君名師範欲何範，君之烈祖遺範存。","永寧昔在掄鑒表，沙汰沈濁澄浚源。","君今取友由取士，得不別白清與渾。","昔公事主盡忠讜，雖及死諫誓不諼。","今君佐藩如佐主，得不陳露詶所恩。","昔公爲善日不足，假寐待旦朝至尊。","今君三十朝未與，得不寸晷倍璵璠。","昔公令子尚貴主，公執舅禮婦執笲。","返拜之儀自此絕，關雎之化皎不昏。","君今遠娉奉明祀，得不齊勵親蘋蘩。","斯言皆爲書佩帶，然後別袂乃可捫。","別袂可捫不可解，解袂開帆悽別魂。","魂搖江樹鳥飛沒，帆挂檣竿鳥尾翻。","翻風駕浪拍何處，直指杭州由上元。","上元蕭寺基址在，杭州潮水霜雪屯。","潮戶迎潮擊潮鼓，潮平潮退有潮痕。","得得爲題羅剎石，古來非獨伍員冤。"]', '["房杜王魏之子孫，雖及百代爲清门。","駿骨鳳毛真可貴，岡头澤底何足論。","去年江上識君面，愛君风貌情已敦。","與君言語见君性，靈府坦蕩消塵煩。","自茲心洽跡亦洽，居常並榻游竝軒。","柳陰覆岸鄭監水，李花壓樹韋公园。","每出新诗共聯綴，闲因醉舞相牽援。","时尋沙尾楓林夕，夜摘蘭叢衣露繁。","今君別我欲何去，自言远結迢迢婚。","簡书五府已再至，波濤万里酬一言。","爲君再拜贈君語，願君静听君勿喧。","君名師範欲何範，君之烈祖遺範存。","永寧昔在掄鑒表，沙汰沈濁澄浚源。","君今取友由取士，得不別白清與渾。","昔公事主尽忠讜，雖及死諫誓不諼。","今君佐藩如佐主，得不陳露詶所恩。","昔公爲善日不足，假寐待旦朝至尊。","今君三十朝未與，得不寸晷倍璵璠。","昔公令子尚貴主，公執舅禮婦執笲。","返拜之儀自此絕，关雎之化皎不昏。","君今远娉奉明祀，得不齊勵親蘋蘩。","斯言皆爲书佩带，然後別袂乃可捫。","別袂可捫不可解，解袂开帆悽別魂。","魂搖江樹鸟飞沒，帆挂檣竿鸟尾翻。","翻风駕浪拍何处，直指杭州由上元。","上元蕭寺基址在，杭州潮水霜雪屯。","潮戶迎潮擊潮鼓，潮平潮退有潮痕。","得得爲題羅剎石，古来非独伍員冤。"]', '诗', 'shi', '', NULL, '去杭州 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efb8e0c4-59ad-4806-9df7-31ce2b642c11', '南家桃', '南家桃', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["南家桃樹深紅色，日照露光看不得。","樹小花狂風易吹，一夜風吹滿牆北。","離人自有經時別，眼前落花心歎息。","更待明年花滿枝，一年迢遞空相憶。"]', '["南家桃樹深紅色，日照露光看不得。","樹小花狂风易吹，一夜风吹满牆北。","離人自有經时別，眼前落花心歎息。","更待明年花满枝，一年迢遞空相憶。"]', '诗', 'shi', '', NULL, '南家桃 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed42547e-1f69-409f-b280-00bfcb7a4cc5', '志堅師', '志堅師', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["嵩山老僧披破衲，七十八年三十臘。","靈武朝天遼海征，宇宙曾行三四匝。","初因怏怏薙却頭，便繞嵩山寂師墖。","淮西未返半年前，已見淮西陣雲合。"]', '["嵩山老僧披破衲，七十八年三十臘。","靈武朝天遼海征，宇宙曾行三四匝。","初因怏怏薙却头，便繞嵩山寂師墖。","淮西未返半年前，已见淮西陣云合。"]', '诗', 'shi', '', NULL, '志堅師 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('097b5cbc-da79-44a4-ae48-1995d118b647', '答子蒙', '答子蒙', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["報盧君，門外雪紛紛。","紛紛門外雪，城中鼓聲絕。","強梁御史人覰步，安得夜開沽酒戶。"]', '["報盧君，门外雪紛紛。","紛紛门外雪，城中鼓声絕。","強梁御史人覰步，安得夜开沽酒戶。"]', '诗', 'shi', '', NULL, '答子蒙 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff94bdfc-9a2b-4d39-aad2-a0639e3d9e73', '辛夷花', '辛夷花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["問君辛夷花，君言已斑駮。","不畏辛夷不爛開，顧我筋骸官束縛。","縛遣推囚名御史，狼藉囚徒滿田地。","明日不推緣國忌，依前不得花前醉。","韓員外家好辛夷，開時乞取三兩枝。","折枝爲贈君莫惜，縱君不折風亦吹。"]', '["问君辛夷花，君言已斑駮。","不畏辛夷不爛开，顧我筋骸官束縛。","縛遣推囚名御史，狼藉囚徒满田地。","明日不推緣国忌，依前不得花前醉。","韓員外家好辛夷，开时乞取三兩枝。","折枝爲贈君莫惜，縱君不折风亦吹。"]', '诗', 'shi', '', NULL, '辛夷花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c026ee76-45ed-450d-96d7-9a4434d909ed', '廳前柏', '廳前柏', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["廳前柏，知君曾對羅希奭。","我本癲狂耽酒人，何事與君爲對敵。","爲對敵，洛陽城中花赤白。","花赤白，囚漸多，花之赤白奈爾何。"]', '["廳前柏，知君曾对羅希奭。","我本癲狂耽酒人，何事與君爲对敵。","爲对敵，洛陽城中花赤白。","花赤白，囚漸多，花之赤白奈爾何。"]', '诗', 'shi', '', NULL, '廳前柏 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b91a878f-7e6b-415a-ac3d-80abbb0040ac', '夜別筵', '夜別筵', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夜長酒闌燈花長，燈花落地復落牀。","似我別淚三四行，滴君滿坐之衣裳。","與君別後淚痕在，年年著衣心莫改。"]', '["夜长酒闌灯花长，灯花落地复落牀。","似我別泪三四行，滴君满坐之衣裳。","與君別後泪痕在，年年著衣心莫改。"]', '诗', 'shi', '', NULL, '夜別筵 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe5427c-1d71-4e93-8166-2119a9280caa', '三泉驛', '三泉驛', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["三泉驛內逢上巳，新葉趨塵花落地。","勸君滿盞君莫辭，別後無人共君醉。","洛陽城中無限人，貴人自貴貧自貧。"]', '["三泉驛內逢上巳，新葉趨塵花落地。","勸君满盞君莫辞，別後無人共君醉。","洛陽城中無限人，貴人自貴貧自貧。"]', '诗', 'shi', '', NULL, '三泉驛 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94c0d9f6-88c4-48ed-b3ea-8d9ebc5262e6', '何滿子歌', '何满子歌', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["何滿能歌能宛轉，天寶年中世稱罕。","嬰刑擊在囹圄間，水調哀音歌憤懣。","梨園弟子奏玄宗，一唱承恩羈網緩。","便將何滿爲曲名，御譜親題樂府纂。","魚家入內本領絕，葉氏有年聲氣短。","自外徒煩記得詞，點拍纔成已夸誕。","我來湖外拜君侯，正值灰飛仲春琯。","廣宴江亭爲我開，紅妝逼坐花枝暖。","此時有態蹋華筵，未吐芳詞貌夷坦。","翠蛾轉盼搖雀釵，碧袖歌垂翻鶴卵。","定面凝眸一聲發，雲停塵下何勞算。","迢迢擊磬遠玲玲，一一貫珠勻款款。","犯羽含商移調態，留情度意拋弦管。","湘妃寶瑟水上來，秦女玉簫空外滿。","纏緜疊破最慇懃，整頓衣裳頗閒散。","冰含遠溜咽還通，鶯泥晚花啼漸嬾。","斂黛吞聲若自冤，鄭袖見捐西子浣。","陰山鳴雁曉斷行，巫峽哀猿夜呼伴。","古者諸侯饗外賓，鹿鳴三奏陳圭瓚。","何如有態一曲終，牙籌記令紅螺盌。"]', '["何满能歌能宛轉，天寶年中世稱罕。","嬰刑擊在囹圄间，水調哀音歌憤懣。","梨园弟子奏玄宗，一唱承恩羈網緩。","便將何满爲曲名，御譜親題乐府纂。","鱼家入內本領絕，葉氏有年声氣短。","自外徒煩記得词，点拍纔成已夸誕。","我来湖外拜君侯，正值灰飞仲春琯。","廣宴江亭爲我开，紅妝逼坐花枝暖。","此时有態蹋华筵，未吐芳词貌夷坦。","翠蛾轉盼搖雀釵，碧袖歌垂翻鹤卵。","定面凝眸一声發，云停塵下何勞算。","迢迢擊磬远玲玲，一一貫珠勻款款。","犯羽含商移調態，留情度意拋弦管。","湘妃寶瑟水上来，秦女玉簫空外满。","纏緜叠破最慇懃，整頓衣裳頗閒散。","冰含远溜咽還通，鶯泥晚花啼漸嬾。","斂黛吞声若自冤，鄭袖见捐西子浣。","陰山鳴雁晓斷行，巫峽哀猿夜呼伴。","古者諸侯饗外賓，鹿鳴三奏陳圭瓚。","何如有態一曲終，牙籌記令紅螺盌。"]', '诗', 'shi', '', NULL, '何滿子歌 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f53f3fb-6dd3-4d61-ba88-a085232c5c58', '通州丁溪館夜別李景信三首 一', '通州丁溪館夜別李景信三首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["月濛濛兮山掩掩，束束別魂眉歛歛。","蠡琖覆時天欲明，碧幌青燈風灩灩。","淚消語盡還暫眠，唯夢千山萬山險。"]', '["月濛濛兮山掩掩，束束別魂眉歛歛。","蠡琖覆时天欲明，碧幌青灯风灩灩。","泪消語尽還暫眠，唯梦千山万山險。"]', '诗', 'shi', '', NULL, '通州丁溪館夜別李景信三首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('181fb69e-a875-4573-9bc9-efb8d2212068', '通州丁溪館夜別李景信三首 二', '通州丁溪館夜別李景信三首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["水環環兮山簇簇，啼鳥聲聲婦人哭。","離牀別臉睡還開，燈灺暗飄珠蔌蔌。","山深虎橫館無門，夜集巴兒扣空木。"]', '["水环环兮山簇簇，啼鸟声声婦人哭。","離牀別臉睡還开，灯灺暗飄珠蔌蔌。","山深虎橫館無门，夜集巴兒扣空木。"]', '诗', 'shi', '', NULL, '通州丁溪館夜別李景信三首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adc63c29-7a3f-4262-b7c5-4494f4104602', '通州丁溪館夜別李景信三首 三', '通州丁溪館夜別李景信三首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雨瀟瀟兮鵑咽咽，傾冠倒枕燈臨滅。","倦僮呼喚譍復眠，啼雞拍翅三聲絕。","握手相看其奈何，奈何其奈天明別。"]', '["雨瀟瀟兮鵑咽咽，傾冠倒枕灯臨滅。","倦僮呼喚譍复眠，啼雞拍翅三声絕。","握手相看其奈何，奈何其奈天明別。"]', '诗', 'shi', '', NULL, '通州丁溪館夜別李景信三首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82c9f4d8-8aa0-483d-ab65-94ed3b4197fb', '酬鄭從事四年九月宴望海亭次用舊韻', '酬鄭從事四年九月宴望海亭次用旧韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["海亭樹木何蘢蔥，寒光透坼秋玲瓏。","湖山四面爭氣色，曠望不與人間同。","一拳墺伏東武小，兩山鬬構秦望雄。","嵌空古墓失文種，突兀怪石疑防風。","舟船駢比有宗侶，水雲滃泱無始終。","雪花布徧稻隴白，日脚插入秋波紅。","興餘望劇酒四坐，歌聲舞豔煙霞中。","酒酣從事歌送我，歌云此樂難再逢。","良時年少猶健羨，使君況是頭白翁。","我聞此曲深歎息，唧唧不異秋草蟲。","憶年十五學構廈，有意蓋覆天下窮。","安知四十虛富貴，朱紫束縛心志空。","妝梳伎女上樓榭，止欲歡樂微茫躬。","雖無趣尚慕賢聖，幸有心目知西東。","欲將滑甘柔藏府，已被鬱噎衝喉嚨。","君今勸我酒太醉，醉語不復能沖融。","勸君莫學虛富貴，不是賢人難變通。"]', '["海亭樹木何蘢蔥，寒光透坼秋玲瓏。","湖山四面爭氣色，曠望不與人间同。","一拳墺伏东武小，兩山鬬構秦望雄。","嵌空古墓失文種，突兀怪石疑防风。","舟船駢比有宗侶，水云滃泱無始終。","雪花布徧稻隴白，日脚插入秋波紅。","兴餘望劇酒四坐，歌声舞豔煙霞中。","酒酣從事歌送我，歌云此乐难再逢。","良时年少猶健羨，使君況是头白翁。","我闻此曲深歎息，唧唧不異秋草蟲。","憶年十五学構廈，有意蓋覆天下窮。","安知四十虛富貴，朱紫束縛心志空。","妝梳伎女上楼榭，止欲歡乐微茫躬。","雖無趣尚慕賢聖，幸有心目知西东。","欲將滑甘柔藏府，已被鬱噎衝喉嚨。","君今勸我酒太醉，醉語不复能沖融。","勸君莫学虛富貴，不是賢人难变通。"]', '诗', 'shi', '', NULL, '酬鄭從事四年九月宴望海亭次用舊韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49449ba6-fe7f-4b59-9d78-586fe5aa13ab', '夢遊春七十韻', '梦游春七十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔歲夢遊春，夢遊何所遇。","夢入深洞中，果遂平生趣。","清泠淺漫流，畫舫蘭篙渡。","過盡萬株桃，盤旋竹林路。","長廊抱小樓，門牖相回互。","樓下雜花叢，叢邊繞鴛鷺。","池光漾霞影，曉日初明煦。","未敢上階行，頻移曲池步。","烏龍不作聲，碧玉曾相慕。","漸到簾幕間，裴回意猶懼。","閑窺東西閤，奇玩參差布。","隔子碧油糊，駝鉤紫金鍍。","逡巡日漸高，影響人將寤。","鸚鵡饑亂鳴，嬌娃睡猶怒。","簾開侍兒起，見我遙相諭。","鋪設繡紅茵，施張鈿妝具。","潛褰翡翠帷，瞥見珊瑚樹。","不辨花貌人，空驚香若霧。","身回夜合偏，態斂晨霞聚。","睡臉桃破風，汗妝蓮委露。","叢梳百葉髻，金蹙重臺屨。","紕輭鈿頭帬，玲瓏合歡袴。","鮮妍脂粉薄，闇澹衣裳故。","最似紅牡丹，雨來春欲暮。","夢魂良易驚，靈境難久寓。","夜夜望天河，無由重沿泝。","結念心所期，返如禪頓悟。","覺來八九年，不向花迴顧。","雜合兩京春，喧闐衆禽護。","我到看花時，但作懷仙句。","浮生轉經歷，道性尤堅固。","近作夢仙詩，亦知勞肺腑。","一夢何足云，良時事婚娶。","當年二紀初，嘉節三星度。","朝蕣玉佩迎，高松女蘿附。","韋門正全盛，出入多歡裕。","甲第漲清池，鳴騶引朱輅。","廣榭舞萎蕤，長筵賓雜厝。","青春詎幾日，華實潛幽蠹。","秋月照潘郎，空山懷謝傅。","紅樓嗟壞壁，金谷迷荒戍。","石壓破闌干，門摧舊梐枑。","雖云覺夢殊，同是終難駐。","悰緒竟何如，棼絲不成絇。","卓女白頭吟，阿嬌金屋賦。","重璧盛姬臺，青冢明妃墓。","盡委窮塵骨，皆隨流波注。","幸有古如今，何勞縑比素。","況余當盛時，早歲諧如務。","詔冊冠賢良，諫垣陳好惡。","三十再登朝，一登還一仆。","寵榮非不早，邅迴亦云屢。","直氣在膏肓，氛氳日沈痼。","不言意不快，快意言多忤。","忤誠人所賊，性亦天之付。","乍可沈爲香，不能浮作瓠。","誠爲堅所守，未爲明所措。","事事身已經，營營計何誤。","美玉琢文珪，良金填武庫。","徒謂自堅貞，安知受礱鑄。","長絲羈野馬，密網羅陰兔。","物外各迢迢，誰能遠相錮。","時來既若飛，禍速當如騖。","曩意自未精，此行何所訴。","努力去江陵，笑言誰與晤。","江花縱可憐，奈非心所慕。","石竹逞奸黠，蔓青誇畝數。","一種薄地生，淺深何足妒。","荷葉水上生，團團水中住。","瀉水置葉中，君看不相汚。"]', '["昔歲梦游春，梦游何所遇。","梦入深洞中，果遂平生趣。","清泠淺漫流，畫舫蘭篙渡。","過尽万株桃，盤旋竹林路。","长廊抱小楼，门牖相回互。","楼下杂花叢，叢邊繞鴛鷺。","池光漾霞影，晓日初明煦。","未敢上階行，頻移曲池步。","烏龙不作声，碧玉曾相慕。","漸到簾幕间，裴回意猶懼。","闲窺东西閤，奇玩參差布。","隔子碧油糊，駝鉤紫金鍍。","逡巡日漸高，影响人將寤。","鸚鵡饑亂鳴，嬌娃睡猶怒。","簾开侍兒起，见我遙相諭。","鋪設繡紅茵，施張鈿妝具。","潛褰翡翠帷，瞥见珊瑚樹。","不辨花貌人，空驚香若霧。","身回夜合偏，態斂晨霞聚。","睡臉桃破风，汗妝蓮委露。","叢梳百葉髻，金蹙重台屨。","紕輭鈿头帬，玲瓏合歡袴。","鲜妍脂粉薄，闇澹衣裳故。","最似紅牡丹，雨来春欲暮。","梦魂良易驚，靈境难久寓。","夜夜望天河，無由重沿泝。","結念心所期，返如禪頓悟。","覺来八九年，不向花迴顧。","杂合兩京春，喧闐衆禽護。","我到看花时，但作懷仙句。","浮生轉經歷，道性尤堅固。","近作梦仙诗，亦知勞肺腑。","一梦何足云，良时事婚娶。","當年二紀初，嘉節三星度。","朝蕣玉佩迎，高松女蘿附。","韋门正全盛，出入多歡裕。","甲第漲清池，鳴騶引朱輅。","廣榭舞萎蕤，长筵賓杂厝。","青春詎幾日，华實潛幽蠹。","秋月照潘郎，空山懷謝傅。","紅楼嗟壞壁，金谷迷荒戍。","石壓破闌干，门摧旧梐枑。","雖云覺梦殊，同是終难駐。","悰緒竟何如，棼絲不成絇。","卓女白头吟，阿嬌金屋賦。","重璧盛姬台，青冢明妃墓。","尽委窮塵骨，皆隨流波注。","幸有古如今，何勞縑比素。","況余當盛时，早歲諧如務。","詔冊冠賢良，諫垣陳好惡。","三十再登朝，一登還一仆。","寵榮非不早，邅迴亦云屢。","直氣在膏肓，氛氳日沈痼。","不言意不快，快意言多忤。","忤誠人所賊，性亦天之付。","乍可沈爲香，不能浮作瓠。","誠爲堅所守，未爲明所措。","事事身已經，營營計何誤。","美玉琢文珪，良金填武庫。","徒謂自堅貞，安知受礱鑄。","长絲羈野马，密網羅陰兔。","物外各迢迢，誰能远相錮。","时来既若飞，禍速當如騖。","曩意自未精，此行何所訴。","努力去江陵，笑言誰與晤。","江花縱可怜，奈非心所慕。","石竹逞奸黠，蔓青誇畝數。","一種薄地生，淺深何足妒。","荷葉水上生，團團水中住。","瀉水置葉中，君看不相汚。"]', '诗', 'shi', '', NULL, '夢遊春七十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6d2314a-5458-462b-9010-d551f91b7e68', '桐花落', '桐花落', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莎草徧桐陰，桐花滿莎落。","蓋覆相團圓，可憐無厚薄。","昔歲幽院中，深堂下簾幕。","同在後門前，因論花好惡。","君誇沈檀樣，云是指撝作。","暗澹滅紫花，句連蹙金萼。","都繡六七枝，鬬成雙孔雀。","尾上稠疊花，又將金解絡。","我愛看不已，君煩睡先著。","我作繡桐詩，繫君帬帶著。","別來苦修道，此意都蕭索。","今日竟相牽，思量偶然錯。"]', '["莎草徧桐陰，桐花满莎落。","蓋覆相團圓，可怜無厚薄。","昔歲幽院中，深堂下簾幕。","同在後门前，因論花好惡。","君誇沈檀樣，云是指撝作。","暗澹滅紫花，句連蹙金萼。","都繡六七枝，鬬成雙孔雀。","尾上稠叠花，又將金解絡。","我愛看不已，君煩睡先著。","我作繡桐诗，繫君帬带著。","別来苦修道，此意都蕭索。","今日竟相牽，思量偶然錯。"]', '诗', 'shi', '', NULL, '桐花落 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57417914-bb35-4c53-a597-ab9cdde6bfa1', '夢昔時', '梦昔时', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["閒窗結幽夢，此夢誰人知。","夜半初得處，天明臨去時。","山川已久隔，雲雨兩無期。","何事來相感，又成新別離。"]', '["閒窗結幽梦，此梦誰人知。","夜半初得处，天明臨去时。","山川已久隔，云雨兩無期。","何事来相感，又成新別離。"]', '诗', 'shi', '', NULL, '夢昔時 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8032953f-2666-462f-a170-59051b654a4d', '恨妝成', '恨妝成', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["曉日穿隙明，開帷理妝點。","傅粉貴重重，施朱憐冉冉。","柔鬟背額垂，叢鬢隨釵斂。","凝翠暈蛾眉，輕紅拂花臉。","滿頭行小梳，當面施圓靨。","最恨落花時，妝成獨披掩。"]', '["晓日穿隙明，开帷理妝点。","傅粉貴重重，施朱怜冉冉。","柔鬟背額垂，叢鬢隨釵斂。","凝翠暈蛾眉，轻紅拂花臉。","满头行小梳，當面施圓靨。","最恨落花时，妝成独披掩。"]', '诗', 'shi', '', NULL, '恨妝成 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7fa54f9-3cfe-4358-b253-74ae88687171', '古決絶詞 一', '古決絶词 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["乍可爲天上牽牛織女星，不願爲庭前紅槿枝。","七月七日一相見，相見故心終不移。","那能朝開暮飛去，一任東西南北吹。","分不兩相守，恨不兩相思。","對面且如此，背面當可知。","春風撩亂伯勞語，況是此時拋去時。","握手苦相問，竟不言後期。","君情既決絕，妾意已參差。","借如死生別，安得長苦悲。"]', '["乍可爲天上牽牛织女星，不願爲庭前紅槿枝。","七月七日一相见，相见故心終不移。","那能朝开暮飞去，一任东西南北吹。","分不兩相守，恨不兩相思。","对面且如此，背面當可知。","春风撩亂伯勞語，況是此时拋去时。","握手苦相问，竟不言後期。","君情既決絕，妾意已參差。","借如死生別，安得长苦悲。"]', '诗', 'shi', '', NULL, '古決絶詞 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bb19a4c-df65-4ba6-8263-af14c3b30cab', '古決絶詞 二', '古決絶词 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["噫春冰之將泮，何予懷之獨結。","有美一人，於焉曠絕。","一日不見，比一日於三年。","況三年之曠別，水得風兮小而已波。","筍在苞兮高不見節，矧桃李之當春。","競衆人而攀折，我自顧悠悠而若雲。","又安能保君皚皚之如雪，感破鏡之分明，覩淚痕之餘血。","幸他人之既不我先，又安能使他人之終不我奪？","已焉哉！織女別黃姑，一年一度暫相見，彼此隔河何事無。"]', '["噫春冰之將泮，何予懷之独結。","有美一人，於焉曠絕。","一日不见，比一日於三年。","況三年之曠別，水得风兮小而已波。","筍在苞兮高不见節，矧桃李之當春。","競衆人而攀折，我自顧悠悠而若云。","又安能保君皚皚之如雪，感破镜之分明，覩泪痕之餘血。","幸他人之既不我先，又安能使他人之終不我奪？","已焉哉！织女別黄姑，一年一度暫相见，彼此隔河何事無。"]', '诗', 'shi', '', NULL, '古決絶詞 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76dca650-59bc-4a93-a326-26dca72e3037', '古決絶詞 三', '古決絶词 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夜夜相抱眠，幽懷尚沈結。","那堪一年事，長遣一宵說。","但感久相思，何暇暫相悅。","虹橋薄夜成，龍駕侵晨列。","生憎野鶴性遲迴，死恨天雞識時節。","曙色漸曈曈，華星欲明滅。","一去又一年，一年何可徹。","有此迢遞期，不如死生別。"]', '["夜夜相抱眠，幽懷尚沈結。","那堪一年事，长遣一宵说。","但感久相思，何暇暫相悅。","虹橋薄夜成，龙駕侵晨列。","生憎野鹤性遲迴，死恨天雞識时節。","曙色漸曈曈，华星欲明滅。","一去又一年，一年何可徹。","有此迢遞期，不如死生別。"]', '诗', 'shi', '', NULL, '古決絶詞 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d720e147-9ffc-44e0-a11a-49198cbce2b7', '櫻桃花', '櫻桃花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["櫻桃花，一枝兩枝千萬朵。","花塼曾立摘花人，窣破羅帬紅似火。"]', '["櫻桃花，一枝兩枝千万朵。","花塼曾立摘花人，窣破羅帬紅似火。"]', '诗', 'shi', '', NULL, '櫻桃花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9a6adf8-3d32-480c-ba91-aea612bab31e', '曹十九舞綠鈿', '曹十九舞綠鈿', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["急管清弄頻，舞衣纔攬結。","含情獨搖手，雙袖參差列。","騕褭柳牽絲，炫轉風回雪。","凝眄嬌不移，往往度繁節。"]', '["急管清弄頻，舞衣纔攬結。","含情独搖手，雙袖參差列。","騕褭柳牽絲，炫轉风回雪。","凝眄嬌不移，往往度繁節。"]', '诗', 'shi', '', NULL, '曹十九舞綠鈿 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52212981-df92-48e1-9a72-1b17d6c7714e', '閨晚', '閨晚', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["紅帬委塼堦，玉爪剺朱橘。","素臆光如砑，明瞳豔凝溢。","調弦不成曲，學書徒弄筆。","夜色侵洞房，春煙透簾出。"]', '["紅帬委塼堦，玉爪剺朱橘。","素臆光如砑，明瞳豔凝溢。","調弦不成曲，学书徒弄笔。","夜色侵洞房，春煙透簾出。"]', '诗', 'shi', '', NULL, '閨晚 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61da7798-6b7f-404b-acad-82e4fa4d6680', '曉將別', '晓將別', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["風露曉淒淒，月下西牆西。","行人帳中起，思婦枕前啼。","屑屑命僮御，晨裝儼已齊。","將去復攜手，日高方解攜。"]', '["风露晓淒淒，月下西牆西。","行人帳中起，思婦枕前啼。","屑屑命僮御，晨裝儼已齊。","將去复携手，日高方解携。"]', '诗', 'shi', '', NULL, '曉將別 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9efdaf5-c077-45ee-8d8b-d123a4e4686e', '薔薇架', '薔薇架', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["五色階前架，一張籠上被。","殷紅稠疊花，半綠鮮明地。","風蔓羅帬帶，露英蓮臉淚。","多逢走馬郎，可惜簾邊思。"]', '["五色階前架，一張籠上被。","殷紅稠叠花，半綠鲜明地。","风蔓羅帬带，露英蓮臉泪。","多逢走马郎，可惜簾邊思。"]', '诗', 'shi', '', NULL, '薔薇架 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9350186-8d14-40b7-b1b3-cd887acf5209', '月暗', '月暗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["月暗燈殘面牆泣，羅纓斗重知啼濕。","真珠簾斷蝙蝠飛，燕子巢空螢火入。","深殿門重夜漏嚴，柔□□□□年急。","君王掌上容一人，更有輕身何處立。"]', '["月暗灯殘面牆泣，羅纓斗重知啼濕。","真珠簾斷蝙蝠飞，燕子巢空螢火入。","深殿门重夜漏嚴，柔□□□□年急。","君王掌上容一人，更有轻身何处立。"]', '诗', 'shi', '', NULL, '月暗 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9d45bd-3b00-4a08-bd62-f156e006b1e0', '新秋', '新秋', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["旦暮已淒涼，離人遠思忙。","夏衣臨曉薄，秋影入檐長。","前事風隨扇，歸心燕在梁。","殷勤寄牛女，河漢正相望。"]', '["旦暮已淒涼，離人远思忙。","夏衣臨晓薄，秋影入檐长。","前事风隨扇，归心燕在梁。","殷勤寄牛女，河漢正相望。"]', '诗', 'shi', '', NULL, '新秋 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c0a2555-7e81-4da1-bc82-ab3cbaf88248', '贈雙文', '贈雙文', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["豔極翻含怨，憐多轉自嬌。","有時還暫笑，閑坐愛無憀。","曉月行看墮，春酥見欲消。","何因肯垂手，不敢望回腰。"]', '["豔極翻含怨，怜多轉自嬌。","有时還暫笑，闲坐愛無憀。","晓月行看墮，春酥见欲消。","何因肯垂手，不敢望回腰。"]', '诗', 'shi', '', NULL, '贈雙文 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25fba788-7700-48d4-815c-9a164c06fd8d', '春別', '春別', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["幽芳本未闌，君去蕙花殘。","河漢秋期遠，關山世路難。","雲屏留粉絮，風幌引香蘭。","腸斷迴文錦，春深獨自看。"]', '["幽芳本未闌，君去蕙花殘。","河漢秋期远，关山世路难。","云屏留粉絮，风幌引香蘭。","腸斷迴文錦，春深独自看。"]', '诗', 'shi', '', NULL, '春別 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9db9fb0-eea2-4266-8edf-d0f099b12989', '和樂天示楊瓊', '和乐天示楊瓊', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["我在江陵少年日，知有楊瓊初喚出。","腰身瘦小歌圓緊，依約年應十六七。","去年十月過蘇州，瓊來拜問郎不識。","青衫玉貌何處去，安得紅旗遮頭白。","我語楊瓊瓊莫語，汝雖笑我我笑汝。","汝今無復小腰身，不似江陵時好女。","楊瓊爲我歌送酒，爾憶江陵縣中否。","江陵王令骨爲灰，車來嫁作尚書婦。","盧戡及第嚴澗在，其餘死者十八九。","我今賀爾亦自多，爾得老成余白首。"]', '["我在江陵少年日，知有楊瓊初喚出。","腰身瘦小歌圓緊，依約年應十六七。","去年十月過蘇州，瓊来拜问郎不識。","青衫玉貌何处去，安得紅旗遮头白。","我語楊瓊瓊莫語，汝雖笑我我笑汝。","汝今無复小腰身，不似江陵时好女。","楊瓊爲我歌送酒，爾憶江陵縣中否。","江陵王令骨爲灰，车来嫁作尚书婦。","盧戡及第嚴澗在，其餘死者十八九。","我今賀爾亦自多，爾得老成余白首。"]', '诗', 'shi', '', NULL, '和樂天示楊瓊 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c8d269-c926-4e73-9957-40d2fc0cc512', '魚中素', '鱼中素', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["重疊魚中素，幽緘手自開。","斜紅餘淚蹟，知著臉邊來。"]', '["重叠鱼中素，幽緘手自开。","斜紅餘泪蹟，知著臉邊来。"]', '诗', 'shi', '', NULL, '魚中素 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b26a58-c9cb-4a98-8980-32df48b58348', '代九九', '代九九', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["昔年桃李月，顏色共花宜。","廻臉蓮初破，低蛾柳竝垂。","望山多倚樹，弄水愛臨池。","遠被登樓識，潛因倒影窺。","隔林徒想像，上砌轉逶迤。","謾擲庭中果，虛攀牆外枝。","強持文玉佩，求結麝香縭。","阿母憐金重，親兄要馬騎。","把將嬌小女，嫁與冶遊兒。","自隱勤勤索，相要事事隨。","每常同坐臥，不省暫參差。","纔學羞兼妒，何言寵便移。","青春來易皎，白日誓先虧。","僻性嗔來見，邪行醉後知。","別牀鋪枕席，當面指瑕疵。","妾貌應猶在，君情遽若斯。","的成終世恨，焉用此宵爲。","鸞鏡燈前撲，鴛衾手下隳。","參商半夜起，琴瑟一聲離。","努力新叢豔，狂風次第吹。"]', '["昔年桃李月，顏色共花宜。","廻臉蓮初破，低蛾柳竝垂。","望山多倚樹，弄水愛臨池。","远被登楼識，潛因倒影窺。","隔林徒想像，上砌轉逶迤。","謾擲庭中果，虛攀牆外枝。","強持文玉佩，求結麝香縭。","阿母怜金重，親兄要马騎。","把將嬌小女，嫁與冶游兒。","自隐勤勤索，相要事事隨。","每常同坐臥，不省暫參差。","纔学羞兼妒，何言寵便移。","青春来易皎，白日誓先虧。","僻性嗔来见，邪行醉後知。","別牀鋪枕席，當面指瑕疵。","妾貌應猶在，君情遽若斯。","的成終世恨，焉用此宵爲。","鸾镜灯前撲，鴛衾手下隳。","參商半夜起，琴瑟一声離。","努力新叢豔，狂风次第吹。"]', '诗', 'shi', '', NULL, '代九九 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2af1c24-204c-47bf-801d-e9b9ba68857c', '盧十九子蒙吟盧七員外洛川懷古六韻命余和', '盧十九子蒙吟盧七員外洛川懷古六韻命余和', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["聞道盧明府，閑行詠洛神。","浪圓疑靨笑，波鬬憶眉嚬。","蹀躞橋頭馬，空濛水上塵。","草芽猶犯雪，冰岸欲消春。","寓目終無限，通辭未有因。","子蒙將此曲，吟似獨眠人。"]', '["闻道盧明府，闲行詠洛神。","浪圓疑靨笑，波鬬憶眉嚬。","蹀躞橋头马，空濛水上塵。","草芽猶犯雪，冰岸欲消春。","寓目終無限，通辞未有因。","子蒙將此曲，吟似独眠人。"]', '诗', 'shi', '', NULL, '盧十九子蒙吟盧七員外洛川懷古六韻命余和 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c26e26e-a157-4137-9bc5-24b8ec2f57cd', '劉阮妻二首 一', '劉阮妻二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["仙洞千年一度開，等閑偷入又偷廻。","桃花飛盡東風起，何處消沈去不來。"]', '["仙洞千年一度开，等闲偷入又偷廻。","桃花飞尽东风起，何处消沈去不来。"]', '诗', 'shi', '', NULL, '劉阮妻二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f26b620f-ed26-4d21-9a14-ad7b34e9e55a', '劉阮妻二首 二', '劉阮妻二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["芙蓉脂肉綠雲鬟，罨畫樓臺青黛山。","千樹桃花萬年藥，不知何事憶人間。"]', '["芙蓉脂肉綠云鬟，罨畫楼台青黛山。","千樹桃花万年藥，不知何事憶人间。"]', '诗', 'shi', '', NULL, '劉阮妻二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('496955eb-549a-4176-84d3-ab6460eaa70f', '桃花', '桃花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["桃花淺深處，似勻深淺妝。","春風助腸斷，吹落白衣裳。"]', '["桃花淺深处，似勻深淺妝。","春风助腸斷，吹落白衣裳。"]', '诗', 'shi', '', NULL, '桃花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ba56a50-65aa-40e2-9aa7-92968d1d44d4', '暮秋', '暮秋', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["看著牆西日又沈，步廊廻合戟門深。","栖烏滿樹聲聲絕，小玉上牀鋪夜衾。"]', '["看著牆西日又沈，步廊廻合戟门深。","栖烏满樹声声絕，小玉上牀鋪夜衾。"]', '诗', 'shi', '', NULL, '暮秋 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed1832b-2c8b-4a26-a5e3-75ffe21934d9', '壓牆花', '壓牆花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["野性大都迷里巷，愛將高樹記人家。","春來偏認平陽宅，爲見牆頭拂面花。"]', '["野性大都迷里巷，愛將高樹記人家。","春来偏認平陽宅，爲见牆头拂面花。"]', '诗', 'shi', '', NULL, '壓牆花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87f6a3f4-2794-4bbf-a3f9-ca1cf1c55ea6', '舞腰', '舞腰', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["帬裾旋旋手迢迢，不趁音聲自趁嬌。","未必諸郎知曲誤，一時偷眼爲廻腰。"]', '["帬裾旋旋手迢迢，不趁音声自趁嬌。","未必諸郎知曲誤，一时偷眼爲廻腰。"]', '诗', 'shi', '', NULL, '舞腰 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0ef9ca9-c45c-48c9-892f-9c010ef044c8', '白衣裳二首 一', '白衣裳二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雨濕輕塵隔院香，玉人初著白衣裳。","半含惆悵閑看繡，一朵棃花壓象牀。"]', '["雨濕轻塵隔院香，玉人初著白衣裳。","半含惆悵闲看繡，一朵棃花壓象牀。"]', '诗', 'shi', '', NULL, '白衣裳二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a44a44-f364-4b68-b465-7f4686aa418f', '白衣裳二首 二', '白衣裳二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["藕絲衫子柳花帬，空著沈香慢火熏。","閑倚屏風笑周昉，枉拋心力畫朝雲。"]', '["藕絲衫子柳花帬，空著沈香慢火熏。","闲倚屏风笑周昉，枉拋心力畫朝云。"]', '诗', 'shi', '', NULL, '白衣裳二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb71085-da80-4dc8-86c0-9afc6cc551fe', '憶事', '憶事', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夜深閑到戟門邊，却繞行廊又獨眠。","明月滿庭池水淥，桐花垂在翠簾前。"]', '["夜深闲到戟门邊，却繞行廊又独眠。","明月满庭池水淥，桐花垂在翠簾前。"]', '诗', 'shi', '', NULL, '憶事 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41743123-f8db-4bc6-936f-76e33c0d235a', '寄舊詩與薛濤因成長句', '寄旧诗與薛濤因成长句', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["詩篇調態人皆有，細膩風光我獨知。","月夜詠花憐暗澹，雨朝題柳爲敧垂。","長教碧玉藏深處，總向紅牋寫自隨。","老大不能收拾得，與君閑似好男兒。"]', '["诗篇調態人皆有，細膩风光我独知。","月夜詠花怜暗澹，雨朝題柳爲敧垂。","长教碧玉藏深处，總向紅牋寫自隨。","老大不能收拾得，與君闲似好男兒。"]', '诗', 'shi', '', NULL, '寄舊詩與薛濤因成長句 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aed8b3b5-a77f-494e-8e76-e1d555680de1', '友封體', '友封體', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["雨送浮涼夏簟清，小樓腰褥怕單輕。","微風暗度香囊轉，朧月斜穿隔子明。","樺燭燄高黃耳吠，柳堤風靜紫騮聲。","頻頻聞動中門鎖，桃葉知嗔未敢迎。"]', '["雨送浮涼夏簟清，小楼腰褥怕單轻。","微风暗度香囊轉，朧月斜穿隔子明。","樺燭燄高黄耳吠，柳堤风静紫騮声。","頻頻闻动中门鎖，桃葉知嗔未敢迎。"]', '诗', 'shi', '', NULL, '友封體 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3edd1e3b-097c-4583-8508-7ad621c58327', '看花', '看花', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["努力少年求好官，好花須是少年看。","君看老大逢花樹，未折一枝心已闌。"]', '["努力少年求好官，好花須是少年看。","君看老大逢花樹，未折一枝心已闌。"]', '诗', 'shi', '', NULL, '看花 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a413ed7-6711-44b2-ad6a-b47450108b1d', '斑竹', '斑竹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["一枝斑竹渡湘沅，萬里行人感別魂。","知是娥皇廟前物，遠隨風雨送啼痕。"]', '["一枝斑竹渡湘沅，万里行人感別魂。","知是娥皇廟前物，远隨风雨送啼痕。"]', '诗', 'shi', '', NULL, '斑竹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d98eb31f-b3ee-4260-92f9-8cb8ea41ea6b', '箏', '箏', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫愁私地愛王昌，夜夜箏聲怨隔牆。","火鳳有凰求不得，春鶯無伴囀空長。","急揮舞破催飛燕，慢逐歌詞弄小娘。","死恨相如新索婦，枉將心力爲他狂。"]', '["莫愁私地愛王昌，夜夜箏声怨隔牆。","火鳳有凰求不得，春鶯無伴囀空长。","急揮舞破催飞燕，慢逐歌词弄小娘。","死恨相如新索婦，枉將心力爲他狂。"]', '诗', 'shi', '', NULL, '箏 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c27e1d9-2475-4e73-b738-7a55dfb45fc9', '春曉', '春晓', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["半欲天明半未明，醉聞花氣睡聞鶯。","𤞇兒撼起鐘聲動，二十年前曉寺情。"]', '["半欲天明半未明，醉闻花氣睡闻鶯。","𤞇兒撼起鐘声动，二十年前晓寺情。"]', '诗', 'shi', '', NULL, '春曉 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b097335d-ca08-4438-9510-e6096fc017b8', '所思二首 一', '所思二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["庾亮樓中初見時，武昌春柳似腰肢。","相逢相失還如夢，爲雨爲雲今不知。"]', '["庾亮楼中初见时，武昌春柳似腰肢。","相逢相失還如梦，爲雨爲云今不知。"]', '诗', 'shi', '', NULL, '所思二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38efdf17-955d-49a2-b653-943a241b1a51', '所思二首 二', '所思二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鄂渚濛濛煙雨微，女郎魂逐暮雲歸。","只應長在漢陽渡，化作鴛鴦一隻飛。"]', '["鄂渚濛濛煙雨微，女郎魂逐暮云归。","只應长在漢陽渡，化作鴛鴦一隻飞。"]', '诗', 'shi', '', NULL, '所思二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ef6401-b33c-4077-89bc-f01fc3279dce', '鶯鶯詩', '鶯鶯诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["殷紅淺碧舊衣裳，取次梳頭闇澹妝。","夜合帶煙籠曉日，牡丹經雨泣殘陽。","低迷隱笑原非笑，散漫清香不似香。","頻動橫波嗔阿母，等閑教見小兒郎。"]', '["殷紅淺碧旧衣裳，取次梳头闇澹妝。","夜合带煙籠晓日，牡丹經雨泣殘陽。","低迷隐笑原非笑，散漫清香不似香。","頻动橫波嗔阿母，等闲教见小兒郎。"]', '诗', 'shi', '', NULL, '鶯鶯詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93b76dba-03fa-4474-ab05-fde7a29b212b', '離思五首 一', '離思五首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["自愛殘妝曉鏡中，環釵謾篸綠絲叢。","須臾日射燕脂頰，一朵紅蘇旋欲融。"]', '["自愛殘妝晓镜中，环釵謾篸綠絲叢。","須臾日射燕脂頰，一朵紅蘇旋欲融。"]', '诗', 'shi', '', NULL, '離思五首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77854aa8-a4df-45d4-8954-3bdfabae4e7a', '離思五首 二', '離思五首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["山泉散漫繞階流，萬樹桃花暎小樓。","閑讀道書慵未起，水晶簾下看梳頭。"]', '["山泉散漫繞階流，万樹桃花暎小楼。","闲读道书慵未起，水晶簾下看梳头。"]', '诗', 'shi', '', NULL, '離思五首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cefcc178-b5f8-4e84-acb2-7426d40d7a60', '離思五首 三', '離思五首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["紅羅著壓逐時新，吉了花紗嫩麴塵。","第一莫嫌材地弱，些些紕縵最宜人。"]', '["紅羅著壓逐时新，吉了花紗嫩麴塵。","第一莫嫌材地弱，些些紕縵最宜人。"]', '诗', 'shi', '', NULL, '離思五首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de747326-60b6-4d83-9a80-ea9dc9faec13', '離思五首 四', '離思五首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["曾經滄海難爲水，除却巫山不是雲。","取次花叢嬾迴顧，半緣修道半緣君。"]', '["曾經滄海难爲水，除却巫山不是云。","取次花叢嬾迴顧，半緣修道半緣君。"]', '诗', 'shi', '', NULL, '離思五首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff039b04-41f7-4bee-9ab1-5706ad5098f4', '離思五首 五', '離思五首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["尋常百種花齊發，偏摘棃花與白人。","今日江頭兩三樹，可憐和葉度殘春。"]', '["尋常百種花齊發，偏摘棃花與白人。","今日江头兩三樹，可怜和葉度殘春。"]', '诗', 'shi', '', NULL, '離思五首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3395d4d-0a3a-4f21-8bbe-df008a886d51', '雜憶五首 一', '杂憶五首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["今年寒食月無光，夜色纔侵已上牀。","憶得雙文通內裏，玉櫳深處暗聞香。"]', '["今年寒食月無光，夜色纔侵已上牀。","憶得雙文通內裏，玉櫳深处暗闻香。"]', '诗', 'shi', '', NULL, '雜憶五首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0c42d02-eead-460c-93d1-11a04736d246', '雜憶五首 二', '杂憶五首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["花籠微月竹籠煙，百尺絲繩拂地懸。","憶得雙文人靜後，潛教桃葉送鞦韆。"]', '["花籠微月竹籠煙，百尺絲繩拂地懸。","憶得雙文人静後，潛教桃葉送鞦韆。"]', '诗', 'shi', '', NULL, '雜憶五首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1012eab2-7f98-4ed7-a813-e7a8a15579a7', '雜憶五首 三', '杂憶五首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["寒輕夜淺繞回廊，不辨花叢暗辨香。","憶得雙文朧月下，小樓前後捉迷藏。"]', '["寒轻夜淺繞回廊，不辨花叢暗辨香。","憶得雙文朧月下，小楼前後捉迷藏。"]', '诗', 'shi', '', NULL, '雜憶五首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99fc571b-24a4-4520-bff8-ee677f323b54', '雜憶五首 四', '杂憶五首 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["山榴似火葉相兼，亞拂塼階半拂檐。","憶得雙文獨披掩，滿頭花草倚新簾。"]', '["山榴似火葉相兼，亞拂塼階半拂檐。","憶得雙文独披掩，满头花草倚新簾。"]', '诗', 'shi', '', NULL, '雜憶五首 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe67598-78d6-4a90-b68b-7a32e2c2a468', '雜憶五首 五', '杂憶五首 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春冰消盡碧波湖，漾影殘霞似有無。","憶得雙文衫子薄，鈿頭雲暎褪紅酥。"]', '["春冰消尽碧波湖，漾影殘霞似有無。","憶得雙文衫子薄，鈿头云暎褪紅酥。"]', '诗', 'shi', '', NULL, '雜憶五首 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc66dae-9544-419e-ad13-bef2f0f0eb00', '有所教', '有所教', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫畫長眉畫短眉，斜紅傷豎莫傷垂。","人人總解爭時勢，都大須看各自宜。"]', '["莫畫长眉畫短眉，斜紅傷豎莫傷垂。","人人總解爭时勢，都大須看各自宜。"]', '诗', 'shi', '', NULL, '有所教 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11b2a981-689c-4ab8-843f-bdfbe7e15669', '襄陽爲盧竇紀事 一', '襄陽爲盧竇紀事 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["帝下真符召玉真，偶逢遊女暫相親。","素書三卷留爲贈，從向人間說向人。"]', '["帝下真符召玉真，偶逢游女暫相親。","素书三卷留爲贈，從向人间说向人。"]', '诗', 'shi', '', NULL, '襄陽爲盧竇紀事 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37e40ad1-9efa-4c05-909c-cd2e7d01b735', '襄陽爲盧竇紀事 二', '襄陽爲盧竇紀事 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["風弄花枝月照階，醉和春睡倚香懷。","依稀似覺雙環動，潛被蕭郎卸玉釵。"]', '["风弄花枝月照階，醉和春睡倚香懷。","依稀似覺雙环动，潛被蕭郎卸玉釵。"]', '诗', 'shi', '', NULL, '襄陽爲盧竇紀事 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaa8f109-244f-4aa0-8d48-0530a4b47bcb', '襄陽爲盧竇紀事 三', '襄陽爲盧竇紀事 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["鶯聲撩亂曙燈殘，暗覓金釵動曉寒。","猶帶春酲嬾相送，櫻桃花下隔簾看。"]', '["鶯声撩亂曙灯殘，暗覓金釵动晓寒。","猶带春酲嬾相送，櫻桃花下隔簾看。"]', '诗', 'shi', '', NULL, '襄陽爲盧竇紀事 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c402e39c-6fb4-4dbd-afcf-a3cdc560e697', '襄陽爲盧竇紀事 四', '襄陽爲盧竇紀事 四', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["琉璃波面月籠煙，暫逐蕭郎走上天。","今日歸時最腸斷，回江還是夜來船。"]', '["琉璃波面月籠煙，暫逐蕭郎走上天。","今日归时最腸斷，回江還是夜来船。"]', '诗', 'shi', '', NULL, '襄陽爲盧竇紀事 四 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86c0f428-44fd-4e96-9058-f5a69df61402', '襄陽爲盧竇紀事 五', '襄陽爲盧竇紀事 五', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["花枝臨水復臨堤，閑照江流亦照泥。","千萬春風好擡舉，夜來曾有鳳皇栖。"]', '["花枝臨水复臨堤，闲照江流亦照泥。","千万春风好擡舉，夜来曾有鳳皇栖。"]', '诗', 'shi', '', NULL, '襄陽爲盧竇紀事 五 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0eba22a-3749-4e5b-9fea-1dc7e9910f5d', '會真詩三十韻', '會真诗三十韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["微月透簾櫳，螢光度碧空。","遙天初縹緲，低樹漸蔥蘢。","龍吹過庭竹，鸞歌拂井桐。","羅綃垂薄霧，環佩響輕風。","絳節隨金母，雲心捧玉童。","更深人悄悄，晨會雨濛濛。","珠瑩光文履，花明隱繡櫳。","寶釵行彩鳳，羅帔掩丹虹。","言自瑤華浦，將朝碧帝宮。","因遊李城北，偶向宋家東。","戲調初微拒，柔情已暗通。","低鬟蟬影動，廻步玉塵蒙。","轉面流花雪，登牀抱綺叢。","鴛鴦交頸舞，翡翠合歡籠。","眉黛羞頻聚，朱脣暖更融。","氣清蘭蘂馥，膚潤玉肌豐。","無力慵移腕，多嬌愛斂躬。","汗光珠點點，髮亂綠鬆鬆。","方喜千年會，俄聞五夜窮。","留連時有限，繾綣意難終。","慢臉含愁態，芳詞誓素衷。","贈環明運合，留結表心同。","啼粉流清鏡，殘燈繞暗蟲。","華光獨冉冉，旭日漸曈曈。","警乘還歸洛，吹簫亦上嵩。","衣香猶染麝，枕膩尚殘紅。","羃羃臨塘草，飄飄思渚蓬。","素琴鳴怨鶴，清漢望歸鴻。","海闊誠難度，天高不易沖。","行雲無處所，蕭史在樓中。"]', '["微月透簾櫳，螢光度碧空。","遙天初縹緲，低樹漸蔥蘢。","龙吹過庭竹，鸾歌拂井桐。","羅綃垂薄霧，环佩响轻风。","絳節隨金母，云心捧玉童。","更深人悄悄，晨會雨濛濛。","珠瑩光文履，花明隐繡櫳。","寶釵行彩鳳，羅帔掩丹虹。","言自瑤华浦，將朝碧帝宮。","因游李城北，偶向宋家东。","戲調初微拒，柔情已暗通。","低鬟蟬影动，廻步玉塵蒙。","轉面流花雪，登牀抱綺叢。","鴛鴦交頸舞，翡翠合歡籠。","眉黛羞頻聚，朱脣暖更融。","氣清蘭蘂馥，膚潤玉肌豐。","無力慵移腕，多嬌愛斂躬。","汗光珠点点，髮亂綠鬆鬆。","方喜千年會，俄闻五夜窮。","留連时有限，繾綣意难終。","慢臉含愁態，芳词誓素衷。","贈环明運合，留結表心同。","啼粉流清镜，殘灯繞暗蟲。","华光独冉冉，旭日漸曈曈。","警乘還归洛，吹簫亦上嵩。","衣香猶染麝，枕膩尚殘紅。","羃羃臨塘草，飄飄思渚蓬。","素琴鳴怨鹤，清漢望归鴻。","海闊誠难度，天高不易沖。","行云無处所，蕭史在楼中。"]', '诗', 'shi', '', NULL, '會真詩三十韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac17224-0a89-415f-83b0-e942a652d48d', '古豔詩二首 一', '古豔诗二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["春來頻到宋家東，垂袖開懷待好風。","鶯藏柳闇無人語，惟有牆花滿樹紅。"]', '["春来頻到宋家东，垂袖开懷待好风。","鶯藏柳闇無人語，惟有牆花满樹紅。"]', '诗', 'shi', '', NULL, '古豔詩二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65076398-9b91-4f22-8f67-4e2981a805aa', '古豔詩二首 二', '古豔诗二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["深院無人草樹光，嬌鶯不語趁陰藏。","等閑弄水浮花片，流出門前賺阮郎。"]', '["深院無人草樹光，嬌鶯不語趁陰藏。","等闲弄水浮花片，流出门前賺阮郎。"]', '诗', 'shi', '', NULL, '古豔詩二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3305dc1-6c72-49a4-a0fe-e356378218f1', '奉和浙西大夫李德裕述夢四十韻大夫本題言贈於夢中詩賦以寄一二僚友故今所和者亦止述翰苑舊游而已次本韻', '奉和浙西大夫李德裕述梦四十韻大夫本題言贈於梦中诗賦以寄一二僚友故今所和者亦止述翰苑旧游而已次本韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["聞有池塘什，還因夢寐遭。","攀禾工類蔡，詠豆敏過曹。","莊蝶玄言祕，羅禽藻思高。","戈矛排筆陣，貔虎讓文韜。","綵繢鸞凰頸，權奇驥騄髦。","神樞千里應，華衮一言褒。","李廣留飛箭，王祥得佩刀。","傳乘司隸馬，繼染翰林毫。","辨穎□超脫，詞鋒豈足櫜。","金剛錐透玉，鑌鐵劒吹毛。","顧我曾陪附，思君正鬱陶。","近酬新樂錄，仍寄續離騷。","阿閣偏隨鳳，方壺共跨鼇。","借騎銀杏葉，橫賜錦垂萄。","冰井分珍果，金瓶貯御醪。","獨辭珠有戒，廉取玉非叨。","麥紙侵紅點，蘭燈燄碧高。","代予言不易，承聖旨偏勞。","繞月同棲鵲，驚風比夜獒。","吏傳開鎖契，神撼引鈴絛。","渥澤深難報，危心過自操。","犯顏誠懇懇，騰口懼忉忉。","佩寵雖緺綬，安貧尚葛袍。","賓親多謝絕，延薦必英豪。","分阻杯盤會，閒隨寺觀遨。","祗園一林杏，仙洞萬株桃。","澥海滄波減，昆明劫火熬。","未陪登鶴駕，已訃墮烏號。","痛淚過江浪，冤聲出海濤。","尚看恩詔濕，已夢壽宮牢。","再造承天寶，新持濟巨篙。","猶憐弊簪履，重委舊旌旄。","北望心彌苦，西回首屢搔。","九霄難就日，兩浙僅容舠。","暮竹寒窗影，衰楊古郡濠。","魚鰕集橘市，鶴鸛起亭臯。","朽刃休衝斗，良弓枉在弢。","早彎摧虎兕，便鑄墾蓬蒿。","漁艇宜孤棹，樓船稱萬艘。","量材分用處，終不學滔滔。"]', '["闻有池塘什，還因梦寐遭。","攀禾工類蔡，詠豆敏過曹。","莊蝶玄言祕，羅禽藻思高。","戈矛排笔陣，貔虎讓文韜。","綵繢鸾凰頸，權奇驥騄髦。","神樞千里應，华衮一言褒。","李廣留飞箭，王祥得佩刀。","傳乘司隸马，繼染翰林毫。","辨穎□超脫，词鋒豈足櫜。","金剛錐透玉，鑌鐵劒吹毛。","顧我曾陪附，思君正鬱陶。","近酬新乐錄，仍寄續離騷。","阿閣偏隨鳳，方壺共跨鼇。","借騎銀杏葉，橫賜錦垂萄。","冰井分珍果，金瓶貯御醪。","独辞珠有戒，廉取玉非叨。","麦紙侵紅点，蘭灯燄碧高。","代予言不易，承聖旨偏勞。","繞月同棲鵲，驚风比夜獒。","吏傳开鎖契，神撼引鈴絛。","渥澤深难報，危心過自操。","犯顏誠懇懇，腾口懼忉忉。","佩寵雖緺綬，安貧尚葛袍。","賓親多謝絕，延薦必英豪。","分阻杯盤會，閒隨寺观遨。","祗园一林杏，仙洞万株桃。","澥海滄波減，昆明劫火熬。","未陪登鹤駕，已訃墮烏號。","痛泪過江浪，冤声出海濤。","尚看恩詔濕，已梦壽宮牢。","再造承天寶，新持濟巨篙。","猶怜弊簪履，重委旧旌旄。","北望心彌苦，西回首屢搔。","九霄难就日，兩浙僅容舠。","暮竹寒窗影，衰楊古郡濠。","鱼鰕集橘市，鹤鸛起亭臯。","朽刃休衝斗，良弓枉在弢。","早彎摧虎兕，便鑄墾蓬蒿。","漁艇宜孤棹，楼船稱万艘。","量材分用处，終不学滔滔。"]', '诗', 'shi', '', NULL, '奉和浙西大夫李德裕述夢四十韻大夫本題言贈於夢中詩賦以寄一二僚友故今所和者亦止述翰苑舊游而已次本韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff97354c-8737-4f1b-b828-f5599f0f219b', '自述', '自述', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["延英引對碧衣郎，江硯宣毫各別牀。","天子下簾親考試，宮人手裏過茶湯。"]', '["延英引对碧衣郎，江硯宣毫各別牀。","天子下簾親考試，宮人手裏過茶湯。"]', '诗', 'shi', '', NULL, '自述 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef14e4f-e564-4e52-a7a8-5db3f45458a6', '春分投簡陽明洞天作', '春分投簡陽明洞天作', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["中分春一半，今日半春徂。","老惜光陰甚，慵牽興緒孤。","偶成投祕簡，聊得泛平湖。","郡邑移仙界，山川展畫圖。","旌旗遮嶼浦，士女滿闉闍。","似木吳兒勁，如花越女姝。","牛儂驚力直，蠶妾笑睢盱。","怪我攜章甫，嘲人託鷓鴣。","閭閻隨地勝，風俗舉華殊。","跣足沿流婦，丫頭避役奴。","雕題雖少有，雞卜尚多巫。","鄉味尤珍蛤，家神愛事烏。","舟船通海嶠，田種繞城隅。","櫛比千艘合，袈裟萬頃鋪。","亥茶闐小市，漁父隔深蘆。","日脚斜穿浪，雲根遠曳蒲。","凝風花氣度，新雨草芽蘇。","粉壞梅辭萼，紅含杏綴珠。","薅餘秧漸長，燒後葑猶枯。","綠綟高懸柳，青錢密辮榆。","馴鷗眠淺瀨，驚雉迸平蕪。","水靜王餘見，山空謝豹呼。","燕狂捎蛺蝶，螟挂集蒲盧。","淺碧鶴新卵，深黃鵝嫩雛。","邨扉以白板，寺壁耀赬糊。","禹廟纔離郭，陳莊恰半途。","石帆何峭嶢，龍瑞本縈紆。","穴爲探符坼，潭因失箭刳。","隄形彎熨斗，峰勢踴香爐。","幢蓋迎三洞，煙霞貯一壺。","桃枝蟠復直，桑樹亞還扶。","鼈解稱從事，松堪作大夫。","榮光飄殿閣，虛籟合笙竽。","庭狎仙翁鹿，池游縣令鳧。","君心除健羨，扣寂入虛無。","岡蹋翻星紀，章飛動帝樞。","東皇提白日，北斗下玄都。","騎吏帬皆紫，科車幰盡朱。","地侯鞭社伯，海若跨天吳。","霧噴雷公怒，煙揚竈鬼趨。","投壺憐玉女，噀飯笑麻姑。","果實經千歲，衣裳重六銖。","瓊杯傳素液，金匕進雕胡。","掌裏承來露，盤中釣得鱸。","菌生悲局促，柯爛覺須臾。","稊米休言聖，醯雞益伏愚。","鼓鼙催瞑色，簪組縛微軀。","遂別真徒侶，還來世路衢。","題詩歎城郭，揮手謝妻孥。","幸有桃源近，全家肯去無。"]', '["中分春一半，今日半春徂。","老惜光陰甚，慵牽兴緒孤。","偶成投祕簡，聊得泛平湖。","郡邑移仙界，山川展畫圖。","旌旗遮嶼浦，士女满闉闍。","似木吳兒勁，如花越女姝。","牛儂驚力直，蠶妾笑睢盱。","怪我携章甫，嘲人託鷓鴣。","閭閻隨地勝，风俗舉华殊。","跣足沿流婦，丫头避役奴。","雕題雖少有，雞卜尚多巫。","乡味尤珍蛤，家神愛事烏。","舟船通海嶠，田種繞城隅。","櫛比千艘合，袈裟万頃鋪。","亥茶闐小市，漁父隔深蘆。","日脚斜穿浪，云根远曳蒲。","凝风花氣度，新雨草芽蘇。","粉壞梅辞萼，紅含杏綴珠。","薅餘秧漸长，燒後葑猶枯。","綠綟高懸柳，青錢密辮榆。","馴鷗眠淺瀨，驚雉迸平蕪。","水静王餘见，山空謝豹呼。","燕狂捎蛺蝶，螟挂集蒲盧。","淺碧鹤新卵，深黄鵝嫩雛。","邨扉以白板，寺壁耀赬糊。","禹廟纔離郭，陳莊恰半途。","石帆何峭嶢，龙瑞本縈紆。","穴爲探符坼，潭因失箭刳。","隄形彎熨斗，峰勢踴香爐。","幢蓋迎三洞，煙霞貯一壺。","桃枝蟠复直，桑樹亞還扶。","鼈解稱從事，松堪作大夫。","榮光飄殿閣，虛籟合笙竽。","庭狎仙翁鹿，池游縣令鳧。","君心除健羨，扣寂入虛無。","岡蹋翻星紀，章飞动帝樞。","东皇提白日，北斗下玄都。","騎吏帬皆紫，科车幰尽朱。","地侯鞭社伯，海若跨天吳。","霧噴雷公怒，煙揚竈鬼趨。","投壺怜玉女，噀飯笑麻姑。","果實經千歲，衣裳重六銖。","瓊杯傳素液，金匕進雕胡。","掌裏承来露，盤中釣得鱸。","菌生悲局促，柯爛覺須臾。","稊米休言聖，醯雞益伏愚。","鼓鼙催瞑色，簪組縛微軀。","遂別真徒侶，還来世路衢。","題诗歎城郭，揮手謝妻孥。","幸有桃源近，全家肯去無。"]', '诗', 'shi', '', NULL, '春分投簡陽明洞天作 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84b5587a-f71a-4b05-a586-9be49cbf6fb6', '春遊', '春游', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["酒戶年年減，山行漸漸難。","欲終心懶慢，轉恐興闌散。","鏡水波猶冷，稽峰雪尚殘。","不能辜物色，乍可怯春寒。","遠目傷千里，新年思萬端。","無人知此意，閑凭小欄干。"]', '["酒戶年年減，山行漸漸难。","欲終心懶慢，轉恐兴闌散。","镜水波猶冷，稽峰雪尚殘。","不能辜物色，乍可怯春寒。","远目傷千里，新年思万端。","無人知此意，闲凭小欄干。"]', '诗', 'shi', '', NULL, '春遊 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb3a6f8-8459-47f3-a523-c4207c3c5776', '除夜酬樂天', '除夜酬乐天', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["引儺綏斾亂毿毿，戲罷人歸思不堪。","虛漲火塵龜浦北，無由阿傘鳳城南。","休官期限元同約，除夜情懷老共諳。","莫道明朝始添歲，今年春在歲前三。"]', '["引儺綏斾亂毿毿，戲罷人归思不堪。","虛漲火塵龟浦北，無由阿傘鳳城南。","休官期限元同約，除夜情懷老共諳。","莫道明朝始添歲，今年春在歲前三。"]', '诗', 'shi', '', NULL, '除夜酬樂天 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9fde5d5-c84d-460a-8642-86813b4068c7', '酬樂天初冬早寒見寄', '酬乐天初冬早寒见寄', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["乍起衣猶冷，微吟帽半敧。","霜凝南屋瓦，雞唱後園枝。","洛水碧雲曉，吳宮黃葉時。","兩傳千里意，書札不如詩。"]', '["乍起衣猶冷，微吟帽半敧。","霜凝南屋瓦，雞唱後园枝。","洛水碧云晓，吳宮黄葉时。","兩傳千里意，书札不如诗。"]', '诗', 'shi', '', NULL, '酬樂天初冬早寒見寄 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f6fcc0-4709-4d41-8e95-2ba1b851be27', '酬白樂天杏花園', '酬白乐天杏花园', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["劉郎不用閑惆悵，且作花間共醉人。","算得貞元舊朝士，幾人同見太和春。"]', '["劉郎不用闲惆悵，且作花间共醉人。","算得貞元旧朝士，幾人同见太和春。"]', '诗', 'shi', '', NULL, '酬白樂天杏花園 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5786583f-f2e4-4d98-97ae-143d78135231', '過東都別樂天二首 一', '過东都別乐天二首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["君應怪我留連久，我欲與君辭別難。","白頭徒侶漸稀少，明日恐君無此歡。"]', '["君應怪我留連久，我欲與君辞別难。","白头徒侶漸稀少，明日恐君無此歡。"]', '诗', 'shi', '', NULL, '過東都別樂天二首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cd675e1-ee14-4478-8dd0-90f6b9f81c03', '過東都別樂天二首 二', '過东都別乐天二首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["自識君來三度別，這回白盡老髭鬚。","戀君不去君須會，知得後廻相見無。"]', '["自識君来三度別，這回白尽老髭鬚。","戀君不去君須會，知得後廻相见無。"]', '诗', 'shi', '', NULL, '過東都別樂天二首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b34aac3b-ebae-43e8-9ef5-aaee061fc76d', '逢白公', '逢白公', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["遠路事無限，相逢唯一言。","月色照榮辱，長安千萬門。"]', '["远路事無限，相逢唯一言。","月色照榮辱，长安千万门。"]', '诗', 'shi', '', NULL, '逢白公 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed2393a3-fef6-4427-b0ce-01bed072df90', '酬白太傅', '酬白太傅', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["太空秋色涼，獨鳥下微陽。","三徑池塘靜，六街車馬忙。","漸能高酒戶，始是入詩狂。","官冷且無事，追陪慎莫忘。"]', '["太空秋色涼，独鸟下微陽。","三徑池塘静，六街车马忙。","漸能高酒戶，始是入诗狂。","官冷且無事，追陪慎莫忘。"]', '诗', 'shi', '', NULL, '酬白太傅 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41194004-fd0f-4bce-a285-934b17fafed0', '和嚴給事聞唐昌觀玉蘂花下有遊仙', '和嚴給事闻唐昌观玉蘂花下有游仙', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["弄玉潛過玉樹時，不教青鳥出花枝。","的應未有諸人覺，只是嚴朗不得知。"]', '["弄玉潛過玉樹时，不教青鸟出花枝。","的應未有諸人覺，只是嚴朗不得知。"]', '诗', 'shi', '', NULL, '和嚴給事聞唐昌觀玉蘂花下有遊仙 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('184d0e8b-963f-4f84-bd96-b085329e3ca7', '贈毛仙翁', '贈毛仙翁', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["仙駕初從蓬海來，相逢又說向天台。","一言親授希微訣，三夕同傾沆瀣杯。","此日臨風飄羽衛，他年嘉約指鹽梅。","花前揮手迢遙去，目斷霓旌不可陪。"]', '["仙駕初從蓬海来，相逢又说向天台。","一言親授希微訣，三夕同傾沆瀣杯。","此日臨风飄羽衛，他年嘉約指鹽梅。","花前揮手迢遙去，目斷霓旌不可陪。"]', '诗', 'shi', '', NULL, '贈毛仙翁 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c574b079-d88b-464f-b53f-bb11bdeb9fe4', '八月十四日夜玩月', '八月十四日夜玩月', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["猶欠一宵輪未滿，紫霞紅襯碧雲端。","誰能喚得姮娥下，引向堂前子細看。"]', '["猶欠一宵輪未满，紫霞紅襯碧云端。","誰能喚得姮娥下，引向堂前子細看。"]', '诗', 'shi', '', NULL, '八月十四日夜玩月 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aea459c-509b-4662-98ac-b877f3fd0bb2', '寒食夜', '寒食夜', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["紅染桃花雪壓棃，玲瓏雞子鬬贏時。","今年不是明寒食，暗地鞦韆別有期。"]', '["紅染桃花雪壓棃，玲瓏雞子鬬贏时。","今年不是明寒食，暗地鞦韆別有期。"]', '诗', 'shi', '', NULL, '寒食夜 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95272c8b-caa7-4baa-8ed3-7308b6ebed7a', '三月三十日程氏館餞杜十四歸京', '三月三十日程氏館餞杜十四归京', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["江春今日盡，程館祖筵開。","我正南冠縶，君尋北路回。","謀身誠太拙，從宦苦無媒。","處困方明命，遭時不在才。","踰年長倚玉，連夜共銜杯。","涸溜霑濡沫，餘光照死灰。","行看鴻欲翥，敢憚酒相催。","拍逐飛觥絕，香隨舞袖來。","消棃拋五徧，娑葛𣩄三臺。","已許尊前倒，臨風淚莫頹。"]', '["江春今日尽，程館祖筵开。","我正南冠縶，君尋北路回。","謀身誠太拙，從宦苦無媒。","处困方明命，遭时不在才。","踰年长倚玉，連夜共銜杯。","涸溜霑濡沫，餘光照死灰。","行看鴻欲翥，敢憚酒相催。","拍逐飞觥絕，香隨舞袖来。","消棃拋五徧，娑葛𣩄三台。","已許尊前倒，臨风泪莫頹。"]', '诗', 'shi', '', NULL, '三月三十日程氏館餞杜十四歸京 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f231302-d3a1-4341-9543-750b8d2909e2', '酬張祕書因寄馬贈詩', '酬張祕书因寄马贈诗', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["丞相功高厭武名，牽將戰馬寄儒生。","四蹄荀距藏雖盡，六尺鬚頭見尚驚。","減粟偷兒憎未飽，騎驢詩客駡先行。","勸君還却司空著，莫遣衙參傍子城。"]', '["丞相功高厭武名，牽將戰马寄儒生。","四蹄荀距藏雖尽，六尺鬚头见尚驚。","減粟偷兒憎未飽，騎驢诗客駡先行。","勸君還却司空著，莫遣衙參傍子城。"]', '诗', 'shi', '', NULL, '酬張祕書因寄馬贈詩 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf4c0d5-df3a-41b2-83b4-aeb8969078d5', '戲酬副使中丞見示四韻', '戲酬副使中丞见示四韻', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["莫恨暫櫜鞬，交游幾箇全。","眼明相見日，肺病欲秋天。","五馬虛盈櫪，雙蛾浪滿船。","可憐俱老大，無處用閑錢。"]', '["莫恨暫櫜鞬，交游幾箇全。","眼明相见日，肺病欲秋天。","五马虛盈櫪，雙蛾浪满船。","可怜俱老大，無处用闲錢。"]', '诗', 'shi', '', NULL, '戲酬副使中丞見示四韻 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4862a80-d33a-4e84-b851-b3bbb6ce9e0c', '贈柔之', '贈柔之', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["窮冬到鄉國，正歲別京華。","自恨風塵眼，常看遠地花。","碧幢還照曜，紅粉莫咨嗟。","嫁得浮雲壻，相隨即是家。"]', '["窮冬到乡国，正歲別京华。","自恨风塵眼，常看远地花。","碧幢還照曜，紅粉莫咨嗟。","嫁得浮云壻，相隨即是家。"]', '诗', 'shi', '', NULL, '贈柔之 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6f9d1f6-d814-4f29-aaff-577b3f3b338c', '修龜山魚池示衆僧', '修龟山鱼池示衆僧', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["勸爾諸僧好護持，不須垂釣引青絲。","雲山莫厭看經坐，便是浮生得道時。"]', '["勸爾諸僧好護持，不須垂釣引青絲。","云山莫厭看經坐，便是浮生得道时。"]', '诗', 'shi', '', NULL, '修龜山魚池示衆僧 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2af18de6-d652-4799-9659-ca3b1f491559', '寄贈薛濤', '寄贈薛濤', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["錦江滑膩蛾眉秀，幻出文君與薛濤。","言語巧偷鸚鵡舌，文章分得鳳皇毛。","紛紛辭客多停筆，箇箇公卿欲夢刀。","別後相思隔煙水，菖蒲花發五雲高。"]', '["錦江滑膩蛾眉秀，幻出文君與薛濤。","言語巧偷鸚鵡舌，文章分得鳳皇毛。","紛紛辞客多停笔，箇箇公卿欲梦刀。","別後相思隔煙水，菖蒲花發五云高。"]', '诗', 'shi', '', NULL, '寄贈薛濤 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('036ceb3f-2c41-4208-8b3b-fdf052517667', '贈劉採春', '贈劉採春', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["新粧巧樣畫雙蛾，謾裹常州透額羅。","正面偷勻光滑笏，緩行輕踏破紋波。","言辭雅措風流足，舉止低迴秀媚多。","更有惱人腸斷處，選詞能唱望夫歌。"]', '["新粧巧樣畫雙蛾，謾裹常州透額羅。","正面偷勻光滑笏，緩行轻踏破紋波。","言辞雅措风流足，舉止低迴秀媚多。","更有惱人腸斷处，選词能唱望夫歌。"]', '诗', 'shi', '', NULL, '贈劉採春 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e73c3ca-362f-4c54-9201-2b219df8180c', '醉題東武', '醉題东武', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["役役行人事，紛紛碎簿書。","功夫兩衙盡，留滯七年餘。","病痛梅天發，親情海岸疎。","因循未歸得，不是憶鱸魚。"]', '["役役行人事，紛紛碎簿书。","功夫兩衙尽，留滯七年餘。","病痛梅天發，親情海岸疎。","因循未归得，不是憶鱸鱼。"]', '诗', 'shi', '', NULL, '醉題東武 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('875827b7-3e08-4c24-8069-e15b5a3099e1', '崔徽歌', '崔徽歌', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["崔徽本不是娼家，教歌按舞娼家長。","使君知有不自由，坐在頭時立在掌。","有客有客名丘夏，善寫儀容得恣把。","爲徽持此謝敬中，以死報郎爲□□。"]', '["崔徽本不是娼家，教歌按舞娼家长。","使君知有不自由，坐在头时立在掌。","有客有客名丘夏，善寫儀容得恣把。","爲徽持此謝敬中，以死報郎爲□□。"]', '诗', 'shi', '', NULL, '崔徽歌 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a880cf-50a6-48c2-babd-0a6a19a7fad3', '一字至七字詩 茶', '一字至七字诗 茶', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["茶，香葉，嫩芽。","慕詩客，愛僧家。","碾雕白玉，羅織紅紗。","銚煎黃蘂色，椀轉麴塵花。","夜後邀陪明月，晨前命對朝霞。","洗盡古今人不倦，將知醉後豈堪誇。"]', '["茶，香葉，嫩芽。","慕诗客，愛僧家。","碾雕白玉，羅织紅紗。","銚煎黄蘂色，椀轉麴塵花。","夜後邀陪明月，晨前命对朝霞。","洗尽古今人不倦，將知醉後豈堪誇。"]', '诗', 'shi', '', NULL, '一字至七字詩 茶 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('280f1aaf-b380-4080-8d96-cca5b5704548', '句', '句', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["兒歌楊柳葉，妾拂石榴花。","松門待制應全遠，藥樹監搜可得知。","髻鬟峨峨高一尺，門前立地看春風。"]', '["兒歌楊柳葉，妾拂石榴花。","松门待制應全远，藥樹監搜可得知。","髻鬟峨峨高一尺，门前立地看春风。"]', '诗', 'shi', '', NULL, '句 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c628410-da54-43bd-965c-e4ab548f0519', '賀雨', '賀雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["皇帝嗣寶曆，元和三年冬。","自冬及春暮，不雨旱爞爞。","上心念下民，懼歲成災凶。","遂下罪己詔，殷勤告萬邦。","帝曰予一人，繼天承祖宗。","憂勤不遑寧，夙夜心忡忡。","元年誅劉闢，一舉靖巴邛。","二年戮李錡，不戰安江東。","顧惟眇眇德，遽有巍巍功。","或者天降沴，無乃儆予躬。","上思天戒，下思致時邕。","莫如率其身，慈和與儉恭。","乃命罷進獻，乃命賑饑窮。","宥死降五刑，責己寬三農。","宮女出宣徽，廐馬減飛龍。","庶政靡不舉，皆出自宸衷。","奔騰道路人，傴僂田野翁。","歡呼相告報，感泣涕霑胸。","順人人心悅，先天天意從。","詔下纔七日，和氣生沖融。","凝爲油油雲，散作習習風。","晝夜三日雨，淒淒復濛濛。","萬心春熙熙，百穀青芃芃。","人變愁爲喜，歲易儉爲豐。","乃知王者心，憂樂與衆同。","皇天與后土，所感無不通。","冠珮何鏘鏘，將相及王公。","蹈舞呼萬歲，列賀明庭中。","小臣誠愚陋，職忝金鑾宮。","稽首再三拜，一言獻天聰。","君以明爲聖，臣以直爲忠。","敢賀有其始，亦願有其終。"]', '["皇帝嗣寶曆，元和三年冬。","自冬及春暮，不雨旱爞爞。","上心念下民，懼歲成災凶。","遂下罪己詔，殷勤告万邦。","帝曰予一人，繼天承祖宗。","憂勤不遑寧，夙夜心忡忡。","元年誅劉闢，一舉靖巴邛。","二年戮李錡，不戰安江东。","顧惟眇眇德，遽有巍巍功。","或者天降沴，無乃儆予躬。","上思天戒，下思致时邕。","莫如率其身，慈和與儉恭。","乃命罷進獻，乃命賑饑窮。","宥死降五刑，責己寬三農。","宮女出宣徽，廐马減飞龙。","庶政靡不舉，皆出自宸衷。","奔腾道路人，傴僂田野翁。","歡呼相告報，感泣涕霑胸。","順人人心悅，先天天意從。","詔下纔七日，和氣生沖融。","凝爲油油云，散作習習风。","晝夜三日雨，淒淒复濛濛。","万心春熙熙，百穀青芃芃。","人变愁爲喜，歲易儉爲豐。","乃知王者心，憂乐與衆同。","皇天與后土，所感無不通。","冠珮何鏘鏘，將相及王公。","蹈舞呼万歲，列賀明庭中。","小臣誠愚陋，職忝金鑾宮。","稽首再三拜，一言獻天聰。","君以明爲聖，臣以直爲忠。","敢賀有其始，亦願有其終。"]', '诗', 'shi', '', NULL, '賀雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd828f73-1d2b-479f-a8ae-d51f3ebfbe5f', '讀張籍古樂府', '读張籍古乐府', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["張君何爲者，業文三十春。","尤工樂府詩，舉代少其倫。","爲詩意如何，六義互鋪陳。","風雅比興外，未嘗著空文。","讀君學仙詩，可諷放佚君。","讀君董公詩，可誨貪暴臣。","讀君商女詩，可感悍婦仁。","讀君勤齊詩，可勸薄夫敦。","上可裨教化，舒之濟萬民。","下可理情性，卷之善一身。","始從青衿歲，迨此白髮新。","日夜秉筆吟，心苦力亦勤。","時無采詩官，委棄如泥塵。","恐君百歲後，滅沒人不聞。","願藏中祕書，百代不湮淪。","願播內樂府，時得聞至尊。","言者志之苗，行者文之根。","所以讀君詩，亦知君爲人。","如何欲五十，官小身賤貧。","病眼街西住，無人行到門。"]', '["張君何爲者，業文三十春。","尤工乐府诗，舉代少其倫。","爲诗意如何，六義互鋪陳。","风雅比兴外，未嘗著空文。","读君学仙诗，可諷放佚君。","读君董公诗，可誨貪暴臣。","读君商女诗，可感悍婦仁。","读君勤齊诗，可勸薄夫敦。","上可裨教化，舒之濟万民。","下可理情性，卷之善一身。","始從青衿歲，迨此白髮新。","日夜秉笔吟，心苦力亦勤。","时無采诗官，委棄如泥塵。","恐君百歲後，滅沒人不闻。","願藏中祕书，百代不湮淪。","願播內乐府，时得闻至尊。","言者志之苗，行者文之根。","所以读君诗，亦知君爲人。","如何欲五十，官小身賤貧。","病眼街西住，無人行到门。"]', '诗', 'shi', '', NULL, '讀張籍古樂府 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('713ae960-bba3-4038-8d32-ba4f2af5d5d3', '哭孔戡', '哭孔戡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洛陽誰不死，戡死聞長安。","我是知戡者，聞之涕泫然。","戡佐山東軍，非義不可干。","拂衣向西來，其道直如弦。","從事得如此，人人以爲難。","人言明明代，合置在朝端。","或望居諫司，有事戡必言。","或望居憲府，有邪戡必彈。","惜哉兩不諧，沒齒爲閑官。","竟不得一日，謇謇立君前。","形骸隨衆人，斂葬北邙山。","平生剛腸內，直氣歸其間。","賢者爲生民，生死懸在天。","謂天不愛人，胡爲生其賢。","謂天果愛民，胡爲奪其年。","茫茫元化中，誰執如此權。"]', '["洛陽誰不死，戡死闻长安。","我是知戡者，闻之涕泫然。","戡佐山东軍，非義不可干。","拂衣向西来，其道直如弦。","從事得如此，人人以爲难。","人言明明代，合置在朝端。","或望居諫司，有事戡必言。","或望居憲府，有邪戡必彈。","惜哉兩不諧，沒齒爲闲官。","竟不得一日，謇謇立君前。","形骸隨衆人，斂葬北邙山。","平生剛腸內，直氣归其间。","賢者爲生民，生死懸在天。","謂天不愛人，胡爲生其賢。","謂天果愛民，胡爲奪其年。","茫茫元化中，誰執如此權。"]', '诗', 'shi', '', NULL, '哭孔戡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee3b027-85e1-4d47-941f-0a149efa1ee0', '凶宅', '凶宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["長安多大宅，列在街西東。","往往朱門內，房廊相對空。","梟鳴松桂樹，狐藏蘭菊叢。","蒼苔黃葉地，日暮多旋風。","前主爲將相，得罪竄巴庸。","後主爲公卿，寢疾歿其中。","連延四五主，殃禍繼相鍾。","自從十年來，不利主人翁。","風雨壞檐隙，蛇鼠穿牆墉。","人凝不敢買，日毀土木功。","嗟嗟俗人心，甚矣其愚蒙。","旦恐災將至，不思禍所從。","我今題此詩，欲悟迷者胸。","凡爲大官人，年祿多高崇。","權重持難久，位高勢易窮。","驕者物之盈，老者數之終。","四者如寇盜，日夜來相攻。","假使居吉土，孰能保其躬。","因小以明大，借家可喻邦。","周秦宅殽函，其宅非不同。","一興八百年，一死望夷宮。","寄語家與國，人凶非宅凶。"]', '["长安多大宅，列在街西东。","往往朱门內，房廊相对空。","梟鳴松桂樹，狐藏蘭菊叢。","蒼苔黄葉地，日暮多旋风。","前主爲將相，得罪竄巴庸。","後主爲公卿，寢疾歿其中。","連延四五主，殃禍繼相鍾。","自從十年来，不利主人翁。","风雨壞檐隙，蛇鼠穿牆墉。","人凝不敢買，日毀土木功。","嗟嗟俗人心，甚矣其愚蒙。","旦恐災將至，不思禍所從。","我今題此诗，欲悟迷者胸。","凡爲大官人，年祿多高崇。","權重持难久，位高勢易窮。","驕者物之盈，老者數之終。","四者如寇盜，日夜来相攻。","假使居吉土，孰能保其躬。","因小以明大，借家可喻邦。","周秦宅殽函，其宅非不同。","一兴八百年，一死望夷宮。","寄語家與国，人凶非宅凶。"]', '诗', 'shi', '', NULL, '凶宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e805ce8-041e-42d8-bde7-8e2225219061', '夢仙', '梦仙', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人有夢仙者，夢身升上清。","坐乘一白鶴，前引雙紅旌。","羽衣忽飄飄，玉鸞俄錚錚。","半空直下視，人世塵冥冥。","漸失鄉國處，纔分山水形。","東海一片白，列岳五點青。","須臾羣仙來，相引朝玉京。","安期羨門輩，列侍如公卿。","仰謁玉皇帝，稽首前致誠。","帝言汝仙才，努力勿自輕。","却後十五年，期汝不死庭。","再拜受斯言，既寤喜且驚。","祕之不敢泄，誓志居巖扃。","恩愛捨骨肉，飲食斷羶腥。","朝餐雲母散，夜吸沆瀣精。","空山三十載，日望輜軿迎。","前期過已久，鸞鶴無來聲。","齒髮日衰白，耳目減聰明。","一朝同物化，身與糞壤幷。","神仙信有之，俗力非可營。","苟無金骨相，不列丹臺名。","徒傳辟穀法，虛受燒丹經。","只自取勤苦，百年終不成。","悲哉夢仙人，一夢誤一生。"]', '["人有梦仙者，梦身升上清。","坐乘一白鹤，前引雙紅旌。","羽衣忽飄飄，玉鸾俄錚錚。","半空直下視，人世塵冥冥。","漸失乡国处，纔分山水形。","东海一片白，列岳五点青。","須臾羣仙来，相引朝玉京。","安期羨门輩，列侍如公卿。","仰謁玉皇帝，稽首前致誠。","帝言汝仙才，努力勿自轻。","却後十五年，期汝不死庭。","再拜受斯言，既寤喜且驚。","祕之不敢泄，誓志居巖扃。","恩愛捨骨肉，饮食斷羶腥。","朝餐云母散，夜吸沆瀣精。","空山三十載，日望輜軿迎。","前期過已久，鸾鹤無来声。","齒髮日衰白，耳目減聰明。","一朝同物化，身與糞壤幷。","神仙信有之，俗力非可營。","苟無金骨相，不列丹台名。","徒傳辟穀法，虛受燒丹經。","只自取勤苦，百年終不成。","悲哉梦仙人，一梦誤一生。"]', '诗', 'shi', '', NULL, '夢仙 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('554b95f5-9862-4836-b3e0-f445ac850fed', '觀刈麥', '观刈麦', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["田家少閑月，五月人倍忙。","夜來南風起，小麥覆隴黃。","婦姑荷簞食，童穉攜壺漿。","相隨餉田去，丁壯在南岡。","足蒸暑土氣，背灼炎天光。","力盡不知熱，但惜夏日長。","復有貧婦人，抱子在其傍。","右手秉遺穗，左臂懸敝筐。","聽其相顧言，聞者爲悲傷。","家田輸稅盡，拾此充飢腸。","今我何功德，曾不事農桑。","吏祿三百石，歲晏有餘糧。","念此私自媿盡日不能忘。"]', '["田家少闲月，五月人倍忙。","夜来南风起，小麦覆隴黄。","婦姑荷簞食，童穉携壺漿。","相隨餉田去，丁壯在南岡。","足蒸暑土氣，背灼炎天光。","力尽不知熱，但惜夏日长。","复有貧婦人，抱子在其傍。","右手秉遺穗，左臂懸敝筐。","听其相顧言，闻者爲悲傷。","家田輸稅尽，拾此充飢腸。","今我何功德，曾不事農桑。","吏祿三百石，歲晏有餘糧。","念此私自媿尽日不能忘。"]', '诗', 'shi', '', NULL, '觀刈麥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbc680d9-dfd3-44f1-b8f1-5e339ad8afae', '題海圖屏風', '題海圖屏风', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海水無風時，波濤安悠悠。","鱗介無小大，遂性各沈浮。","突兀海底鼇，首冠三神丘。","釣網不能制，其來非一秋。","或者不量力，謂茲鼇可求。","贔屭牽不動，綸絕沈其鉤。","一鼇既頓頷，諸鼇齊掉頭。","白濤與黑浪，呼吸繞咽喉。","噴風激飛廉，鼓波怒陽侯。","鯨鯢得其便，張口欲吞舟。","萬里無活鱗，百川多倒流。","遂使江漢水，朝宗意亦休。","蒼然屏風上，此畫良有由。"]', '["海水無风时，波濤安悠悠。","鱗介無小大，遂性各沈浮。","突兀海底鼇，首冠三神丘。","釣網不能制，其来非一秋。","或者不量力，謂茲鼇可求。","贔屭牽不动，綸絕沈其鉤。","一鼇既頓頷，諸鼇齊掉头。","白濤與黑浪，呼吸繞咽喉。","噴风激飞廉，鼓波怒陽侯。","鯨鯢得其便，張口欲吞舟。","万里無活鱗，百川多倒流。","遂使江漢水，朝宗意亦休。","蒼然屏风上，此畫良有由。"]', '诗', 'shi', '', NULL, '題海圖屏風 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4aa1b26-6427-485e-b698-a77989f9e567', '羸駿', '羸駿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["驊騮失其主，羸餓無人牧。","向風嘶一聲，莽蒼黃河曲。","蹋冰水畔立，臥雪冢間宿。","歲暮田野空，寒草不滿腹。","豈無市駿者，盡是凡人目。","相馬失於瘦，遂遺千里足。","村中何擾擾，有吏徵芻粟。","輸彼軍廐中，化作駑駘肉。"]', '["驊騮失其主，羸餓無人牧。","向风嘶一声，莽蒼黄河曲。","蹋冰水畔立，臥雪冢间宿。","歲暮田野空，寒草不满腹。","豈無市駿者，尽是凡人目。","相马失於瘦，遂遺千里足。","村中何擾擾，有吏徵芻粟。","輸彼軍廐中，化作駑駘肉。"]', '诗', 'shi', '', NULL, '羸駿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('643e8598-02dc-4b1c-9079-60b9ff28db06', '廢琴', '廢琴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["絲桐合爲琴，中有太古聲。","古聲澹無味，不稱今人情。","玉徽光彩滅，朱弦塵土生。","廢棄來已久，遺音尚泠泠。","不辭爲君彈，縱彈人不聽。","何物使之然，羌笛與秦箏。"]', '["絲桐合爲琴，中有太古声。","古声澹無味，不稱今人情。","玉徽光彩滅，朱弦塵土生。","廢棄来已久，遺音尚泠泠。","不辞爲君彈，縱彈人不听。","何物使之然，羌笛與秦箏。"]', '诗', 'shi', '', NULL, '廢琴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c10b6235-6d2c-4d3a-b5a5-6ca89cd0ba1b', '李都尉古劒', '李都尉古劒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["古劒寒黯黯，鑄來幾千秋。","白光納日月，紫氣排斗牛。","有客借一觀，愛之不敢求。","湛然玉匣中，秋水澄不流。","至寶有本性，精剛無與儔。","可使寸寸折，不能繞指柔。","願快直士心，將斷佞臣頭。","不願報小怨，夜半刺私讎。","勸君慎所用，無作神兵羞。"]', '["古劒寒黯黯，鑄来幾千秋。","白光納日月，紫氣排斗牛。","有客借一观，愛之不敢求。","湛然玉匣中，秋水澄不流。","至寶有本性，精剛無與儔。","可使寸寸折，不能繞指柔。","願快直士心，將斷佞臣头。","不願報小怨，夜半刺私讎。","勸君慎所用，無作神兵羞。"]', '诗', 'shi', '', NULL, '李都尉古劒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a351f7cb-46e0-4519-b17f-2a812ccf3069', '雲居寺孤桐', '云居寺孤桐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一株青玉立，千葉綠雲委。","亭亭五丈餘，高意猶未已。","山僧年九十，清淨老不死。","自云手種時，一棵青桐子。","直從萌芽拔，高自毫末始。","四面無附枝，中心有通理。","寄言立身者，孤直當如此。"]', '["一株青玉立，千葉綠云委。","亭亭五丈餘，高意猶未已。","山僧年九十，清淨老不死。","自云手種时，一棵青桐子。","直從萌芽拔，高自毫末始。","四面無附枝，中心有通理。","寄言立身者，孤直當如此。"]', '诗', 'shi', '', NULL, '雲居寺孤桐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0877cd66-9611-4b76-9fe6-0c6a06e90d48', '京兆府新栽蓮', '京兆府新栽蓮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["汚溝貯濁水，水上葉田田。","我來一長歎，知是東溪蓮。","下有青泥汚，馨香無復全。","上有紅塵撲，顏色不得鮮。","物性猶如此，人事亦宜然。","託根非其所，不如遭棄捐。","昔在溪中日，花葉媚清漣。","今來不得地，顦顇府門前。"]', '["汚溝貯濁水，水上葉田田。","我来一长歎，知是东溪蓮。","下有青泥汚，馨香無复全。","上有紅塵撲，顏色不得鲜。","物性猶如此，人事亦宜然。","託根非其所，不如遭棄捐。","昔在溪中日，花葉媚清漣。","今来不得地，顦顇府门前。"]', '诗', 'shi', '', NULL, '京兆府新栽蓮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aba082d-e238-4881-84e1-b15d57d8ad1d', '月夜登閣避暑', '月夜登閣避暑', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["旱久炎氣盛，中人若燔燒。","青風隱何處，草樹不動搖。","何以避暑氣，無如出塵囂。","行行都門外，佛閣正岧嶤。","清涼近高生，煩熱委靜銷。","開襟當軒坐，意泰神飄飄。","迴看歸路傍，禾黍盡枯焦。","獨善誠有計，將何救旱苗。"]', '["旱久炎氣盛，中人若燔燒。","青风隐何处，草樹不动搖。","何以避暑氣，無如出塵囂。","行行都门外，佛閣正岧嶤。","清涼近高生，煩熱委静銷。","开襟當軒坐，意泰神飄飄。","迴看归路傍，禾黍尽枯焦。","独善誠有計，將何救旱苗。"]', '诗', 'shi', '', NULL, '月夜登閣避暑 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed31a7fa-eef3-4b6b-893b-6cac8b1a65ac', '初授拾遺', '初授拾遺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["奉詔登左掖，束帶參朝議。","何言初命卑，且脫風塵吏。","杜甫陳子昂，才名括天地。","當時非不遇，尚無過斯位。","況余蹇薄者，寵至不自意。","驚近白日光，慙非青雲器。","天子方從諫，朝廷無忌諱。","豈不思匪躬，適遇時無事。","受命已旬月，飽食隨班次。","諫紙忽盈箱，對之終自媿。"]', '["奉詔登左掖，束带參朝議。","何言初命卑，且脫风塵吏。","杜甫陳子昂，才名括天地。","當时非不遇，尚無過斯位。","況余蹇薄者，寵至不自意。","驚近白日光，慙非青云器。","天子方從諫，朝廷無忌諱。","豈不思匪躬，適遇时無事。","受命已旬月，飽食隨班次。","諫紙忽盈箱，对之終自媿。"]', '诗', 'shi', '', NULL, '初授拾遺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e81ae3-9e6d-44ee-a3c9-2a8d49b44bfb', '贈元稹', '贈元稹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自我從宦遊，七年在長安。","所得惟元君，乃知定交難。","豈無山上苗，徑寸無歲寒。","豈無要津水，咫尺有波瀾。","之子異於是，久處誓不諼。","無波古井水，有節秋竹竿。","一爲同心友，三及芳歲闌。","花下鞍馬遊，雪中杯酒歡。","衡門相逢迎，不具帶與冠。","春風日高睡，秋月夜深看。","不爲同登科，不爲同署官。","所合在方寸，心源無異端。"]', '["自我從宦游，七年在长安。","所得惟元君，乃知定交难。","豈無山上苗，徑寸無歲寒。","豈無要津水，咫尺有波瀾。","之子異於是，久处誓不諼。","無波古井水，有節秋竹竿。","一爲同心友，三及芳歲闌。","花下鞍马游，雪中杯酒歡。","衡门相逢迎，不具带與冠。","春风日高睡，秋月夜深看。","不爲同登科，不爲同署官。","所合在方寸，心源無異端。"]', '诗', 'shi', '', NULL, '贈元稹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('661ef3f3-58b7-46ec-b6d1-57aeec5fd95c', '哭劉敦質', '哭劉敦質', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小樹兩株柏，新土三尺墳。","蒼蒼白露草，此地哭劉君。","哭君豈無辭，辭云君子人。","如何天不弔，窮悴至終身。","愚者多貴壽，賢者獨賤迍。","龍亢彼無悔，蠖屈此不伸。","哭罷持此辭，吾將詰羲文。"]', '["小樹兩株柏，新土三尺墳。","蒼蒼白露草，此地哭劉君。","哭君豈無辞，辞云君子人。","如何天不弔，窮悴至終身。","愚者多貴壽，賢者独賤迍。","龙亢彼無悔，蠖屈此不伸。","哭罷持此辞，吾將詰羲文。"]', '诗', 'shi', '', NULL, '哭劉敦質 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5b36596-f308-49fc-addc-b70e609fe19b', '答友問', '答友问', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["大圭廉不割，利劒用不缺。","當其斬馬時，良玉不如鐵。","置鐵在洪爐，鐵消易如雪。","良玉同其中，三日燒不熱。","君疑才與德，詠此知優劣。"]', '["大圭廉不割，利劒用不缺。","當其斬马时，良玉不如鐵。","置鐵在洪爐，鐵消易如雪。","良玉同其中，三日燒不熱。","君疑才與德，詠此知優劣。"]', '诗', 'shi', '', NULL, '答友問 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa451140-ea5c-4abe-a2cd-e1f37f0e40f4', '雜興三首 一', '杂兴三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["楚王多內寵，傾國選嬪妃。","又愛從禽樂，馳騁每相隨。","錦韝臂花隼，羅袂控金羈。","遂習宮中女，皆如馬上兒。","色禽合爲荒，刑政兩已衰。","雲夢春仍獵，章華夜不歸。","東風二月天，春雁正離離。","美人挾銀鏑，一發疊雙飛。","飛鴻驚斷行，斂翅避蛾眉。","君王顧之笑，弓箭生光輝。","迴眸語君曰，昔聞莊王時。","有一愚夫人，其名曰樊姬。","不有此遊樂，三載斷鮮肥。"]', '["楚王多內寵，傾国選嬪妃。","又愛從禽乐，驰騁每相隨。","錦韝臂花隼，羅袂控金羈。","遂習宮中女，皆如马上兒。","色禽合爲荒，刑政兩已衰。","云梦春仍獵，章华夜不归。","东风二月天，春雁正離離。","美人挾銀鏑，一發叠雙飞。","飞鴻驚斷行，斂翅避蛾眉。","君王顧之笑，弓箭生光輝。","迴眸語君曰，昔闻莊王时。","有一愚夫人，其名曰樊姬。","不有此游乐，三載斷鲜肥。"]', '诗', 'shi', '', NULL, '雜興三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7ad936c-1640-4c51-9e56-035c42caf1e2', '雜興三首 二', '杂兴三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["越國政初荒，越天旱不已。","風日燥水田，水涸塵飛起。","國中新下令，官渠禁流水。","流水不入田，壅入王宮裏。","餘波養魚鳥，倒影浮樓雉。","澹灩九折池，縈迴十餘里。","四月芰荷發，越王日遊嬉。","左右好風來，香動芙蓉蘂。","但愛芙蓉香，又種芙蓉子。","不念閶門外，千里稻苗死。"]', '["越国政初荒，越天旱不已。","风日燥水田，水涸塵飞起。","国中新下令，官渠禁流水。","流水不入田，壅入王宮裏。","餘波養鱼鸟，倒影浮楼雉。","澹灩九折池，縈迴十餘里。","四月芰荷發，越王日游嬉。","左右好风来，香动芙蓉蘂。","但愛芙蓉香，又種芙蓉子。","不念閶门外，千里稻苗死。"]', '诗', 'shi', '', NULL, '雜興三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc5c87a4-7be3-4752-ad17-2c81e3b791e6', '雜興三首 三', '杂兴三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吳王心日侈，服玩盡奇瓌。","身臥翠羽帳，手持紅玉杯。","冠垂明月珠，帶束通天犀。","行動自矜顧，數步一裴回。","小人知所好，懷寶四方來。","奸邪得藉手，從此倖門開。","古稱國之寶，穀米與賢才。","今看君王眼，視之如塵灰。","伍員諫已死，浮屍去不迴。","姑蘇臺下草，麋鹿暗生麑。"]', '["吳王心日侈，服玩尽奇瓌。","身臥翠羽帳，手持紅玉杯。","冠垂明月珠，带束通天犀。","行动自矜顧，數步一裴回。","小人知所好，懷寶四方来。","奸邪得藉手，從此倖门开。","古稱国之寶，穀米與賢才。","今看君王眼，視之如塵灰。","伍員諫已死，浮屍去不迴。","姑蘇台下草，麋鹿暗生麑。"]', '诗', 'shi', '', NULL, '雜興三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3115a223-afb9-44d9-8984-e2ab4dbae3ad', '宿紫閣山北村', '宿紫閣山北村', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晨遊柴閣峰，暮宿山下村。","村老見余喜，爲余開一尊。","舉杯未及飲，暴卒來入門。","柴衣挾刀斧，草草十餘人。","奪我席上酒，掣我盤中飧。","主人退後立，斂手反如賓。","中庭有奇樹，種來三十春。","主人惜不得，持斧斷其根。","口稱采造家，身屬神策軍。","主人慎勿語，中尉正承恩。"]', '["晨游柴閣峰，暮宿山下村。","村老见余喜，爲余开一尊。","舉杯未及饮，暴卒来入门。","柴衣挾刀斧，草草十餘人。","奪我席上酒，掣我盤中飧。","主人退後立，斂手反如賓。","中庭有奇樹，種来三十春。","主人惜不得，持斧斷其根。","口稱采造家，身屬神策軍。","主人慎勿語，中尉正承恩。"]', '诗', 'shi', '', NULL, '宿紫閣山北村 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a146cbfd-885c-4744-9f8f-a0b41e9e4d6b', '讀漢書', '读漢书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["禾黍與稂莠，雨來同日滋。","桃李與荆棘，霜降同夜萎。","草木既區別，榮枯那等夷。","茫茫天地意，無乃太無私。","小人與君子，用置各有宜。","奈何西漢末，忠邪竝信之。","不然盡信忠，早絕邪臣窺。","不然盡信邪，早使忠臣知。","優游兩不斷，盛業日已衰。","痛矣蕭京輩，終令陷禍機。","每讀元成紀，憤憤令人悲。","寄言爲國者，不得學天時。","寄言爲臣者，可以鑒於斯。"]', '["禾黍與稂莠，雨来同日滋。","桃李與荆棘，霜降同夜萎。","草木既區別，榮枯那等夷。","茫茫天地意，無乃太無私。","小人與君子，用置各有宜。","奈何西漢末，忠邪竝信之。","不然尽信忠，早絕邪臣窺。","不然尽信邪，早使忠臣知。","優游兩不斷，盛業日已衰。","痛矣蕭京輩，終令陷禍機。","每读元成紀，憤憤令人悲。","寄言爲国者，不得学天时。","寄言爲臣者，可以鑒於斯。"]', '诗', 'shi', '', NULL, '讀漢書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9e9798-70d0-4432-a198-5936c1262cc5', '贈樊著作', '贈樊著作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陽城爲諫議，以正事其君。","其手如屈軼，舉必指佞臣。","卒使不仁者，不得秉國鈞。","元稹爲御史，以直立其身。","其心如肺石，動必達窮民。","東川八十家，冤憤一言伸。","劉闢肆亂心，殺人正紛紛。","其嫂曰庾氏，棄絕不爲親。","從史萌逆節，隱心潛負恩。","其佐曰孔戡，捨去不爲賓。","凡此士與女，其道天下聞。","常恐國史上，但記鳳與麟。","賢者不爲名，名彰教乃敦。","每惜若人輩，身死名亦淪。","君爲著作郎，職廢志空存。","雖有良史才，直筆無所申。","何不自著書？實錄彼善人。","編爲一家言，以備史闕文。"]', '["陽城爲諫議，以正事其君。","其手如屈軼，舉必指佞臣。","卒使不仁者，不得秉国鈞。","元稹爲御史，以直立其身。","其心如肺石，动必達窮民。","东川八十家，冤憤一言伸。","劉闢肆亂心，殺人正紛紛。","其嫂曰庾氏，棄絕不爲親。","從史萌逆節，隐心潛負恩。","其佐曰孔戡，捨去不爲賓。","凡此士與女，其道天下闻。","常恐国史上，但記鳳與麟。","賢者不爲名，名彰教乃敦。","每惜若人輩，身死名亦淪。","君爲著作郎，職廢志空存。","雖有良史才，直笔無所申。","何不自著书？實錄彼善人。","編爲一家言，以備史闕文。"]', '诗', 'shi', '', NULL, '贈樊著作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('033c5ceb-150d-4729-8782-da90abfb9938', '蜀路石婦', '蜀路石婦', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["道旁一石婦，無記復無銘。","傳是此鄉女，爲婦孝且貞。","十五嫁邑人，十六夫征行。","夫行二十載，婦獨守孤焭。","其夫有父母，老病不安寧。","其婦執婦道，一一如禮經。","晨昏問起居，恭順發心誠。","藥餌自調節，膳羞必甘馨。","夫行竟不歸，婦德轉光明。","後人高其節，刻石像婦形。","儼然整衣巾，若立在閨庭。","似見舅姑禮，如聞環珮聲。","至今爲婦者，見此孝心生。","不比山頭石，空有望夫名。"]', '["道旁一石婦，無記复無銘。","傳是此乡女，爲婦孝且貞。","十五嫁邑人，十六夫征行。","夫行二十載，婦独守孤焭。","其夫有父母，老病不安寧。","其婦執婦道，一一如禮經。","晨昏问起居，恭順發心誠。","藥餌自調節，膳羞必甘馨。","夫行竟不归，婦德轉光明。","後人高其節，刻石像婦形。","儼然整衣巾，若立在閨庭。","似见舅姑禮，如闻环珮声。","至今爲婦者，见此孝心生。","不比山头石，空有望夫名。"]', '诗', 'shi', '', NULL, '蜀路石婦 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39232610-67ba-4ec5-9d49-7bdf3db5b7d2', '折劒頭', '折劒头', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["拾得折劒頭，不知折之由。","一握青蛇尾，數寸碧峰頭。","疑是斬鯨鯢，不然刺蛟虯。","缺落泥土中，委棄無人收。","我有鄙介性，好剛不好柔。","勿輕直折劒，猶勝曲全鉤。"]', '["拾得折劒头，不知折之由。","一握青蛇尾，數寸碧峰头。","疑是斬鯨鯢，不然刺蛟虯。","缺落泥土中，委棄無人收。","我有鄙介性，好剛不好柔。","勿轻直折劒，猶勝曲全鉤。"]', '诗', 'shi', '', NULL, '折劒頭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80c6a20-d207-4c2f-98c2-fc06f64968d8', '登樂遊園望', '登乐游园望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獨上樂遊園，四望天日曛。","東北何靄靄，宮闕入煙雲。","愛此高處立，忽如遺垢氛。","耳目暫清曠，懷抱鬱不伸。","下視十二街，綠樹間紅塵。","車馬徒滿眼，不見心所親。","孔生死洛陽，元九謫荆門。","可憐南北路，高蓋者何人。"]', '["独上乐游园，四望天日曛。","东北何靄靄，宮闕入煙云。","愛此高处立，忽如遺垢氛。","耳目暫清曠，懷抱鬱不伸。","下視十二街，綠樹间紅塵。","车马徒满眼，不见心所親。","孔生死洛陽，元九謫荆门。","可怜南北路，高蓋者何人。"]', '诗', 'shi', '', NULL, '登樂遊園望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28749904-b223-425a-bc49-fa96ae2d984e', '酬元九對新栽竹有懷見寄', '酬元九对新栽竹有懷见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔我十年前，與君始相識。","曾將秋竹竿，比君孤且直。","中心一以合，外事紛無極。","共保秋竹心，風霜侵不得。","始嫌梧桐樹，秋至先改色。","不愛楊柳枝，春來輭無力。","憐君別我後，見竹長相憶。","長欲在眼前，故栽庭戶側。","分首今何處，君南我在北。","吟我贈君詩，對之心惻惻。"]', '["昔我十年前，與君始相識。","曾將秋竹竿，比君孤且直。","中心一以合，外事紛無極。","共保秋竹心，风霜侵不得。","始嫌梧桐樹，秋至先改色。","不愛楊柳枝，春来輭無力。","怜君別我後，见竹长相憶。","长欲在眼前，故栽庭戶側。","分首今何处，君南我在北。","吟我贈君诗，对之心惻惻。"]', '诗', 'shi', '', NULL, '酬元九對新栽竹有懷見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7f1a145-ba1c-4447-8e8b-a478940eb598', '感鶴', '感鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鶴有不羣者，飛飛在野田。","飢不啄腐鼠，渴不飲盜泉。","貞姿自耿介，雜鳥何翩翾。","同遊不同志，如此十餘年。","一興嗜慾念，遂爲矰繳牽。","委質小池內，爭食羣雞前。","不惟懷稻粱，兼亦競腥羶。","不惟戀主人，兼亦狎鳥鳶。","物心不可知，天性有時遷。","一飽尚如此，況乘大夫軒。"]', '["鹤有不羣者，飞飞在野田。","飢不啄腐鼠，渴不饮盜泉。","貞姿自耿介，杂鸟何翩翾。","同游不同志，如此十餘年。","一兴嗜慾念，遂爲矰繳牽。","委質小池內，爭食羣雞前。","不惟懷稻粱，兼亦競腥羶。","不惟戀主人，兼亦狎鸟鳶。","物心不可知，天性有时遷。","一飽尚如此，況乘大夫軒。"]', '诗', 'shi', '', NULL, '感鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0581caee-7b84-4a76-8f99-5aca00d752f5', '春雪', '春雪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["元和歲在卯，六年春二月。","月晦寒食天，天陰夜飛雪。","連宵復竟日，浩浩殊未歇。","大似落鵝毛，密如飄玉屑。","寒銷春茫蒼，氣變風凜冽。","上林草盡沒，曲江水復結。","紅乾杏花死，綠凍楊枝折。","所憐物性傷，非惜年芳絕。","上天有時令，四序平分別。","寒燠苟反常，物生皆夭閼。","我觀聖人意，魯史有其說。","或記水不冰，或書霜不殺。","上將儆政教，下以防災孽。","茲雪今如何，信美非時節。"]', '["元和歲在卯，六年春二月。","月晦寒食天，天陰夜飞雪。","連宵复竟日，浩浩殊未歇。","大似落鵝毛，密如飄玉屑。","寒銷春茫蒼，氣变风凜冽。","上林草尽沒，曲江水复結。","紅乾杏花死，綠凍楊枝折。","所怜物性傷，非惜年芳絕。","上天有时令，四序平分別。","寒燠苟反常，物生皆夭閼。","我观聖人意，魯史有其说。","或記水不冰，或书霜不殺。","上將儆政教，下以防災孽。","茲雪今如何，信美非时節。"]', '诗', 'shi', '', NULL, '春雪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7820d8bc-5b50-4d4e-a9e3-f6ea86a8619e', '高僕射', '高僕射', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["富貴人所愛，聖人去其泰。","所以致仕年，著在禮經內。","玄元亦有訓，知止則不殆。","二疏獨能行，遺跡東門外。","清風久銷歇，迨此向千載。","斯人古亦稀，何況今之代。","遑遑名利客，白首千百輩。","惟有高僕射，七十懸車蓋。","我年雖未老，歲月亦云邁。","預恐耄及時，貪榮不能退。","中心私自儆，何以爲我戒。","故作僕射詩，書之於大帶。"]', '["富貴人所愛，聖人去其泰。","所以致仕年，著在禮經內。","玄元亦有訓，知止則不殆。","二疏独能行，遺跡东门外。","清风久銷歇，迨此向千載。","斯人古亦稀，何況今之代。","遑遑名利客，白首千百輩。","惟有高僕射，七十懸车蓋。","我年雖未老，歲月亦云邁。","預恐耄及时，貪榮不能退。","中心私自儆，何以爲我戒。","故作僕射诗，书之於大带。"]', '诗', 'shi', '', NULL, '高僕射 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c3b0506-115f-4a31-9136-1620270ed02e', '白牡丹', '白牡丹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["城中看花客，旦暮走營營。","素華人不顧，亦占牡丹名。","閉在深寺中，車馬無來聲。","唯有錢學士，盡日繞叢行。","憐此皓然質，無人自芳馨。","衆嫌我獨賞，移植在中庭。","留景夜不暝，迎光曙先明。","對之心亦靜，虛白相向生。","唐昌玉蘂花，攀玩衆所爭。","折來比顏色，一種如瑤瓊。","彼因稀見貴，此以多爲輕。","始知無正色，愛惡隨人情。","豈惟花獨爾，理與人事幷。","君看入時者，紫豔與紅英。"]', '["城中看花客，旦暮走營營。","素华人不顧，亦占牡丹名。","閉在深寺中，车马無来声。","唯有錢学士，尽日繞叢行。","怜此皓然質，無人自芳馨。","衆嫌我独賞，移植在中庭。","留景夜不暝，迎光曙先明。","对之心亦静，虛白相向生。","唐昌玉蘂花，攀玩衆所爭。","折来比顏色，一種如瑤瓊。","彼因稀见貴，此以多爲轻。","始知無正色，愛惡隨人情。","豈惟花独爾，理與人事幷。","君看入时者，紫豔與紅英。"]', '诗', 'shi', '', NULL, '白牡丹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4afb736a-6bee-488d-8748-f3bb270459ac', '贈內', '贈內', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["生爲同室親，死爲同穴塵。","他人尚相勉，而況我與君。","黔婁固窮士，妻賢忘其貧。","冀缺一農夫，妻敬儼如賓。","陶潛不營生，翟氏自爨薪。","梁鴻不肯仕，孟光甘布帬。","君雖不讀書，此事耳亦聞。","至此千載後，傳是何如人。","人生未死間，不能忘其身。","所須者衣食，不過飽與溫。","蔬食足充飢，何必膏粱珍。","繒絮足禦寒，何必錦繡文。","君家有貽訓，清白遺子孫。","我亦貞苦士，與君新結婚。","庶保貧與素，偕老同欣欣。"]', '["生爲同室親，死爲同穴塵。","他人尚相勉，而況我與君。","黔婁固窮士，妻賢忘其貧。","冀缺一農夫，妻敬儼如賓。","陶潛不營生，翟氏自爨薪。","梁鴻不肯仕，孟光甘布帬。","君雖不读书，此事耳亦闻。","至此千載後，傳是何如人。","人生未死间，不能忘其身。","所須者衣食，不過飽與溫。","蔬食足充飢，何必膏粱珍。","繒絮足禦寒，何必錦繡文。","君家有貽訓，清白遺子孫。","我亦貞苦士，與君新結婚。","庶保貧與素，偕老同欣欣。"]', '诗', 'shi', '', NULL, '贈內 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('723657d7-cb24-44f4-aa06-4e0bc3ccdbd7', '寄唐生', '寄唐生', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賈誼哭時事，阮籍哭路岐。","唐生今亦哭，異代同其悲。","唐生者何人，五十寒且飢。","不悲口無食，不悲身無衣。","所悲忠與義，悲甚則哭之。","太尉擊賊日，尚書叱盜時。","大夫死兇寇，諫議謫蠻夷。","每見如此事，聲發涕輒隨。","往往聞其風，俗士猶或非。","憐君頭半白，其志竟不衰。","我亦君之徒，鬱鬱何所爲。","不能發聲哭，轉作樂府詩。","篇篇無空文，句句必盡規。","功高虞人箴，痛甚騷人辭。","非求宮律高，不務文字奇。","惟歌生民病，願得天子知。","未得天子知，甘受時人嗤。","藥良氣味苦，琴澹音聲稀。","不懼權豪怒，亦任親朋議。","人竟無奈何，呼作狂男兒。","每逢羣盜息，或遇雲霧披。","但自高聲歌，庶幾天聽卑。","歌哭雖異名，所感則同歸。","寄君三十章，與君爲哭詞。"]', '["賈誼哭时事，阮籍哭路岐。","唐生今亦哭，異代同其悲。","唐生者何人，五十寒且飢。","不悲口無食，不悲身無衣。","所悲忠與義，悲甚則哭之。","太尉擊賊日，尚书叱盜时。","大夫死兇寇，諫議謫蠻夷。","每见如此事，声發涕輒隨。","往往闻其风，俗士猶或非。","怜君头半白，其志竟不衰。","我亦君之徒，鬱鬱何所爲。","不能發声哭，轉作乐府诗。","篇篇無空文，句句必尽規。","功高虞人箴，痛甚騷人辞。","非求宮律高，不務文字奇。","惟歌生民病，願得天子知。","未得天子知，甘受时人嗤。","藥良氣味苦，琴澹音声稀。","不懼權豪怒，亦任親朋議。","人竟無奈何，呼作狂男兒。","每逢羣盜息，或遇云霧披。","但自高声歌，庶幾天听卑。","歌哭雖異名，所感則同归。","寄君三十章，與君爲哭词。"]', '诗', 'shi', '', NULL, '寄唐生 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a59fc41-c8e9-42ed-8790-62fdd405ece8', '傷唐衢二首 一', '傷唐衢二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自我心存道，外物少能逼。","常排傷心事，不爲長歎息。","忽聞唐衢死，不覺動顏色。","悲端從東來，觸我心惻惻。","伊昔未相知，偶遊滑臺側。","同宿李翺家，一言如舊識。","酒酣出送我，風雪黃河北。","日西竝馬頭，語別至昏黑。","君歸向東鄭，我來遊上國。","交心不交面，從此重相憶。","憐君儒家子，不得詩書力。","五十著青衫，試官無祿食。","遺文僅千首，六義無差忒。","散在京洛間，何人爲收拾。"]', '["自我心存道，外物少能逼。","常排傷心事，不爲长歎息。","忽闻唐衢死，不覺动顏色。","悲端從东来，觸我心惻惻。","伊昔未相知，偶游滑台側。","同宿李翺家，一言如旧識。","酒酣出送我，风雪黄河北。","日西竝马头，語別至昏黑。","君归向东鄭，我来游上国。","交心不交面，從此重相憶。","怜君儒家子，不得诗书力。","五十著青衫，試官無祿食。","遺文僅千首，六義無差忒。","散在京洛间，何人爲收拾。"]', '诗', 'shi', '', NULL, '傷唐衢二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdf28257-4200-41af-9cfa-7cc858b62fef', '傷唐衢二首 二', '傷唐衢二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶昨元和初，忝備諫官位。","是時兵革後，生民正顦顇。","但傷民病痛，不識時忌諱。","遂作秦中吟，一吟悲一事。","貴人皆怪怒，閑人亦非訾。","天高未及聞，荆棘生滿地。","惟有唐衢見，知我平生志。","一讀興歎嗟，再吟垂涕泗。","因和三十韻，手題遠緘寄。","致吾陳杜間，賞愛非常意。","此人無復見，此詩猶可貴。","今日開篋看，蠹魚損文字。","不知何處葬，欲問先歔欷。","終去哭墳前，還君一掬淚。"]', '["憶昨元和初，忝備諫官位。","是时兵革後，生民正顦顇。","但傷民病痛，不識时忌諱。","遂作秦中吟，一吟悲一事。","貴人皆怪怒，闲人亦非訾。","天高未及闻，荆棘生满地。","惟有唐衢见，知我平生志。","一读兴歎嗟，再吟垂涕泗。","因和三十韻，手題远緘寄。","致吾陳杜间，賞愛非常意。","此人無复见，此诗猶可貴。","今日开篋看，蠹鱼損文字。","不知何处葬，欲问先歔欷。","終去哭墳前，還君一掬泪。"]', '诗', 'shi', '', NULL, '傷唐衢二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ec36535-f0a9-4635-9a2a-ab25a4e5965e', '問友', '问友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["種蘭不種艾，蘭生艾亦生。","根荄相交長，莖葉相附榮。","香莖與臭葉，日夜俱長大。","鋤艾恐傷蘭，溉蘭恐滋艾。","蘭亦未能溉，艾亦未能除。","沈吟意不決，問君合何如。"]', '["種蘭不種艾，蘭生艾亦生。","根荄相交长，莖葉相附榮。","香莖與臭葉，日夜俱长大。","鋤艾恐傷蘭，溉蘭恐滋艾。","蘭亦未能溉，艾亦未能除。","沈吟意不決，问君合何如。"]', '诗', 'shi', '', NULL, '問友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de070606-3e25-4100-9b11-4038f0c5a870', '悲哉行', '悲哉行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悲哉爲儒者，力學不知疲。","讀書眼欲暗，秉筆手生胝。","十上方一第，成名常苦遲。","縱有宦達者，兩鬢已成絲。","可憐少壯日，適在窮賤時。","丈夫老且病，焉用富貴爲。","沈沈朱門宅，中有乳臭兒。","狀貌如婦人，光明膏粱肌。","手不把書卷，身不擐戎衣。","二十襲封爵，門承勳戚資。","春來日日出，服御何輕肥。","朝從博徒飲，暮有倡樓期。","平封還酒債，堆金選蛾眉。","聲色狗馬外，其餘一無知。","山苗與澗松，地勢隨高卑。","古來無奈何，非君獨傷悲。"]', '["悲哉爲儒者，力学不知疲。","读书眼欲暗，秉笔手生胝。","十上方一第，成名常苦遲。","縱有宦達者，兩鬢已成絲。","可怜少壯日，適在窮賤时。","丈夫老且病，焉用富貴爲。","沈沈朱门宅，中有乳臭兒。","狀貌如婦人，光明膏粱肌。","手不把书卷，身不擐戎衣。","二十襲封爵，门承勳戚資。","春来日日出，服御何轻肥。","朝從博徒饮，暮有倡楼期。","平封還酒債，堆金選蛾眉。","声色狗马外，其餘一無知。","山苗與澗松，地勢隨高卑。","古来無奈何，非君独傷悲。"]', '诗', 'shi', '', NULL, '悲哉行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5091996e-23c3-43ad-8b9e-54ba20c8e529', '紫藤', '紫藤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["藤花紫蒙茸，藤葉青扶疎。","誰謂好顏色，而爲害有餘。","下如蛇屈盤，上若繩縈紆。","可憐中間樹，束縛成枯株。","柔蔓不自勝，嫋嫋挂空虛。","豈知纏樹木，千夫力不如。","先柔後爲害，有似諛佞徒。","附著君權勢，君迷不肯誅。","又如妖婦人，綢繆蠱其夫。","奇邪壞人室，夫惑不能除。","寄言邦與家，所慎在其初。","毫末不早辨，滋蔓信難圖。","願以藤爲戒，銘之于座隅。"]', '["藤花紫蒙茸，藤葉青扶疎。","誰謂好顏色，而爲害有餘。","下如蛇屈盤，上若繩縈紆。","可怜中间樹，束縛成枯株。","柔蔓不自勝，嫋嫋挂空虛。","豈知纏樹木，千夫力不如。","先柔後爲害，有似諛佞徒。","附著君權勢，君迷不肯誅。","又如妖婦人，綢繆蠱其夫。","奇邪壞人室，夫惑不能除。","寄言邦與家，所慎在其初。","毫末不早辨，滋蔓信难圖。","願以藤爲戒，銘之于座隅。"]', '诗', 'shi', '', NULL, '紫藤 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a06e4034-9520-4474-8068-3624207e846a', '放鷹', '放鷹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十月鷹出籠，草枯雉兔肥。","下韝隨指顧，百擲無一遺。","鷹翅疾如風，鷹爪利如錐。","本爲鳥所設，今爲人所資。","孰能使之然，有術甚易知。","取其向背性，制在飢飽時。","不可使長飽，不可使長飢。","飢則力不足，飽則背人飛。","乘飢縱搏擊，未飽須縶維。","所以爪翅功，而人坐收之。","聖明馭英雄，其術亦如斯。","鄙語不可棄，吾聞諸獵師。"]', '["十月鷹出籠，草枯雉兔肥。","下韝隨指顧，百擲無一遺。","鷹翅疾如风，鷹爪利如錐。","本爲鸟所設，今爲人所資。","孰能使之然，有術甚易知。","取其向背性，制在飢飽时。","不可使长飽，不可使长飢。","飢則力不足，飽則背人飞。","乘飢縱搏擊，未飽須縶維。","所以爪翅功，而人坐收之。","聖明馭英雄，其術亦如斯。","鄙語不可棄，吾闻諸獵師。"]', '诗', 'shi', '', NULL, '放鷹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('984cabd9-8d66-45aa-8d01-d602de5aea5e', '慈烏夜啼', '慈烏夜啼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慈烏失其母，啞啞吐哀音。","晝夜不飛去，經年守故林。","夜夜夜半啼，聞者爲霑襟。","聲中如告訴，未盡反哺心。","百鳥豈無母，爾獨哀怨深。","應是母慈重，使爾悲不任。","昔有吳起者，母歿喪不臨。","嗟哉斯徒輩，其心不如禽。","慈烏復慈烏，鳥中之曾參。"]', '["慈烏失其母，啞啞吐哀音。","晝夜不飞去，經年守故林。","夜夜夜半啼，闻者爲霑襟。","声中如告訴，未尽反哺心。","百鸟豈無母，爾独哀怨深。","應是母慈重，使爾悲不任。","昔有吳起者，母歿喪不臨。","嗟哉斯徒輩，其心不如禽。","慈烏复慈烏，鸟中之曾參。"]', '诗', 'shi', '', NULL, '慈烏夜啼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76db2d4d-67b9-4819-a586-dee0e28b7046', '燕詩示劉叟', '燕诗示劉叟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["梁上有雙燕，翩翩雄與雌。","銜泥兩椽間，一巢生四兒。","四兒日夜長，索食聲孜孜。","青蟲不易捕，黃口無飽期。","觜爪雖欲敝，心力不知疲。","須臾十來往，猶恐巢中飢。","辛勤三十日，母瘦雛漸肥。","喃喃教言語，一一刷毛衣。","一旦羽翼成，引上庭樹枝。","舉翅不回顧，隨風四散飛。","雌雄空中鳴，聲盡呼不歸。","却入空巢裏，啁啾終夜悲。","燕燕爾勿悲，爾當返自思。","思爾爲雛日，高飛背母時。","當時父母念，今日爾應知。"]', '["梁上有雙燕，翩翩雄與雌。","銜泥兩椽间，一巢生四兒。","四兒日夜长，索食声孜孜。","青蟲不易捕，黄口無飽期。","觜爪雖欲敝，心力不知疲。","須臾十来往，猶恐巢中飢。","辛勤三十日，母瘦雛漸肥。","喃喃教言語，一一刷毛衣。","一旦羽翼成，引上庭樹枝。","舉翅不回顧，隨风四散飞。","雌雄空中鳴，声尽呼不归。","却入空巢裏，啁啾終夜悲。","燕燕爾勿悲，爾當返自思。","思爾爲雛日，高飞背母时。","當时父母念，今日爾應知。"]', '诗', 'shi', '', NULL, '燕詩示劉叟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a3a88f3-0230-4ebf-8966-f0f8086f725c', '采地黃者', '采地黄者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["麥死春不雨，禾損秋早霜。","歲晏無口食，田中采地黃。","采時將何用，持以易餱糧。","凌晨荷鋤去，薄暮不盈筐。","攜來朱門家，賣與白面郎。","與君噉肥馬，可使照地光。","願易馬殘粟，救此苦飢腸。"]', '["麦死春不雨，禾損秋早霜。","歲晏無口食，田中采地黄。","采时將何用，持以易餱糧。","凌晨荷鋤去，薄暮不盈筐。","携来朱门家，賣與白面郎。","與君噉肥马，可使照地光。","願易马殘粟，救此苦飢腸。"]', '诗', 'shi', '', NULL, '采地黃者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaf65a51-cd9e-45cd-a646-fc5bebbae6df', '初入太行路', '初入太行路', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天冷日不光，太行峰蒼莽。","嘗聞此中險，今我方獨往。","馬蹄凍且滑，羊腸不可上。","若比世路難，猶自平於掌。"]', '["天冷日不光，太行峰蒼莽。","嘗闻此中險，今我方独往。","马蹄凍且滑，羊腸不可上。","若比世路难，猶自平於掌。"]', '诗', 'shi', '', NULL, '初入太行路 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2336d910-2309-4e9f-bf77-0756cd8d57e2', '鄧魴張徹落第', '鄧魴張徹落第', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["古琴無俗韻，奏罷無人聽。","寒松無妖花，枝下無人行。","春風十二街，軒騎不暫停。","奔車看牡丹，走馬聽秦箏。","衆目悅芳豔，松獨守其貞。","衆耳喜鄭衛，琴亦不改聲。","懷哉二夫子，念此無自輕。"]', '["古琴無俗韻，奏罷無人听。","寒松無妖花，枝下無人行。","春风十二街，軒騎不暫停。","奔车看牡丹，走马听秦箏。","衆目悅芳豔，松独守其貞。","衆耳喜鄭衛，琴亦不改声。","懷哉二夫子，念此無自轻。"]', '诗', 'shi', '', NULL, '鄧魴張徹落第 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bc21d9c-17f8-48f2-9a6a-a22caa97ccc8', '送王處士', '送王处士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["王門豈無酒，侯門豈無肉。","主人貴且驕，待客禮不足。","望塵而拜者，朝夕走碌碌。","王生獨拂衣，遐舉如雲鵠。","寧歸白雲外，飲水臥空谷。","不能隨衆人，斂手低眉目。","扣門與我別，酤酒留君宿。","好去采薇人，終南山正綠。"]', '["王门豈無酒，侯门豈無肉。","主人貴且驕，待客禮不足。","望塵而拜者，朝夕走碌碌。","王生独拂衣，遐舉如云鵠。","寧归白云外，饮水臥空谷。","不能隨衆人，斂手低眉目。","扣门與我別，酤酒留君宿。","好去采薇人，終南山正綠。"]', '诗', 'shi', '', NULL, '送王處士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3416a316-b7b3-4ad4-9260-63d0ec9e7af2', '村居苦寒', '村居苦寒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["八年十二月，五日雪紛紛。","竹柏皆凍死，況彼無衣民。","回觀村閭間，十室八九貧。","北風利如劒，布絮不蔽身。","唯燒蒿棘火，愁坐夜待晨。","乃知大寒歲，農者尤苦辛。","顧我當此日，草堂深掩門。","褐裘覆絁被，坐臥有餘溫。","幸免飢凍苦，又無壠畝勤。","念彼深可媿，自問是何人。"]', '["八年十二月，五日雪紛紛。","竹柏皆凍死，況彼無衣民。","回观村閭间，十室八九貧。","北风利如劒，布絮不蔽身。","唯燒蒿棘火，愁坐夜待晨。","乃知大寒歲，農者尤苦辛。","顧我當此日，草堂深掩门。","褐裘覆絁被，坐臥有餘溫。","幸免飢凍苦，又無壠畝勤。","念彼深可媿，自问是何人。"]', '诗', 'shi', '', NULL, '村居苦寒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a06424-0792-49e3-88e0-c388c86f13c7', '納粟', '納粟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有吏夜叩門，高聲催納粟。","家人不待曉，場上張燈燭。","揚簸淨如珠，一車三十斛。","猶憂納不中，鞭責及僮僕。","昔余謬從事，內媿才不足。","連授四命官，坐尸十年祿。","常聞古人語，損益周必復。","今日諒甘心，還他太倉穀。"]', '["有吏夜叩门，高声催納粟。","家人不待晓，場上張灯燭。","揚簸淨如珠，一车三十斛。","猶憂納不中，鞭責及僮僕。","昔余謬從事，內媿才不足。","連授四命官，坐尸十年祿。","常闻古人語，損益周必复。","今日諒甘心，還他太倉穀。"]', '诗', 'shi', '', NULL, '納粟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('034a478a-eefe-4d0c-b15d-5b44cfa71bcf', '薛中丞', '薛中丞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百人無一直，百直無一遇。","借問遇者誰，正人行得路。","中丞薜存誠，守直心甚固。","皇明燭如日，再使秉王度。","奸豪與佞巧，非不憎且懼。","直道漸光明，邪謀難蓋覆。","每因匪躬節，知有匡時具。","張爲墜網綱，倚作頹檐柱。","悠哉上天意，報施紛回互。","自古已冥茫，從今尤不諭。","豈與小人意，昏然同好惡。","不然君子人，何反如朝露。","裴相昨已夭，薛君今又去。","以我惜賢心，五年如旦暮。","況聞善人命，長短繫運數。","今我一涕零，豈爲中丞故。"]', '["百人無一直，百直無一遇。","借问遇者誰，正人行得路。","中丞薜存誠，守直心甚固。","皇明燭如日，再使秉王度。","奸豪與佞巧，非不憎且懼。","直道漸光明，邪謀难蓋覆。","每因匪躬節，知有匡时具。","張爲墜網綱，倚作頹檐柱。","悠哉上天意，報施紛回互。","自古已冥茫，從今尤不諭。","豈與小人意，昏然同好惡。","不然君子人，何反如朝露。","裴相昨已夭，薛君今又去。","以我惜賢心，五年如旦暮。","況闻善人命，长短繫運數。","今我一涕零，豈爲中丞故。"]', '诗', 'shi', '', NULL, '薛中丞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ead7bf0f-a37e-45b1-ac88-8685b31734dd', '秋池二首 一', '秋池二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["前池秋始半，卉物多摧壞。","欲暮槿先萎，未霜荷已敗。","默然有所感，可以從茲誡。","本不種松筠，早彫何足怪。"]', '["前池秋始半，卉物多摧壞。","欲暮槿先萎，未霜荷已敗。","默然有所感，可以從茲誡。","本不種松筠，早彫何足怪。"]', '诗', 'shi', '', NULL, '秋池二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f9d160d-f49d-4237-ab23-0527fd57ec4f', '秋池二首 二', '秋池二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鑿池貯秋水，中有蘋與芰。","天旱水暗消，塌然委空地。","有似泛泛者，附離權與貴。","一旦恩勢移，相隨共顦顇。"]', '["鑿池貯秋水，中有蘋與芰。","天旱水暗消，塌然委空地。","有似泛泛者，附離權與貴。","一旦恩勢移，相隨共顦顇。"]', '诗', 'shi', '', NULL, '秋池二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c88a2e2d-77ed-4699-8fa2-7ced4ac3918e', '夏旱', '夏旱', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["太陰不離畢，太歲仍在午。","旱日與炎風，枯燋我田畝。","金石欲銷鑠，況茲禾與黍。","嗸嗸萬族中，唯農最辛苦。","憫然望歲者，出門何所覩。","但見棘與茨，羅生徧場圃。","惡苗承沴氣，欣然得其所。","感此因問天，可能長不雨。"]', '["太陰不離畢，太歲仍在午。","旱日與炎风，枯燋我田畝。","金石欲銷鑠，況茲禾與黍。","嗸嗸万族中，唯農最辛苦。","憫然望歲者，出门何所覩。","但见棘與茨，羅生徧場圃。","惡苗承沴氣，欣然得其所。","感此因问天，可能长不雨。"]', '诗', 'shi', '', NULL, '夏旱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfca1d70-ebf1-4c0a-be2c-9ecd5ba26192', '諭友', '諭友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨夜霜一降，殺君庭中槐。","乾葉不待黃，索索飛下來。","憐君感節物，晨起步前階。","臨風蹋葉立，半日顏色哀。","西望長安城，歌鐘十二街。","何人不歡樂，君獨心悠哉。","白日頭上走，朱顏鏡中頹。","平生青雲心，銷化成死灰。","我今贈一言，勝飲酒千杯。","其言雖甚鄙，可破悒悒懷。","朱門有勳貴，陋巷有顏回。","窮通各問命，不繫才不才。","推此自豁豁，不必待安排。"]', '["昨夜霜一降，殺君庭中槐。","乾葉不待黄，索索飞下来。","怜君感節物，晨起步前階。","臨风蹋葉立，半日顏色哀。","西望长安城，歌鐘十二街。","何人不歡乐，君独心悠哉。","白日头上走，朱顏镜中頹。","平生青云心，銷化成死灰。","我今贈一言，勝饮酒千杯。","其言雖甚鄙，可破悒悒懷。","朱门有勳貴，陋巷有顏回。","窮通各问命，不繫才不才。","推此自豁豁，不必待安排。"]', '诗', 'shi', '', NULL, '諭友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f871d40-8c88-44fe-8203-2fdaa77c38b0', '丘中有一士二首 一', '丘中有一士二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["丘中有一士，不知其姓名。","面色不憂苦，血氣常和平。","每選隙地居，不蹋要路行。","舉動無尤悔，物莫與之爭。","藜藿不充腸，布褐不蔽形。","終歲守窮餓，而無嗟歎聲。","豈是愛貧賤，深知時俗情。","勿矜羅弋巧，鸞鶴在冥冥。"]', '["丘中有一士，不知其姓名。","面色不憂苦，血氣常和平。","每選隙地居，不蹋要路行。","舉动無尤悔，物莫與之爭。","藜藿不充腸，布褐不蔽形。","終歲守窮餓，而無嗟歎声。","豈是愛貧賤，深知时俗情。","勿矜羅弋巧，鸾鹤在冥冥。"]', '诗', 'shi', '', NULL, '丘中有一士二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('697f64d7-e6f6-4762-9c52-76b0fc10aa3f', '丘中有一士二首 二', '丘中有一士二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["丘中有一士，守道歲月深。","行披帶索衣，坐拍無弦琴。","不飲濁泉水，不息曲木陰。","所逢苟非義，糞土千黃金。","鄉人化其風，熏如蘭在林。","智愚與強弱，不忍相欺侵。","我欲訪其人，將行復沈吟。","何必見其面，但在學其心。"]', '["丘中有一士，守道歲月深。","行披带索衣，坐拍無弦琴。","不饮濁泉水，不息曲木陰。","所逢苟非義，糞土千黄金。","乡人化其风，熏如蘭在林。","智愚與強弱，不忍相欺侵。","我欲訪其人，將行复沈吟。","何必见其面，但在学其心。"]', '诗', 'shi', '', NULL, '丘中有一士二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6ea2741-b818-4e31-8de2-3c4b5057ff91', '新製布裘', '新製布裘', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["桂布白似雪，吳緜輭於雲。","布重緜且厚，爲裘有餘溫。","朝擁坐至暮，夜覆眠達晨。","誰知嚴冬月，支體暖如春。","中夕忽有念，撫裘起逡巡。","丈夫貴兼濟，豈獨善一身。","安得萬里裘，蓋裹周四垠。","穩暖皆如我，天下無寒人。"]', '["桂布白似雪，吳緜輭於云。","布重緜且厚，爲裘有餘溫。","朝擁坐至暮，夜覆眠達晨。","誰知嚴冬月，支體暖如春。","中夕忽有念，撫裘起逡巡。","丈夫貴兼濟，豈独善一身。","安得万里裘，蓋裹周四垠。","穩暖皆如我，天下無寒人。"]', '诗', 'shi', '', NULL, '新製布裘 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6509e378-c9e7-4afa-ba95-5bc4be21114c', '杏園中棗樹', '杏园中棗樹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人言百果中，唯棗凡且鄙。","皮皴似龜手，葉小如鼠耳。","胡爲不自知，生花此園裏。","豈宜遇攀玩，幸免遭傷毀。","二月曲江頭，雜英紅旖旎。","棗亦在其間，如嫫對西子。","東風不擇木，吹喣長未已。","眼看欲合抱，得盡生生理。","寄言遊春客，乞君一迴視。","君愛繞指柔，從君憐柳杞。","君求悅目豔，不敢爭桃李。","君若作大車，輪軸材須此。"]', '["人言百果中，唯棗凡且鄙。","皮皴似龟手，葉小如鼠耳。","胡爲不自知，生花此园裏。","豈宜遇攀玩，幸免遭傷毀。","二月曲江头，杂英紅旖旎。","棗亦在其间，如嫫对西子。","东风不擇木，吹喣长未已。","眼看欲合抱，得尽生生理。","寄言游春客，乞君一迴視。","君愛繞指柔，從君怜柳杞。","君求悅目豔，不敢爭桃李。","君若作大车，輪軸材須此。"]', '诗', 'shi', '', NULL, '杏園中棗樹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa3153c-cbac-4b0c-82e9-679a9dc8907c', '蝦蟇', '蝦蟇', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嘉魚薦宗朝，靈龜貢邦家。","應龍能致雨，潤我百穀芽。","蠢蠢水族中，無用者蝦蟇。","形穢肌肉腥，出沒於泥沙。","六月七月交，時雨正滂沱。","蝦蟇得其志，快樂無以加。","地既蕃其生，使之族類多。","天又與其聲，得以相諠譁。","豈惟玉池上，汚君清冷波。","可獨瑤瑟前，亂君鹿鳴歌。","常恐飛上天，跳躍隨姮娥。","往往蝕明月，遣君無奈何。"]', '["嘉鱼薦宗朝，靈龟貢邦家。","應龙能致雨，潤我百穀芽。","蠢蠢水族中，無用者蝦蟇。","形穢肌肉腥，出沒於泥沙。","六月七月交，时雨正滂沱。","蝦蟇得其志，快乐無以加。","地既蕃其生，使之族類多。","天又與其声，得以相諠譁。","豈惟玉池上，汚君清冷波。","可独瑤瑟前，亂君鹿鳴歌。","常恐飞上天，跳躍隨姮娥。","往往蝕明月，遣君無奈何。"]', '诗', 'shi', '', NULL, '蝦蟇 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcdaaf94-7746-4dd6-9d48-359d09af6013', '寄隱者', '寄隐者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賣藥向都城，行憩青門樹。","道逢馳驛者，色有非常懼。","親族走相送，欲別不敢住。","私怪問道旁，何人復何故。","云是右丞相，當國握樞務。","祿厚食萬錢，恩深日三顧。","昨日延英對，今日崖州去。","由來君臣間，寵辱在朝暮。","青青東郊草，中有歸山路。","歸去臥雲人，謀身計非誤。"]', '["賣藥向都城，行憩青门樹。","道逢驰驛者，色有非常懼。","親族走相送，欲別不敢住。","私怪问道旁，何人复何故。","云是右丞相，當国握樞務。","祿厚食万錢，恩深日三顧。","昨日延英对，今日崖州去。","由来君臣间，寵辱在朝暮。","青青东郊草，中有归山路。","归去臥云人，謀身計非誤。"]', '诗', 'shi', '', NULL, '寄隱者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a551b820-311d-4ef5-8def-9b1f4a6c1bdd', '放魚', '放鱼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曉日提竹籃，家僮買春蔬。","青青芹蕨下，疊臥雙白魚。","無聲但呀呀，以氣相喣濡。","傾籃寫地上，撥刺長尺餘。","豈唯刀机憂，坐見螻蟻圖。","脫泉雖已久，得水猶可蘇。","放之小池中，且用救乾枯。","水小池窄狹，動尾觸四隅。","一時幸苟活，久遠將何如。","憐其不得所，移放於南湖。","南湖連西江，好去勿踟躕。","施恩即望報，吾非斯人徒。","不須泥沙底，辛苦覓明珠。"]', '["晓日提竹籃，家僮買春蔬。","青青芹蕨下，叠臥雙白鱼。","無声但呀呀，以氣相喣濡。","傾籃寫地上，撥刺长尺餘。","豈唯刀机憂，坐见螻蟻圖。","脫泉雖已久，得水猶可蘇。","放之小池中，且用救乾枯。","水小池窄狹，动尾觸四隅。","一时幸苟活，久远將何如。","怜其不得所，移放於南湖。","南湖連西江，好去勿踟躕。","施恩即望報，吾非斯人徒。","不須泥沙底，辛苦覓明珠。"]', '诗', 'shi', '', NULL, '放魚 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('105eb4ed-6526-4794-a6e4-1d58247288cf', '文柏牀', '文柏牀', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陵上有老柏，柯葉寒蒼蒼。","朝爲風煙樹，暮爲宴寢牀。","以其多奇文，宜升君子堂。","刮削露節目，拂拭生輝光。","玄斑狀貍首，素質如截肪。","雖充悅目玩，終乏周身防。","華彩誠可愛，生理苦已傷。","方知自殘者，爲有好文章。"]', '["陵上有老柏，柯葉寒蒼蒼。","朝爲风煙樹，暮爲宴寢牀。","以其多奇文，宜升君子堂。","刮削露節目，拂拭生輝光。","玄斑狀貍首，素質如截肪。","雖充悅目玩，終乏周身防。","华彩誠可愛，生理苦已傷。","方知自殘者，爲有好文章。"]', '诗', 'shi', '', NULL, '文柏牀 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50768326-3c0c-47dd-a680-3c99496db4ad', '潯陽三題 廬山桂', '潯陽三題 廬山桂', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["偃蹇月中桂，結根依青天。","天風繞月起，吹子下人間。","飄零委何處，乃落匡廬山。","生爲石上桂，葉如翦碧鮮。","枝幹日長大，根荄日牢堅。","不歸天上月，空老山中年。","廬山去咸陽，道里三四千。","無人爲移植，得入上林園。","不及紅花樹，長栽溫室前。"]', '["偃蹇月中桂，結根依青天。","天风繞月起，吹子下人间。","飄零委何处，乃落匡廬山。","生爲石上桂，葉如翦碧鲜。","枝幹日长大，根荄日牢堅。","不归天上月，空老山中年。","廬山去咸陽，道里三四千。","無人爲移植，得入上林园。","不及紅花樹，长栽溫室前。"]', '诗', 'shi', '', NULL, '潯陽三題 廬山桂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a02fed1-83bf-4927-bcac-bbe87e95cc87', '潯陽三題 湓浦竹', '潯陽三題 湓浦竹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潯陽十月天，天氣仍溫燠。","有霜不殺草，有風不落木。","玄冥氣力薄，草木冬猶綠。","誰肯湓浦頭，回眼看修竹。","其有顧盼者，持刀斬且束。","剖劈青琅玕，家家蓋牆屋。","吾聞汾晉間，竹少重如玉。","胡爲取輕賤，生此西江曲。"]', '["潯陽十月天，天氣仍溫燠。","有霜不殺草，有风不落木。","玄冥氣力薄，草木冬猶綠。","誰肯湓浦头，回眼看修竹。","其有顧盼者，持刀斬且束。","剖劈青琅玕，家家蓋牆屋。","吾闻汾晉间，竹少重如玉。","胡爲取轻賤，生此西江曲。"]', '诗', 'shi', '', NULL, '潯陽三題 湓浦竹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('823ebceb-6848-442c-918e-5cbfe2a70f93', '潯陽三題 東林寺白蓮', '潯陽三題 东林寺白蓮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東林北塘水，湛湛見底清。","中生白芙蓉，菡萏三百莖。","白日發光彩，清飆散芳馨。","洩香銀囊破，瀉露玉盤傾。","我慙塵垢眼，見此瓊瑤英。","乃知紅蓮花，虛得清淨名。","夏萼敷未歇，秋房結纔成。","夜深衆僧寢，獨起繞池行。","欲收一顆子，寄向長安城。","但恐出山去，人間種不生。"]', '["东林北塘水，湛湛见底清。","中生白芙蓉，菡萏三百莖。","白日發光彩，清飆散芳馨。","洩香銀囊破，瀉露玉盤傾。","我慙塵垢眼，见此瓊瑤英。","乃知紅蓮花，虛得清淨名。","夏萼敷未歇，秋房結纔成。","夜深衆僧寢，独起繞池行。","欲收一顆子，寄向长安城。","但恐出山去，人间種不生。"]', '诗', 'shi', '', NULL, '潯陽三題 東林寺白蓮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ab973dc-252d-4372-a57b-b37b39bd9698', '大水', '大水', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潯陽郊郭間，大水歲一至。","閭閻半飄蕩，城堞多傾墜。","蒼茫生海色，渺漫連空翠。","風卷白波飜，日煎紅浪沸。","工商徹屋去，牛馬登山避。","況當率稅時，頗害農桑事。","獨有傭舟子，鼓枻生意氣。","不知萬人災，自覓錐刀利。","吾無奈爾何，爾非久得志。","九月霜降後，水涸爲平地。"]', '["潯陽郊郭间，大水歲一至。","閭閻半飄蕩，城堞多傾墜。","蒼茫生海色，渺漫連空翠。","风卷白波飜，日煎紅浪沸。","工商徹屋去，牛马登山避。","況當率稅时，頗害農桑事。","独有傭舟子，鼓枻生意氣。","不知万人災，自覓錐刀利。","吾無奈爾何，爾非久得志。","九月霜降後，水涸爲平地。"]', '诗', 'shi', '', NULL, '大水 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f92bfbe6-80e7-4db6-9b66-94d8c2d57e23', '續古詩十首 一', '續古诗十首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["戚戚復戚戚，送君遠行役。","行役非中原，海外黃沙磧。","伶俜獨居妾，迢遰長征客。","君望功名歸，妾憂生死隔。","誰家無夫婦，何人不離坼。","所恨薄命身，嫁遲別日迫。","妾身有存歿，妾心無改易。","生作閨中婦，死作山頭石。"]', '["戚戚复戚戚，送君远行役。","行役非中原，海外黄沙磧。","伶俜独居妾，迢遰长征客。","君望功名归，妾憂生死隔。","誰家無夫婦，何人不離坼。","所恨薄命身，嫁遲別日迫。","妾身有存歿，妾心無改易。","生作閨中婦，死作山头石。"]', '诗', 'shi', '', NULL, '續古詩十首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a36f4666-50ef-4b26-a8ab-afd115dd7897', '續古詩十首 二', '續古诗十首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["掩淚別鄉里，飄颻將遠行。","茫茫綠野中，春盡孤客情。","驅馬上丘隴，高低路不平。","風吹棠棃花，啼鳥時一聲。","古墓何代人，不知姓與名。","化作路傍土，年年春草生。","感彼忽自悟，今我何營營。"]', '["掩泪別乡里，飄颻將远行。","茫茫綠野中，春尽孤客情。","驱马上丘隴，高低路不平。","风吹棠棃花，啼鸟时一声。","古墓何代人，不知姓與名。","化作路傍土，年年春草生。","感彼忽自悟，今我何營營。"]', '诗', 'shi', '', NULL, '續古詩十首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c0621f3-319f-49b3-87b0-508dd2ddbaac', '續古詩十首 三', '續古诗十首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝采山上薇，暮采山上薇。","歲晏薇亦盡，飢來何所爲。","坐飲白石水，手把青松枝。","擊節獨長謌，其聲清且悲。","櫪馬非不肥，所苦常縶維。","豢豕非不飽，所憂竟爲犧。","行行歌此曲，以慰常苦飢。"]', '["朝采山上薇，暮采山上薇。","歲晏薇亦尽，飢来何所爲。","坐饮白石水，手把青松枝。","擊節独长謌，其声清且悲。","櫪马非不肥，所苦常縶維。","豢豕非不飽，所憂竟爲犧。","行行歌此曲，以慰常苦飢。"]', '诗', 'shi', '', NULL, '續古詩十首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('befb8898-91d2-4889-a5e7-11d8b5b19dba', '續古詩十首 四', '續古诗十首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雨露長纖草，山苗高入雲。","風雪折勁木，澗松摧爲薪。","風摧此何意，雨長彼何因。","百丈澗底死，寸莖山上春。","可憐苦節士，感此涕盈巾。"]', '["雨露长纖草，山苗高入云。","风雪折勁木，澗松摧爲薪。","风摧此何意，雨长彼何因。","百丈澗底死，寸莖山上春。","可怜苦節士，感此涕盈巾。"]', '诗', 'shi', '', NULL, '續古詩十首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e1e3774-5373-4448-84b6-4c59bd55bee3', '續古詩十首 五', '續古诗十首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["窈窕雙鬟女，容德俱如玉。","晝居不踰閾，夜行常秉燭。","氣如含露蘭，心如貫霜竹。","宜當備嬪御，胡爲守幽獨。","無媒不得選，年忽過三六。","歲暮望漢宮，誰在黃金屋。","邯鄲進倡女，能唱黃花曲。","一曲稱君心，恩榮連九族。"]', '["窈窕雙鬟女，容德俱如玉。","晝居不踰閾，夜行常秉燭。","氣如含露蘭，心如貫霜竹。","宜當備嬪御，胡爲守幽独。","無媒不得選，年忽過三六。","歲暮望漢宮，誰在黄金屋。","邯鄲進倡女，能唱黄花曲。","一曲稱君心，恩榮連九族。"]', '诗', 'shi', '', NULL, '續古詩十首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0ab4f70-9cbc-4d3f-93c5-f9a5cd723297', '續古詩十首 六', '續古诗十首 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["栖栖遠方士，讀書三十年。","業成無知己，徒步來入關。","長安多王候，英俊競攀援。","幸隨衆賓末，得厠門館間。","東閤有旨酒，中堂有管弦。","何爲向隅客，對此不開顏。","富貴無是非，主人終日歡。","貧賤多悔尤，客子中夜歎。","歸去復歸去，故鄉貧亦安。"]', '["栖栖远方士，读书三十年。","業成無知己，徒步来入关。","长安多王候，英俊競攀援。","幸隨衆賓末，得厠门館间。","东閤有旨酒，中堂有管弦。","何爲向隅客，对此不开顏。","富貴無是非，主人終日歡。","貧賤多悔尤，客子中夜歎。","归去复归去，故乡貧亦安。"]', '诗', 'shi', '', NULL, '續古詩十首 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b37176b6-1ae4-441f-9295-32a8094995e8', '續古詩十首 七', '續古诗十首 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["涼風飄嘉樹，日夜減芳華。","下有感秋婦，攀條苦悲嗟。","我本幽閑女，結髮事豪家。","豪家多婢僕，門內頗驕奢。","良人近封候，出入鳴玉珂。","自從富貴來，恩薄讒言多。","冢婦獨守禮，羣妾互奇衺。","但信言有玷，不察心無瑕。","容光未銷歇，歡愛忽蹉跎。","何意掌上玉，化爲眼中砂。","盈盈一尺水，浩浩千丈河。","勿言小大異，隨分有風波。","閨房猶復爾，邦國當如何。"]', '["涼风飄嘉樹，日夜減芳华。","下有感秋婦，攀條苦悲嗟。","我本幽闲女，結髮事豪家。","豪家多婢僕，门內頗驕奢。","良人近封候，出入鳴玉珂。","自從富貴来，恩薄讒言多。","冢婦独守禮，羣妾互奇衺。","但信言有玷，不察心無瑕。","容光未銷歇，歡愛忽蹉跎。","何意掌上玉，化爲眼中砂。","盈盈一尺水，浩浩千丈河。","勿言小大異，隨分有风波。","閨房猶复爾，邦国當如何。"]', '诗', 'shi', '', NULL, '續古詩十首 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c5d972-21a8-4f8a-98d3-476743028682', '續古詩十首 八', '續古诗十首 八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["心亦無所迫，身亦無所拘。","何爲腸中氣，鬱鬱不得舒。","不舒良有以，同心久離居。","五年不見面，三年不得書。","念此令人老，抱膝坐長吁。","豈無盈尊酒，非君誰與娛。"]', '["心亦無所迫，身亦無所拘。","何爲腸中氣，鬱鬱不得舒。","不舒良有以，同心久離居。","五年不见面，三年不得书。","念此令人老，抱膝坐长吁。","豈無盈尊酒，非君誰與娛。"]', '诗', 'shi', '', NULL, '續古詩十首 八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b2ba0b5-f8f6-458a-bf97-a2b555d4f25b', '續古詩十首 九', '續古诗十首 九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["攬衣出門行，遊觀繞林渠。","澹澹春水暖，東風生綠蒲。","上有和鳴雁，下有掉尾魚。","飛沈一何樂，鱗羽各有徒。","而我方獨處，不與之子俱。","顧彼自傷己，禽魚之不如。","出遊欲遣憂，孰知憂有餘。"]', '["攬衣出门行，游观繞林渠。","澹澹春水暖，东风生綠蒲。","上有和鳴雁，下有掉尾鱼。","飞沈一何乐，鱗羽各有徒。","而我方独处，不與之子俱。","顧彼自傷己，禽鱼之不如。","出游欲遣憂，孰知憂有餘。"]', '诗', 'shi', '', NULL, '續古詩十首 九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e87f60d5-df4f-4786-90c8-f401f0c7bf4c', '續古詩十首 十', '續古诗十首 十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春旦日初出，曈曈耀晨輝。","草木照未遠，浮雲已蔽之。","天地黯以晦，當午如昏時。","雖有東南風，力微不能吹。","中園何所有，滿地青青葵。","陽光委雲上，傾心欲何依。"]', '["春旦日初出，曈曈耀晨輝。","草木照未远，浮云已蔽之。","天地黯以晦，當午如昏时。","雖有东南风，力微不能吹。","中园何所有，满地青青葵。","陽光委云上，傾心欲何依。"]', '诗', 'shi', '', NULL, '續古詩十首 十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('468231ca-94eb-4bc2-bd53-2b59457346b9', '秦中吟十首 議婚', '秦中吟十首 議婚', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天下無正聲，悅耳即爲娛。","人間無正色，悅目即爲姝。","顏色非相遠，貧富則有殊。","貧爲時所棄，富爲時所趨。","紅樓富家女，金縷繡羅襦。","見人不斂手，嬌癡二八初。","母兄未開口，已嫁不須臾。","綠窗貧家女，寂莫二十餘。","荆釵不直錢，衣上無真珠。","幾迴人欲聘，臨日又踟躕。","主人會良媒，置酒滿玉壺。","四座且勿飲，聽我歌兩途。","富家女易嫁，嫁早輕其夫。","貧家女難嫁，嫁晚孝於姑。","聞君欲娶婦，娶婦意何如。"]', '["天下無正声，悅耳即爲娛。","人间無正色，悅目即爲姝。","顏色非相远，貧富則有殊。","貧爲时所棄，富爲时所趨。","紅楼富家女，金縷繡羅襦。","见人不斂手，嬌癡二八初。","母兄未开口，已嫁不須臾。","綠窗貧家女，寂莫二十餘。","荆釵不直錢，衣上無真珠。","幾迴人欲聘，臨日又踟躕。","主人會良媒，置酒满玉壺。","四座且勿饮，听我歌兩途。","富家女易嫁，嫁早轻其夫。","貧家女难嫁，嫁晚孝於姑。","闻君欲娶婦，娶婦意何如。"]', '诗', 'shi', '', NULL, '秦中吟十首 議婚 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c2ac3e-a037-46f4-bc65-ef37a2e1881f', '秦中吟十首 重賦', '秦中吟十首 重賦', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["厚地植桑麻，所要濟生民。","生民理布帛，所求活一身。","身外充征賦，上以奉君親。","國家定兩稅，本意在愛人。","厥初防其淫，明敕內外臣。","稅外加一物，皆以枉法論。","奈何歲月久，貪吏得因循。","浚我以求寵，斂索無冬春。","織絹未成匹，繰絲未盈斤。","里胥迫我納，不許暫逡巡。","歲暮天地閉，陰風生破村。","夜深煙火盡，霰雪白紛紛。","幼者形不蔽，老者體無溫。","悲喘與寒氣，幷入鼻中辛。","昨日輸殘稅，因窺官庫門。","繒帛如山積，絲絮如雲屯。","號爲羨餘物，隨月獻至尊。","奪我身上煖，買爾眼前恩。","進入瓊林庫，歲久化爲塵。"]', '["厚地植桑麻，所要濟生民。","生民理布帛，所求活一身。","身外充征賦，上以奉君親。","国家定兩稅，本意在愛人。","厥初防其淫，明敕內外臣。","稅外加一物，皆以枉法論。","奈何歲月久，貪吏得因循。","浚我以求寵，斂索無冬春。","织絹未成匹，繰絲未盈斤。","里胥迫我納，不許暫逡巡。","歲暮天地閉，陰风生破村。","夜深煙火尽，霰雪白紛紛。","幼者形不蔽，老者體無溫。","悲喘與寒氣，幷入鼻中辛。","昨日輸殘稅，因窺官庫门。","繒帛如山積，絲絮如云屯。","號爲羨餘物，隨月獻至尊。","奪我身上煖，買爾眼前恩。","進入瓊林庫，歲久化爲塵。"]', '诗', 'shi', '', NULL, '秦中吟十首 重賦 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce5ee95-a94a-4bdc-9cf1-cac8447f93e5', '秦中吟十首 傷宅', '秦中吟十首 傷宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["誰家起甲第，朱門大道邊。","豐屋中櫛比，高牆外迴環。","纍纍六七堂，棟宇相連延。","一堂費百萬，鬱鬱起青煙。","洞房溫且清，寒暑不能干。","高堂虛且迥，坐臥見南山。","繞廊柴藤架，夾砌紅藥欄。","攀枝摘櫻桃，帶花移牡丹。","主人此中坐，十載爲大官。","廚有臭敗肉，庫有貫朽錢。","誰能將我語，問爾骨肉間。","豈無窮賤者，忍不救飢寒。","如何奉一身，直欲保千年。","不見馬家宅，今作奉誠園。"]', '["誰家起甲第，朱门大道邊。","豐屋中櫛比，高牆外迴环。","纍纍六七堂，棟宇相連延。","一堂費百万，鬱鬱起青煙。","洞房溫且清，寒暑不能干。","高堂虛且迥，坐臥见南山。","繞廊柴藤架，夾砌紅藥欄。","攀枝摘櫻桃，带花移牡丹。","主人此中坐，十載爲大官。","廚有臭敗肉，庫有貫朽錢。","誰能將我語，问爾骨肉间。","豈無窮賤者，忍不救飢寒。","如何奉一身，直欲保千年。","不见马家宅，今作奉誠园。"]', '诗', 'shi', '', NULL, '秦中吟十首 傷宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f8a372b-192c-42ff-93fd-748759d01005', '秦中吟十首 傷友', '秦中吟十首 傷友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陋巷孤寒士，出門苦恓恓。","雖云志氣高，豈免顏色低。","平生同門友，通籍在金閨。","曩者膠漆契，邇來雲雨睽。","正逢下朝歸，軒騎五門西。","是時天久陰，三日雨淒淒。","蹇驢避路立，肥馬當風嘶。","迴頭忘相識，占道上沙堤。","昔年洛陽社，貧賤相提攜。","今日長安道，對面隔雲泥。","近日多如此，非君獨慘悽。","死生不變者，唯聞任與黎。"]', '["陋巷孤寒士，出门苦恓恓。","雖云志氣高，豈免顏色低。","平生同门友，通籍在金閨。","曩者膠漆契，邇来云雨睽。","正逢下朝归，軒騎五门西。","是时天久陰，三日雨淒淒。","蹇驢避路立，肥马當风嘶。","迴头忘相識，占道上沙堤。","昔年洛陽社，貧賤相提携。","今日长安道，对面隔云泥。","近日多如此，非君独慘悽。","死生不变者，唯闻任與黎。"]', '诗', 'shi', '', NULL, '秦中吟十首 傷友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62438a7-3101-43a8-b9a0-a9104fa95f9d', '秦中吟十首 不致仕', '秦中吟十首 不致仕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七十而致仕，禮法有明文。","何乃貪榮者，斯言如不聞。","可憐八九十，齒墮雙眸昏。","朝露貪名利，夕陽憂子孫。","挂冠顧翠緌，懸車惜朱輪。","金章腰不勝，傴僂入君門。","誰不愛富貴，誰不戀君恩。","年高須告老，名遂合退身。","少時共嗤誚，晚歲多因循。","賢哉漢二疏，彼獨是何人。","寂莫東門路，無人繼去塵。"]', '["七十而致仕，禮法有明文。","何乃貪榮者，斯言如不闻。","可怜八九十，齒墮雙眸昏。","朝露貪名利，夕陽憂子孫。","挂冠顧翠緌，懸车惜朱輪。","金章腰不勝，傴僂入君门。","誰不愛富貴，誰不戀君恩。","年高須告老，名遂合退身。","少时共嗤誚，晚歲多因循。","賢哉漢二疏，彼独是何人。","寂莫东门路，無人繼去塵。"]', '诗', 'shi', '', NULL, '秦中吟十首 不致仕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eff3368f-d3ef-4efc-8f76-3fc5451498d7', '秦中吟十首 立碑', '秦中吟十首 立碑', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勳德既下衰，文章亦陵夷。","但見山中石，立作路旁碑。","銘勳悉太公，敘德皆仲尼。","復以多爲貴，千言直萬貲。","爲文彼何人，想見下筆時。","但欲愚者悅，不思賢者嗤。","豈獨賢者嗤，仍傳後代疑。","古石蒼苔字，安知是媿詞。","我聞望江縣，麴令撫惸嫠。","在官有仁政，名不聞京師。","身歿欲歸葬，百姓遮路岐。","攀轅不得歸，留葬此江湄。","至今道其名，男女涕皆垂。","無人立碑碣，唯有邑人知。"]', '["勳德既下衰，文章亦陵夷。","但见山中石，立作路旁碑。","銘勳悉太公，敘德皆仲尼。","复以多爲貴，千言直万貲。","爲文彼何人，想见下笔时。","但欲愚者悅，不思賢者嗤。","豈独賢者嗤，仍傳後代疑。","古石蒼苔字，安知是媿词。","我闻望江縣，麴令撫惸嫠。","在官有仁政，名不闻京師。","身歿欲归葬，百姓遮路岐。","攀轅不得归，留葬此江湄。","至今道其名，男女涕皆垂。","無人立碑碣，唯有邑人知。"]', '诗', 'shi', '', NULL, '秦中吟十首 立碑 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d73a7ee-1ba7-4554-b380-3ecc19cba200', '秦中吟十首 輕肥', '秦中吟十首 轻肥', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["意氣驕滿路，鞍馬光照塵。","借問何爲者，人稱是內臣。","朱紱皆大夫，紫綬或將軍。","誇赴軍中宴，走馬去如雲。","尊罍溢九醞，水陸羅八珍。","果擘洞庭橘，膾切天池鱗。","食飽心自若，酒酣氣益振。","是歲江南旱，衢州人食人。"]', '["意氣驕满路，鞍马光照塵。","借问何爲者，人稱是內臣。","朱紱皆大夫，紫綬或將軍。","誇赴軍中宴，走马去如云。","尊罍溢九醞，水陸羅八珍。","果擘洞庭橘，膾切天池鱗。","食飽心自若，酒酣氣益振。","是歲江南旱，衢州人食人。"]', '诗', 'shi', '', NULL, '秦中吟十首 輕肥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbb4237d-7ec6-4eeb-ab1f-200accf6954d', '秦中吟十首 五弦', '秦中吟十首 五弦', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["清歌且罷唱，紅袂亦停舞。","趙叟抱五弦，宛轉當胸撫。","大聲麄若散，颯颯風和雨。","小聲細欲絕，切切鬼神語。","又如鵲報喜，轉作猨啼苦。","十指無定音，顛倒宮徵羽。","坐客聞此聲，形神若無主。","行客聞此聲，駐足不能舉。","嗟嗟俗人耳，好今不好古。","所以綠窗琴，日日生塵土。"]', '["清歌且罷唱，紅袂亦停舞。","趙叟抱五弦，宛轉當胸撫。","大声麄若散，颯颯风和雨。","小声細欲絕，切切鬼神語。","又如鵲報喜，轉作猨啼苦。","十指無定音，顛倒宮徵羽。","坐客闻此声，形神若無主。","行客闻此声，駐足不能舉。","嗟嗟俗人耳，好今不好古。","所以綠窗琴，日日生塵土。"]', '诗', 'shi', '', NULL, '秦中吟十首 五弦 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9676361e-0b9d-492d-8405-0b8e46a5be84', '秦中吟十首 歌舞', '秦中吟十首 歌舞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秦中歲云暮，大雪滿皇州。","雪中退朝者，朱紫盡公候。","貴有風雪興，富無飢寒憂。","所營唯第宅，所務在追遊。","朱門車馬客，紅燭歌舞樓。","歡酣促密坐，醉煖脫重裘。","秋官爲主人，廷尉居上頭。","日中爲一樂，夜半不能休。","豈知閿鄉獄，中有凍死囚。"]', '["秦中歲云暮，大雪满皇州。","雪中退朝者，朱紫尽公候。","貴有风雪兴，富無飢寒憂。","所營唯第宅，所務在追游。","朱门车马客，紅燭歌舞楼。","歡酣促密坐，醉煖脫重裘。","秋官爲主人，廷尉居上头。","日中爲一乐，夜半不能休。","豈知閿乡獄，中有凍死囚。"]', '诗', 'shi', '', NULL, '秦中吟十首 歌舞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc2eede8-a26c-402f-b4c8-97a2ad1f1207', '秦中吟十首 買花', '秦中吟十首 買花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["帝城春欲暮，喧喧車馬度。","共道牡丹時，相隨買花去。","貴賤無常價，酬直看花數。","灼灼百朵紅，戔戔五束素。","上張幄幕庇，旁織巴籬護。","水灑復泥封，移來色如故。","家家習爲俗，人人迷不悟。","有一田舍翁，偶來買花處。","低頭獨長歎，此歎無人喻。","一叢深色花，十戶中人賦。"]', '["帝城春欲暮，喧喧车马度。","共道牡丹时，相隨買花去。","貴賤無常價，酬直看花數。","灼灼百朵紅，戔戔五束素。","上張幄幕庇，旁织巴籬護。","水灑复泥封，移来色如故。","家家習爲俗，人人迷不悟。","有一田舍翁，偶来買花处。","低头独长歎，此歎無人喻。","一叢深色花，十戶中人賦。"]', '诗', 'shi', '', NULL, '秦中吟十首 買花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50a07b10-b4b7-4847-b588-d8d622377cc9', '贈友五首 一', '贈友五首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一年十二月，每月有常令。","君出臣奉行，謂之握金鏡。","由茲六氣順，以遂萬物性。","時令一反常，生靈受其病。","周漢德下衰，王風始不競。","又從斬鼂錯，諸侯益強盛。","百里不同禁，四時自爲政。","盛夏興土功，方春勦人命。","誰能救其失，待君佐邦柄。","峨峨象魏門，懸法彝倫正。"]', '["一年十二月，每月有常令。","君出臣奉行，謂之握金镜。","由茲六氣順，以遂万物性。","时令一反常，生靈受其病。","周漢德下衰，王风始不競。","又從斬鼂錯，諸侯益強盛。","百里不同禁，四时自爲政。","盛夏兴土功，方春勦人命。","誰能救其失，待君佐邦柄。","峨峨象魏门，懸法彝倫正。"]', '诗', 'shi', '', NULL, '贈友五首 一 白居易 shi');
